import { BitmapFontManager, BitmapText, Container } from 'pixi.js';

import { px } from '../render/units.ts';

import { MENU_COLOR } from './MenuList.ts';
import type { Measure } from './TextLayout.ts';

export const FONT = {
  TITLE: 'motox-bold',
  MENU: 'motox-bold',
  SMALL: 'motox-small',
} as const;

export type FontName = (typeof FONT)[keyof typeof FONT];

export const FONT_FAMILY = 'Arial, Helvetica, "Liberation Sans", sans-serif';

export const FONT_SIZE: Readonly<Record<FontName, number>> = {
  [FONT.MENU]: px(13),
  [FONT.SMALL]: px(10),
};

export const SHADOW_OFFSET = 2;

export const FONT_CHARS: (string | string[])[] = [
  [' ', '~'],
  ['¡', 'ÿ'],
];

export interface GlyphMetrics {
  readonly chars: Readonly<
    Record<string, { xAdvance: number; kerning?: Record<string, number> }>
  >;
  readonly lineHeight: number;
  readonly baseMeasurementFontSize?: number;
}

export type FontInstaller = (name: FontName, size: number) => GlyphMetrics;

const installWithPixi: FontInstaller = (name, size) =>
  BitmapFontManager.install({
    name,
    chars: FONT_CHARS,
    textureStyle: { scaleMode: 'linear' },
    dynamicFill: true,
    style: { fontFamily: FONT_FAMILY, fontSize: size, fill: 0xffffff },
  });

const installed = new Map<string, GlyphMetrics>();

export function installFonts(install: FontInstaller = installWithPixi): void {
  for (const name of new Set<FontName>(Object.values(FONT))) {
    if (installed.has(name)) continue;
    installed.set(name, install(name, FONT_SIZE[name]));
  }
}

export function resetFonts(): void {
  installed.clear();
}

export function fontMetrics(name: FontName): GlyphMetrics {
  const font = installed.get(name);
  if (!font) throw new Error(`font '${name}' is not installed — call installFonts()`);
  return font;
}

export function fontHeight(name: FontName): number {
  const font = fontMetrics(name);
  return Math.ceil(font.lineHeight * fontScale(name, font));
}

export function fontScale(
  name: FontName,
  font: GlyphMetrics = fontMetrics(name),
): number {
  const base = font.baseMeasurementFontSize;
  return base === undefined || base <= 0 ? 1 : FONT_SIZE[name] / base;
}

export function glyphMeasure(font: GlyphMetrics, scale = 1): Measure {
  return (text, start, length) => {
    let width = 0;
    let previous: string | null = null;
    const end = Math.min(start + length, text.length);
    for (let at = Math.max(0, start); at < end; at += 1) {
      const char = text.charAt(at);
      const glyph = font.chars[char];
      if (glyph) {
        const kerning = previous === null ? 0 : (glyph.kerning?.[previous] ?? 0);
        width += glyph.xAdvance + kerning;
      }
      previous = char;
    }
    return width * scale;
  };
}

export function measureFor(name: FontName): Measure {
  const font = fontMetrics(name);
  return glyphMeasure(font, fontScale(name, font));
}

export interface ShadowTextOptions {
  font: FontName;
  color?: number;
  text?: string;
  anchorX?: number;
}

export class ShadowText extends Container {
  private readonly passes: BitmapText[];
  private anchor: number;
  private value: string;

  constructor(options: ShadowTextOptions) {
    super({ label: 'shadow-text' });

    const { font, color = MENU_COLOR.LABEL, text = '', anchorX = 0 } = options;
    this.value = text;
    this.anchor = anchorX;

    const size = FONT_SIZE[font];
    this.passes = [MENU_COLOR.DIVIDER, MENU_COLOR.SHADOW, color].map((fill, pass) => {
      const child = new BitmapText({
        text,
        style: { fontFamily: font, fontSize: size, fill, whiteSpace: 'pre' },
        x: px(SHADOW_OFFSET - pass),
        y: px(SHADOW_OFFSET - pass),
      });
      child.anchor.x = anchorX;
      this.addChild(child);
      return child;
    });
  }

  get text(): string {
    return this.value;
  }

  set text(text: string) {
    if (text === this.value) return;
    this.value = text;
    for (const pass of this.passes) pass.text = text;
  }

  set color(color: number) {
    this.passes[2]!.style.fill = color;
  }

  set anchorX(anchorX: number) {
    if (anchorX === this.anchor) return;
    this.anchor = anchorX;
    for (const pass of this.passes) pass.anchor.x = anchorX;
  }
}
