import { ACTION, type SoftKeySide } from '../core/Input.ts';
import { INPUT_BIT } from '../data/constants.ts';

export interface TouchSink {
  press(bit: number): void;
  release(bit: number): void;
  pressSoftKey(side: SoftKeySide): void;
}

export interface TouchButton {
  readonly id: string;
  readonly label: string;
  readonly bit?: number;
  readonly softKey?: SoftKeySide;
  readonly action: number;
  readonly hint?: string;
}

export interface TouchGroup {
  readonly id: string;
  readonly style: string;
  readonly buttons: readonly TouchButton[];
}

export interface TouchLayout {
  readonly id: string;
  readonly groups: readonly TouchGroup[];
}

function softGroup(leftLabel: string, rightLabel: string): TouchGroup {
  return {
    id: 'soft',
    style:
      'left:var(--tc-gap);right:var(--tc-gap);bottom:var(--tc-gap);' +
      'justify-content:space-between;',
    buttons: [
      { id: 'soft-left', label: leftLabel, softKey: 'left', action: ACTION.SOFT_LEFT },
      {
        id: 'soft-right',
        label: rightLabel,
        softKey: 'right',
        action: ACTION.SOFT_RIGHT,
      },
    ],
  };
}

