export function layoutButtons(layout: TouchLayout): TouchButton[] {
  return layout.groups.flatMap((group) => [...group.buttons]);
}

export type ButtonStateListener = (id: string, down: boolean) => void;

export class TouchRouter {
  private buttons = new Map<string, TouchButton>();
  private readonly live = new Set<number>();
  private readonly holders = new Map<number, string>();
  private readonly counts = new Map<string, number>();
  private readonly sink: TouchSink;
  private readonly onState: ButtonStateListener | undefined;

  constructor(sink: TouchSink, onState?: ButtonStateListener) {
    this.sink = sink;
    this.onState = onState;
  }

  setButtons(buttons: Iterable<TouchButton>): void {
    this.clear();
    this.buttons = new Map();
    for (const button of buttons) this.buttons.set(button.id, button);
  }

  down(pointerId: number, buttonId: string | undefined): void {
    this.live.add(pointerId);
    this.retarget(pointerId, buttonId);
  }

  move(pointerId: number, buttonId: string | undefined): void {
    if (!this.live.has(pointerId)) return;
    this.retarget(pointerId, buttonId);
  }

  up(pointerId: number): void {
    this.live.delete(pointerId);
    this.retarget(pointerId, undefined);
  }

  clear(): void {
    for (const pointerId of [...this.holders.keys()]) {
      this.retarget(pointerId, undefined);
    }
    this.live.clear();
  }

  get held(): string[] {
    return [...this.counts.keys()].sort();
  }

  private retarget(pointerId: number, buttonId: string | undefined): void {
    const target =
      buttonId !== undefined && this.buttons.has(buttonId) ? buttonId : undefined;
    const previous = this.holders.get(pointerId);
    if (previous === target) return;

    if (previous !== undefined) {
      this.holders.delete(pointerId);
      this.releaseOne(previous);
    }
    if (target === undefined) return;
    this.holders.set(pointerId, target);
    this.pressOne(target);
  }

  private pressOne(id: string): void {
    const count = this.counts.get(id) ?? 0;
    this.counts.set(id, count + 1);
    if (count > 0) return;
    const button = this.buttons.get(id)!;
    if (button.softKey !== undefined) this.sink.pressSoftKey(button.softKey);
    else if (button.bit !== undefined) this.sink.press(button.bit);
    this.onState?.(id, true);
  }

  private releaseOne(id: string): void {
    const count = this.counts.get(id) ?? 0;
    if (count > 1) {
      this.counts.set(id, count - 1);
      return;
    }
    this.counts.delete(id);
    const button = this.buttons.get(id);
    if (button?.bit !== undefined) this.sink.release(button.bit);
    this.onState?.(id, false);
  }
}

