export interface TouchControlsOptions {
  sink: TouchSink;
  layout?: TouchLayout;
  labels?: Readonly<Record<string, string>>;
  document?: Document;
}

export class TouchControls {
  readonly router: TouchRouter;

  private readonly doc: Document;
  private labels: Readonly<Record<string, string>>;
  private readonly elements = new Map<string, HTMLElement>();
  private pad: HTMLElement | undefined;
  private layout: TouchLayout;
  private detachers: Array<() => void> = [];

  constructor(options: TouchControlsOptions) {
    this.doc = options.document ?? document;
    this.labels = options.labels ?? {};
    this.layout = options.layout ?? MENU_LAYOUT;
    this.router = new TouchRouter(options.sink, (id, down) => {
      this.elements.get(id)?.classList.toggle('is-down', down);
    });
  }

  mount(host: HTMLElement = this.doc.body): void {
    if (this.pad) return;
    injectStyle(this.doc);

    const pad = this.doc.createElement('div');
    pad.className = 'tc-pad';
    host.appendChild(pad);
    this.pad = pad;
    this.build();

    const view = this.doc.defaultView ?? window;
    this.listen(pad, 'pointerdown', (event) => {
      event.preventDefault();
      this.router.down(event.pointerId, buttonIdOf(event.target));
    });
    this.listen(pad, 'contextmenu', (event) => event.preventDefault());
    this.listen(view, 'pointermove', (event) => {
      this.router.move(event.pointerId, this.buttonAt(event.clientX, event.clientY));
    });
    this.listen(view, 'pointerup', (event) => this.router.up(event.pointerId));
    this.listen(view, 'pointercancel', (event) => this.router.up(event.pointerId));
    this.listen(view, 'blur', () => this.router.clear());
  }

  setLayout(layout: TouchLayout, labels?: Readonly<Record<string, string>>): void {
    if (labels) this.labels = labels;
    if (layout.id === this.layout.id) {
      this.applyLabels();
      return;
    }
    this.layout = layout;
    if (this.pad) this.build();
  }

  setLabels(labels: Readonly<Record<string, string>>): void {
    this.labels = labels;
    this.applyLabels();
  }

  private applyLabels(): void {
    for (const button of layoutButtons(this.layout)) {
      const element = this.elements.get(button.id);
      if (!element) continue;
      const text = this.labels[button.id] ?? button.label;
      element.textContent = text;
      element.hidden = text === '';
    }
  }

  get visible(): boolean {
    return this.pad !== undefined && !this.pad.hidden;
  }

  set visible(value: boolean) {
    if (!this.pad) return;
    if (!value) this.router.clear();
    this.pad.hidden = !value;
  }

  destroy(): void {
    this.router.clear();
    for (const detacher of this.detachers) detacher();
    this.detachers = [];
    this.pad?.remove();
    this.pad = undefined;
    this.elements.clear();
  }

  private build(): void {
    const pad = this.pad!;
    this.router.clear();
    pad.replaceChildren();
    this.elements.clear();

    for (const group of this.layout.groups) {
      const element = this.doc.createElement('div');
      element.className = 'tc-group';
      element.style.cssText = group.style;
      for (const button of group.buttons) element.appendChild(this.buildButton(button));
      pad.appendChild(element);
    }
    this.router.setButtons(layoutButtons(this.layout));
  }

  private buildButton(button: TouchButton): HTMLElement {
    const element = this.doc.createElement('button');
    element.type = 'button';
    element.className = button.softKey !== undefined ? 'tc-button tc-soft' : 'tc-button';
    element.dataset.touchId = button.id;
    const text = this.labels[button.id] ?? button.label;
    element.textContent = text;
    element.hidden = text === '';
    if (button.hint !== undefined) element.title = button.hint;
    element.tabIndex = -1;
    element.setAttribute('aria-hidden', 'true');
    this.elements.set(button.id, element);
    return element;
  }

  private buttonAt(x: number, y: number): string | undefined {
    return buttonIdOf(this.doc.elementFromPoint(x, y));
  }

  private listen<K extends keyof WindowEventMap>(
    target: EventTarget,
    type: K,
    handler: (event: WindowEventMap[K]) => void,
  ): void {
    const listener = handler as EventListener;
    target.addEventListener(type, listener);
    this.detachers.push(() => target.removeEventListener(type, listener));
  }
}

function buttonIdOf(node: EventTarget | null): string | undefined {
  if (node === null || !(node instanceof Element)) return undefined;
  const element = node.closest<HTMLElement>('[data-touch-id]');
  return element?.dataset.touchId;
}

function injectStyle(doc: Document): void {
  if (doc.getElementById(STYLE_ID)) return;
  const style = doc.createElement('style');
  style.id = STYLE_ID;
  style.textContent = STYLE_TEXT;
  doc.head.appendChild(style);
}

export function isTouchLikely(view: Window = window): boolean {
  if ((view.navigator?.maxTouchPoints ?? 0) > 0) return true;
  return view.matchMedia?.('(pointer: coarse)').matches === true;
}
