import { Container, Graphics, Sprite } from 'pixi.js';

import {
  LOGICAL_HEIGHT,
  LOGICAL_WIDTH,
  SCREEN_HEIGHT,
  SCREEN_WIDTH,
} from '../core/config.ts';
import {
  HUD_LAYOUT,
  SPRITE_STRIPS,
  TRICK_SLOTS,
  TRICK_TEXT_STRING,
} from '../data/constants.ts';
import {
  ANIM,
  EFFECT_PREVIOUS_X,
  EFFECT_PREVIOUS_Y,
  SCREEN_SPACE,
  type ParticleFx,
} from '../render/ParticleFx.ts';
import {
  anchorAt,
  recordFrame,
  stripFrame,
  stripPivot,
  type TextureLookup,
} from '../render/BikeView.ts';
import { UI_SPRITE_SCALE, px } from '../render/units.ts';

export const BAR_STRIP = 0;
export const ICON_STRIP = 1;
export const THROTTLE_STRIP = 2;
export const PROGRESS_STRIP = 3;
export const DIGIT_STRIP = 4;
export const GLYPH_STRIP = 13;

export const HUD_BAR_RECORD = 72;

export const ICON_FRAME = {
  SOFT_LEFT: 0,
  BOOST_FULL: 1,
  SOFT_RIGHT: 2,
  BOOST_EMPTY: 3,
} as const;

export const PROGRESS_FRAME = { PLAYER: 0, OPPONENT: 1, ERASE: 2 } as const;

export const BOOST_PIPS = 3;

export const TIME_PARTS = 3;

export const TIME_PART_MAX = 99;

export const DECIMAL_BASE = 10;

export const POPUP_LIFE = 40;

export const POPUP_COLUMNS = 12;

export const POPUP_COLUMN_DIVISOR = 14;

const GLYPH_ORIGIN = 'A'.charCodeAt(0);

const GLYPH_SPACE_CODE = ' '.charCodeAt(0);

const GLYPH_ACCENT_CODE = 'É'.charCodeAt(0);

export const GLYPH_SPACE = -1;

export const POPUP_NAMES = 2;

export const TRICK_NAME_COUNT = TRICK_SLOTS + POPUP_NAMES;

export const FIRST_TRICK_TEXT = TRICK_TEXT_STRING;

function shiftRight(value: number, bits: number): number {
  return Math.floor(value / 2 ** bits);
}

export interface HudLayout {
  readonly barX: number;
  readonly viewportHeight: number;
  readonly softLeftX: number;
  readonly softRightX: number;
  readonly softIconY: number;
  readonly progressLeft: number;
  readonly progressRight: number;
  readonly progressY: number;
  readonly boostIconX: readonly number[];
  readonly boostIconY: number;
  readonly timeDigitX: readonly number[];
  readonly timeDigitY: number;
  readonly digitAdvance: number;
  readonly throttleIconX: number;
  readonly throttleIconY: number;
  readonly popupX: number;
  readonly popupY: number;
  readonly popupStep: number;
  readonly popupOffsets: readonly number[];
}

function unsignedAt(index: number): number {
  return HUD_LAYOUT[index]! & 0xff;
}

function signedAt(index: number): number {
  return HUD_LAYOUT[index]!;
}

function popupColumnOffsets(screenWidth: number): number[] {
  const pitch = Math.trunc((screenWidth << 10) / POPUP_COLUMN_DIVISOR);
  let offset = -((screenWidth << 10) >> 1) + pitch;
  const offsets: number[] = [];
  for (let column = 0; column < POPUP_COLUMNS; column += 1) {
    offsets.push(Math.trunc(offset / POPUP_LIFE));
    offset += pitch;
  }
  return offsets;
}

export function hudLayout(
  screenWidth = SCREEN_WIDTH,
  screenHeight = SCREEN_HEIGHT,
  swapSoftKeys = false,
): HudLayout {
  const barX = (screenWidth - unsignedAt(0)) >> 1;
  const barHeight = unsignedAt(1);
  const viewportHeight = screenHeight - barHeight;

  let softLeftX = unsignedAt(2) + barX;
  let softRightX = unsignedAt(3) + barX;
  if (swapSoftKeys) [softLeftX, softRightX] = [softRightX, softLeftX];

  const popupOffsets = popupColumnOffsets(screenWidth);

  const popupTopY = (viewportHeight - barHeight) << 10;

  return {
    barX,
    viewportHeight,
    softLeftX,
    softRightX,
    softIconY: unsignedAt(4) + viewportHeight,
    progressLeft: unsignedAt(5) + barX,
    progressRight: unsignedAt(6) + barX,
    progressY: signedAt(7) + viewportHeight,
    boostIconX: [unsignedAt(8) + barX, unsignedAt(9) + barX, unsignedAt(10) + barX],
    boostIconY: unsignedAt(11) + viewportHeight,
    timeDigitX: [unsignedAt(12) + barX, unsignedAt(13) + barX, unsignedAt(14) + barX],
    timeDigitY: unsignedAt(15) + viewportHeight,
    digitAdvance: SPRITE_STRIPS[DIGIT_STRIP]!.width + 1,
    throttleIconX: unsignedAt(16) + barX,
    throttleIconY: unsignedAt(17) + viewportHeight,
    popupX: (screenWidth << 10) >> 1,
    popupY: viewportHeight << 10,
    popupStep: Math.trunc((popupTopY + 102400) / POPUP_LIFE),
    popupOffsets,
  };
}

export function minutesOf(ms: number): number {
  return Math.trunc(ms / 60000);
}

export function secondsOf(ms: number): number {
  return Math.trunc((ms % 60000) / 1000);
}

export function hundredthsOf(ms: number): number {
  return Math.trunc((ms % 1000) / 10);
}

export interface ProgressSource {
  readonly jointX: Int32Array | readonly number[];
  readonly wrapCount: number;
}

export interface HudView {
  readonly boostCharges: number;
  readonly throttleLatched: boolean;
  readonly timeMs: number;
  readonly player?: ProgressSource | undefined;
  readonly opponent?: ProgressSource | undefined;
}

export interface ProgressScale {
  readonly startX: number;
  readonly span: number;
  readonly scale: number;
}

export function progressScale(
  layout: HudLayout,
  startX: number,
  span: number,
): ProgressScale {
  return {
    startX,
    span,
    scale: Math.trunc(((layout.progressRight - layout.progressLeft) << 20) / span),
  };
}

export function buildTrickGlyphs(names: readonly string[]): Int8Array[] {
  const accent = SPRITE_STRIPS[GLYPH_STRIP]!.frames - 1;
  const table: Int8Array[] = [];
  for (let entry = 0; entry < TRICK_NAME_COUNT; entry += 1) {
    const name = (names[entry] ?? '').toUpperCase();
    const glyphs = new Int8Array(name.length);
    for (let index = 0; index < name.length; index += 1) {
      const code = name.charCodeAt(index);
      glyphs[index] =
        code === GLYPH_SPACE_CODE
          ? GLYPH_SPACE
          : code === GLYPH_ACCENT_CODE
            ? accent
            : code - GLYPH_ORIGIN;
    }
    table.push(glyphs);
  }
  return table;
}

function frame(textures: TextureLookup, name: string) {
  const texture = textures[name];
  if (!texture) throw new Error(`no atlas frame '${name}'`);
  return texture;
}

function stripSprite(textures: TextureLookup, strip: number, index: number): Sprite {
  const pivot = stripPivot(strip);
  const sprite = new Sprite({
    texture: frame(textures, stripFrame(strip, index)),
    scale: UI_SPRITE_SCALE,
  });
  anchorAt(sprite, pivot.x, pivot.y);
  return sprite;
}

export class Hud {
  readonly container = new Container({ label: 'hud' });

  readonly layout: HudLayout;

  private readonly textures: TextureLookup;

  private readonly bar: Sprite;

  private readonly gutters = new Graphics({ label: 'hud-gutters' });

  private readonly softIcons: Sprite[] = [];
  private readonly boostIcons: Sprite[] = [];
  private readonly throttleIcon: Sprite;
  private readonly digits: Sprite[] = [];

  private readonly markers: Sprite[] = [];
  private readonly erasers: Sprite[] = [];

  private readonly markerX = [0, 0];

  private scale: ProgressScale;

  private trickGlyphs: Int8Array[];

  private needsFullDraw = true;

  private readonly timeParts = new Int32Array(TIME_PARTS);

  private readonly timePartsDrawn = new Int32Array(TIME_PARTS).fill(-1);
  private readonly timeDigits = new Int32Array(TIME_PARTS * 2);
  private readonly timeDigitsDrawn = new Int32Array(TIME_PARTS * 2).fill(-1);

  private boostChargesDrawn = -1;
  private throttleLatchedDrawn = false;

  constructor(
    textures: TextureLookup,
    options: {
      layout?: HudLayout;
      scale?: ProgressScale;
      trickNames?: readonly string[];
    } = {},
  ) {
    this.textures = textures;
    const layout = options.layout ?? hudLayout();
    this.layout = layout;
    this.scale = options.scale ?? progressScale(layout, 0, 1 << 10);
    this.trickGlyphs = buildTrickGlyphs(options.trickNames ?? []);

    this.container.addChild(this.gutters);

    this.bar = this.buildBar(textures, layout);

    this.buildProgress(textures, layout);
    this.buildSoftIcons(textures, layout);
    this.buildBoostIcons(textures, layout);

    this.throttleIcon = stripSprite(textures, THROTTLE_STRIP, 0);
    this.throttleIcon.label = 'hud-throttle';
    this.throttleIcon.position.set(px(layout.throttleIconX), px(layout.throttleIconY));
    this.container.addChild(this.throttleIcon);

    this.buildDigits(textures, layout);

    this.buildGutters(layout);
  }

  private buildBar(textures: TextureLookup, layout: HudLayout): Sprite {
    const bar = new Sprite({
      texture: frame(textures, recordFrame(HUD_BAR_RECORD)),
      label: 'hud-bar',
      scale: UI_SPRITE_SCALE,
    });
    bar.position.set(px(layout.barX), px(layout.viewportHeight));
    this.container.addChild(bar);
    return bar;
  }

  private buildGutters(layout: HudLayout): void {
    if (layout.barX <= 0) return;
    this.gutters
      .rect(
        0,
        px(layout.viewportHeight),
        LOGICAL_WIDTH,
        LOGICAL_HEIGHT - px(layout.viewportHeight),
      )
      .fill(0x000000);
  }

  private buildProgress(textures: TextureLookup, layout: HudLayout): void {
    for (let rider = 0; rider < 2; rider += 1) {
      const eraser = stripSprite(textures, PROGRESS_STRIP, PROGRESS_FRAME.ERASE);
      const marker = stripSprite(textures, PROGRESS_STRIP, rider);
      eraser.label = `hud-eraser-${rider}`;
      marker.label = `hud-marker-${rider}`;
      eraser.visible = false;
      marker.visible = false;
      eraser.y = px(layout.progressY);
      marker.y = px(layout.progressY);
      this.erasers.push(eraser);
      this.markers.push(marker);
      this.container.addChild(eraser, marker);
    }
  }

  private buildSoftIcons(textures: TextureLookup, layout: HudLayout): void {
    for (const [side, x] of [
      [ICON_FRAME.SOFT_LEFT, layout.softLeftX],
      [ICON_FRAME.SOFT_RIGHT, layout.softRightX],
    ] as const) {
      const icon = stripSprite(textures, ICON_STRIP, side);
      icon.label = `hud-soft-${side}`;
      icon.position.set(px(x), px(layout.softIconY));
      this.softIcons.push(icon);
      this.container.addChild(icon);
    }
  }

  private buildBoostIcons(textures: TextureLookup, layout: HudLayout): void {
    for (let pip = 0; pip < BOOST_PIPS; pip += 1) {
      const icon = stripSprite(textures, ICON_STRIP, ICON_FRAME.BOOST_FULL);
      icon.label = `hud-boost-${pip}`;
      icon.position.set(px(layout.boostIconX[pip]!), px(layout.boostIconY));
      icon.visible = false;
      this.boostIcons.push(icon);
      this.container.addChild(icon);
    }
  }

  private buildDigits(textures: TextureLookup, layout: HudLayout): void {
    for (let field = 0; field < TIME_PARTS; field += 1) {
      for (let half = 0; half < 2; half += 1) {
        const digit = stripSprite(textures, DIGIT_STRIP, 0);
        digit.label = `hud-digit-${field * 2 + half}`;
        digit.position.set(
          px(layout.timeDigitX[field]! + half * layout.digitAdvance),
          px(layout.timeDigitY),
        );
        this.digits.push(digit);
        this.container.addChild(digit);
      }
    }
  }

  setProgressScale(scale: ProgressScale): void {
    this.scale = scale;
  }

  setTrickNames(names: readonly string[]): void {
    this.trickGlyphs = buildTrickGlyphs(names);
  }

  invalidate(): void {
    this.needsFullDraw = true;
  }

  get pendingFullDraw(): boolean {
    return this.needsFullDraw;
  }

  draw(view: HudView): void {
    if (this.needsFullDraw) {
      this.drawFull(view);
      this.needsFullDraw = false;
      return;
    }

    if (view.player) this.updateMarker(view.player, 0);
    else this.hideMarker(0);
    if (view.opponent) this.updateMarker(view.opponent, 1);
    else this.hideMarker(1);

    if (view.boostCharges !== this.boostChargesDrawn) {
      for (let pip = 0; pip < BOOST_PIPS; pip += 1) {
        this.setBoostPip(
          pip,
          pip < view.boostCharges ? ICON_FRAME.BOOST_FULL : ICON_FRAME.BOOST_EMPTY,
        );
      }
      this.boostChargesDrawn = view.boostCharges;
    }

    if (view.throttleLatched !== this.throttleLatchedDrawn) {
      this.setThrottle(view.throttleLatched);
      this.throttleLatchedDrawn = view.throttleLatched;
    }

    this.updateTimeDigits(view.timeMs);
    for (let index = 0; index < this.timeDigits.length; index += 1) {
      if (this.timeDigits[index] === this.timeDigitsDrawn[index]) continue;
      this.setDigit(index, this.timeDigits[index]!);
      this.timeDigitsDrawn[index] = this.timeDigits[index]!;
    }
  }

  private drawFull(view: HudView): void {
    this.bar.visible = true;

    for (let rider = 0; rider < 2; rider += 1) this.erasers[rider]!.visible = false;
    if (view.player) this.placeMarker(view.player, 0);
    else this.hideMarker(0);
    if (view.opponent) this.placeMarker(view.opponent, 1);
    else this.hideMarker(1);

    for (const icon of this.softIcons) icon.visible = true;

    for (let pip = 0; pip < BOOST_PIPS; pip += 1) {
      if (pip < view.boostCharges) this.setBoostPip(pip, ICON_FRAME.BOOST_FULL);
      else this.boostIcons[pip]!.visible = false;
    }
    this.boostChargesDrawn = view.boostCharges;

    this.setThrottle(view.throttleLatched);
    this.throttleLatchedDrawn = view.throttleLatched;

    this.updateTimeDigits(view.timeMs);
    for (let index = 0; index < this.timeDigits.length; index += 1) {
      this.setDigit(index, this.timeDigits[index]!);
      this.timeDigitsDrawn[index] = this.timeDigits[index]!;
    }
  }

  markerPosition(rider: ProgressSource): number {
    const { startX, span, scale } = this.scale;
    const distance = rider.jointX[2]! + rider.wrapCount * span - startX;
    const scaled = shiftRight(distance * scale, 10);
    const width = this.layout.progressRight - this.layout.progressLeft;
    return (
      this.layout.progressLeft + Math.max(0, Math.min(shiftRight(scaled, 10), width))
    );
  }

  private placeMarker(rider: ProgressSource, index: number): void {
    const x = this.markerPosition(rider);
    const marker = this.markers[index]!;
    marker.x = px(x);
    marker.visible = true;
    this.markerX[index] = x;
  }

  private updateMarker(rider: ProgressSource, index: number): void {
    const eraser = this.erasers[index]!;
    if (this.layout.progressY >= this.layout.viewportHeight) {
      eraser.x = px(this.markerX[index]!);
      eraser.visible = true;
    } else {
      eraser.visible = false;
    }
    this.placeMarker(rider, index);
  }

  private hideMarker(index: number): void {
    this.markers[index]!.visible = false;
    this.erasers[index]!.visible = false;
  }

  private setBoostPip(pip: number, iconFrame: number): void {
    const icon = this.boostIcons[pip]!;
    icon.texture = frame(this.textures, stripFrame(ICON_STRIP, iconFrame));
    icon.visible = true;
  }

  private setThrottle(latched: boolean): void {
    this.throttleIcon.texture = frame(
      this.textures,
      stripFrame(THROTTLE_STRIP, latched ? 1 : 0),
    );
  }

  private setDigit(index: number, value: number): void {
    this.digits[index]!.texture = frame(this.textures, stripFrame(DIGIT_STRIP, value));
  }

  private updateTimeDigits(timeMs: number): void {
    this.timeParts[0] = minutesOf(timeMs);
    this.timeParts[1] = secondsOf(timeMs);
    this.timeParts[2] = hundredthsOf(timeMs);

    for (let field = 0; field < TIME_PARTS; field += 1) {
      const part = this.timeParts[field]!;
      if (part === this.timePartsDrawn[field]) continue;
      this.timePartsDrawn[field] = part;
      const clamped = part < TIME_PART_MAX ? part : TIME_PART_MAX;
      const tens = Math.trunc(clamped / DECIMAL_BASE);
      this.timeDigits[field * 2] = tens;
      this.timeDigits[field * 2 + 1] = clamped - tens * DECIMAL_BASE;
    }
  }

  spellTrick(fx: ParticleFx, entry: number): void {
    const glyphs = this.trickGlyphs[entry];
    if (!glyphs) return;

    const { popupX, popupY, popupStep, popupOffsets } = this.layout;
    let column = ((POPUP_COLUMNS - glyphs.length) >> 1) + 1;
    for (let index = 0; index < glyphs.length; index += 1, column += 1) {
      const glyph = glyphs[index]!;
      const offset = popupOffsets[column];
      if (glyph < 0 || offset === undefined) continue;

      const slot = fx.spawn(popupX, popupY, GLYPH_STRIP, POPUP_LIFE);
      if (slot < 0) continue;
      fx.set(slot, EFFECT_PREVIOUS_X, popupX - offset);
      fx.set(slot, EFFECT_PREVIOUS_Y, popupY + popupStep);
      fx.setParams(slot, ANIM.FIXED | SCREEN_SPACE, 0, glyph, 0);
    }
  }

  destroy(): void {
    this.container.destroy({ children: true });
  }
}
