import { Assets, type Spritesheet, type Texture } from 'pixi.js';

import type { TextureLookup } from './BikeView.ts';

export const ATLAS_BASE = 'assets/atlas/';

export const ATLAS_PAGES = [
  'bike',
  'fx',
  'hud',
  'softkeys',
  'sprites',
  'tilesets',
  'ui',
] as const;

export type AtlasPage = (typeof ATLAS_PAGES)[number];

export function atlasUrl(page: string, base: string = ATLAS_BASE): string {
  return `${base}${page}.json`;
}

export interface SheetLike {
  readonly textures: Readonly<Record<string, Texture>>;
}

export type SheetLoader = (
  urls: readonly string[],
  onProgress?: (progress: number) => void,
) => Promise<Record<string, SheetLike>>;

export interface LoadAtlasOptions {
  base?: string;
  onProgress?: (progress: number) => void;
  load?: SheetLoader;
}

const loadWithAssets: SheetLoader = (urls, onProgress) =>
  Assets.load<Spritesheet>([...urls], onProgress) as Promise<Record<string, SheetLike>>;

export async function loadAtlases(
  pages: readonly string[] = ATLAS_PAGES,
  options: LoadAtlasOptions = {},
): Promise<TextureLookup> {
  const { base = ATLAS_BASE, onProgress, load = loadWithAssets } = options;

  const urls = pages.map((page) => atlasUrl(page, base));
  const sheets = await load(urls, onProgress);

  const textures: Record<string, Texture> = {};
  const source: Record<string, string> = {};

  pages.forEach((page, at) => {
    const url = urls[at]!;
    const sheet = sheets[url];
    if (!sheet?.textures) throw new Error(`atlas page '${page}' loaded no textures`);

    for (const [name, texture] of Object.entries(sheet.textures)) {
      const already = source[name];
      if (already !== undefined) {
        throw new Error(
          `duplicate atlas frame '${name}' on pages '${already}' and '${page}'`,
        );
      }
      source[name] = page;
      textures[name] = texture;
    }
  });

  return Object.freeze(textures);
}
