export type Measure = (text: string, start: number, length: number) => number;

export function textWidth(measure: Measure, text: string): number {
  return measure(text, 0, text.length);
}

function skipToken(text: string, cursor: number, length: number): number {
  if (text.charCodeAt(cursor) > 32) return 1;
  if (cursor < length - 1) {
    const next = text.charAt(cursor + 1);
    if (next === '!' || next === '?' || next === ':') return 2;
  }
  return 0;
}

export function wrapPoint(
  measure: Measure,
  text: string,
  start: number,
  width: number,
): number {
  const length = text.length;
  if (start >= length) return -1;

  const lineStart = start;
  let cursor = start;
  let breakAt = start;

  for (;;) {
    if (cursor < length) {
      const skip = skipToken(text, cursor, length);
      if (skip > 0) {
        cursor += skip;
        continue;
      }
    }

    const measured = measure(text, lineStart, cursor - lineStart);
    if (breakAt === lineStart && measured > width) {
      do {
        cursor -= 1;
      } while (measure(text, lineStart, cursor - lineStart) > width);
      breakAt = cursor;
      break;
    }
    if (measured <= width) breakAt = cursor;
    if (measured > width || cursor >= length || text.charAt(cursor) === '\n') break;
    cursor += 1;
  }

  return breakAt >= length ? breakAt : breakAt + 1;
}

export function wrapLines(measure: Measure, text: string, width: number): string[] {
  const lines: string[] = [];
  let start = 0;
  while (start >= 0) {
    const next = wrapPoint(measure, text, start, width);
    if (next < 0) break;
    lines.push(text.slice(start, next).trim());
    start = next;
  }
  return lines;
}

export function ellipsise(measure: Measure, text: string, width: number): string {
  if (textWidth(measure, text) <= width) return text;

  const limit = width - measure('.', 0, 1);
  let cut = 0;
  while (cut < text.length && measure(text, 0, cut) < limit) cut += 1;
  return text.slice(0, Math.max(0, cut - 1)) + '.';
}
