import { CHALLENGES, TARGET_FORMAT } from '../../data/constants.ts';
import { TRICK_SLOTS, type Bike } from '../../game/Bike.ts';
import { RACE_FLAG, type RaceState } from '../../game/RaceState.ts';
import type { ChallengeResult } from '../../game/ScoreModel.ts';

import {
  RESULT_STRING,
  formatString,
  formatStrings,
  formatTimeLong,
  type StringSlots,
} from './strings.ts';
import { landedTrickText, requirementText } from './text.ts';

export const MS_PER_TICK = 60;

export function describeResult(
  slots: StringSlots,
  state: RaceState,
  format: number,
): string {
  const bike = state.player.bike as Bike;
  switch (format) {
    case TARGET_FORMAT.TIME_MINUTES:
      return formatTimeLong(slots, state.player.timeMs);
    case TARGET_FORMAT.NUMBER: {
      let landed = 0;
      for (let slot = 7; slot < TRICK_SLOTS; slot += 1)
        landed += bike.trickTotals[slot] ?? 0;
      return String(landed);
    }
    case TARGET_FORMAT.TRICK_LIST:
      return landedTrickText(slots, bike.trickTotals);
    case TARGET_FORMAT.TIME_SECONDS: {
      formatString(
        slots,
        RESULT_STRING.GHOST_TIME,
        formatTimeLong(slots, state.opponent?.timeMs ?? 0),
      );
      return (
        formatTimeLong(slots, state.player.timeMs) + slots.text(RESULT_STRING.GHOST_TIME)
      );
    }
    default:
      return '';
  }
}

export function describeShortfall(
  slots: StringSlots,
  state: RaceState,
  format: number,
  graded: ChallengeResult,
): string {
  const row = CHALLENGES[state.challenge]!;
  const bike = state.player.bike as Bike;
  switch (format) {
    case TARGET_FORMAT.TIME_MINUTES: {
      const bronzeTime = row.targetBronze * MS_PER_TICK;
      if (!state.hasFlag(RACE_FLAG.COMBO)) return formatTimeLong(slots, bronzeTime);
      const owed = requirementText(slots, state.challenge, bike.trickTotals);
      const beatTheClock = state.player.timeMs <= bronzeTime;
      if (beatTheClock) return owed;
      const target = formatStrings(slots, RESULT_STRING.COMBO_TARGET, [
        slots.text(graded.measureTextId),
        formatTimeLong(slots, bronzeTime),
      ]);
      return `${target}\n${owed}`;
    }
    case TARGET_FORMAT.NUMBER:
      return String(row.targetBronze);
    case TARGET_FORMAT.TRICK_LIST:
      return graded.missingTrickTextIds.length > 0
        ? slots.text(graded.missingTrickTextIds[0]!)
        : '';
    case TARGET_FORMAT.TIME_SECONDS:
      return formatTimeLong(
        slots,
        (state.opponent?.timeMs ?? 0) - row.targetBronze * MS_PER_TICK,
      );
    default:
      return '';
  }
}
