import type { Scene } from './Scene.ts';

export interface InputSink {
  clear(): void;
}

export interface SceneManagerOptions {
  input?: InputSink;
}

export const QUEUED_TRANSITION_TICKS = 35;

type PendingKind = 'push' | 'replace';

interface Pending {
  scene: Scene;
  kind: PendingKind;
  ticksLeft: number;
}

export class SceneManager {
  private readonly stack: Scene[] = [];
  private readonly input: InputSink | undefined;
  private pending: Pending | undefined;

  constructor(options: SceneManagerOptions = {}) {
    this.input = options.input;
  }

  get current(): Scene | undefined {
    return this.stack[this.stack.length - 1];
  }

  get depth(): number {
    return this.stack.length;
  }

  get isTransitioning(): boolean {
    return this.pending !== undefined;
  }

  push(scene: Scene): void {
    this.cancelQueued();
    this.current?.pause?.();
    this.stack.push(scene);
    this.input?.clear();
    scene.enter();
  }

  pop(): void {
    this.cancelQueued();
    const scene = this.stack.pop();
    if (!scene) return;
    this.input?.clear();
    scene.exit();
    this.current?.resume?.();
  }

  replace(scene: Scene): void {
    this.cancelQueued();
    const outgoing = this.stack.pop();
    this.stack.push(scene);
    this.input?.clear();
    outgoing?.exit();
    scene.enter();
  }

  queue(
    scene: Scene,
    kind: PendingKind = 'replace',
    ticks = QUEUED_TRANSITION_TICKS,
  ): void {
    this.pending = { scene, kind, ticksLeft: Math.max(1, ticks) };
  }

  skipQueued(): void {
    const pending = this.pending;
    if (!pending) return;
    this.pending = undefined;
    this.apply(pending);
  }

  cancelQueued(): void {
    this.pending = undefined;
  }

  update(): void {
    const pending = this.pending;
    if (pending) {
      if (--pending.ticksLeft > 0) return;
      this.pending = undefined;
      this.apply(pending);
      return;
    }
    this.current?.update();
  }

  render(alpha: number): void {
    this.current?.render(alpha);
  }

  private apply(pending: Pending): void {
    if (pending.kind === 'push') this.push(pending.scene);
    else this.replace(pending.scene);
  }
}
