import {
  CHALLENGES,
  CHALLENGE_COUNT,
  CHALLENGE_TYPES,
  PART,
  PARTS,
  PART_CATEGORY_NAMES,
  RANK,
  SCREEN,
} from '../data/constants.ts';
import type { Bike } from '../game/Bike.ts';
import { ReplayBike } from '../game/Ghost.ts';
import type { GhostStore } from '../game/Ghost.ts';
import { RACE_FLAG, type RaceState } from '../game/RaceState.ts';
import {
  POINTS_FIRST_MEDAL,
  POINTS_PER_STEP,
  gradeChallenge,
  type ChallengeResult,
} from '../game/ScoreModel.ts';
import type { SaveService } from '../save/SaveService.ts';

import {
  RESULT_STRING,
  RESULT_TEXT,
  formatString,
  formatStrings,
  formatTimeLong,
  medalTextOf,
  type StringSlots,
} from './results/strings.ts';
import { MS_PER_TICK, describeResult, describeShortfall } from './results/describe.ts';
export * from './results/describe.ts';

export * from './results/strings.ts';
export * from './results/text.ts';

export const RESULT_SCREEN = {
  CHALLENGE: SCREEN.CHALLENGE,
  SUCCESS: SCREEN.RESULT_SUCCESS,
  FAIL: SCREEN.RESULT_FAIL,
  PART_UNLOCKED: SCREEN.RESULT_PART_UNLOCKED,
  NEW_BEST: SCREEN.RESULT_NEW_BEST,
  MISSIONS_UNLOCKED: SCREEN.RESULT_MISSIONS_UNLOCKED,
  BONUS_TRACK: SCREEN.RESULT_BONUS_TRACK,
} as const;

export const NOTICE = {
  BEST: 1,
  PART: 4,
  POINTS: 8,
} as const;

const FREE_RIDE_CHALLENGES = 2;

const RANKED_CHALLENGE_COUNT = CHALLENGE_COUNT - FREE_RIDE_CHALLENGES;

const OVERALL_GOLD_PART = PART.SKATER_PIG;

export const SHOW_DOWN_STEP_LIMIT = 5000;

export interface ProgressionOptions {
  save: SaveService;
  slots: StringSlots;
  ghosts?: GhostStore;
}

export interface FinishOutcome extends ChallengeResult {
  screen: number;
  improvedBest: boolean;
  improvedRank: boolean;
  careerPoints: number;
  unlockedPart: number;
  missionsUnlocked: number;
  ghostSaved: boolean;
}

interface ScoredRun {
  graded: ChallengeResult;
  measure: string;
  value: string;
  shortfall: string;
}

export class Progression {
  private readonly save: SaveService;
  private readonly slots: StringSlots;
  private readonly ghosts: GhostStore | undefined;

  notices = 0;

  constructor(options: ProgressionOptions) {
    this.save = options.save;
    this.slots = options.slots;
    this.ghosts = options.ghosts;
  }

  finish(state: RaceState): FinishOutcome {
    if (state.hasFlag(RACE_FLAG.GHOST_ONLY)) {
      return blankOutcome(RESULT_SCREEN.CHALLENGE);
    }

    const challenge = state.challenge;

    if (state.hasFlag(RACE_FLAG.SHOW_DOWN)) this.runOutRival(state);

    const scored = this.scoreRun(state);
    const { improvedBest, ghostSaved } = this.recordBest(state, scored.graded);

    if (scored.graded.rank === RANK.UNRANKED) {
      return this.failOutcome(scored, improvedBest, ghostSaved);
    }
    return this.successOutcome(challenge, scored, improvedBest, ghostSaved);
  }

  private scoreRun(state: RaceState): ScoredRun {
    const challenge = state.challenge;
    const row = CHALLENGES[challenge]!;
    const format = CHALLENGE_TYPES[row.type]!.targetFormat;
    const bike = state.player.bike as Bike;

    const graded = gradeChallenge(challenge, {
      timeMs: state.player.timeMs,
      trickTotals: bike.trickTotals,
      ...(state.opponent === undefined ? {} : { opponentTimeMs: state.opponent.timeMs }),
    });
    const measure = this.slots.text(graded.measureTextId);
    const value = describeResult(this.slots, state, format);
    const shortfall = describeShortfall(this.slots, state, format, graded);

    return { graded, measure, value, shortfall };
  }

  private recordBest(
    state: RaceState,
    graded: ChallengeResult,
  ): { improvedBest: boolean; ghostSaved: boolean } {
    const challenge = state.challenge;
    const hadResult = this.save.bestResult(challenge) !== 0;
    const improvedBest = this.save.recordResult(challenge, graded.result, true);
    if (improvedBest) {
      this.refreshResultString(challenge);
      if (hadResult) this.notices |= NOTICE.BEST;
    }
    return { improvedBest, ghostSaved: improvedBest && this.saveGhost(state) };
  }

  private failOutcome(
    scored: ScoredRun,
    improvedBest: boolean,
    ghostSaved: boolean,
  ): FinishOutcome {
    formatString(this.slots, RESULT_STRING.MISSED, scored.shortfall);
    formatStrings(this.slots, RESULT_STRING.FAIL_LINE, [scored.measure, scored.value]);
    return {
      ...scored.graded,
      screen: RESULT_SCREEN.FAIL,
      improvedBest,
      improvedRank: false,
      careerPoints: 0,
      unlockedPart: -1,
      missionsUnlocked: 0,
      ghostSaved,
    };
  }

  private successOutcome(
    challenge: number,
    scored: ScoredRun,
    improvedBest: boolean,
    ghostSaved: boolean,
  ): FinishOutcome {
    formatString(
      this.slots,
      RESULT_STRING.RATING,
      this.slots.text(medalTextOf(scored.graded.rank)),
    );
    formatStrings(this.slots, RESULT_STRING.SUCCESS_LINE, [scored.measure, scored.value]);

    const previousRank = this.save.challengeRank(challenge);
    const { improvedRank, careerPoints, unlockedPart, missionsUnlocked } = this.record(
      challenge,
      scored.graded.rank,
      previousRank,
    );

    return {
      ...scored.graded,
      screen: RESULT_SCREEN.SUCCESS,
      improvedBest,
      improvedRank,
      careerPoints,
      unlockedPart,
      missionsUnlocked,
      ghostSaved,
    };
  }

  private record(
    challenge: number,
    rank: number,
    previousRank: number,
  ): {
    improvedRank: boolean;
    careerPoints: number;
    unlockedPart: number;
    missionsUnlocked: number;
  } {
    const owned = ownedParts(this.save);
    if (!this.save.recordRank(challenge, rank)) {
      return {
        improvedRank: false,
        careerPoints: 0,
        unlockedPart: -1,
        missionsUnlocked: 0,
      };
    }

    const unlockedPart = newlyOwnedPart(this.save, owned);
    if (unlockedPart >= 0) this.announcePart(unlockedPart);

    let points = previousRank < RANK.BRONZE ? POINTS_FIRST_MEDAL : 0;
    if (rank >= RANK.SILVER && previousRank < RANK.SILVER) points += POINTS_PER_STEP;
    if (rank >= RANK.GOLD && previousRank < RANK.GOLD) points += POINTS_PER_STEP;

    const missionsUnlocked = this.save.addCareerPoints(points);
    if (missionsUnlocked > 0) {
      formatString(this.slots, RESULT_STRING.MISSIONS, String(missionsUnlocked));
      this.notices |= NOTICE.POINTS;
    }

    return { improvedRank: true, careerPoints: points, unlockedPart, missionsUnlocked };
  }

  private announcePart(part: number): void {
    const category = PART_CATEGORY_NAMES[PARTS[part]!.category]!;
    this.save.unlockPart(part);
    formatStrings(this.slots, RESULT_STRING.PART, [
      this.slots.text(PARTS[part]!.nameString),
      this.slots.text(category),
    ]);
    this.slots.setString(RESULT_STRING.PART_LINE, this.slots.text(RESULT_TEXT.BLANK));
    this.notices |= NOTICE.PART;
    this.save.saveProgress();
  }

  lapResult(challenge: number, timeMs: number): boolean {
    const hadResult = this.save.bestResult(challenge) !== 0;
    if (!this.save.recordResult(challenge, timeMs, false)) return false;
    this.refreshResultString(challenge);
    if (hadResult) this.notices |= NOTICE.BEST;
    return true;
  }

  refreshResultString(challenge: number): string {
    const best = this.save.bestResult(challenge);
    if (best === 0) {
      return formatString(
        this.slots,
        RESULT_STRING.BEST_RESULT,
        this.slots.text(RESULT_TEXT.NO_RESULT),
      );
    }
    return formatString(
      this.slots,
      RESULT_STRING.BEST_RESULT,
      best < 0 ? String(Math.abs(best)) : formatTimeLong(this.slots, best),
    );
  }

  nextNoticeScreen(): number {
    if ((this.notices & NOTICE.PART) !== 0) {
      this.notices &= ~NOTICE.PART;
      return RESULT_SCREEN.PART_UNLOCKED;
    }
    if ((this.notices & NOTICE.BEST) !== 0) {
      this.notices &= ~NOTICE.BEST;
      return RESULT_SCREEN.NEW_BEST;
    }
    if ((this.notices & NOTICE.POINTS) !== 0) {
      this.notices &= ~NOTICE.POINTS;
      return RESULT_SCREEN.MISSIONS_UNLOCKED;
    }
    return this.overallRankReward();
  }

  private overallRankReward(): number {
    const rank = this.overallRank();
    if (rank === RANK.UNRANKED) return RESULT_SCREEN.CHALLENGE;

    if (rank >= RANK.BRONZE && !this.save.freeRideUnlocked(0)) {
      this.save.unlockFreeRide(0);
      this.save.saveProgress();
      return RESULT_SCREEN.BONUS_TRACK;
    }
    if (rank >= RANK.SILVER && !this.save.freeRideUnlocked(1)) {
      this.save.unlockFreeRide(1);
      this.save.saveProgress();
      return RESULT_SCREEN.BONUS_TRACK;
    }
    if (rank === RANK.GOLD && !this.save.partUnlocked(OVERALL_GOLD_PART)) {
      this.announcePart(OVERALL_GOLD_PART);
      this.notices &= ~NOTICE.PART;
      return RESULT_SCREEN.PART_UNLOCKED;
    }
    return RESULT_SCREEN.CHALLENGE;
  }

  overallRank(): number {
    let rank: number = RANK.UNRANKED;
    for (let challenge = 0; challenge < RANKED_CHALLENGE_COUNT; challenge += 1) {
      rank = Math.min(rank, this.save.challengeRank(challenge));
    }
    return rank;
  }

  private runOutRival(state: RaceState): void {
    const rival = state.opponent;
    if (rival === undefined) return;
    for (let step = 0; step < SHOW_DOWN_STEP_LIMIT && !rival.finished; step += 1) {
      rival.bike.step();
      rival.timeMs += MS_PER_TICK;
      state.checkLineCrossing(rival);
    }
  }

  private saveGhost(state: RaceState): boolean {
    if (this.ghosts === undefined) return false;
    const bike = state.player.bike;
    if (!(bike instanceof ReplayBike) || !bike.hasReplay()) return false;
    const ghost = bike.toGhost();
    if (ghost === null) return false;
    return this.ghosts.save(state.challenge, ghost);
  }
}

function ownedParts(save: SaveService): number {
  let mask = 0;
  for (let part = 0; part < PARTS.length; part += 1) {
    if (save.partUnlocked(part)) mask |= 1 << part;
  }
  return mask;
}

function newlyOwnedPart(save: SaveService, owned: number): number {
  for (let part = 0; part < PARTS.length; part += 1) {
    if ((owned & (1 << part)) === 0 && save.partUnlocked(part)) return part;
  }
  return -1;
}

function blankOutcome(screen: number): FinishOutcome {
  return {
    screen,
    rank: RANK.UNRANKED,
    result: 0,
    measureTextId: -1,
    missingTrickTextIds: [],
    improvedBest: false,
    improvedRank: false,
    careerPoints: 0,
    unlockedPart: -1,
    missionsUnlocked: 0,
    ghostSaved: false,
  };
}
