import { STRING } from '../../data/constants.ts';
import { hundredthsOf, minutesOf, secondsOf } from '../../ui/Hud.ts';

export const TEMPLATE_COUNT = STRING.START_YOUR_ENGINE;

export const RESULT_STRING = {
  PART: STRING.A_FAN_DONATION_WAS,
  MISSIONS: STRING.YOU_UNLOCKED_NEW_MISSION,
  RATING: STRING.YOUR_RATING,
  MISSED: STRING.MISSED_OBJECTIVE_S,
  SUCCESS_LINE: STRING.TEXT_10,
  FAIL_LINE: STRING.TEXT_11,
  COMBO_TARGET: STRING.TEXT_12,
  BEST_RESULT: STRING.BEST_RESULT_SO_FAR,
  GHOST_TIME: STRING.GHOST_TIME,
  TIME_SHORT: STRING.TEXT_13,
  TIME_LONG: STRING.TEXT_21,
  REQUIREMENTS: STRING.TEXT_200,
  PART_LINE: STRING.TEXT_202,
} as const;

export const RESULT_TEXT = {
  NONE: STRING.NONE,
  MEDAL: [-1, STRING.AMATEUR, STRING.PRO, STRING.TOP_DOG] as readonly number[],
  NO_RESULT: STRING.N_A,
  GROUNDED: STRING.GROUNDED,
  AIRBORNE: STRING.AIRBORNE,
  BLANK: STRING.TEXT_203,
} as const;

const ASCII_ZERO = 48;

const PAD_BELOW = 10;

export interface StringSlots {
  text(id: number): string;
  template(id: number): string;
  setString(id: number, value: string): void;
}

export class SlotStrings implements StringSlots {
  private readonly strings: string[];
  private readonly templates: readonly string[];

  constructor(strings: readonly string[]) {
    this.strings = [...strings];
    this.templates = strings.slice(0, TEMPLATE_COUNT);
  }

  text(id: number): string {
    if (id === -1) return '';
    const slot = id < 0 ? id & 0xff : id;
    return this.strings[slot] ?? '';
  }

  template(id: number): string {
    return this.templates[id] ?? '';
  }

  setString(id: number, value: string): void {
    this.strings[id] = value;
  }
}

export function substitute(template: string, args: readonly (string | null)[]): string {
  let buffer = template;
  let used = 0;
  for (let at = 0; at < buffer.length - 1 && used < args.length; at += 1) {
    if (buffer[at] !== '%') continue;
    const digit = buffer.charCodeAt(at + 1) - ASCII_ZERO;
    if (digit < 0 || digit > 9) continue;
    const argument = args[digit - 1] ?? '';
    buffer = buffer.slice(0, at) + argument + buffer.slice(at + 2);
    used += 1;
  }
  return buffer;
}

export function formatStrings(
  slots: StringSlots,
  id: number,
  args: readonly (string | null)[],
): string {
  const value = substitute(slots.template(id), args);
  slots.setString(id, value);
  return value;
}

export function formatString(
  slots: StringSlots,
  id: number,
  argument: string | null,
): string {
  return formatStrings(slots, id, [argument]);
}

export function formatTimeLong(slots: StringSlots, ms: number): string {
  return formatStrings(slots, RESULT_STRING.TIME_LONG, [
    pad(minutesOf(ms)),
    pad(secondsOf(ms)),
    pad(hundredthsOf(ms)),
  ]);
}

export function formatTimeShort(slots: StringSlots, ms: number): string {
  return formatStrings(slots, RESULT_STRING.TIME_SHORT, [
    pad(secondsOf(ms)),
    pad(hundredthsOf(ms)),
  ]);
}

function pad(value: number): string {
  return value < PAD_BELOW ? `0${value}` : String(value);
}

export function medalTextOf(rank: number): number {
  return RESULT_TEXT.MEDAL[rank] ?? -1;
}
