import { ICON_STRIPS, MENU_ICONS, SOFT_KEYS, SPRITE_STRIPS } from '../data/constants.ts';
import type { Menu, MenuItem } from '../data/constants.ts';
import { ACTION } from '../core/Input.ts';
import { dividePx, px, shiftPx } from '../render/units.ts';

import { ellipsise, textWidth, type Measure } from './TextLayout.ts';

export const SCREEN_KIND = {
  LIST: -1,
  TEXT: 1,
  NONE: 2,
  CHALLENGE_LIST: 3,
  PAUSE: 4,
  SCORE_PAIRS: 5,
} as const;

export const MENU_COLOR = {
  BACKGROUND: 0xa51710,
  DIVIDER: 0x8c140e,
  RULE: 0x2c2929,
  LABEL: 0xfcb037,
  SELECTED: 0xffffff,
  SHADOW: 0x0a0a0a,
} as const;

export const ARROW_STRIP = 15;
export const ARROW_FRAME = { UP: 0, DOWN: 1 } as const;

export const SOFT_KEY_INSET = px(3);

export const MARQUEE_STEP = px(1536);
export const MARQUEE_DELAY = 20;

export const SCROLL_SHIFT = 10;

export const SCROLL_SNAP = px(3);

export const LAYOUT = {
  titleTop: px(2),
  titleGap: px(1),
  dividerGap: px(3),
  softKeyGap: px(3),
  tickerGap: px(3),
  screenInset: px(8),
  listInset: px(4),
  listGap: px(2),
  rowGap: px(2),
  iconGap: px(4),
  iconColumn: px(8),
  marqueeTail: px(8),
  marqueeHead: px(8),
  marqueeInset: px(4),
  tickerInset: px(4),
  scrollRound: px(1 << (SCROLL_SHIFT - 1)),
} as const;

export interface MenuMetrics {
  screenWidth: number;
  screenHeight: number;
  titleFontHeight: number;
  menuFontHeight: number;
  smallFontHeight: number;
  softKeyIconHeight: number;
  measureTitle: Measure;
  measureMenu: Measure;
  measureSmall: Measure;
}

export interface MenuBands {
  dividerHeight: number;
  titleBottom: number;
  headerBottom: number;
  footerTop: number;
  listBottom: number;
  tickerTop: number;
  softKeyTop: number;
  contentWidth: number;
}

export function measureLayout(metrics: MenuMetrics): MenuBands {
  const dividerHeight = stripFrameHeight(ARROW_STRIP) + LAYOUT.dividerGap;
  const titleBottom = LAYOUT.titleTop + metrics.titleFontHeight + LAYOUT.titleGap;
  const headerBottom = titleBottom + dividerHeight;
  const softKeyTop = metrics.screenHeight - metrics.softKeyIconHeight - LAYOUT.softKeyGap;
  const tickerTop = softKeyTop - metrics.smallFontHeight - LAYOUT.tickerGap;
  const footerTop = tickerTop - dividerHeight;
  return {
    dividerHeight,
    titleBottom,
    headerBottom,
    footerTop,
    listBottom: footerTop,
    tickerTop,
    softKeyTop,
    contentWidth: metrics.screenWidth - LAYOUT.screenInset,
  };
}

export function iconStripOf(icon: number): number {
  return ICON_STRIPS[MENU_ICONS[icon]!.strip]!;
}

export function stripFrameHeight(strip: number): number {
  const row = SPRITE_STRIPS[strip]!;
  return px(Math.trunc(row.height / row.frames));
}

export function stripWidth(strip: number): number {
  return px(SPRITE_STRIPS[strip]!.width);
}

export function itemHeight(item: MenuItem, menuFontHeight: number): number {
  let height: number;
  if (item.icon >= 0) {
    height = stripFrameHeight(iconStripOf(item.icon));
    if (item.labelString !== -1) height = Math.max(menuFontHeight, height);
  } else {
    height = menuFontHeight;
  }
  return height + LAYOUT.rowGap;
}

export function listHeightOf(items: readonly MenuItem[], menuFontHeight: number): number {
  return itemHeight(items[0]!, menuFontHeight) * items.length;
}

export function widestLabel(
  items: readonly MenuItem[],
  label: (id: number) => string,
  measure: Measure,
): number {
  let widest = 0;
  for (const item of items) {
    if (item.labelString === -1) continue;
    const width = textWidth(measure, label(item.labelString));
    if (width > widest) widest = width;
  }
  return widest;
}

export interface Marquee {
  active: boolean;
  position: number;
  max: number;
  min: number;
  delay: number;
  direction: number;
}

export function newMarquee(): Marquee {
  return { active: false, position: 0, max: 0, min: 0, delay: 0, direction: 1 };
}

export function startMarquee(
  marquee: Marquee,
  width: number,
  x: number,
  bands: MenuBands,
  screenWidth: number,
): void {
  marquee.active = false;
  if (width <= bands.contentWidth) return;
  marquee.active = true;
  marquee.max = (width + LAYOUT.marqueeTail + LAYOUT.marqueeHead - x) << SCROLL_SHIFT;
  marquee.min = (screenWidth - LAYOUT.marqueeInset - x) << SCROLL_SHIFT;
  marquee.delay = MARQUEE_DELAY;
  marquee.position = marquee.min;
  marquee.direction = 1;
}

export function stepMarquee(marquee: Marquee): number {
  const offset = shiftPx(marquee.position, SCROLL_SHIFT);
  marquee.delay -= 1;
  if (marquee.delay < 0) {
    marquee.position += MARQUEE_STEP * marquee.direction;
    if (marquee.position >= marquee.max || marquee.position < marquee.min) {
      marquee.direction = -marquee.direction;
    }
  }
  return offset;
}

export interface MenuRow {
  index: number;
  item: MenuItem;
  text: string;
  x: number;
  y: number;
  scrolling: boolean;
  color: number;
  centred: boolean;
  icon: number;
  iconX: number;
  iconY: number;
}

export interface SoftKeyBar {
  left: number;
  right: number;
}

export interface MenuInput {
  consume(mask: number): boolean;
  takeSoftKeyEvents(): number;
}

export type MenuEvent =
  | { kind: 'move'; index: number }
  | { kind: 'activate'; index: number; item: MenuItem }
  | { kind: 'softKey'; action: number; side: 'left' | 'right' };

export interface MenuListOptions {
  menu: Menu;
  items: readonly MenuItem[];
  metrics: MenuMetrics;
  label(id: number): string;
  swapSoftKeys?: boolean;
  softKeyGate?(index: number): { left: boolean; right: boolean };
}

export class MenuList {
  readonly menu: Menu;
  readonly items: readonly MenuItem[];
  readonly metrics: MenuMetrics;
  readonly bands: MenuBands;
  readonly kind: number;

  swapSoftKeys: boolean;

  selected = 0;
  scrollTarget = 0;
  scrollFixed = 0;
  maxScroll = 0;
  listTop = 0;
  listHeight = 0;
  listViewportHeight = 0;
  listContentHeight = 0;
  scrollUpArrow = false;
  scrollDownArrow = false;

  leftSoftKeyEnabled = true;
  rightSoftKeyEnabled = true;

  tickerText: string | null = null;
  tickerX = 0;
  tickerWidth = 0;
  tickerWrap = 0;
  tickerDelay = 0;

  readonly titleMarquee = newMarquee();
  readonly itemMarquee = newMarquee();

  readonly lines: string[] = [];
  readonly itemWidths: number[] = [];

  readonly label: (id: number) => string;
  private readonly softKeyGate?: (index: number) => { left: boolean; right: boolean };

  constructor(options: MenuListOptions) {
    this.menu = options.menu;
    this.items = options.items;
    this.metrics = options.metrics;
    this.kind = options.menu.kind;
    this.swapSoftKeys = options.swapSoftKeys ?? false;
    this.label = options.label;
    this.softKeyGate = options.softKeyGate;
    this.bands = measureLayout(options.metrics);

    this.measureItems();
    this.select(0, 1, true);
    this.layout(false, false);
    this.layoutTitleMarquee();
  }

  private measureItems(): void {
    const { measureMenu } = this.metrics;
    const first = this.items[0];
    const column =
      first && first.icon >= 0
        ? stripWidth(iconStripOf(first.icon)) + LAYOUT.iconGap
        : LAYOUT.iconGap;
    this.lines.length = 0;
    this.itemWidths.length = 0;
    for (const item of this.items) {
      const text = this.label(item.labelString);
      const line = ellipsise(measureMenu, text, this.bands.contentWidth - column);
      this.lines.push(line);
      this.itemWidths.push(column + textWidth(measureMenu, text));
    }
  }

  select(index: number, direction: number, reset: boolean): void {
    const items = this.items;
    const count = items.length;
    if (count === 0) return;
    const previous = reset ? -1 : this.selected;

    const wrapped =
      this.kind !== SCREEN_KIND.TEXT &&
      this.kind !== SCREEN_KIND.SCORE_PAIRS &&
      (index < 0 || index >= count);
    if (wrapped) {
      if (index < 0) index = count - 1;
      if (index >= count) index = 0;
    } else {
      if (index < 0) index = 0;
      if (index >= count) index = count - 1;
    }

    if (this.kind !== SCREEN_KIND.TEXT) {
      index = this.skipDisabled(index, direction, previous, reset);
    }

    this.selected = index;
    if (wrapped || reset) this.layout(false, true);

    const gate = this.softKeyGate?.(index);
    this.leftSoftKeyEnabled = gate?.left ?? true;
    this.rightSoftKeyEnabled = gate?.right ?? true;

    if (previous !== this.selected && (this.kind !== SCREEN_KIND.TEXT || reset)) {
      const hint = items[this.selected]!.tickerString;
      this.setTicker(hint === -1 ? null : this.label(hint));
    }
    this.layoutItemMarquee();
  }

  private skipDisabled(
    index: number,
    direction: number,
    previous: number,
    reset: boolean,
  ): number {
    const items = this.items;
    const count = items.length;
    while (items[index]!.enabled === 0) {
      if (direction === 0) direction = 1;
      index += direction;
      if (index < 0) {
        if (!reset) return previous;
        index = 0;
        direction = -direction;
      }
      if (index < count) continue;
      if (!reset) return previous;
      index = 0;
      direction = -direction;
    }
    return index;
  }

  private scrollToSelection(rowHeight: number): void {
    let target = -this.selected * rowHeight;
    if (target < -this.maxScroll) target = -this.maxScroll;
    if (target > 0) target = 0;
    this.scrollTarget = target | 0;
  }

  layout(animate: boolean, toSelection: boolean): void {
    this.scrollUpArrow = false;
    this.scrollDownArrow = false;
    const items = this.items;
    if (items.length === 0) return;
    const { menuFontHeight } = this.metrics;
    const bands = this.bands;

    this.listViewportHeight = bands.listBottom - bands.headerBottom - LAYOUT.listInset;
    this.listContentHeight = listHeightOf(items, menuFontHeight);
    this.listTop = bands.headerBottom + LAYOUT.listGap;
    this.listHeight = bands.listBottom - LAYOUT.listGap - this.listTop;

    if (this.listViewportHeight >= this.listContentHeight) {
      this.scrollTarget = shiftPx(this.listViewportHeight - this.listContentHeight, 1);
      this.scrollFixed = this.scrollTarget << SCROLL_SHIFT;
      this.maxScroll = this.listContentHeight - this.listHeight;
      return;
    }

    const rowHeight = itemHeight(items[0]!, menuFontHeight);
    const visible = this.fitWholeRows(rowHeight);

    if (this.kind === SCREEN_KIND.TEXT || this.kind === SCREEN_KIND.SCORE_PAIRS) {
      if (this.selected > items.length - visible) {
        this.selected = items.length - visible;
      }
      this.scrollToSelection(rowHeight);
    } else {
      this.clampScroll(rowHeight, visible, toSelection);
    }

    this.applyScroll(animate);
  }

  private fitWholeRows(rowHeight: number): number {
    const before = this.listHeight;
    const visible = Math.trunc(this.listHeight / rowHeight);
    this.listHeight = visible * rowHeight;
    this.listTop += dividePx(before - this.listHeight, 2);
    this.maxScroll = this.listContentHeight - this.listHeight;
    return visible;
  }

  private clampScroll(rowHeight: number, visible: number, toSelection: boolean): void {
    if (toSelection) this.scrollToSelection(rowHeight);
    let scroll = -this.scrollTarget;
    const first = Math.trunc(scroll / rowHeight);
    const last = first + visible;
    if (visible > 2) {
      if (this.selected <= first) scroll -= rowHeight;
      if (this.selected >= last - 1) scroll += rowHeight;
    } else {
      if (this.selected < first) scroll -= rowHeight;
      if (this.selected > last - 1) scroll += rowHeight;
    }
    if (scroll > this.maxScroll) scroll = this.maxScroll;
    if (scroll < 0) scroll = 0;
    this.scrollTarget = -scroll | 0;
  }

  private applyScroll(animate: boolean): void {
    if (animate) {
      const delta = (this.scrollTarget << SCROLL_SHIFT) - this.scrollFixed;
      this.scrollFixed +=
        delta < -SCROLL_SNAP || delta > SCROLL_SNAP ? dividePx(delta, 4) : delta;
    } else {
      this.scrollFixed = this.scrollTarget << SCROLL_SHIFT;
    }
    this.scrollUpArrow = this.scrollTarget < 0;
    this.scrollDownArrow = this.scrollTarget > -this.maxScroll;
  }

  setTicker(text: string | null): void {
    if (text !== this.tickerText) {
      this.tickerX = 0;
      this.tickerDelay = Number.MAX_SAFE_INTEGER;
    }
    if (text !== null) {
      this.tickerWidth = textWidth(this.metrics.measureSmall, text);
      this.tickerWrap = (this.metrics.screenWidth + this.tickerWidth) << SCROLL_SHIFT;
      if (this.tickerWidth > this.bands.contentWidth) this.tickerDelay = MARQUEE_DELAY;
      this.tickerX = (this.metrics.screenWidth - LAYOUT.tickerInset) << SCROLL_SHIFT;
    }
    this.tickerText = text;
  }

  stepTicker(): number {
    const x = this.metrics.screenWidth - shiftPx(this.tickerX, SCROLL_SHIFT);
    this.tickerDelay -= 1;
    if (this.tickerDelay < 0) {
      this.tickerX += MARQUEE_STEP;
      if (this.tickerX >= this.tickerWrap) this.tickerX -= this.tickerWrap;
    }
    return x;
  }

  layoutTitleMarquee(): void {
    if (this.menu.titleString === -1) {
      this.titleMarquee.active = false;
      return;
    }
    const x =
      this.menu.titleIcon >= 0
        ? LAYOUT.titleTop + stripWidth(iconStripOf(this.menu.titleIcon)) + LAYOUT.titleGap
        : LAYOUT.titleTop;
    const width = textWidth(this.metrics.measureTitle, this.label(this.menu.titleString));
    startMarquee(this.titleMarquee, width, x, this.bands, this.metrics.screenWidth);
  }

  layoutItemMarquee(): void {
    if (this.kind === SCREEN_KIND.TEXT) {
      this.itemMarquee.active = false;
      return;
    }
    const first = this.items[0];
    const x =
      first && first.icon >= 0
        ? LAYOUT.iconGap + stripWidth(iconStripOf(first.icon))
        : LAYOUT.iconGap;
    startMarquee(
      this.itemMarquee,
      this.itemWidths[this.selected] ?? 0,
      x,
      this.bands,
      this.metrics.screenWidth,
    );
  }

  update(input: MenuInput): MenuEvent | null {
    const soft = this.softKeyEvent(input);
    if (soft) return soft;
    if (this.kind === SCREEN_KIND.NONE) return null;

    if (input.consume(ACTION.ACCEL)) {
      this.select(this.selected - 1, -1, false);
      return { kind: 'move', index: this.selected };
    }
    if (input.consume(ACTION.BRAKE)) {
      this.select(this.selected + 1, 1, false);
      return { kind: 'move', index: this.selected };
    }
    if (input.consume(ACTION.FIRE)) return this.activate();
    return null;
  }

  activate(): MenuEvent | null {
    if (this.selected < 0) return null;
    const index = this.kind === SCREEN_KIND.TEXT ? 0 : this.selected;
    const item = this.items[index];
    if (!item) return null;
    return { kind: 'activate', index, item };
  }

  private softKeyEvent(input: MenuInput): MenuEvent | null {
    const events = input.takeSoftKeyEvents();
    if (events === 0) return null;
    let side: 'left' | 'right' | null = null;
    if (events === ACTION.SOFT_LEFT && this.leftSoftKeyEnabled) side = 'left';
    if (events === ACTION.SOFT_RIGHT && this.rightSoftKeyEnabled) side = 'right';
    if (side === null) return null;
    const key = side === 'left' ? this.menu.leftSoftKey : this.menu.rightSoftKey;
    if (key < 0) return null;
    return { kind: 'softKey', action: SOFT_KEYS[key]!.action, side };
  }

  softKeyBar(): SoftKeyBar {
    const left = this.leftSoftKeyEnabled ? this.menu.leftSoftKey : -1;
    const right = this.rightSoftKeyEnabled ? this.menu.rightSoftKey : -1;
    return this.swapSoftKeys ? { left: right, right: left } : { left, right };
  }

  step(): void {
    this.layout(true, false);
  }

  get firstRowY(): number {
    return shiftPx(this.scrollFixed + LAYOUT.scrollRound, SCROLL_SHIFT) + this.listTop;
  }

  rows(): MenuRow[] {
    const items = this.items;
    if (items.length === 0) return [];
    return items[0]!.icon >= 0 ? this.menuRows() : this.textRows();
  }

  private menuRows(): MenuRow[] {
    const { menuFontHeight, screenWidth, measureMenu } = this.metrics;
    const items = this.items;
    const rowHeight = itemHeight(items[0]!, menuFontHeight);
    const strip = iconStripOf(items[0]!.icon);
    const iconWidth = stripWidth(strip);
    const iconHeight = stripFrameHeight(strip);
    const iconOffsetY = iconHeight < rowHeight ? shiftPx(rowHeight - iconHeight, 1) : 0;
    const labelOffsetY = shiftPx(rowHeight - menuFontHeight, 1);

    const widest = widestLabel(items, (id) => this.label(id), measureMenu);
    const minX = iconWidth + LAYOUT.iconColumn;
    let columnX = shiftPx(screenWidth - (widest - iconWidth - LAYOUT.iconGap), 1);
    if (columnX < minX) columnX = minX;

    const rows: MenuRow[] = [];
    let y = this.firstRowY;
    for (let index = 0; index < items.length; index += 1) {
      const item = items[index]!;
      const selected = index === this.selected;
      const scrolling = selected && this.itemMarquee.active;
      rows.push({
        index,
        item,
        text: scrolling ? this.label(item.labelString) : this.lines[index]!,
        x: scrolling ? screenWidth - stepMarquee(this.itemMarquee) : columnX,
        y: y + labelOffsetY,
        scrolling,
        color: this.rowColor(index),
        centred: false,
        icon: item.icon,
        iconX: columnX - LAYOUT.iconGap,
        iconY: y + iconOffsetY,
      });
      y += rowHeight;
    }
    return rows;
  }

  private textRows(): MenuRow[] {
    const { menuFontHeight } = this.metrics;
    const rows: MenuRow[] = [];
    let y = this.firstRowY;
    for (let index = 0; index < this.items.length; index += 1) {
      const item = this.items[index]!;
      if (item.labelString === -1) {
        y += menuFontHeight + LAYOUT.rowGap;
        continue;
      }
      const text =
        this.kind === SCREEN_KIND.TEXT
          ? this.label(item.labelString)
          : this.lines[index]!;
      const scrolling =
        this.kind !== SCREEN_KIND.TEXT &&
        index === this.selected &&
        this.itemMarquee.active;
      rows.push({
        index,
        item,
        text: scrolling ? this.label(item.labelString) : text,
        x: this.textRowX(text, scrolling),
        y,
        scrolling,
        color: this.rowColor(index),
        centred: this.kind === SCREEN_KIND.TEXT,
        icon: -1,
        iconX: 0,
        iconY: 0,
      });
      y += menuFontHeight + LAYOUT.rowGap;
    }
    return rows;
  }

  private textRowX(text: string, scrolling: boolean): number {
    const { screenWidth, measureMenu } = this.metrics;
    const centreX = shiftPx(screenWidth, 1);
    if (this.kind === SCREEN_KIND.TEXT) return centreX;
    if (scrolling) return screenWidth - stepMarquee(this.itemMarquee);
    return centreX - shiftPx(textWidth(measureMenu, text), 1);
  }

  private rowColor(index: number): number {
    if (this.items[index]!.enabled === 0) return MENU_COLOR.RULE;
    const highlightable =
      this.kind !== SCREEN_KIND.TEXT && this.kind !== SCREEN_KIND.SCORE_PAIRS;
    return index === this.selected && highlightable
      ? MENU_COLOR.SELECTED
      : MENU_COLOR.LABEL;
  }
}
