import { RACE_MODE } from '../../game/RaceState.ts';

import type { AppShell } from '../AppShell.ts';
import type { RaceShell } from '../RaceScene.ts';
import { openGoals } from './Briefing.ts';
import { PENDING_SCREEN_DELAY } from './ScreenStack.ts';
import { BUSY_STRING, SCREEN, SHELL_MODE } from './screens.ts';

export function makeRaceShell(shell: AppShell): RaceShell {
  return {
    finished: (state) => {
      shell.queueScreen(shell.progression.finish(state).screen);
    },
    paused: () => {
      shell.pauseToMenu();
    },
    goals: () => {
      openGoals(shell);
    },
    lapResult: (challenge, timeMs) => {
      shell.progression.lapResult(challenge, timeMs);
    },
  };
}

export function setMode(shell: AppShell, mode: number): void {
  shell.input.clear();
  if (mode === SHELL_MODE.RACE) {
    shell.paused = false;
    shell.audio.playMusic(true);
    if (shell.list) {
      shell.list.leftSoftKeyEnabled = true;
      shell.list.rightSoftKeyEnabled = true;
    }
    shell.race?.setActive(true);
  } else if (mode === SHELL_MODE.MENU && shell.mode === SHELL_MODE.RACE) {
    shell.audio.stopSound();
    shell.race?.setActive(false);
  }
  if (mode !== SHELL_MODE.MENU) shell.view?.setList(null);
  shell.mode = mode;
}

export function queueScreen(shell: AppShell, screen: number): void {
  shell.pendingScreen = screen;
  shell.pendingScreenDelay = PENDING_SCREEN_DELAY;
}

export function pauseToMenu(shell: AppShell): void {
  if (shell.mode !== SHELL_MODE.RACE) return;
  if (shell.pendingScreenDelay > 0) {
    shell.pendingScreenDelay = -1;
    shell.openScreen(shell.pendingScreen, false);
    return;
  }
  shell.openScreen(SCREEN.PAUSE, false);
}

export function loadChallenge(shell: AppShell, challenge: number, mode: number): void {
  shell.showBusy(BUSY_STRING.LOADING);
  if (shell.race && (challenge !== shell.raceChallenge || mode !== shell.raceMode)) {
    shell.race.exit();
    shell.race = null;
  }
  if (!shell.race) {
    shell.race = shell.createRace?.({ challenge, mode, shell: shell.raceShell }) ?? null;
    shell.race?.enter();
    shell.raceChallenge = challenge;
    shell.raceMode = mode;
  }
  shell.race?.restart();
  if (mode === RACE_MODE.PLAY) shell.preparedChallenge = challenge;
  shell.hideBusy();
}
