import { Application, Container, TextureSource } from 'pixi.js';
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../core/config.ts';
import type { RenderTarget } from '../core/Game.ts';
import { Viewport } from './Viewport.ts';

const BACKGROUND_COLOUR = 0x000000;

export const LAYER_ORDER = [
  'bg',
  'parallax',
  'terrain',
  'entities',
  'fx',
  'hud',
  'overlay',
] as const;

export type LayerName = (typeof LAYER_ORDER)[number];

export type Layers = Readonly<Record<LayerName, Container>>;

export const WORLD_LAYERS: readonly LayerName[] = ['terrain', 'entities', 'fx'];

export function createLayers(root: Container): Layers {
  const layers = {} as Record<LayerName, Container>;
  for (const name of LAYER_ORDER) {
    const layer = new Container({ label: name });
    layers[name] = layer;
    root.addChild(layer);
  }
  return layers;
}

export class Renderer implements RenderTarget {
  readonly layers: Layers;

  readonly viewport: Viewport;

  private readonly app: Application;
  private readonly detachViewport: () => void;

  private constructor(app: Application) {
    this.app = app;
    this.layers = createLayers(app.stage);
    this.viewport = new Viewport({
      canvas: app.canvas,
      onChange: (metrics) => {
        const dpr = typeof window === 'undefined' ? 1 : window.devicePixelRatio || 1;
        app.renderer.resize(LOGICAL_WIDTH, LOGICAL_HEIGHT, metrics.scale * dpr);
      },
    });
    this.detachViewport = this.viewport.attach();
  }

  static async create(mount: HTMLElement): Promise<Renderer> {
    TextureSource.defaultOptions.scaleMode = 'linear';

    const app = new Application();
    await app.init({
      width: LOGICAL_WIDTH,
      height: LOGICAL_HEIGHT,
      background: BACKGROUND_COLOUR,
      antialias: false,
      roundPixels: false,
      resolution: 1,
      autoDensity: false,
      autoStart: false,
      sharedTicker: false,
    });

    mount.appendChild(app.canvas);

    return new Renderer(app);
  }

  get stage(): Container {
    return this.app.stage;
  }

  layer(name: LayerName): Container {
    return this.layers[name];
  }

  render(): void {
    this.app.render();
  }

  destroy(): void {
    this.detachViewport();
    this.app.destroy({ removeView: true }, { children: true });
  }
}
