import { FrameStats } from './FrameStats.ts';
import { Loop } from './Loop.ts';
import { JavaRandom } from './Random.ts';
import { SceneManager } from './SceneManager.ts';
import type { InputSink } from './SceneManager.ts';
import type { Scene } from './Scene.ts';

export interface RenderTarget {
  render(): void;
}

export interface GameOptions {
  target?: RenderTarget;
  seed?: number | bigint;
  input?: InputSink;
}

export class Game {
  readonly scenes: SceneManager;

  readonly random: JavaRandom;

  readonly stats = new FrameStats();

  private readonly loop: Loop;
  private readonly target: RenderTarget | undefined;

  constructor(options: GameOptions = {}) {
    this.target = options.target;
    this.scenes = new SceneManager({ input: options.input });
    this.random =
      options.seed === undefined ? new JavaRandom() : new JavaRandom(options.seed);
    this.loop = new Loop(
      {
        update: () => this.scenes.update(),
        render: (alpha) => {
          this.scenes.render(alpha);
          this.target?.render();
        },
      },
      { stats: this.stats },
    );
  }

  get tick(): number {
    return this.loop.tick;
  }

  start(scene: Scene): void {
    this.scenes.push(scene);
    this.loop.start();
  }

  stop(): void {
    this.loop.stop();
  }

  step(count = 1): void {
    this.loop.step(count);
  }

  enter(scene: Scene): void {
    this.scenes.push(scene);
  }
}
