import { refreshOptionLabels, refreshSoundLabel } from '../../i18n/Strings.ts';
import type { MenuItem } from '../../data/constants.ts';
import { MenuList, SCREEN_KIND } from '../../ui/MenuList.ts';

import type { AppShell } from '../AppShell.ts';
import { BOARD_HOME_ROW, buildBoard } from './Board.ts';
import { openPartsMenu, partsSoftKeyGate } from './Garage.ts';
import {
  BUSY_TEXT_SCREENS,
  PROMPT_STRING,
  SCREEN,
  SHELL_MODE,
  THEME_PROMPT,
  THEME_SCREEN,
} from './screens.ts';
import { wrapScreenText } from './TextWrap.ts';

export const PENDING_SCREEN_DELAY = 35;

export function shellBack(shell: AppShell): void {
  shell.openScreen(shell.screenBack[shell.screen] ?? SCREEN.TITLE, false);
}

function rememberSelection(
  shell: AppShell,
  from: number,
  target: number,
  withBack: boolean,
): void {
  if (withBack) {
    if (shell.screenKind(from) !== SCREEN_KIND.TEXT) {
      shell.screenSelection[from] = shell.selectedItem;
    }
    if (target !== from) shell.screenBack[target] = from;
  } else {
    let remembered = from === target ? shell.selectedItem : 0;
    if (shell.screenKind(from) === SCREEN_KIND.PAUSE) remembered = 0;
    shell.screenSelection[from] = remembered;
  }
  if (from === SCREEN.EXIT) shell.screenSelection[SCREEN.TITLE] = 0;
}

function screenItems(shell: AppShell, target: number, kind: number): readonly MenuItem[] {
  if (kind !== SCREEN_KIND.TEXT) return shell.model.items[target]!;
  return wrapScreenText(shell, target, BUSY_TEXT_SCREENS.includes(target));
}

function softKeyGate(
  shell: AppShell,
  screen: number,
  items: readonly MenuItem[],
  index: number,
): { left: boolean; right: boolean } {
  if (screen === SCREEN.PARTS) return partsSoftKeyGate(shell, items, index);
  if (
    screen === SCREEN.LANGUAGE &&
    shell.screenBack[SCREEN.LANGUAGE] !== SCREEN.OPTIONS
  ) {
    return { left: true, right: false };
  }
  return { left: true, right: true };
}

function buildList(
  shell: AppShell,
  target: number,
  kind: number,
  fresh: boolean,
): MenuList {
  const items = screenItems(shell, target, kind);
  const list = new MenuList({
    menu: shell.model.menus[target]!,
    items,
    metrics: shell.metrics,
    label: (id) => shell.text(id),
    swapSoftKeys: shell.swapSoftKeys,
    softKeyGate: (index) => softKeyGate(shell, target, items, index),
  });
  list.select(shell.screenSelection[target] ?? 0, 1, fresh);
  list.layout(false, false);
  list.layoutTitleMarquee();
  return list;
}

export function openScreen(shell: AppShell, target: number, withBack: boolean): void {
  if (shell.model.menus[target] === undefined) return;
  shell.input.clear();

  const from = shell.screen;
  rememberSelection(shell, from, target, withBack);

  const fresh = target !== from || shell.mode !== SHELL_MODE.MENU;
  prepareScreen(shell, from, target);
  if (shell.mode !== SHELL_MODE.MENU) shell.setMode(SHELL_MODE.MENU);

  shell.wrappedLines = null;
  const kind = shell.screenKind(target);
  shell.list = buildList(shell, target, kind, fresh);
  shell.view?.setList(shell.list);
  shell.screen = target;

  if (target === SCREEN.CAREER && shell.save.bikeChoice === -1) {
    shell.screenBack[SCREEN.BIKE] = SCREEN.TITLE;
    openScreen(shell, SCREEN.BIKE, false);
    return;
  }

  if (kind === SCREEN_KIND.CHALLENGE_LIST || target === SCREEN.CHALLENGE) {
    applyTheme(shell, target);
  }
}

export function screenTheme(shell: AppShell, screen: number): number {
  const themed = THEME_SCREEN.indexOf(screen);
  if (themed >= 0) return themed;
  if (screen !== SCREEN.CHALLENGE) return -1;
  return shell.screenBack[SCREEN.CHALLENGE] === SCREEN.FREE_RIDE ? shell.environment : -1;
}

function applyTheme(shell: AppShell, target: number): void {
  const theme = screenTheme(shell, target);
  if (theme < 0) return;
  const last = shell.save.lastTheme;
  if (last >= 0 && last !== theme) {
    prompt(
      shell,
      shell.table.text(THEME_PROMPT.QUESTION),
      shell.table.text(THEME_PROMPT.ANSWER),
      THEME_PROMPT.LEFT_SOFT_KEY,
      -1,
      target,
    );
  }
  shell.save.lastTheme = theme;
  shell.save.saveProgress();
}

function prepareScreen(shell: AppShell, from: number, to: number): void {
  const model = shell.model;
  const preselect = shell.language.menuSelection();
  if (to === SCREEN.LANGUAGE && preselect !== null) {
    shell.screenSelection[SCREEN.LANGUAGE] = preselect;
  }
  if (to === SCREEN.OPTIONS) refreshOptionLabels(shell.table, shell.save.progress);

  const kind = shell.screenKind(to);
  if (shell.mode === SHELL_MODE.RACE && kind === SCREEN_KIND.PAUSE && !shell.paused) {
    shell.audio.stopSound();
  }
  if (from === SCREEN.OPTIONS && to === shell.screenBack[SCREEN.OPTIONS]) {
    shell.save.saveProgress();
  }
  if (to === SCREEN.JUKEBOX) refreshSoundLabel(shell.table, shell.save.progress);
  if (to === SCREEN.SCORES) {
    buildBoard(shell);
    shell.screenSelection[SCREEN.SCORES] = BOARD_HOME_ROW;
  }
  if (kind === SCREEN_KIND.CHALLENGE_LIST) model.refreshRankIcons(shell, to);
  if (to === SCREEN.CAREER) model.rebuildCareerMenu(shell);
  if (from === SCREEN.PARTS) model.items[SCREEN.PARTS] = model.partsItems;

  model.applyConditions(shell, to);

  if (to === SCREEN.PARTS) openPartsMenu(shell);
}

export function refreshScreen(shell: AppShell): void {
  if (shell.mode !== SHELL_MODE.MENU) return;
  const previous = shell.selectedItem;
  openScreen(shell, shell.screen, false);
  const kind = shell.screenKind(shell.screen);
  let keep = true;
  if (kind !== SCREEN_KIND.TEXT && kind !== SCREEN_KIND.SCORE_PAIRS) {
    const rows = shell.model.items[shell.screen]!;
    keep = previous < rows.length && rows[previous]!.enabled !== 0;
  }
  if (keep) shell.list?.select(previous, 0, false);
}

export function setPromptStrings(
  shell: AppShell,
  question: string,
  answer: string,
  left: number,
  right: number,
): void {
  shell.table.setString(PROMPT_STRING.QUESTION, question);
  shell.table.setString(PROMPT_STRING.ANSWER, answer);
  const menu = shell.model.menus[SCREEN.PROMPT];
  if (menu) {
    menu.leftSoftKey = left;
    menu.rightSoftKey = right;
  }
}

export function prompt(
  shell: AppShell,
  question: string,
  answer: string,
  left: number,
  right: number,
  back: number,
): void {
  setPromptStrings(shell, question, answer, left, right);
  shell.openScreenWithBack(SCREEN.PROMPT, back);
}
