import type { SaveService } from '../save/SaveService.ts';

export const VIBRATE_MS = 550;

export interface Vibrator {
  vibrate(ms: number): boolean;
}

export function navigatorVibrator(
  nav:
    | { vibrate?: (pattern: number | number[]) => boolean }
    | undefined = typeof navigator === 'undefined' ? undefined : navigator,
): Vibrator | null {
  const vibrate = nav?.vibrate;
  if (typeof vibrate !== 'function') return null;
  return { vibrate: (ms: number) => vibrate.call(nav, ms) !== false };
}

export interface HapticsOptions {
  save: SaveService;
  vibrator?: Vibrator | null;
}

export class Haptics {
  readonly save: SaveService;

  private readonly vibrator: Vibrator | null;

  constructor(options: HapticsOptions) {
    this.save = options.save;
    this.vibrator =
      options.vibrator === undefined ? navigatorVibrator() : options.vibrator;
  }

  get supported(): boolean {
    return this.vibrator !== null;
  }

  get enabled(): boolean {
    return this.save.vibration;
  }

  vibrate(ms: number = VIBRATE_MS): boolean {
    if (!this.enabled || !this.vibrator || ms <= 0) return false;
    try {
      return this.vibrator.vibrate(ms);
    } catch {
      return false;
    }
  }

  crash(): boolean {
    return this.vibrate(VIBRATE_MS);
  }

  cancel(): void {
    try {
      this.vibrator?.vibrate(0);
    } catch {}
  }

  toggleVibration(): boolean {
    this.save.vibration = !this.save.vibration;
    this.vibrate(VIBRATE_MS);
    return this.save.vibration;
  }
}
