import {
  CHALLENGES,
  CHALLENGE_TYPES,
  ENVIRONMENT_NAME_STRING,
  STRING,
  TARGET_FORMAT,
  TRACKS,
  TRICK,
  type Challenge,
  type ChallengeType,
  type MenuItem,
} from '../../data/constants.ts';
import { TRICK_SLOTS } from '../../game/Bike.ts';
import { TRICK_TEXT_BASE } from '../../game/TrickDetector.ts';
import type { StringTable } from '../../i18n/Strings.ts';

import type { AppShell } from '../AppShell.ts';
import { removeMenuItem } from '../HighScores.ts';
import {
  RESULT_TEXT,
  formatStrings,
  formatTimeLong,
  formatTimeShort,
  requirementText,
} from '../Results.ts';
import { PART_PROMISE_STRING, setupPartNames } from './Garage.ts';
import { copyRows } from './MenuModel.ts';
import { SCREEN } from './screens.ts';

export const ENVIRONMENT_NAME_BASE = ENVIRONMENT_NAME_STRING;

export const GHOST_ROW_TYPES: readonly number[] = [2, 3];

export const WATCH_GHOST_STRING = STRING.DEMO;

export const COMBO_TYPE = 5;

export const TARGET_MS_PER_TICK = 60;

export const BRIEFING_STRING = {
  ENVIRONMENT: STRING.TEXT_197,
  TITLE: STRING.TEXT_198,
  DESCRIPTION: STRING.TEXT_199,
  TARGETS: STRING.TEXT_200,
  HELP: STRING.TEXT_201,
  PART: STRING.TEXT_202,
  TARGET_TEMPLATE: STRING.AMATEUR_PRO_TOP_DOG,
  SETUP_TEMPLATE: STRING.TIRES_SUSPENSION_ENGINE_NITRO,
  COMBO_TARGETS: STRING.TEXT_204,
  SETUP: STRING.TEXT_205,
} as const;

const TRICK_HINT_BY_SLOT: Readonly<Record<number, string>> = {
  [TRICK.CRAZY_COW]: '(9)',
  [TRICK.GRIZZLY]: '(3)',
  [TRICK.HEADACHE]: '(7)',
  [TRICK.CORDOVA]: '(3)',
  [TRICK.DOUBLE_GRAB]: '(9)',
  [TRICK.TSUNAMI]: '(7)',
  [TRICK.LAZY_BOY]: '(1)',
  [TRICK.ROCK_SOLID]: '(0)',
  [TRICK.BAR_HOP]: '(#)',
  [TRICK.MC_METZ]: '(*)',
};

export const TRICK_HINTS: readonly (string | null)[] = Array.from(
  { length: TRICK_SLOTS },
  (_, slot) => TRICK_HINT_BY_SLOT[slot] ?? null,
);

type Targets = readonly [gold: string, silver: string, bronze: string] | null;

function targetTexts(slots: StringTable, row: Challenge, type: ChallengeType): Targets {
  const times = (format: (table: StringTable, ms: number) => string): Targets => [
    format(slots, row.targetGold * TARGET_MS_PER_TICK),
    format(slots, row.targetSilver * TARGET_MS_PER_TICK),
    format(slots, row.targetBronze * TARGET_MS_PER_TICK),
  ];
  switch (type.targetFormat) {
    case TARGET_FORMAT.TIME_MINUTES:
      return times(formatTimeLong);
    case TARGET_FORMAT.TIME_SECONDS:
      return times(formatTimeShort);
    case TARGET_FORMAT.NUMBER:
      return [String(row.targetGold), String(row.targetSilver), String(row.targetBronze)];
    case TARGET_FORMAT.TRICK_LIST: {
      const line = (slot: number): string =>
        `\n${slots.text(TRICK_TEXT_BASE + slot)}${TRICK_HINTS[slot] ?? ''}`;
      const first = line(row.targetBronze);
      const second = line(row.targetSilver);
      const third = line(row.targetGold);
      return [`${first}${second}${third}\n`, `${first}${second}\n`, `${first}\n`];
    }
    default:
      return null;
  }
}

function targetSource(
  slots: StringTable,
  challenge: number,
  row: Challenge,
  targets: Targets,
): number {
  let source: number = RESULT_TEXT.BLANK;
  if (targets !== null) {
    formatStrings(slots, BRIEFING_STRING.TARGET_TEMPLATE, [...targets]);
    source = BRIEFING_STRING.TARGET_TEMPLATE;
  }
  if (row.type === COMBO_TYPE) {
    slots.setString(BRIEFING_STRING.COMBO_TARGETS, slots.text(source));
    requirementText(slots, challenge, undefined, TRICK_HINTS);
    source = BRIEFING_STRING.TARGETS;
  }
  return source;
}

function writeBriefing(
  shell: AppShell,
  row: Challenge,
  type: ChallengeType,
  source: number,
): void {
  const slots = shell.table;
  const partPending = row.unlockPart >= 0 && !shell.save.partUnlocked(row.unlockPart);
  slots.setString(BRIEFING_STRING.TITLE, slots.text(type.titleString));
  slots.setString(BRIEFING_STRING.TARGETS, slots.text(source));
  slots.setString(BRIEFING_STRING.DESCRIPTION, slots.text(type.descriptionString));
  slots.setString(BRIEFING_STRING.HELP, slots.text(type.helpString));
  slots.setString(
    BRIEFING_STRING.PART,
    slots.text(partPending ? PART_PROMISE_STRING : RESULT_TEXT.BLANK),
  );
}

function writeSetupLine(shell: AppShell, setup: number, track: number): void {
  const slots = shell.table;
  formatStrings(
    slots,
    BRIEFING_STRING.SETUP_TEMPLATE,
    setupPartNames(shell, setup, track),
  );
  slots.setString(BRIEFING_STRING.SETUP, slots.text(BRIEFING_STRING.SETUP_TEMPLATE));
}

function challengeRows(shell: AppShell, row: Challenge): void {
  let rows: readonly MenuItem[] = copyRows(shell.model.challengeTemplate);
  if (!GHOST_ROW_TYPES.includes(row.type)) {
    rows = removeMenuItem(rows, WATCH_GHOST_STRING);
  }
  shell.model.items[SCREEN.CHALLENGE] = copyRows(rows);
}

function setChallengeEnvironment(shell: AppShell, challenge: number): void {
  shell.environment = TRACKS[CHALLENGES[challenge]!.track]!.environment;
  shell.table.setString(
    BRIEFING_STRING.ENVIRONMENT,
    shell.table.text(ENVIRONMENT_NAME_BASE + shell.environment),
  );
}

export function openChallenge(shell: AppShell, challenge: number): void {
  shell.challenge = challenge;
  const slots = shell.table;
  const row = CHALLENGES[challenge]!;
  const type = CHALLENGE_TYPES[row.type]!;

  const targets = targetTexts(slots, row, type);
  if (type.helpString === BRIEFING_STRING.SETUP)
    writeSetupLine(shell, row.setup, row.track);
  writeBriefing(shell, row, type, targetSource(slots, challenge, row, targets));
  challengeRows(shell, row);

  setChallengeEnvironment(shell, challenge);
  shell.progression.refreshResultString(challenge);
}

export function openGoals(shell: AppShell): void {
  if (CHALLENGES[shell.challenge]!.type === COMBO_TYPE) {
    requirementText(
      shell.table,
      shell.challenge,
      shell.race?.player.trickTotals,
      TRICK_HINTS,
    );
    shell.table.setString(
      BRIEFING_STRING.HELP,
      shell.table.text(BRIEFING_STRING.COMBO_TARGETS),
    );
  }
  shell.openScreen(SCREEN.GOALS, false);
}
