import {
  CHALLENGE_COUNT,
  MENUS,
  MENU_ITEMS,
  SCREEN,
  STRING,
  type Menu,
  type MenuItem,
} from '../data/constants.ts';
import { px, shiftPx } from '../render/units.ts';
import type { SaveService } from '../save/SaveService.ts';
import { SHELL_ACTION } from './shell/actions.ts';
import { MENU_COLOR, SCREEN_KIND, type MenuMetrics } from '../ui/MenuList.ts';
import { textWidth } from '../ui/TextLayout.ts';
import {
  RESULT_TEXT,
  formatString,
  formatTimeLong,
  type StringSlots,
} from './Results.ts';

export const MENU_ACTION = {
  OPEN_SUBMENU: SHELL_ACTION.OPEN_WITH_BACK,
  OPEN_CHALLENGE: SHELL_ACTION.OPEN_CHALLENGE,
  EXIT_LINK: SHELL_ACTION.EXIT_LINK,
} as const;

export const CAREER_MENU = 1;

export const SCORE_PAIR_ROWS = 5;

export const SCORE_LABEL_X = px(8);

export const SCORE_VALUE_INSET = px(4);

export const SCORE_ROW_GAP = px(2);

export function formatBestResult(slots: StringSlots, result: number): string {
  if (result === 0) return slots.text(RESULT_TEXT.NO_RESULT);
  return result < 0 ? String(Math.abs(result)) : formatTimeLong(slots, result);
}

export function hasStoredResult(save: SaveService, challenge: number): boolean {
  return save.bestResult(challenge) !== 0;
}

export function storedResultCount(save: SaveService): number {
  let count = 0;
  for (let challenge = 0; challenge < CHALLENGE_COUNT; challenge += 1) {
    if (save.bestResult(challenge) !== 0) count += 1;
  }
  return count;
}

export interface HighScoreEntry {
  challenge: number;
  labelString: number;
  menu: number;
  position: number;
}

export interface HighScoreEntryOptions {
  careerMenu?: number;
  includeChallenge?(challenge: number): boolean;
  dropEmptyGroups?: boolean;
}

export function highScoreEntries(options: HighScoreEntryOptions = {}): HighScoreEntry[] {
  const careerMenu = options.careerMenu ?? CAREER_MENU;
  const include = options.includeChallenge;
  const dropEmpty = options.dropEmptyGroups ?? true;

  const entries: HighScoreEntry[] = [];
  for (const group of MENU_ITEMS[careerMenu] ?? []) {
    if (group.action !== MENU_ACTION.OPEN_SUBMENU) continue;
    const menu = group.param;
    const rows: HighScoreEntry[] = [];
    let position = 0;
    for (const row of MENU_ITEMS[menu] ?? []) {
      if (row.action !== MENU_ACTION.OPEN_CHALLENGE) continue;
      const challenge = row.param;
      const slot = position;
      position += 1;
      if (include && !include(challenge)) continue;
      rows.push({ challenge, labelString: row.labelString, menu, position: slot });
    }
    if (rows.length === 0 && dropEmpty) continue;
    entries.push({
      challenge: -1,
      labelString: MENUS[menu]?.titleString ?? group.labelString,
      menu,
      position: -1,
    });
    entries.push(...rows);
  }
  return entries;
}

export interface ScorePair {
  label: string;
  value: string | null;
}

export interface ScorePairRow extends ScorePair {
  index: number;
  labelX: number;
  valueX: number;
  y: number;
  centred: boolean;
  color: number;
}

export interface HighScoreBoardOptions {
  save: SaveService;
  slots: StringSlots;
  label(id: number): string;
  entries?: readonly HighScoreEntry[];
  rowLabel?(entry: HighScoreEntry, label: string): string;
  entryOptions?: HighScoreEntryOptions;
}

export class HighScoreBoard {
  readonly entries: readonly HighScoreEntry[];

  private readonly save: SaveService;
  private readonly slots: StringSlots;
  private readonly label: (id: number) => string;
  private readonly rowLabel: (entry: HighScoreEntry, label: string) => string;

  page = 0;

  constructor(options: HighScoreBoardOptions) {
    this.save = options.save;
    this.slots = options.slots;
    this.label = options.label;
    this.rowLabel = options.rowLabel ?? ((_entry, label) => label);
    this.entries = options.entries ?? highScoreEntries(options.entryOptions ?? {});
  }

  get pageCount(): number {
    return Math.max(1, Math.ceil(this.entries.length / SCORE_PAIR_ROWS));
  }

  get pageTop(): number {
    return this.page * SCORE_PAIR_ROWS;
  }

  setPage(page: number): boolean {
    const clamped = Math.min(Math.max(page, 0), this.pageCount - 1);
    if (clamped === this.page) return false;
    this.page = clamped;
    return true;
  }

  pageUp(): boolean {
    return this.setPage(this.page - 1);
  }

  pageDown(): boolean {
    return this.setPage(this.page + 1);
  }

  pairs(): ScorePair[] {
    const pairs: ScorePair[] = [];
    for (let row = 0; row < SCORE_PAIR_ROWS; row += 1) {
      const entry = this.entries[this.pageTop + row];
      if (!entry) {
        pairs.push({ label: '', value: '' });
        continue;
      }
      const label = this.label(entry.labelString);
      if (entry.challenge < 0) {
        pairs.push({ label, value: null });
        continue;
      }
      pairs.push({
        label: this.rowLabel(entry, label),
        value: formatBestResult(this.slots, this.save.bestResult(entry.challenge)),
      });
    }
    return pairs;
  }

  rows(firstRowY: number, metrics: MenuMetrics): ScorePairRow[] {
    return scorePairRows(this.pairs(), firstRowY, metrics);
  }
}

export function scorePairRows(
  pairs: readonly ScorePair[],
  firstRowY: number,
  metrics: MenuMetrics,
): ScorePairRow[] {
  const rows: ScorePairRow[] = [];
  let y = firstRowY;
  for (let index = 0; index < pairs.length; index += 1) {
    const pair = pairs[index]!;
    const centred = pair.value === null;
    const value = pair.value ?? '';
    rows.push({
      index,
      label: pair.label,
      value: pair.value,
      labelX: centred ? shiftPx(metrics.screenWidth, 1) : SCORE_LABEL_X,
      valueX:
        metrics.screenWidth - SCORE_VALUE_INSET - textWidth(metrics.measureMenu, value),
      y,
      centred,
      color: MENU_COLOR.LABEL,
    });
    y += metrics.menuFontHeight + SCORE_ROW_GAP;
  }
  return rows;
}

export interface HighScoreScreenOptions {
  titleString?: number;
  leftSoftKey?: number;
  rightSoftKey?: number;
}

export function highScoreScreen(options: HighScoreScreenOptions = {}): {
  menu: Menu;
  items: MenuItem[];
} {
  const menu: Menu = {
    titleString: options.titleString ?? -1,
    kind: SCREEN_KIND.SCORE_PAIRS,
    titleIcon: -1,
    leftSoftKey: options.leftSoftKey ?? -1,
    rightSoftKey: options.rightSoftKey ?? 1,
  };
  const items: MenuItem[] = [];
  for (let row = 0; row < SCORE_PAIR_ROWS; row += 1) {
    items.push({
      labelString: -1,
      icon: -1,
      tickerString: -1,
      action: -1,
      param: -1,
      enabled: 1,
      condition: -1,
    });
  }
  return { menu, items };
}

export const EXIT_LINK = {
  MENU: SCREEN.EXIT,
  LABEL_STRING: STRING.GO_TO,
  ACTION: MENU_ACTION.EXIT_LINK,
  PARAM: 1,
} as const;

export interface ExitLinkProperties {
  url: string | null;
  label: string | null;
}

export interface ExitLinkHost {
  open(url: string): boolean;
  shutdown(): void;
}

export function exitLinkAvailable(properties: ExitLinkProperties): boolean {
  return properties.url !== null && properties.label !== null;
}

export function removeMenuItem(
  items: readonly MenuItem[],
  labelString: number,
): readonly MenuItem[] {
  const index = items.findIndex((item) => item.labelString === labelString);
  return index < 0 ? items : [...items.slice(0, index), ...items.slice(index + 1)];
}

export function applyExitLink(
  slots: StringSlots,
  properties: ExitLinkProperties,
  items: readonly MenuItem[] = MENU_ITEMS[EXIT_LINK.MENU] ?? [],
): readonly MenuItem[] {
  if (!exitLinkAvailable(properties)) {
    return removeMenuItem(items, EXIT_LINK.LABEL_STRING);
  }
  formatString(slots, EXIT_LINK.LABEL_STRING, properties.label!);
  return items;
}

export function openExitLink(
  param: number,
  properties: ExitLinkProperties,
  host: ExitLinkHost,
): boolean {
  if (param !== EXIT_LINK.PARAM) return false;
  if (properties.url === null) return false;
  try {
    const opened = host.open(properties.url);
    host.shutdown();
    return opened;
  } catch {
    return false;
  }
}
