import { TRACK_COUNT } from '../data/constants.ts';

export const LEVEL_BASE = 'assets/levels/';

export const MARKER_KIND = { START: 'start' } as const;

export interface StringName {
  string: number;
  en: string;
}

export interface LevelEnvironment {
  id: number;
  name: StringName;
  area: StringName;
  tilesheetRecord: number;
  skyColour: number;
  surfaceGrip: number;
  sprayStrip: number;
  sprayThreshold: number;
}

export interface LevelTerrain {
  record: number;
  points: ReadonlyArray<readonly [x: number, y: number]>;
}

export interface LevelMarker {
  kind: string;
  x: number;
  y: number;
}

export interface LevelLayer {
  index: number;
  record: number;
  packed: boolean;
  width: number;
  height: number;
  cells: ReadonlyArray<readonly number[]>;
}

export interface Level {
  id: number;
  environment: LevelEnvironment;
  terrain: LevelTerrain;
  markers: readonly LevelMarker[];
  layers: readonly LevelLayer[];
  racingLine: null;
}

export interface EnvironmentBlocks {
  environment: number;
  name: StringName;
  record: number;
  blocks: ReadonlyArray<ReadonlyArray<readonly number[]>>;
  tileOpacity: { record: number; bits: readonly number[] };
}

export interface BlocksJson {
  environments: readonly EnvironmentBlocks[];
}

export function levelUrl(track: number, base: string = LEVEL_BASE): string {
  return `${base}track-${String(track).padStart(2, '0')}.json`;
}

export function blocksUrl(base: string = LEVEL_BASE): string {
  return `${base}blocks.json`;
}

const levels = new Map<number, Level>();
const blocks = new Map<number, EnvironmentBlocks>();

export function registerLevel(level: Level): void {
  levels.set(level.id, level);
}

export function registerBlocks(json: BlocksJson): void {
  for (const entry of json.environments) blocks.set(entry.environment, entry);
}

export function forgetLevels(): void {
  levels.clear();
  blocks.clear();
}

export function levelCount(): number {
  return levels.size;
}

export function levelFor(track: number): Level {
  const level = levels.get(track);
  if (!level) throw new Error(`no track ${track}`);
  return level;
}

export function levelForTerrainRecord(record: number): Level {
  for (const level of levels.values()) {
    if (level.terrain.record === record) return level;
  }
  throw new Error(`no terrain polyline for record ${record}`);
}

export function layerOf(level: Level, index: number): LevelLayer {
  const layer = level.layers.find((candidate) => candidate.index === index);
  if (!layer) throw new Error(`track ${level.id} has no layer ${index}`);
  return layer;
}

export function blocksFor(environment: number): EnvironmentBlocks {
  const entry = blocks.get(environment);
  if (!entry) throw new Error(`no block table for environment ${environment}`);
  return entry;
}

export interface LoadLevelOptions {
  base?: string;
  fetch?: typeof fetch;
  onProgress?: (progress: number) => void;
}

export async function loadLevels(options: LoadLevelOptions = {}): Promise<number> {
  const base = options.base ?? LEVEL_BASE;
  const fetchImpl =
    options.fetch ?? ((...args: Parameters<typeof fetch>) => globalThis.fetch(...args));

  const read = async (url: string): Promise<unknown> => {
    const response = await fetchImpl(url);
    if (!response.ok) throw new Error(`${url}: ${response.status}`);
    return response.json();
  };

  const total = TRACK_COUNT + 1;
  let done = 0;
  const step = (): void => {
    done += 1;
    options.onProgress?.(done / total);
  };

  await Promise.all([
    (async (): Promise<void> => {
      registerBlocks((await read(blocksUrl(base))) as BlocksJson);
      step();
    })(),
    ...Array.from({ length: TRACK_COUNT }, async (_, track) => {
      registerLevel((await read(levelUrl(track, base))) as Level);
      step();
    }),
  ]);

  return levels.size;
}
