import { decodeBase64 } from '../core/base64.ts';
import { CHALLENGE_COUNT, PARTS } from '../data/constants.ts';
import {
  ENVIRONMENT_COUNT,
  challengeKey,
  fittedFromMask,
  partsOfMask,
  rankNameOf,
  type Progress,
  type RankName,
} from './Progress.ts';

export const V1_PROGRESS_LENGTH = 23;

export const V1_PROGRESS = {
  LANGUAGE: 0,
  MUSIC_VOLUME: 1,
  MUSIC_TRACK: 2,
  SFX_VOLUME: 3,
  VIBRATION: 4,
  SHOW_GHOST: 5,
  LATCHED_THROTTLE: 6,
  BIKE: 7,
  UNLOCKED_PARTS: 8,
  FITTED_PARTS: 9,
  RANK_WORDS: 13,
  CAREER_POINTS: 19,
  LAST_THEME: 20,
} as const;

export const V1_UNLOCK_BIT = {
  FREE_RIDE_1: 0x400000,
  FREE_RIDE_2: 0x800000,
} as const;

const RANK_WORD_PAIRS = 3;

const LOW_WORD_CHALLENGES = 32;

export function intsToBytes(ints: ArrayLike<number>): Uint8Array {
  const bytes = new Uint8Array(ints.length << 2);
  const view = new DataView(bytes.buffer);
  for (let i = 0; i < ints.length; i++) view.setInt32(i << 2, ints[i]! | 0, false);
  return bytes;
}

export function bytesToInts(bytes: Uint8Array): Int32Array<ArrayBuffer> {
  const count = bytes.length >> 2;
  const ints = new Int32Array(count);
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  for (let i = 0; i < count; i++) ints[i] = view.getInt32(i << 2, false);
  return ints;
}

export function decodeV1Value(value: string): Int32Array<ArrayBuffer> | null {
  const match = /^v(\d+):/.exec(value);
  const payload = match === null ? value : value.slice(match[0].length);
  try {
    return bytesToInts(decodeBase64(payload));
  } catch {
    return null;
  }
}

export function progressFromV1(ints: ArrayLike<number>): Progress {
  const at = (index: number): number => ints[index] ?? 0;
  const unlocks = at(V1_PROGRESS.UNLOCKED_PARTS);
  const fitted = [];
  for (let environment = 0; environment < ENVIRONMENT_COUNT; environment++) {
    fitted.push(fittedFromMask(at(V1_PROGRESS.FITTED_PARTS + environment)));
  }
  return {
    language: at(V1_PROGRESS.LANGUAGE),
    musicVolume: at(V1_PROGRESS.MUSIC_VOLUME),
    musicTrack: at(V1_PROGRESS.MUSIC_TRACK),
    sfxVolume: at(V1_PROGRESS.SFX_VOLUME),
    vibration: at(V1_PROGRESS.VIBRATION) !== 0,
    showGhost: at(V1_PROGRESS.SHOW_GHOST) !== 0,
    latchedThrottle: at(V1_PROGRESS.LATCHED_THROTTLE) !== 0,
    bike: at(V1_PROGRESS.BIKE),
    unlockedParts: partsOfMask(unlocks & partMask()),
    unlocked: {
      freeRide1: (unlocks & V1_UNLOCK_BIT.FREE_RIDE_1) !== 0,
      freeRide2: (unlocks & V1_UNLOCK_BIT.FREE_RIDE_2) !== 0,
    },
    fittedParts: fitted,
    ranks: ranksFromV1(ints),
    careerPoints: at(V1_PROGRESS.CAREER_POINTS),
    lastTheme: at(V1_PROGRESS.LAST_THEME),
  };
}

export function bestFromV1(ints: ArrayLike<number>): Int32Array<ArrayBuffer> {
  const results = new Int32Array(CHALLENGE_COUNT);
  const count = Math.min(ints.length, CHALLENGE_COUNT);
  for (let challenge = 0; challenge < count; challenge++) {
    results[challenge] = ints[challenge]! | 0;
  }
  return results;
}

function partMask(): number {
  return PARTS.length >= 32 ? -1 : (1 << PARTS.length) - 1;
}

function ranksFromV1(ints: ArrayLike<number>): Record<string, RankName> {
  const ranks: Record<string, RankName> = {};
  for (let challenge = 0; challenge < CHALLENGE_COUNT; challenge++) {
    const high = challenge >= LOW_WORD_CHALLENGES;
    const bit = 1 << (high ? challenge - LOW_WORD_CHALLENGES : challenge);
    let rank = 0;
    for (let pair = 0; pair < RANK_WORD_PAIRS; pair++) {
      const word = ints[V1_PROGRESS.RANK_WORDS + pair * 2 + (high ? 0 : 1)] ?? 0;
      if ((word & bit) !== 0) rank++;
    }
    if (rank > 0) ranks[challengeKey(challenge)] = rankNameOf(rank);
  }
  return ranks;
}
