import type { MenuItem } from '../../data/constants.ts';
import { px } from '../../render/units.ts';
import { wrapPoint } from '../../ui/TextLayout.ts';

import type { AppShell } from '../AppShell.ts';
import { BUSY_STRING } from './screens.ts';

export const WRAPPED_LABEL_BASE = 0x10000;

export const CONTENT_INSET = px(8);

function wrapLabels(shell: AppShell, screen: number): string[] {
  const measure = shell.metrics.measureMenu;
  const width = shell.metrics.screenWidth - CONTENT_INSET;
  const lines: string[] = [];
  let previousLength = 0;

  for (const item of shell.model.items[screen] ?? []) {
    const text = shell.table.text(item.labelString);
    let start = 0;
    while (start >= 0) {
      const end = wrapPoint(measure, text, start, width);
      if (end < 0) break;
      const line = text.slice(start, end).trim();
      if (line.length > 0 || previousLength > 0) lines.push(line);
      previousLength = line.length;
      start = end;
    }
    if (previousLength > 0) {
      lines.push('');
      previousLength = 0;
    }
  }
  return lines;
}

function trimTrailingBlanks(lines: string[]): void {
  let count = lines.length;
  for (let index = lines.length - 1; index >= 0; index -= 1) {
    if (lines[index]!.length > 0) {
      count = index + 1;
      break;
    }
  }
  lines.length = count;
}

function lineRows(lines: readonly string[], template: MenuItem | undefined): MenuItem[] {
  const rows: MenuItem[] = [];
  for (let index = 0; index < lines.length; index += 1) {
    rows.push({
      labelString: lines[index]!.length === 0 ? -1 : WRAPPED_LABEL_BASE + index,
      icon: -1,
      tickerString: template?.tickerString ?? -1,
      action: template?.action ?? -1,
      param: template?.param ?? -1,
      enabled: 1,
      condition: template?.condition ?? -1,
    });
  }
  return rows;
}

export function wrapScreenText(
  shell: AppShell,
  screen: number,
  busy: boolean,
): MenuItem[] {
  if (busy) shell.showBusy(BUSY_STRING.LOADING);
  const lines = wrapLabels(shell, screen);
  trimTrailingBlanks(lines);
  shell.wrappedLines = lines;
  const rows = lineRows(lines, shell.model.items[screen]?.[0]);
  if (busy) shell.hideBusyQuiet();
  return rows;
}
