import { CHALLENGES } from '../../data/constants.ts';
import { storedResultCount } from '../HighScores.ts';

import type { AppShell } from '../AppShell.ts';
import { SCREEN } from './screens.ts';

export const CONDITION = {
  SAVED_RESULTS: 1,
  BEST_RESULT: 2,
  PART_UNLOCKED: 3,
  GROUP_UNLOCKED: 4,
  CHALLENGE_UNLOCKED: 5,
  FREE_SETUP: 6,
  OPTIONS_FROM_TITLE: 7,
} as const;

function groupUnlocked(shell: AppShell, screen: number): boolean {
  const rows = shell.model.items[screen] ?? [];
  for (let index = 0; index < rows.length - 1; index += 1) {
    if (shell.save.challengeUnlocked(rows[index]!.param)) return true;
  }
  return false;
}

export function conditionMet(shell: AppShell, condition: number, param: number): boolean {
  switch (condition) {
    case CONDITION.SAVED_RESULTS:
      return storedResultCount(shell.save) > 0;
    case CONDITION.BEST_RESULT:
      return shell.save.bestResult(shell.challenge) !== 0;
    case CONDITION.PART_UNLOCKED:
      return shell.save.partUnlocked(param);
    case CONDITION.GROUP_UNLOCKED:
      return groupUnlocked(shell, param);
    case CONDITION.CHALLENGE_UNLOCKED:
      return shell.save.challengeUnlocked(param);
    case CONDITION.FREE_SETUP:
      return (CHALLENGES[shell.challenge]?.setup ?? 0) < 0;
    case CONDITION.OPTIONS_FROM_TITLE:
      return shell.screenBack[SCREEN.OPTIONS] === SCREEN.TITLE;
    default:
      return true;
  }
}
