import { VIBRATE_MS } from '../../audio/Haptics.ts';
import { RACE_MODE } from '../../game/RaceState.ts';
import { VOLUME_SLOT_BY_MENU_PARAM } from '../../save/SaveService.ts';

import type { AppShell } from '../AppShell.ts';
import { SCREEN, SHELL_MODE } from './screens.ts';

export const SHELL_ACTION = {
  ACTIVATE: 1,
  BACK_ALIAS: 2,
  BACK: 3,
  RESUME: 4,
  OPEN_WITH_BACK: 5,
  OPEN: 6,
  OPEN_CHALLENGE: 7,
  START: 8,
  WATCH_GHOST: 9,
  RESTART: 10,
  EXIT: 11,
  SET_LANGUAGE: 12,
  FIT_PART: 13,
  SELECT_BIKE: 14,
  CLEAR_DATA: 15,
  NEXT_NOTICE: 16,
  SELECT_TRACK: 17,
  TOGGLE_VOLUME: 18,
  TOGGLE_VIBRATION: 19,
  TOGGLE_THROTTLE: 20,
  TOGGLE_GHOST: 21,
  EXIT_LINK: 23,
} as const;

function back(shell: AppShell): void {
  shell.openScreen(shell.screenBack[shell.screen] ?? SCREEN.TITLE, false);
}

function startRace(shell: AppShell, mode: number): void {
  shell.loadChallenge(shell.challenge, mode);
  shell.setMode(SHELL_MODE.RACE);
}

function toggleVolume(shell: AppShell, param: number): void {
  const slot = VOLUME_SLOT_BY_MENU_PARAM[param];
  if (slot === undefined) return;
  shell.audio.toggleVolume(slot);
  shell.refreshScreen();
}

function selectTrack(shell: AppShell, param: number): void {
  shell.save.musicTrack = param;
  shell.list?.select(shell.selectedItem, 0, false);
  shell.audio.playMusic(false);
}

export type ShellActionHandler = (shell: AppShell, param: number) => void;

export const SHELL_ACTIONS: Readonly<Record<number, ShellActionHandler>> = {
  [SHELL_ACTION.ACTIVATE]: (shell) => {
    shell.activateSelected();
  },
  [SHELL_ACTION.BACK_ALIAS]: back,
  [SHELL_ACTION.BACK]: back,
  [SHELL_ACTION.OPEN_WITH_BACK]: (shell, param) => {
    shell.openScreen(param, true);
  },
  [SHELL_ACTION.OPEN]: (shell, param) => {
    shell.openScreen(param, false);
  },
  [SHELL_ACTION.RESUME]: (shell) => {
    shell.setMode(SHELL_MODE.RACE);
  },
  [SHELL_ACTION.OPEN_CHALLENGE]: (shell, param) => {
    shell.openChallenge(param);
    shell.openScreen(SCREEN.CHALLENGE, true);
  },
  [SHELL_ACTION.START]: (shell, param) => {
    if (param < 0 && shell.challenge !== shell.preparedChallenge) {
      shell.openScreen(SCREEN.BRIEFING, true);
      return;
    }
    startRace(shell, RACE_MODE.PLAY);
  },
  [SHELL_ACTION.WATCH_GHOST]: (shell) => {
    startRace(shell, RACE_MODE.WATCH_GHOST);
  },
  [SHELL_ACTION.RESTART]: (shell) => {
    shell.race?.restart();
    shell.setMode(SHELL_MODE.RACE);
  },
  [SHELL_ACTION.NEXT_NOTICE]: (shell) => {
    shell.openScreen(shell.progression.nextNoticeScreen(), false);
  },
  [SHELL_ACTION.EXIT]: (shell) => {
    shell.shutdown();
  },
  [SHELL_ACTION.SET_LANGUAGE]: (shell, param) => {
    void shell.language.selectLanguage(param);
  },
  [SHELL_ACTION.FIT_PART]: (shell, param) => {
    shell.fitPart(param);
  },
  [SHELL_ACTION.SELECT_BIKE]: (shell, param) => {
    shell.selectBike(param);
  },
  [SHELL_ACTION.CLEAR_DATA]: (shell) => {
    shell.clearAllData();
  },
  [SHELL_ACTION.SELECT_TRACK]: selectTrack,
  [SHELL_ACTION.TOGGLE_VOLUME]: toggleVolume,
  [SHELL_ACTION.TOGGLE_VIBRATION]: (shell) => {
    shell.save.vibration = !shell.save.vibration;
    shell.haptics?.vibrate(VIBRATE_MS);
    shell.refreshScreen();
  },
  [SHELL_ACTION.TOGGLE_THROTTLE]: (shell) => {
    shell.save.latchedThrottle = !shell.save.latchedThrottle;
    shell.refreshScreen();
  },
  [SHELL_ACTION.TOGGLE_GHOST]: (shell) => {
    shell.save.showGhost = !shell.save.showGhost;
    shell.refreshScreen();
  },
  [SHELL_ACTION.EXIT_LINK]: (shell, param) => {
    shell.openExitLink(param);
  },
};
