import type { AudioService } from '../audio/AudioService.ts';
import type { Haptics } from '../audio/Haptics.ts';
import type { Input } from '../core/Input.ts';
import type { Scene } from '../core/Scene.ts';
import type { MenuItem } from '../data/constants.ts';
import type { LanguageService, StringTable } from '../i18n/Strings.ts';
import type { SaveService } from '../save/SaveService.ts';
import {
  MenuList,
  SCREEN_KIND,
  type MenuEvent,
  type MenuMetrics,
} from '../ui/MenuList.ts';
import { MenuScreen } from '../ui/MenuScreen.ts';

import type { ExitLinkProperties, HighScoreBoard } from './HighScores.ts';
import type { RaceShell } from './RaceScene.ts';
import { Progression } from './Results.ts';
import { SHELL_ACTIONS } from './shell/actions.ts';
import { boardRows, turnBoardPage } from './shell/Board.ts';
import { openChallenge } from './shell/Briefing.ts';
import { conditionMet } from './shell/Conditions.ts';
import {
  clearAllData,
  hideBusy,
  hideBusyQuiet,
  installLanguageHost,
  openShellExitLink,
  showBusy,
  shutdown,
} from './shell/Lifecycle.ts';
import { fitPart, itemMarker, selectBike } from './shell/Garage.ts';
import { MenuModel } from './shell/MenuModel.ts';
import { appProperty, appPropertyInt } from './shell/properties.ts';
import {
  loadChallenge,
  makeRaceShell,
  pauseToMenu,
  queueScreen,
  setMode,
} from './shell/RaceHandoff.ts';
import {
  openScreen,
  prompt,
  refreshScreen,
  screenTheme,
  setPromptStrings,
} from './shell/ScreenStack.ts';
import { SCREEN, SHELL_MODE } from './shell/screens.ts';
import { WRAPPED_LABEL_BASE, wrapScreenText } from './shell/TextWrap.ts';
import { sameTouchState, touchState } from './shell/TouchState.ts';
import type {
  AppShellOptions,
  AppShellView,
  RaceFactory,
  ShellRace,
  ShellTouchState,
} from './shell/types.ts';

export * from './shell/index.ts';

export class AppShell implements Scene {
  mode: number = SHELL_MODE.SPLASH;
  screen: number = SCREEN.TITLE;
  challenge = 0;
  environment = 0;
  busy = false;
  paused = false;

  readonly screenBack: number[] = [];
  readonly screenSelection: number[] = [];

  list: MenuList | null = null;
  readonly view: MenuScreen | null = null;

  pendingScreen = -1;
  pendingScreenDelay = -1;

  race: ShellRace | null = null;

  preparedChallenge = -1;

  readonly swapSoftKeys: boolean;
  readonly soundPresent: boolean;
  readonly exitLink: ExitLinkProperties;
  readonly haptics: Haptics | null;

  readonly save: SaveService;
  readonly input: Input;
  readonly audio: AudioService;
  readonly language: LanguageService;
  readonly metrics: MenuMetrics;
  readonly progression: Progression;

  readonly model = new MenuModel();

  board: HighScoreBoard | null = null;

  wrappedLines: string[] | null = null;

  readonly properties: Readonly<Record<string, string>>;
  private readonly viewOptions: AppShellView | undefined;
  readonly onShutdown: (() => void) | undefined;
  private readonly onTouchState: ((state: ShellTouchState) => void) | undefined;
  readonly openUrl: ((url: string) => boolean) | undefined;
  readonly createRace: RaceFactory | undefined;

  raceChallenge = -1;
  raceMode = -1;

  readonly raceShell: RaceShell = makeRaceShell(this);

  previousTicker: string | null = null;

  private frameCount = 0;

  private lastTouchState: ShellTouchState | null = null;

  constructor(options: AppShellOptions) {
    this.save = options.save;
    this.input = options.input;
    this.audio = options.audio;
    this.language = options.language;
    this.metrics = options.metrics;
    this.haptics = options.haptics ?? null;
    this.properties = options.appProperties ?? {};
    this.viewOptions = options.view;
    this.onShutdown = options.onShutdown;
    this.onTouchState = options.onTouchState;
    this.openUrl = options.openUrl;
    this.createRace = options.createRace;
    this.progression =
      options.progression ?? new Progression({ save: this.save, slots: this.table });

    this.swapSoftKeys = appPropertyInt(this.properties, 'SOFTKEYSWAP', 0) !== 0;
    this.soundPresent = appPropertyInt(this.properties, 'SOUNDNOTPRESENT', 0) === 0;
    this.exitLink = {
      url: appProperty(this.properties, 'UNITYEXITURL'),
      label: appProperty(this.properties, 'UNITYEXITLINK'),
    };

    installLanguageHost(this);

    this.view = this.viewOptions === undefined ? null : this.createView(this.viewOptions);
  }

  private createView(options: AppShellView): MenuScreen {
    return new MenuScreen(options.textures, {
      itemMarker: (item) => this.itemMarker(item),
      scorePairRows: (firstRowY) => boardRows(this, firstRowY),
    });
  }

  get table(): StringTable {
    return this.language.table;
  }

  get selectedItem(): number {
    return this.list?.selected ?? 0;
  }

  itemMarker(item: MenuItem): number {
    return itemMarker(this, item);
  }

  enter(): void {
    const view = this.viewOptions;
    if (view && this.view) {
      view.layers.hud.addChild(this.view.container);
      view.layers.overlay.addChild(this.view.overlay);
    }
    this.model.build(this);
    const boot = this.language.bootScreen();
    if (boot === SCREEN.LANGUAGE) this.screenBack[SCREEN.LANGUAGE] = SCREEN.TITLE;
    this.openScreen(boot, false);
  }

  exit(): void {
    this.race?.exit();
    this.race = null;
    this.view?.destroy();
  }

  touchState(): ShellTouchState {
    return touchState(this);
  }

  private publishTouchState(): void {
    const next = this.touchState();
    if (sameTouchState(this.lastTouchState, next)) return;
    this.lastTouchState = next;
    this.onTouchState?.(next);
  }

  update(): void {
    this.publishTouchState();
    if (this.mode !== SHELL_MODE.RACE) this.input.latch();
    if (this.busy) return;
    if (this.mode === SHELL_MODE.RACE) {
      if (this.pendingScreenDelay < 0) this.race?.update();
      else if ((this.pendingScreenDelay -= 1) === 0) {
        this.openScreen(this.pendingScreen, false);
      }
    }
    if (this.mode === SHELL_MODE.MENU && this.list) {
      const event = this.list.update(this.input);
      if (event) this.handleMenuEvent(event);
    }
    this.frameCount += 1;
    this.view?.draw(this.frameCount);
  }

  render(alpha: number): void {
    if (this.mode === SHELL_MODE.RACE) this.race?.render(alpha);
  }

  pause(): void {
    if (this.paused) return;
    this.paused = true;
    this.input.clear();
    if (this.mode === SHELL_MODE.SPLASH) return;
    this.audio.stopSound();
    if (
      this.mode === SHELL_MODE.RACE ||
      this.screenKind(this.screen) !== SCREEN_KIND.PAUSE
    ) {
      this.pauseToMenu();
    }
  }

  resume(): void {
    this.paused = false;
  }

  refreshStrings(): void {
    this.model.refreshExitScreen(this);
  }

  screenKind(screen: number): number {
    return this.model.menus[screen]?.kind ?? SCREEN_KIND.LIST;
  }

  itemsOf(screen: number): readonly MenuItem[] {
    return this.model.items[screen] ?? [];
  }

  openScreenWithBack(screen: number, back: number): void {
    this.openScreen(screen, false);
    this.screenBack[screen] = back;
  }

  openScreen(target: number, withBack: boolean): void {
    openScreen(this, target, withBack);
  }

  screenTheme(screen: number): number {
    return screenTheme(this, screen);
  }

  refreshScreen(): void {
    refreshScreen(this);
  }

  conditionMet(condition: number, param: number): boolean {
    return conditionMet(this, condition, param);
  }

  wrapScreenText(screen: number, busy: boolean): MenuItem[] {
    return wrapScreenText(this, screen, busy);
  }

  setMode(mode: number): void {
    setMode(this, mode);
  }

  queueScreen(screen: number): void {
    queueScreen(this, screen);
  }

  pauseToMenu(): void {
    pauseToMenu(this);
  }

  private handleMenuEvent(event: MenuEvent): void {
    if (event.kind === 'softKey') this.runAction(event.action, -1);
    if (event.kind === 'activate') this.runAction(event.item.action, event.item.param);
    if (
      event.kind === 'move' &&
      this.screenKind(this.screen) === SCREEN_KIND.SCORE_PAIRS
    ) {
      this.turnBoardPage(event.index);
    }
  }

  private turnBoardPage(index: number): void {
    turnBoardPage(this, index);
  }

  activateSelected(): void {
    const event = this.list?.activate();
    if (event?.kind === 'activate') this.runAction(event.item.action, event.item.param);
  }

  runAction(action: number, param: number): void {
    SHELL_ACTIONS[action]?.(this, param);
  }

  fitPart(part: number): void {
    fitPart(this, part);
  }

  selectBike(bike: number): void {
    selectBike(this, bike);
  }

  clearAllData(): void {
    clearAllData(this);
  }

  openExitLink(param: number): void {
    openShellExitLink(this, param);
  }

  shutdown(): void {
    shutdown(this);
  }

  setPromptStrings(question: string, answer: string, left: number, right: number): void {
    setPromptStrings(this, question, answer, left, right);
  }

  prompt(
    question: string,
    answer: string,
    left: number,
    right: number,
    back: number,
  ): void {
    prompt(this, question, answer, left, right, back);
  }

  openChallenge(challenge: number): void {
    openChallenge(this, challenge);
  }

  loadChallenge(challenge: number, mode: number): void {
    loadChallenge(this, challenge, mode);
  }

  showBusy(stringId: number): void {
    showBusy(this, stringId);
  }

  hideBusy(): void {
    hideBusy(this);
  }

  hideBusyQuiet(): void {
    hideBusyQuiet(this);
  }

  text(id: number): string {
    if (id === -1) return '';
    if (id >= WRAPPED_LABEL_BASE) {
      return this.wrappedLines?.[id - WRAPPED_LABEL_BASE] ?? '';
    }
    return this.table.text(id);
  }
}
