import { SCREEN_WIDTH } from '../core/config.ts';
import { lengthFixed } from '../core/fixed.ts';
import { FIXED_ONE, FIXED_SHIFT } from '../data/constants.ts';
import { levelFor, levelForTerrainRecord, type Level } from './Levels.ts';

export type TerrainPoint = readonly [x: number, y: number];

export interface Normal {
  x: number;
  y: number;
}

interface TerrainLines {
  x: Int32Array;
  y: Int32Array;
  normalX: Int32Array;
  normalY: Int32Array;
}

function plotPoints(lines: TerrainLines, points: readonly TerrainPoint[]): number {
  const { x, y, normalX, normalY } = lines;
  let previousX = points[0]![0] << FIXED_SHIFT;
  let previousY = points[0]![1] << FIXED_SHIFT;
  x[0] = previousX;
  y[0] = previousY;

  let maxY = 0;

  for (let i = 1; i < points.length; i += 1) {
    const pointX = points[i]![0] << FIXED_SHIFT;
    const pointY = points[i]![1] << FIXED_SHIFT;
    if (pointY > maxY) maxY = pointY;

    const dx = pointX - previousX;
    const dy = pointY - previousY;
    const inverse = (0x100000 / lengthFixed(dx, dy)) | 0;

    x[i] = pointX;
    y[i] = pointY;
    normalX[i - 1] = -((dy * inverse) >> FIXED_SHIFT);
    normalY[i - 1] = (dx * inverse) >> FIXED_SHIFT;

    previousX = pointX;
    previousY = pointY;
  }

  return maxY;
}

function wrapTail(
  lines: TerrainLines,
  count: number,
  trackLength: number,
  span: number,
): number {
  const { x, y, normalX, normalY } = lines;
  let write = count - 1;
  let read = 0;
  let covered = 0;
  while (covered < span) {
    x[write] = x[read]! + trackLength;
    y[write] = y[read]!;
    normalX[write] = normalX[read]!;
    normalY[write] = normalY[read]!;
    covered = x[read]!;
    read += 1;
    write += 1;
  }
  return write;
}

export class Terrain {
  readonly x: Int32Array;
  readonly y: Int32Array;
  readonly normalX: Int32Array;
  readonly normalY: Int32Array;

  readonly segments: number;

  readonly trackLength: number;

  readonly maxY: number;

  readonly sourcePoints: number;

  constructor(points: readonly TerrainPoint[], screenWidth: number = SCREEN_WIDTH) {
    const count = points.length;
    if (count < 2) throw new Error(`terrain needs at least 2 points, got ${count}`);

    const capacity = count * 2 + 2;
    const lines: TerrainLines = {
      x: new Int32Array(capacity),
      y: new Int32Array(capacity),
      normalX: new Int32Array(capacity),
      normalY: new Int32Array(capacity),
    };

    const maxY = plotPoints(lines, points);
    const trackLength = lines.x[count - 1]!;
    const segments = wrapTail(lines, count, trackLength, screenWidth << FIXED_SHIFT);

    this.x = lines.x;
    this.y = lines.y;
    this.normalX = lines.normalX;
    this.normalY = lines.normalY;
    this.segments = segments;
    this.trackLength = trackLength;
    this.maxY = maxY;
    this.sourcePoints = count;
  }

  static fromLevel(level: Level, screenWidth?: number): Terrain {
    return new Terrain(level.terrain.points, screenWidth);
  }

  static fromRecord(record: number, screenWidth?: number): Terrain {
    return Terrain.fromLevel(levelForTerrainRecord(record), screenWidth);
  }

  static forTrack(track: number, screenWidth?: number): Terrain {
    return Terrain.fromLevel(levelFor(track), screenWidth);
  }

  segmentAt(xFixed: number): number {
    const x = this.x;
    let low = 0;
    let high = this.segments - 1;

    for (;;) {
      const mid = (high + low) >> 1;
      const start = x[mid]!;
      const end = x[mid + 1]!;
      if (xFixed < start) {
        high = mid;
      } else {
        low = mid + 1;
      }
      if ((xFixed >= start && xFixed < end) || low >= high) return mid;
    }
  }

  heightAt(xFixed: number): number {
    const segment = this.segmentAt(xFixed);
    const rise = -this.normalX[segment]!;
    const run = this.normalY[segment]!;
    const startY = this.y[segment]!;
    if (run === 0) return startY;
    return startY + Math.trunc(Math.imul(rise, xFixed - this.x[segment]!) / run);
  }

  slopeAt(xFixed: number): number {
    const segment = this.segmentAt(xFixed);
    const run = this.normalY[segment]!;
    if (run === 0) return 0;
    return Math.trunc((-this.normalX[segment]! << FIXED_SHIFT) / run);
  }

  normalAt(xFixed: number): Normal {
    const segment = this.segmentAt(xFixed);
    return { x: this.normalX[segment]!, y: this.normalY[segment]! };
  }

  firstSegmentCrossing(x0: number, y0: number, x1: number, y1: number): number {
    const first = this.segmentAt(x0);
    const last = this.segmentAt(x1);
    for (let segment = first; segment <= last; segment += 1) {
      if (this.segmentCrosses(segment, x0, y0, x1, y1)) return segment;
    }
    return -1;
  }

  private segmentCrosses(
    segment: number,
    x0: number,
    y0: number,
    x1: number,
    y1: number,
  ): boolean {
    const segmentDy = this.y[segment + 1]! - this.y[segment]!;
    const segmentDx = this.x[segment + 1]! - this.x[segment]!;
    const rayDx = x0 - x1;
    const rayDy = y0 - y1;

    const determinant = segmentDy * rayDx - segmentDx * rayDy;
    if (determinant === 0) return false;

    const toStartX = this.x[segment]! - x0;
    const toStartY = this.y[segment]! - y0;

    const alongRay = rayDy * toStartX - rayDx * toStartY;
    const alongSegment = segmentDx * toStartY - segmentDy * toStartX;

    if (determinant > 0) {
      if (alongRay < 0 || alongRay > determinant) return false;
      return alongSegment >= 0 && alongSegment <= determinant;
    }
    if (alongRay > 0 || alongRay < determinant) return false;
    return alongSegment <= 0 && alongSegment >= determinant;
  }

  intersectionPoint(
    out: Int32Array,
    segment: number,
    x0: number,
    y0: number,
    x1: number,
    y1: number,
  ): boolean {
    const startX = this.x[segment]!;
    const startY = this.y[segment]!;

    const rayDx = x1 - x0;
    if (rayDx === 0) return false;
    const segmentDx = this.x[segment + 1]! - startX;
    if (segmentDx === 0) return false;

    const rayGradient = Math.trunc(((y1 - y0) * FIXED_ONE) / rayDx);
    const segmentGradient = Math.trunc(
      ((this.y[segment + 1]! - startY) * FIXED_ONE) / segmentDx,
    );

    if (rayGradient === segmentGradient) {
      out[0] = startX + ((x0 - startX) >> 1);
      out[1] = startY + ((y0 - startY) >> 1);
      return true;
    }

    const rayIntercept = y0 - Math.floor((x0 * rayGradient) / FIXED_ONE);
    const segmentIntercept = startY - Math.floor((startX * segmentGradient) / FIXED_ONE);

    const x =
      Math.trunc(
        ((segmentIntercept - rayIntercept) * FIXED_ONE) / (rayGradient - segmentGradient),
      ) | 0;
    out[0] = x;
    out[1] = (Math.floor((rayGradient * x) / FIXED_ONE) + rayIntercept) | 0;
    return true;
  }

  wrapX(xFixed: number): number {
    let wrapped = xFixed % this.trackLength;
    if (wrapped < 0) wrapped += this.trackLength;
    return wrapped;
  }
}
