import { SCREEN_WIDTH } from '../core/config.ts';
import { CRASH_ANIMATION, FIXED_SHIFT } from '../data/constants.ts';
import { WORLD_LAYERS } from './Renderer.ts';
import type { Layers } from './Renderer.ts';
import { VIEWPORT_HEIGHT } from './TerrainView.ts';

export interface CameraTarget {
  readonly jointX: Int32Array;
  readonly jointY: Int32Array;
  readonly animation: number;
}

export const FOLLOW_JOINTS = {
  riding: [0, 1],
  crashing: [4, 8],
} as const satisfies Record<string, readonly [number, number]>;

export const OFF_SCREEN = undefined;

export interface Camera2DOptions {
  readonly worldHeight: number;
  readonly trackLengthFixed: number;
  readonly terrainMaxYFixed: number;
  readonly bikeLength: number;
  readonly viewportWidth?: number;
  readonly viewportHeight?: number;
}

export class Camera2D {
  x = 0;
  y = 0;

  readonly viewportWidth: number;
  readonly viewportHeight: number;

  readonly trackLength: number;

  private readonly maxY: number;
  private readonly terrainMaxY: number;
  private readonly bikeLength: number;

  constructor(options: Camera2DOptions) {
    this.viewportWidth = options.viewportWidth ?? SCREEN_WIDTH;
    this.viewportHeight = options.viewportHeight ?? VIEWPORT_HEIGHT;
    this.trackLength = options.trackLengthFixed >> FIXED_SHIFT;
    this.terrainMaxY = options.terrainMaxYFixed >> FIXED_SHIFT;
    this.bikeLength = options.bikeLength;
    this.maxY = options.worldHeight - this.viewportHeight - 1;
  }

  follow(target: CameraTarget): void {
    const pair =
      target.animation === CRASH_ANIMATION
        ? FOLLOW_JOINTS.crashing
        : FOLLOW_JOINTS.riding;
    const first = pair[0];
    const second = pair[1];

    const midX =
      (target.jointX[first]! + target.jointX[second]!) / (1 << (FIXED_SHIFT + 1));
    const midY =
      (target.jointY[first]! + target.jointY[second]!) / (1 << (FIXED_SHIFT + 1));

    this.x = Math.max(0, midX - (this.viewportWidth >> 2));
    this.y = Math.min(this.maxY, midY - (this.viewportHeight >> 1));
  }

  apply(layers: Layers): void {
    for (const name of WORLD_LAYERS) layers[name].position.set(-this.x, -this.y);
  }

  wrapOffset(drawLeft: number, drawRight: number): number | undefined {
    const left = this.x;
    const right = left + this.viewportWidth;

    if (left < drawRight && right >= drawLeft) return 0;

    if (right >= this.trackLength) {
      return left - this.trackLength < drawRight && right - this.trackLength >= drawLeft
        ? this.trackLength
        : OFF_SCREEN;
    }

    if (left < this.bikeLength) {
      return left + this.trackLength < drawRight && right + this.trackLength >= drawLeft
        ? -this.terrainMaxY
        : OFF_SCREEN;
    }

    return OFF_SCREEN;
  }

  seamShift(): number {
    return this.x > this.trackLength - this.viewportWidth ? this.trackLength : 0;
  }
}
