import { Container, Rectangle, Sprite, Texture } from 'pixi.js';
import { SCREEN_HEIGHT, SCREEN_WIDTH } from '../core/config.ts';
import {
  BLOCK_SIZE,
  BLOCK_TILES,
  HUD_LAYOUT,
  TILES_PER_ROW,
  TILE_SIZE,
} from '../data/constants.ts';
import { blocksFor, layerOf, levelFor } from '../game/Levels.ts';
import type { Level, LevelLayer } from '../game/Levels.ts';
import { SPRITE_SCALE, texels } from './units.ts';

export const TILE_SIZE_PX = texels(TILE_SIZE);

export const VIEWPORT_HEIGHT = SCREEN_HEIGHT - HUD_LAYOUT[1]!;

export type LayerIndex = 0 | 1;

export interface FlatLayer {
  width: number;
  height: number;
  cells: readonly number[];
}

function flatten(layer: LevelLayer): FlatLayer {
  return { width: layer.width, height: layer.height, cells: layer.cells.flat() };
}

export class TileMap {
  readonly layer0: FlatLayer;
  readonly layer1: FlatLayer;
  readonly tiles: readonly number[];
  readonly opacity: readonly number[];
  readonly skyColour: number;
  readonly tilesheetRecord: number;

  readonly pixelHeight: number;

  constructor(
    layer0: FlatLayer,
    layer1: FlatLayer,
    tiles: readonly number[],
    opacity: readonly number[],
    skyColour: number,
    tilesheetRecord: number,
  ) {
    this.layer0 = layer0;
    this.layer1 = layer1;
    this.tiles = tiles;
    this.opacity = opacity;
    this.skyColour = skyColour;
    this.tilesheetRecord = tilesheetRecord;
    this.pixelHeight = layer0.height * BLOCK_SIZE;
  }

  static fromLevel(level: Level): TileMap {
    const blocks = blocksFor(level.environment.id);
    return new TileMap(
      flatten(layerOf(level, 0)),
      flatten(layerOf(level, 1)),
      blocks.blocks.flat(2),
      blocks.tileOpacity.bits,
      level.environment.skyColour,
      level.environment.tilesheetRecord,
    );
  }

  static forTrack(track: number): TileMap {
    return TileMap.fromLevel(levelFor(track));
  }

  tileAt(layer: LayerIndex, tileX: number, tileY: number): number {
    if (tileX < 0) return -1;

    const map = layer === 0 ? this.layer0 : this.layer1;
    const blockY = tileY >> 2;
    if (blockY < 0 || blockY >= map.height) return -1;

    let blockX = tileX >> 2;
    let wrappedX = tileX;
    if (blockX >= map.width) {
      blockX %= map.width;
      wrappedX %= map.width * BLOCK_TILES;
    }

    const block = map.cells[blockX + blockY * map.width]!;
    if (block < 0) return -1;

    const withinX = wrappedX - blockX * BLOCK_TILES;
    const withinY = tileY - blockY * BLOCK_TILES;
    return this.tiles[
      block * BLOCK_TILES * BLOCK_TILES + withinY * BLOCK_TILES + withinX
    ]!;
  }

  showsLayerBehind(id: number): boolean {
    return (this.opacity[id >> 5]! & (1 << (id & 31))) !== 0;
  }
}

export class TerrainView {
  readonly container = new Container({ label: 'terrain' });

  readonly columns: number;
  readonly rows: number;

  private readonly map: TileMap;
  private readonly sheet: Texture;
  private readonly tiles = new Map<number, Texture>();

  private readonly back: Sprite[] = [];
  private readonly front: Sprite[] = [];

  private originX: number;
  private originY = 0;

  constructor(
    map: TileMap,
    sheet: Texture,
    viewportWidth: number = SCREEN_WIDTH,
    viewportHeight: number = VIEWPORT_HEIGHT,
  ) {
    this.map = map;
    this.sheet = sheet;

    this.columns = tileSpan(viewportWidth);
    this.rows = tileSpan(viewportHeight);

    const back = new Container({ label: 'layer0' });
    const front = new Container({ label: 'layer1' });
    for (let i = 0; i < this.columns * this.rows; i += 1) {
      const backTile = new Sprite({ visible: false, scale: SPRITE_SCALE });
      const frontTile = new Sprite({ visible: false, scale: SPRITE_SCALE });
      this.back.push(backTile);
      this.front.push(frontTile);
      back.addChild(backTile);
      front.addChild(frontTile);
    }
    this.container.addChild(back, front);

    this.originX = -viewportWidth;
  }

  scrollTo(cameraX: number, cameraY: number): void {
    const tileX = Math.floor(cameraX / TILE_SIZE);
    const tileY = Math.max(0, Math.floor(cameraY / TILE_SIZE));

    if (Math.abs(tileX - this.originX) > this.columns)
      this.originX = tileX - this.columns;
    if (Math.abs(tileY - this.originY) > this.rows) this.originY = tileY - this.rows;

    while (this.originX < tileX) {
      this.refillLine(this.originX + this.columns, this.originY, true);
      this.originX += 1;
    }
    while (this.originX > tileX) {
      this.originX -= 1;
      this.refillLine(this.originX, this.originY, true);
    }
    while (this.originY < tileY) {
      this.refillLine(this.originX, this.originY + this.rows, false);
      this.originY += 1;
    }
    while (this.originY > tileY) {
      this.originY -= 1;
      this.refillLine(this.originX, this.originY, false);
    }
  }

  cellAt(tileX: number, tileY: number): { back: Sprite; front: Sprite } | undefined {
    if (tileX < this.originX || tileX >= this.originX + this.columns) return undefined;
    if (tileY < this.originY || tileY >= this.originY + this.rows) return undefined;
    const slot = this.slot(tileX, tileY);
    return { back: this.back[slot]!, front: this.front[slot]! };
  }

  destroy(): void {
    this.container.destroy({ children: true });
    for (const texture of this.tiles.values()) texture.destroy();
    this.tiles.clear();
  }

  private refillLine(tileX: number, tileY: number, vertical: boolean): void {
    const length = vertical ? this.rows : this.columns;
    for (let i = 0; i < length; i += 1) {
      const x = vertical ? tileX : tileX + i;
      const y = vertical ? tileY + i : tileY;

      let back = this.map.tileAt(0, x, y);
      const front = this.map.tileAt(1, x, y);
      if (front >= 0 && !this.map.showsLayerBehind(front)) back = -1;

      const slot = this.slot(x, y);
      this.place(this.back[slot]!, back, x, y);
      this.place(this.front[slot]!, front, x, y);
    }
  }

  private place(sprite: Sprite, tile: number, tileX: number, tileY: number): void {
    if (tile < 0) {
      sprite.visible = false;
      return;
    }
    sprite.texture = this.tileTexture(tile);
    sprite.position.set(tileX * TILE_SIZE, tileY * TILE_SIZE);
    sprite.visible = true;
  }

  private slot(tileX: number, tileY: number): number {
    const column = ((tileX % this.columns) + this.columns) % this.columns;
    const row = ((tileY % this.rows) + this.rows) % this.rows;
    return row * this.columns + column;
  }

  private tileTexture(id: number): Texture {
    const cached = this.tiles.get(id);
    if (cached) return cached;

    const frame = this.sheet.frame;
    const texture = new Texture({
      source: this.sheet.source,
      frame: new Rectangle(
        frame.x + (id % TILES_PER_ROW) * TILE_SIZE_PX,
        frame.y + Math.floor(id / TILES_PER_ROW) * TILE_SIZE_PX,
        TILE_SIZE_PX,
        TILE_SIZE_PX,
      ),
    });
    this.tiles.set(id, texture);
    return texture;
  }
}

function tileSpan(pixels: number): number {
  return pixels % TILE_SIZE === 0
    ? pixels / TILE_SIZE + 1
    : Math.floor((pixels + TILE_SIZE) / TILE_SIZE) + 1;
}
