import { Container, Graphics, Sprite } from 'pixi.js';

import { FIXED_SHIFT, SPRITE_STRIPS } from '../data/constants.ts';
import { JOINT, STATE } from '../game/Bike.ts';
import { JOINT_PREVIOUS_X, JOINT_PREVIOUS_Y, jointAt } from '../game/Physics.ts';

import { anchorAt, stripFrame, stripPivot, type TextureLookup } from './BikeView.ts';
import { SPRITE_SCALE } from './units.ts';

const FIXED_ONE = 1 << FIXED_SHIFT;

export const EFFECT_SLOTS = 64;

export const EFFECT_STRIDE = 7;

export const EFFECT_X = 0;
export const EFFECT_Y = 1;
export const EFFECT_PREVIOUS_X = 2;
export const EFFECT_PREVIOUS_Y = 3;
export const EFFECT_LIFE = 4;
export const EFFECT_KIND = 5;
export const EFFECT_PARAMS = 6;

export const GRAVITY = 128;

export const NO_GRAVITY = 0x40;

export const SCREEN_SPACE = 0x80;

export const ANIM = {
  LIFE: 0,
  CYCLE: 1,
  FIXED: 2,
} as const;

export const TEXT_KIND = 4;

export const BOOST_STRIP = 8;

export const SPRAY_Y_OFFSET = 7680;

export const WHEELSPIN_RAMP = 756;

export function packParams(
  mode: number,
  frames: number,
  frame: number,
  shift: number,
): number {
  return (
    (((frames & 0xff) << 24) |
      ((shift & 0xff) << 16) |
      ((frame & 0xff) << 8) |
      (mode & 0xff)) >>>
    0
  );
}

export function stripFrames(strip: number): number {
  const row = SPRITE_STRIPS[strip];
  if (!row) throw new Error(`no sprite strip ${strip}`);
  return row.frames;
}

export interface ParticleCamera {
  readonly x: number;
  readonly y: number;
}

export class ParticleFx {
  readonly container = new Container({ label: 'fx' });

  readonly slots = new Int32Array(EFFECT_SLOTS * EFFECT_STRIDE);

  private readonly lines = new Graphics({ label: 'fx-lines' });

  private readonly sprites: Sprite[] = [];

  private readonly textures: TextureLookup;

  spawned = 0;

  constructor(textures: TextureLookup) {
    this.textures = textures;

    this.container.addChild(this.lines);
    for (let slot = 0; slot < EFFECT_SLOTS; slot += 1) {
      const sprite = new Sprite({ visible: false, scale: SPRITE_SCALE });
      this.sprites.push(sprite);
      this.container.addChild(sprite);
    }
  }

  spawn(x: number, y: number, kind: number, life: number): number {
    for (let slot = 0; slot < EFFECT_SLOTS; slot += 1) {
      const at = slot * EFFECT_STRIDE;
      if (this.slots[at + EFFECT_LIFE] !== 0) continue;

      this.slots[at + EFFECT_X] = x;
      this.slots[at + EFFECT_PREVIOUS_X] = x;
      this.slots[at + EFFECT_Y] = y;
      this.slots[at + EFFECT_PREVIOUS_Y] = y;
      this.slots[at + EFFECT_KIND] = kind;
      this.slots[at + EFFECT_LIFE] = life;
      this.slots[at + EFFECT_PARAMS] = 0;
      this.spawned += 1;
      return slot;
    }
    return -1;
  }

  set(slot: number, field: number, value: number): void {
    this.slots[slot * EFFECT_STRIDE + field] = value;
  }

  get(slot: number, field: number): number {
    return this.slots[slot * EFFECT_STRIDE + field]!;
  }

  setParams(
    slot: number,
    mode: number,
    frames: number,
    frame: number,
    shift: number,
  ): void {
    this.slots[slot * EFFECT_STRIDE + EFFECT_PARAMS] = packParams(
      mode,
      frames,
      frame,
      shift,
    );
  }

  get live(): number {
    let count = 0;
    for (let at = 0; at < this.slots.length; at += EFFECT_STRIDE) {
      if (this.slots[at + EFFECT_LIFE] !== 0) count += 1;
    }
    return count;
  }

  step(): void {
    const slots = this.slots;
    for (let at = 0; at < slots.length; at += EFFECT_STRIDE) {
      if (slots[at + EFFECT_LIFE] === 0) continue;

      const x = slots[at + EFFECT_X]!;
      const y = slots[at + EFFECT_Y]!;
      slots[at + EFFECT_X] = x + (x - slots[at + EFFECT_PREVIOUS_X]!);
      slots[at + EFFECT_Y] = y + (y - slots[at + EFFECT_PREVIOUS_Y]!);
      if ((slots[at + EFFECT_KIND]! & NO_GRAVITY) === 0) {
        slots[at + EFFECT_Y] = slots[at + EFFECT_Y]! + GRAVITY;
      }
      slots[at + EFFECT_PREVIOUS_X] = x;
      slots[at + EFFECT_PREVIOUS_Y] = y;
      slots[at + EFFECT_LIFE] = slots[at + EFFECT_LIFE]! - 1;
    }
  }

  clear(): void {
    for (let at = 0; at < this.slots.length; at += EFFECT_STRIDE) {
      this.slots[at + EFFECT_LIFE] = 0;
    }
  }

  sync(camera: ParticleCamera): void {
    this.lines.clear();

    for (let slot = 0; slot < EFFECT_SLOTS; slot += 1) {
      this.syncSlot(slot, camera);
    }
  }

  private syncSlot(slot: number, camera: ParticleCamera): void {
    const slots = this.slots;
    const at = slot * EFFECT_STRIDE;
    const sprite = this.sprites[slot]!;
    if (slots[at + EFFECT_LIFE] === 0) {
      sprite.visible = false;
      return;
    }

    const kind = slots[at + EFFECT_KIND]!;
    let x = slots[at + EFFECT_X]! / FIXED_ONE;
    let y = slots[at + EFFECT_Y]! / FIXED_ONE;

    if (kind < 0) {
      sprite.visible = false;
      this.strokeTrail(at, x, y, kind);
      return;
    }

    if ((kind & ~SCREEN_SPACE) === TEXT_KIND) {
      sprite.visible = false;
      return;
    }

    const params = slots[at + EFFECT_PARAMS]!;
    const frame = this.animateFrame(at, params);

    if ((params & SCREEN_SPACE) !== 0) {
      x += camera.x;
      y += camera.y;
    }

    this.paintSprite(sprite, kind, frame, x, y);
  }

  private strokeTrail(at: number, x: number, y: number, kind: number): void {
    const slots = this.slots;
    this.lines
      .moveTo(x, y)
      .lineTo(
        slots[at + EFFECT_PREVIOUS_X]! / FIXED_ONE,
        slots[at + EFFECT_PREVIOUS_Y]! / FIXED_ONE,
      )
      .stroke({ width: 1, color: kind & 0xffffff, alignment: 0.5 });
  }

  private animateFrame(at: number, params: number): number {
    const slots = this.slots;
    const mode = params & 0x3f;
    let frame = 0;
    if (mode === ANIM.LIFE) {
      frame = slots[at + EFFECT_LIFE]! >> ((params & 0xff0000) >> 16);
    } else if (mode === ANIM.FIXED) {
      frame = (params & 0xff00) >> 8;
    } else if (mode === ANIM.CYCLE) {
      const shift = (params & 0xff0000) >> 16;
      const frames = (params & 0xff000000) >>> 24;
      frame = (params & 0xff00) >> 8;
      if ((slots[at + EFFECT_LIFE]! & shift) === 0) {
        frame += 1;
        if (frame >= frames) {
          frame -= frames;
          slots[at + EFFECT_PARAMS] = packParams(mode, frames, frame, shift);
        }
      }
    }
    return frame;
  }

  private paintSprite(
    sprite: Sprite,
    kind: number,
    frame: number,
    x: number,
    y: number,
  ): void {
    const texture = this.textures[stripFrame(kind, frame)];
    if (!texture) throw new Error(`no atlas frame '${stripFrame(kind, frame)}'`);

    if (sprite.texture !== texture) {
      sprite.texture = texture;
      const pivot = stripPivot(kind);
      anchorAt(sprite, pivot.x, pivot.y);
    }
    sprite.position.set(x, y);
    sprite.visible = true;
  }

  destroy(): void {
    this.container.destroy({ children: true });
  }
}

export interface SprayEmitterSource {
  readonly jointX: Int32Array;
  readonly jointY: Int32Array;
  readonly joints: Int32Array;
  readonly dustFlags: Uint8Array;
  readonly state: Int32Array;
  readonly rearGrounded: boolean;
  readonly frontGrounded: boolean;
  readonly driveImpulse: number;
  readonly throttleRamp: number;
  readonly groundSpeed: number;
  readonly wheelStiffness: number;
  readonly crashTimer: number;
  readonly boosting: boolean;
  readonly spraySprite: number;
}

export function emitBikeSpray(
  fx: ParticleFx,
  bike: SprayEmitterSource,
  finished: boolean,
): void {
  if (bike.rearGrounded && bike.driveImpulse > 0) {
    if (bike.throttleRamp > WHEELSPIN_RAMP) spawnSpray(fx, bike, JOINT.REAR_WHEEL);

    if (!finished) {
      if (bike.boosting) spawnBoost(fx, bike);

      if (
        bike.groundSpeed > bike.state[STATE.TOP_SPEED]! >> 2 &&
        bike.wheelStiffness !== bike.state[STATE.SURFACE_GRIP]
      ) {
        if (bike.rearGrounded) spawnSpray(fx, bike, JOINT.REAR_WHEEL);
        if (bike.frontGrounded) spawnSpray(fx, bike, JOINT.FRONT_WHEEL);
      }
    }
  }

  for (let joint = 0; joint < bike.dustFlags.length; joint += 1) {
    if (bike.dustFlags[joint]! > 0) spawnSpray(fx, bike, joint);
  }
}

function spawnSpray(fx: ParticleFx, bike: SprayEmitterSource, joint: number): void {
  if (bike.crashTimer === 0) return;

  const strip = bike.spraySprite;
  const frames = stripFrames(strip);
  const slot = fx.spawn(
    bike.jointX[joint]!,
    bike.jointY[joint]! + SPRAY_Y_OFFSET,
    strip,
    frames << 1,
  );
  if (slot >= 0) fx.setParams(slot, ANIM.LIFE | NO_GRAVITY, frames, 0, 1);
  bike.dustFlags[joint] = 0;
}

function spawnBoost(fx: ParticleFx, bike: SprayEmitterSource): void {
  const at = jointAt(JOINT.REAR_WHEEL);
  const frames = stripFrames(BOOST_STRIP);
  const slot = fx.spawn(
    bike.joints[at + JOINT_PREVIOUS_X]!,
    bike.joints[at + JOINT_PREVIOUS_Y]! + SPRAY_Y_OFFSET,
    BOOST_STRIP,
    frames << 1,
  );
  if (slot >= 0) fx.setParams(slot, ANIM.LIFE | NO_GRAVITY, frames, 0, 1);
}
