import { Container, Graphics, Sprite, Texture } from 'pixi.js';

import { inverseLengthFixed } from '../core/fixed.ts';
import { FIXED_SHIFT, SPRITE_STRIPS } from '../data/constants.ts';
import { STATE } from '../game/Bike.ts';

import { SPRITE_SCALE, texels } from './units.ts';

const FIXED_ONE = 1 << FIXED_SHIFT;

export interface BikeViewSource {
  readonly jointX: Int32Array;
  readonly jointY: Int32Array;
  readonly state: Int32Array;
  readonly bikeVariant: number;
  readonly wheelPhase: number;
}

export const BODY_RECORDS = [97, 98, 99, 100, 101] as const;

export const BODY_PIVOT_BIAS = [3, 3, 3, 3, 7] as const;

export const HIDDEN_COLOUR = 4;

export const FORK_COLOUR = 0xc0c0c0;

export const FRONT_WHEEL_STRIP = 6;
export const REAR_WHEEL_STRIP = 7;

export const RIDER_SEGMENTS = [
  { record: 108, from: 4, to: 5, pivotBias: 0 },
  { record: 102, from: 4, to: 9, pivotBias: -6 },
  { record: 105, from: 4, to: 6, pivotBias: 0 },
  { record: 111, from: 5, to: 8, pivotBias: 0 },
  { record: 114, from: 8, to: 7, pivotBias: 0 },
] as const;

export const RIDER_VARIANTS = 3;

export const STRIP_SLUGS = [
  'hud/bar',
  'hud/icon',
  'hud/throttle',
  'hud/progress',
  'hud/digit',
  'sprites/marker',
  'bike/wheel-front',
  'bike/wheel-rear',
  'fx/boost',
  'sprites/strip-09',
  'sprites/strip-10',
  'sprites/strip-11',
  'sprites/strip-12',
  'hud/glyph',
  'sprites/strip-14',
  'sprites/strip-15',
  'sprites/strip-16',
  'sprites/strip-17',
  'sprites/strip-18',
  'sprites/strip-19',
  'sprites/strip-20',
] as const;

export const RECORD_SLUGS: Record<number, string> = {
  0: 'ui/title',
  1: 'ui/logo',
  2: 'ui/splash',
  4: 'tilesets/env-0',
  5: 'tilesets/env-1',
  6: 'tilesets/env-2',
  7: 'tilesets/env-3',
  84: 'softkeys/icon-0',
  85: 'softkeys/icon-1',
  86: 'softkeys/icon-2',
  89: 'fx/backdrop',
};

for (let colour = 0; colour < BODY_RECORDS.length; colour += 1) {
  RECORD_SLUGS[BODY_RECORDS[colour]!] = `bike/body-${colour}`;
}

for (let limb = 0; limb < RIDER_SEGMENTS.length * RIDER_VARIANTS; limb += 1) {
  const base = Math.floor(limb / RIDER_VARIANTS);
  RECORD_SLUGS[102 + limb] = `bike/limb-${base}-${limb % RIDER_VARIANTS}`;
}

SPRITE_STRIPS.forEach((row, strip) => {
  if (row.frames === 1) RECORD_SLUGS[row.record] = STRIP_SLUGS[strip]!;
});

const STRIP_NAMES: string[][] = [];
const STRIP_PIVOTS: StripPivot[] = [];

export function recordFrame(record: number): string {
  const name = RECORD_SLUGS[record];
  if (name === undefined) throw new Error(`no atlas frame for record ${record}`);
  return name;
}

export function stripFrame(strip: number, frame: number): string {
  const row = (STRIP_NAMES[strip] ??= []);
  const cached = row[frame];
  if (cached !== undefined) return cached;

  const slug = STRIP_SLUGS[strip];
  if (slug === undefined) throw new Error(`no sprite strip ${strip}`);

  const name =
    SPRITE_STRIPS[strip]!.frames === 1
      ? slug
      : `${slug}/${String(frame).padStart(3, '0')}`;
  row[frame] = name;
  return name;
}

export interface StripPivot {
  readonly x: number;
  readonly y: number;
  readonly height: number;
}

export function stripPivot(strip: number): StripPivot {
  const cached = STRIP_PIVOTS[strip];
  if (cached !== undefined) return cached;

  const row = SPRITE_STRIPS[strip];
  if (!row) throw new Error(`no sprite strip ${strip}`);

  const height = row.height / row.frames;
  const pivot: StripPivot = {
    x: row.pivotX === -2 ? row.width >> 1 : row.pivotX === -3 ? row.width : row.pivotX,
    y: row.pivotY === -2 ? height >> 1 : row.pivotY === -5 ? height : row.pivotY,
    height,
  };
  STRIP_PIVOTS[strip] = pivot;
  return pivot;
}

export type TextureLookup = Readonly<Record<string, Texture>>;

export class BikeView {
  readonly container = new Container({ label: 'bike' });

  private readonly fork = new Graphics();
  private readonly frontWheel: Sprite;
  private readonly rearWheel: Sprite;
  private readonly body: Sprite;
  private readonly limbs: Sprite[] = [];

  private readonly textures: TextureLookup;

  private colour = -1;
  private variant = -1;

  constructor(textures: TextureLookup) {
    this.textures = textures;

    const wheel = stripPivot(FRONT_WHEEL_STRIP);
    const rearPivot = stripPivot(REAR_WHEEL_STRIP);
    this.frontWheel = new Sprite({
      texture: frame(textures, stripFrame(FRONT_WHEEL_STRIP, 0)),
      scale: SPRITE_SCALE,
    });
    this.rearWheel = new Sprite({
      texture: frame(textures, stripFrame(REAR_WHEEL_STRIP, 0)),
      scale: SPRITE_SCALE,
    });
    anchorAt(this.frontWheel, wheel.x, wheel.y);
    anchorAt(this.rearWheel, rearPivot.x, rearPivot.y);

    this.body = new Sprite({
      texture: frame(textures, recordFrame(BODY_RECORDS[0])),
      scale: SPRITE_SCALE,
    });
    this.body.anchor.set(0.5);

    for (const segment of RIDER_SEGMENTS) {
      const limb = new Sprite({
        texture: frame(textures, recordFrame(segment.record)),
        scale: SPRITE_SCALE,
      });
      limb.anchor.set(0.5);
      this.limbs.push(limb);
    }

    this.container.addChild(this.fork, this.frontWheel, this.rearWheel, this.body);
    this.container.addChild(...this.limbs);
  }

  sync(bike: BikeViewSource): void {
    const colour = bike.state[STATE.COLOUR] ?? 0;
    const variant = bike.bikeVariant;

    this.syncChassis(bike, colour);
    this.syncBody(bike, colour);
    this.syncRider(bike, variant);
  }

  destroy(): void {
    this.container.destroy({ children: true });
  }

  private syncChassis(bike: BikeViewSource, colour: number): void {
    const visible = colour !== HIDDEN_COLOUR;
    this.fork.visible = visible;
    this.frontWheel.visible = visible;
    this.rearWheel.visible = visible;
    if (!visible) return;

    const frontX = bike.jointX[1]! / FIXED_ONE;
    const frontY = bike.jointY[1]! / FIXED_ONE;
    const wheelX = bike.jointX[3]! / FIXED_ONE;
    const wheelY = bike.jointY[3]! / FIXED_ONE;

    this.fork
      .clear()
      .moveTo(frontX, frontY)
      .lineTo(wheelX, wheelY)
      .stroke({ width: 1, color: FORK_COLOUR, alignment: 0.5 });

    const spin = bike.wheelPhase >> FIXED_SHIFT;
    this.frontWheel.texture = frame(this.textures, stripFrame(FRONT_WHEEL_STRIP, spin));
    this.rearWheel.texture = frame(this.textures, stripFrame(REAR_WHEEL_STRIP, spin));
    this.frontWheel.position.set(wheelX, wheelY);
    this.rearWheel.position.set(bike.jointX[2]! / FIXED_ONE, bike.jointY[2]! / FIXED_ONE);
  }

  private syncBody(bike: BikeViewSource, colour: number): void {
    if (colour !== this.colour) {
      const record = BODY_RECORDS[colour];
      if (record === undefined) throw new Error(`no bike body for colour ${colour}`);
      this.body.texture = frame(this.textures, recordFrame(record));
      this.colour = colour;
    }

    placeBetween(this.body, bike, 0, 1, BODY_PIVOT_BIAS[colour] ?? 0);
  }

  private syncRider(bike: BikeViewSource, variant: number): void {
    if (variant !== this.variant) {
      if (variant < 0 || variant >= RIDER_VARIANTS)
        throw new Error(`no rider variant ${variant}`);
      for (let i = 0; i < RIDER_SEGMENTS.length; i += 1) {
        const segment = RIDER_SEGMENTS[i]!;
        this.limbs[i]!.texture = frame(
          this.textures,
          recordFrame(segment.record + variant),
        );
      }
      this.variant = variant;
    }

    for (let i = 0; i < RIDER_SEGMENTS.length; i += 1) {
      const segment = RIDER_SEGMENTS[i]!;
      placeBetween(this.limbs[i]!, bike, segment.from, segment.to, segment.pivotBias);
    }
  }
}

export function anchorAt(sprite: Sprite, pivotX: number, pivotY: number): void {
  sprite.anchor.set(
    texels(pivotX) / sprite.texture.width,
    texels(pivotY) / sprite.texture.height,
  );
}

function placeBetween(
  sprite: Sprite,
  bike: BikeViewSource,
  from: number,
  to: number,
  pivotBias: number,
): void {
  const fromX = bike.jointX[from]!;
  const fromY = bike.jointY[from]!;
  const dx = bike.jointX[to]! - fromX;
  const dy = bike.jointY[to]! - fromY;

  const inverse = inverseLengthFixed(dx, dy);
  const axisX = (dx * inverse) >> FIXED_SHIFT;
  const axisY = (dy * inverse) >> FIXED_SHIFT;

  const biasX = -pivotBias * axisY;
  const biasY = pivotBias * axisY + pivotBias * axisX;

  sprite.position.set(
    (fromX + dx / 2 + biasX) / FIXED_ONE,
    (fromY + dy / 2 + biasY) / FIXED_ONE,
  );
  sprite.rotation = Math.atan2(axisY, axisX);
}

function frame(textures: TextureLookup, name: string): Texture {
  const texture = textures[name];
  if (!texture) throw new Error(`no atlas frame '${name}'`);
  return texture;
}
