import { SCREEN_WIDTH } from '../core/config.ts';
import { fixedDiv, fixedMul, inverseLengthFixed } from '../core/fixed.ts';
import {
  ANIMATION,
  ANIMATIONS,
  CRASH_ANIMATION,
  ENVIRONMENTS,
  FIXED_ONE,
  FIXED_SHIFT,
  JOINTS,
  PARTS,
  POSE_JOINTS,
  POSE_STRIDE,
  RIDER_INITIAL_STATE,
  RIDER_STATE_SLOTS,
  TRACKS,
  WHEEL_FRAMES,
} from '../data/constants.ts';

import { SNAPSHOT_TAIL_FIELDS } from '../data/snapshot-layout.ts';

import {
  buildJoints,
  integrate,
  JOINT_PREVIOUS_X,
  JOINT_PREVIOUS_Y,
  JOINT_STRIDE,
  JOINT_X,
  JOINT_Y,
  JointRef,
  measureAngleLimits,
  measureLinks,
  measureSuspension,
  relaxConstraints,
  TerrainContact,
  translateJoints,
} from './Physics.ts';
import {
  BIKE_INPUT,
  BIKE_LINKS,
  BIKE_SUSPENSION,
  COYOTE_FRAMES,
  CRASH_TICKS,
  DRAW_MARGIN,
  FRONT_LINK_STIFFNESS,
  HALF_PIXEL,
  JOINT,
  MAX_BOOST_CHARGES,
  REAR_LINK_STIFFNESS,
  RIDER_ANGLE_LIMITS,
  RIDER_LINKS,
  SNAPSHOT_JOINT_SLOTS,
  STATE,
  WHEELSPIN_RAMP,
} from './BikeLayout.ts';
import { Terrain } from './Terrain.ts';
import { TrickScorer } from './TrickScoring.ts';

import type { SnapshotTailField } from '../data/snapshot-layout.ts';
import type { Bounds, Heading } from './Physics.ts';

type TailAccessor = readonly [
  read: (bike: Bike) => number,
  write: (bike: Bike, value: number) => void,
];

export {
  BIKE_INPUT,
  BIKE_LENGTH_FIXED,
  JOINT,
  STATE,
  TRICK,
  TRICK_SLOTS,
} from './BikeLayout.ts';

export interface BikeOptions {
  isOpponent?: boolean;
}

export class Bike {
  private readonly tricks = new TrickScorer();
  readonly trickTotals = this.tricks.totals;
  readonly trickPending = this.tricks.pending;
  readonly dustFlags = new Uint8Array(JOINTS.length);

  state = new Int32Array(RIDER_STATE_SLOTS);

  joints: Int32Array = new Int32Array(0);
  jointX: Int32Array = new Int32Array(0);
  jointY: Int32Array = new Int32Array(0);
  rearWheelPreviousX = 0;

  readonly contact: TerrainContact;
  protected readonly terrain: Terrain;
  readonly isOpponent: boolean;

  private readonly bikeLinks = Int32Array.from(BIKE_LINKS);
  private readonly riderLinks = Int32Array.from(RIDER_LINKS);
  private readonly bikeSuspension = Int32Array.from(BIKE_SUSPENSION);
  private readonly riderSuspension = new Int32Array(0);
  private readonly bikeAngleLimits = new Int32Array(0);
  private readonly riderAngleLimits = Int32Array.from(RIDER_ANGLE_LIMITS);

  private readonly contactNormal = new Int32Array(2);
  readonly rearContactNormal = new Int32Array(2);
  readonly frontContactNormal = new Int32Array(2);

  rearGrounded = false;
  frontGrounded = false;

  crashTimer = 0;
  private settling = false;
  startX = 0;
  leftLimitX = 0;

  private inverseBodyLength = 0;
  fittedParts = 0;

  groundSpeed = 0;
  throttleRamp = 0;
  driveImpulse = 0;
  wheelStiffness = 0;
  private airborneFrames = 0;

  headingX = 0;
  headingY = 0;
  protected previousHeadingY = 0;
  private anchorX = 0;
  private anchorY = 0;

  lean = 0;
  private leanInput = false;

  animation = 0;
  animationProgress = 0;
  private animationFrames = 0;
  private posePoints = new Int32Array(POSE_STRIDE);

  private sprayStrip = 0;
  private sprayThreshold = 0;
  wheelPhase = 0;

  drawLeft = 0;
  drawRight = 0;
  readonly bounds: Bounds = { minX: 0, maxX: 0, minY: 0, maxY: 0 };

  boostCharges = 0;
  private boostTimer = -1;
  private boostPower = 0;
  private boostHeld = false;

  gapToPlayer = 0;
  opponentProfile = -1;
  protected aiTargetHeight = 0;

  track = 0;
  wrapCount = 0;
  bikeVariant = 0;

  protected inputBits = 0;

  private readonly heading: Heading = { x: 0, y: 0 };

  private readonly jointRefs: readonly JointRef[] = JOINTS.map(
    (_, index) => new JointRef(this, index),
  );

  private static readonly TAIL_BY_FIELD: Record<SnapshotTailField, TailAccessor> = {
    animation: [(b) => b.animation, (b, v) => b.restoreAnimation(v)],
    animationProgress: [
      (b) => b.animationProgress,
      (b, v) => void (b.animationProgress = v),
    ],
    lean: [(b) => b.lean, (b, v) => void (b.lean = v)],
    driveImpulse: [(b) => b.driveImpulse, (b, v) => void (b.driveImpulse = v)],
    wheelStiffness: [(b) => b.wheelStiffness, (b, v) => void (b.wheelStiffness = v)],
    rearContactNormalX: [
      (b) => b.rearContactNormal[0]!,
      (b, v) => void (b.rearContactNormal[0] = v),
    ],
    rearContactNormalY: [
      (b) => b.rearContactNormal[1]!,
      (b, v) => void (b.rearContactNormal[1] = v),
    ],
    rearGrounded: [
      (b) => (b.rearGrounded ? 1 : 0),
      (b, v) => void (b.rearGrounded = v !== 0),
    ],
    frontGrounded: [
      (b) => (b.frontGrounded ? 1 : 0),
      (b, v) => void (b.frontGrounded = v !== 0),
    ],
    headingX: [(b) => b.headingX, (b, v) => void (b.headingX = v)],
    headingY: [(b) => b.headingY, (b, v) => void (b.headingY = v)],
    groundSpeed: [(b) => b.groundSpeed, (b, v) => void (b.groundSpeed = v)],
    airborneFrames: [(b) => b.airborneFrames, (b, v) => void (b.airborneFrames = v)],
    leanInput: [(b) => (b.leanInput ? 1 : 0), (b, v) => void (b.leanInput = v !== 0)],
    boostPower: [(b) => b.boostPower, (b, v) => void (b.boostPower = v)],
    boostTimer: [(b) => b.boostTimer, (b, v) => void (b.boostTimer = v)],
    boostCharges: [(b) => b.boostCharges, (b, v) => void (b.boostCharges = v)],
    boostHeld: [(b) => (b.boostHeld ? 1 : 0), (b, v) => void (b.boostHeld = v !== 0)],
    bikeVariant: [(b) => b.bikeVariant, (b, v) => void (b.bikeVariant = v)],
    fittedParts: [(b) => b.fittedParts, (b, v) => void (b.fittedParts = v)],
  };

  private static readonly TAIL_ACCESSORS: readonly TailAccessor[] =
    SNAPSHOT_TAIL_FIELDS.map((field) => Bike.TAIL_BY_FIELD[field]);

  constructor(terrain: Terrain, options: BikeOptions = {}) {
    this.terrain = terrain;
    this.isOpponent = options.isOpponent ?? false;
    this.contact = new TerrainContact(terrain);
  }

  static forTrack<T extends Bike>(
    this: new (terrain: Terrain, options?: BikeOptions) => T,
    track: number,
    options: BikeOptions = {},
  ): T {
    const bike = new this(Terrain.forTrack(track), options);
    bike.buildSkeleton();
    bike.setTrack(track);
    return bike;
  }

  private restoreAnimation(animation: number): void {
    this.animation = animation;
    this.animationFrames =
      animation < CRASH_ANIMATION ? ANIMATIONS[animation]!.frames : 0;
  }

  joint(index: number): JointRef {
    return this.jointRefs[index]!;
  }

  buildSkeleton(): void {
    this.state = Int32Array.from(RIDER_INITIAL_STATE);
    this.joints = buildJoints(JOINTS);
    this.jointX = new Int32Array(JOINTS.length);
    this.jointY = new Int32Array(JOINTS.length);

    measureLinks(this.joints, this.bikeLinks);
    measureSuspension(this.joints, this.bikeSuspension);
    measureAngleLimits(this.joints, this.bikeAngleLimits);
    measureLinks(this.joints, this.riderLinks);
    measureSuspension(this.joints, this.riderSuspension);
    measureAngleLimits(this.joints, this.riderAngleLimits);

    const rear = this.joint(JOINT.CHASSIS_REAR);
    const front = this.joint(JOINT.CHASSIS_FRONT);
    this.inverseBodyLength = inverseLengthFixed(front.x - rear.x, front.y - rear.y);
    this.posePoints = new Int32Array(POSE_STRIDE);
  }

  setTrack(track: number): void {
    this.track = track;
    const environment = ENVIRONMENTS[TRACKS[track]!.environment]!;
    this.sprayStrip = environment.sprayStrip;
    this.sprayThreshold = environment.sprayThreshold;
    this.crashTimer = 1;
  }

  setSurfaceGrip(grip: number): void {
    this.state[STATE.SURFACE_GRIP] = grip;
  }

  applyParts(mask: number): void {
    this.fittedParts = mask;
    this.state[STATE.BOOST_POWER] = 0;
    this.state[STATE.BOOST_DURATION] = 0;
    for (let i = 0; i < PARTS.length; i += 1) {
      if ((mask & (1 << i)) === 0) continue;
      const part = PARTS[i]!;
      if (part.stateA < RIDER_STATE_SLOTS) this.state[part.stateA] = part.valueA;
      if (part.stateB < RIDER_STATE_SLOTS) this.state[part.stateB] = part.valueB;
      if (part.stateC < RIDER_STATE_SLOTS) this.state[part.stateC] = part.valueC;
    }
    this.bikeLinks[REAR_LINK_STIFFNESS] = this.state[STATE.REAR_LINK]!;
    this.bikeLinks[FRONT_LINK_STIFFNESS] = this.state[STATE.FRONT_LINK]!;
    this.boostPower = this.state[STATE.BOOST_POWER]!;
  }

  resetBoost(): void {
    this.boostCharges = this.state[STATE.BOOST_POWER] !== 0 ? 1 : 0;
    this.boostTimer = -1;
  }

  snapshotSize(): number {
    return (
      this.state.length +
      (this.joints.length / JOINT_STRIDE) * SNAPSHOT_JOINT_SLOTS.length +
      Bike.TAIL_ACCESSORS.length
    );
  }

  saveSnapshot(out: Int32Array, at = 0): void {
    let n = at;
    out.set(this.state, n);
    n += this.state.length;
    for (let joint = 0; joint < this.joints.length; joint += JOINT_STRIDE) {
      for (const slot of SNAPSHOT_JOINT_SLOTS) out[n++] = this.joints[joint + slot]!;
    }
    for (const [read] of Bike.TAIL_ACCESSORS) out[n++] = read(this);
  }

  loadSnapshot(source: ArrayLike<number>, at = 0): void {
    let n = at;
    for (let i = 0; i < this.state.length; i += 1) this.state[i] = source[n++]!;
    for (let joint = 0; joint < this.joints.length; joint += JOINT_STRIDE) {
      for (const slot of SNAPSHOT_JOINT_SLOTS) this.joints[joint + slot] = source[n++]!;
    }
    for (const [, write] of Bike.TAIL_ACCESSORS) write(this, source[n++]!);
    if (this.boostPower === 0) this.boostCharges = 0;
    this.bikeLinks[REAR_LINK_STIFFNESS] = this.state[STATE.REAR_LINK]!;
    this.bikeLinks[FRONT_LINK_STIFFNESS] = this.state[STATE.FRONT_LINK]!;
    this.syncJointPixels();
  }

  pressInput(bits: number): void {
    this.inputBits |= bits;
  }

  requestTrick(animation: number): void {
    if (this.crashTimer >= 0) return;
    this.inputBits &= ~BIKE_INPUT.TRICK_MASK;
    this.inputBits |= animation;
  }

  protected sampleInput(): void {}

  protected retainsInput(): boolean {
    return false;
  }

  step(): void {
    this.applyInput();
    this.solveConstraints();
    this.stepAnimation();
    this.collideTerrain();
    this.wrapWorld();
    this.syncJointPixels();
  }

  private applyInput(): void {
    this.sampleInput();

    const bits = this.resolveBoost(this.inputBits);

    if ((bits & BIKE_INPUT.TRICK_MASK) !== 0) {
      this.startAnimation(bits & BIKE_INPUT.TRICK_MASK);
      this.inputBits &= ~BIKE_INPUT.TRICK_MASK;
    }

    if ((bits & BIKE_INPUT.THROTTLE) !== 0) this.applyThrottle(1);
    else if ((bits & BIKE_INPUT.BRAKE) !== 0) this.applyThrottle(-1);
    else this.applyThrottle(0);

    if ((bits & BIKE_INPUT.LEAN_RIGHT) !== 0) this.applyLean(1);
    if ((bits & BIKE_INPUT.LEAN_LEFT) !== 0) this.applyLean(-1);

    if (!this.retainsInput()) this.inputBits = 0;

    this.applyDrive();
    this.applyLeanTorque();

    integrate(this.joints, this.state[STATE.GRAVITY]!, this.leftLimitX, this.bounds);

    this.advanceWheelPhase();
  }

  private resolveBoost(bits: number): number {
    if ((bits & BIKE_INPUT.BOOST) !== BIKE_INPUT.BOOST) {
      this.boostHeld = false;
      return bits;
    }
    if (!this.boostHeld) this.boostHeld = this.tryBoost();
    return bits & ~BIKE_INPUT.BRAKE;
  }

  private applyDrive(): void {
    if (!this.rearGrounded) return;
    const rear = this.joint(JOINT.REAR_WHEEL);
    rear.forceX = fixedMul(this.driveImpulse, this.rearContactNormal[0]!);
    rear.forceY = fixedMul(this.driveImpulse, this.rearContactNormal[1]!);
  }

  private applyLeanTorque(): void {
    if (this.lean === 0) return;

    const a = this.joint(JOINT.CHASSIS_REAR);
    const b = this.joint(JOINT.CHASSIS_FRONT);
    const weightA = a.weight;
    const weightB = b.weight;
    const perpendicularX = this.headingY;
    const perpendicularY = -this.headingX;
    let torque =
      (Math.imul(this.state[STATE.LEAN_TORQUE]!, this.lean) / (weightA + weightB)) | 0;

    a.forceX = fixedMul(fixedMul(perpendicularX, torque), weightA);
    a.forceY = fixedMul(fixedMul(perpendicularY, torque), weightA);
    torque = -torque;
    b.forceX = fixedMul(fixedMul(perpendicularX, torque), weightB);
    b.forceY = fixedMul(fixedMul(perpendicularY, torque), weightB);

    if (!this.leanInput) {
      this.lean = fixedMul(this.lean, this.state[STATE.LEAN_DECAY]!);
      this.lean += this.lean < 0 ? 1 : 0;
    }
    this.leanInput = false;
  }

  private advanceWheelPhase(): void {
    let spin = this.groundSpeed < 0 ? -this.groundSpeed : this.groundSpeed;
    if (spin > FIXED_ONE) spin = FIXED_ONE;
    this.wheelPhase += spin;
    const wrap = WHEEL_FRAMES << FIXED_SHIFT;
    if (this.wheelPhase >= wrap) this.wheelPhase %= wrap;
  }

  private applyThrottle(direction: number): void {
    this.driveImpulse = 0;
    if (!this.canSteer()) return;

    const surfaceGrip = this.state[STATE.SURFACE_GRIP]!;
    const tireGrip = this.state[STATE.TIRE_GRIP]!;
    const rear = this.joint(JOINT.REAR_WHEEL);
    const dx = rear.x - rear.previousX;
    const dy = rear.y - rear.previousY;
    this.groundSpeed =
      (Math.imul(this.rearContactNormal[0]!, dx) +
        Math.imul(this.rearContactNormal[1]!, dy)) >>
      FIXED_SHIFT;

    if (direction > 0 && this.rearGrounded) {
      const power =
        this.state[STATE.ENGINE_POWER]! +
        (this.boostTimer > 0 ? this.boostPower : 0) -
        this.enginePenalty();
      const topSpeed = this.state[STATE.TOP_SPEED]!;
      let ramp = fixedDiv(topSpeed - this.groundSpeed, topSpeed);
      if (ramp > FIXED_ONE) ramp = FIXED_ONE;
      this.throttleRamp = ramp;
      const grip = Math.min(tireGrip + surfaceGrip, FIXED_ONE);
      this.driveImpulse =
        ramp > WHEELSPIN_RAMP ? fixedMul(grip, power) : fixedMul(ramp, power);
      this.boostTimer -= 1;
    }

    this.wheelStiffness = surfaceGrip;
    if (direction < 0) {
      this.wheelStiffness =
        Math.imul(surfaceGrip + tireGrip, this.state[STATE.BRAKE_SCALE]!) >> 6;
    }
  }

  protected enginePenalty(): number {
    return 0;
  }

  private applyLean(direction: number): void {
    if (!this.canSteer()) return;
    this.lean = Math.max(-FIXED_ONE, Math.min(FIXED_ONE, this.lean + (direction << 7)));
    this.leanInput = true;
  }

  private tryBoost(): boolean {
    if (
      this.boostTimer < 0 &&
      this.boostCharges > 0 &&
      this.animation !== CRASH_ANIMATION &&
      this.crashTimer < 0
    ) {
      this.boostTimer = this.state[STATE.BOOST_DURATION]!;
      this.boostCharges -= 1;
      return true;
    }
    return false;
  }

  private solveConstraints(): void {
    relaxConstraints(
      this.joints,
      this.bikeLinks,
      this.bikeSuspension,
      this.bikeAngleLimits,
      this.updateHeading,
    );
    if (this.animation === CRASH_ANIMATION) {
      relaxConstraints(
        this.joints,
        this.riderLinks,
        this.riderSuspension,
        this.riderAngleLimits,
        this.updateHeading,
      );
    }
  }

  protected readonly updateHeading = (): Heading => {
    const a = this.joint(JOINT.CHASSIS_REAR);
    const b = this.joint(JOINT.CHASSIS_FRONT);
    this.headingX = fixedMul(b.x - a.x, this.inverseBodyLength);
    this.headingY = fixedMul(b.y - a.y, this.inverseBodyLength);
    this.anchorX = a.x;
    this.anchorY = a.y;
    this.heading.x = this.headingX;
    this.heading.y = this.headingY;
    return this.heading;
  };

  private stepAnimation(): void {
    if (this.animation === 0) {
      this.animationProgress = Math.imul(
        (this.lean + FIXED_ONE) >> 1,
        this.animationFrames - 1,
      );
    }
    const frame = this.animationProgress >> FIXED_SHIFT;
    if (this.animation === CRASH_ANIMATION) return;

    const lastFrame = this.animationFrames - 1;
    this.buildPose(frame);
    this.applyPose();
    this.advanceAnimation(lastFrame);
  }

  private buildPose(frame: number): void {
    const pose = this.posePoints;
    const offsets = ANIMATIONS[this.animation]!.offsets;
    const base = Math.imul(frame, POSE_STRIDE);
    const headingX = this.headingX;
    const headingY = this.headingY;

    for (let i = 0; i < POSE_STRIDE; i += 2) {
      const offsetX = offsets[base + i]!;
      const offsetY = offsets[base + i + 1]!;
      pose[i] =
        ((Math.imul(offsetX, headingX) - Math.imul(offsetY, headingY)) >> FIXED_SHIFT) +
        this.anchorX;
      pose[i + 1] =
        ((Math.imul(offsetX, headingY) + Math.imul(offsetY, headingX)) >> FIXED_SHIFT) +
        this.anchorY;
    }
  }

  private applyPose(): void {
    const pose = this.posePoints;
    for (let i = 0; i < POSE_JOINTS.length; i += 1) {
      const joint = this.joint(POSE_JOINTS[i]!);
      const x = joint.x;
      const y = joint.y;
      joint.x = x + ((pose[i * 2]! - x) >> 1);
      joint.y = y + (pose[i * 2 + 1]! - y);
    }
  }

  private advanceAnimation(lastFrame: number): void {
    if (this.animation === 0 || this.animation === CRASH_ANIMATION) return;
    this.animationProgress += FIXED_ONE;
    if (this.animationProgress > lastFrame << FIXED_SHIFT) {
      this.tricks.completeAnimation(this.animation);
      this.resetAnimation();
    }
  }

  private startAnimation(animation: number): void {
    if (this.animation > 0 && animation !== CRASH_ANIMATION) return;
    this.animation = animation;
    this.animationFrames =
      animation < CRASH_ANIMATION ? ANIMATIONS[animation]!.frames : 0;
    this.animationProgress = 0;
    if (animation === CRASH_ANIMATION) {
      this.clearTrickCounts(true);
      this.crashTimer = CRASH_TICKS;
      this.startX = this.bounds.minX;
    }
  }

  private resetAnimation(): void {
    this.animation = 0;
    this.animationProgress = 0;
    this.animationFrames = ANIMATIONS[ANIMATION.IDLE]!.frames;
  }

  private collideTerrain(): void {
    if (this.crashTimer !== 0) {
      this.crashTimer -= 1;
      if (this.crashTimer === 0) this.placeAtStart();
    }

    this.contact.begin(this.bounds);
    this.collideJoints();
    this.updateGroundState();
    this.enforceAnimationLimits();
    this.accumulateWheelTricks();
  }

  private collideJoints(): void {
    const surfaceGrip = this.state[STATE.SURFACE_GRIP]!;
    const penetrationScale = this.state[STATE.PENETRATION_SCALE]!;
    const tested =
      this.animation !== CRASH_ANIMATION ? 5 : this.joints.length / JOINT_STRIDE;

    for (let i = 0; i < tested; i += 1) {
      const isWheel = i === JOINT.REAR_WHEEL || i === JOINT.FRONT_WHEEL;
      const isContactJoint =
        (i === JOINT.RIDER_HIP && this.animation !== CRASH_ANIMATION) || isWheel;

      let normal = this.contactNormal;
      if (i === JOINT.REAR_WHEEL) normal = this.rearContactNormal;
      else if (i === JOINT.FRONT_WHEEL) normal = this.frontContactNormal;

      const penetration = this.contact.collide(
        this.joints,
        i,
        normal,
        this.contactStiffness(i, isWheel, surfaceGrip) >> 5,
        penetrationScale,
        isContactJoint,
      );
      if (penetration > this.sprayThreshold) this.dustFlags[i] = 1;

      const touching = penetration !== 0;
      if (i === JOINT.REAR_WHEEL) this.rearGrounded = touching;
      if (i === JOINT.FRONT_WHEEL) this.frontGrounded = touching;

      const fatal = i === 0 || i === 1 || i === 4 || i === 7;
      if (fatal && touching && this.crashTimer < 0) this.requestTrick(CRASH_ANIMATION);
    }
  }

  private contactStiffness(index: number, isWheel: boolean, surfaceGrip: number): number {
    let stiffness = isWheel ? this.wheelStiffness : surfaceGrip;
    if (isWheel) {
      if (stiffness !== surfaceGrip) {
        stiffness = (stiffness / 3) | 0;
        if (index === JOINT.FRONT_WHEEL && this.groundSpeed > 0) stiffness <<= 1;
        if (index === JOINT.REAR_WHEEL && this.groundSpeed < 0) stiffness <<= 1;
      } else {
        stiffness += (this.state[STATE.ROLLING_GRIP]! << 1) + surfaceGrip - FIXED_ONE;
        if (stiffness < surfaceGrip) stiffness = surfaceGrip;
      }
    }
    if (index >= 5) stiffness <<= 3;
    return stiffness;
  }

  private updateGroundState(): void {
    this.airborneFrames += 1;
    if (this.rearGrounded || this.frontGrounded) {
      this.airborneFrames = 0;
      return;
    }
    this.beginSpinTracking();
    this.trackSpin();
  }

  private enforceAnimationLimits(): void {
    if (!this.isGrounded()) {
      if (
        this.animation === ANIMATION.GRIZZLY ||
        this.animation === ANIMATION.HEADACHE ||
        this.animation === ANIMATION.CRAZY_COW
      ) {
        this.requestTrick(CRASH_ANIMATION);
      }
      return;
    }
    switch (this.animation) {
      case ANIMATION.IDLE:
      case ANIMATION.GRIZZLY:
      case ANIMATION.HEADACHE:
      case ANIMATION.CRAZY_COW:
      case CRASH_ANIMATION:
        break;
      default:
        this.requestTrick(CRASH_ANIMATION);
    }
  }

  private accumulateWheelTricks(): void {
    if (this.animation === CRASH_ANIMATION) return;
    if (this.rearGrounded && !this.frontGrounded) this.tricks.countWheelie();
    if (!this.rearGrounded && this.frontGrounded) this.tricks.countStoppie();
    if (this.rearGrounded && this.frontGrounded) this.scoreTricks();
  }

  private wrapWorld(): void {
    const trackLength = this.terrain.trackLength;
    if (!this.settling && this.bounds.minX > trackLength + (SCREEN_WIDTH << 9)) {
      translateJoints(this.joints, -trackLength, 0);
      this.bounds.minX -= trackLength;
      this.bounds.maxX -= trackLength;
      this.wrapCount += 1;
    }
    this.drawLeft = (this.bounds.minX - DRAW_MARGIN) >> FIXED_SHIFT;
    this.drawRight = (this.bounds.maxX + DRAW_MARGIN) >> FIXED_SHIFT;
  }

  syncJointPixels(): void {
    for (let i = 0; i < this.jointX.length; i += 1) {
      const joint = this.joint(i);
      this.jointX[i] = joint.x;
      this.jointY[i] = joint.y;
    }
    this.rearWheelPreviousX = this.joint(JOINT.REAR_WHEEL).previousX;
  }

  placeAtStart(): void {
    this.resetAnimation();
    this.clearTrickCounts(true);
    this.boostTimer = -1;
    this.inputBits &= ~0x0b;

    this.resetJointsToStart();
    this.settleOnGround(this.dropToGround());

    for (let at = 0; at < this.joints.length; at += JOINT_STRIDE) {
      this.joints[at + JOINT_PREVIOUS_X] = this.joints[at + JOINT_X]!;
      this.joints[at + JOINT_PREVIOUS_Y] = this.joints[at + JOINT_Y]!;
    }
    this.crashTimer -= 1;
    this.dustFlags.fill(0);
  }

  private resetJointsToStart(): void {
    const offsetX = this.startX - (JOINTS[0]!.x << FIXED_SHIFT);
    for (let i = 0; i < JOINTS.length; i += 1) {
      const joint = this.joint(i);
      const x = (JOINTS[i]!.x << FIXED_SHIFT) + offsetX;
      const y = JOINTS[i]!.y << FIXED_SHIFT;
      joint.x = x;
      joint.previousX = x;
      joint.y = y;
      joint.previousY = y;
      joint.forceX = 0;
      joint.forceY = 0;
    }
  }

  private dropToGround(): JointRef {
    const rear = this.joint(JOINT.REAR_WHEEL);
    const front = this.joint(JOINT.FRONT_WHEEL);
    const rearGround = this.terrain.heightAt(rear.x) - HALF_PIXEL;
    const frontGround = this.terrain.heightAt(front.x) - HALF_PIXEL;
    const onRear = rearGround <= frontGround;

    const pinned = onRear ? rear : front;
    const ground = onRear ? rearGround : frontGround;
    const restJoint = onRear ? JOINT.REAR_WHEEL : JOINT.FRONT_WHEEL;
    const restY = JOINTS[restJoint]!.y << FIXED_SHIFT;

    translateJoints(this.joints, 0, ground - restY - HALF_PIXEL);
    return pinned;
  }

  private settleOnGround(pinned: JointRef): void {
    const rear = this.joint(JOINT.REAR_WHEEL);
    const front = this.joint(JOINT.FRONT_WHEEL);
    const pinnedX = pinned.x;

    this.settling = true;
    for (let i = 9; i > 0; i -= 1) {
      rear.forceY = HALF_PIXEL;
      front.forceY = HALF_PIXEL;
      pinned.x = pinnedX;
      this.crashTimer = 0;
      this.step();
      relaxConstraints(
        this.joints,
        this.bikeLinks,
        this.bikeSuspension,
        this.bikeAngleLimits,
        this.updateHeading,
      );
      this.collideTerrain();
    }
    this.settling = false;
  }

  scoreTricks(): void {
    const airTricks = this.tricks.score();
    if (this.state[STATE.BOOST_POWER]! > 0) {
      this.boostCharges = Math.min(MAX_BOOST_CHARGES, this.boostCharges + airTricks);
    }
  }

  clearTrickCounts(keepTotals: boolean): void {
    this.tricks.clear(keepTotals);
  }

  private beginSpinTracking(): void {
    this.tricks.spin.begin(this.wheelQuadrant());
  }

  private trackSpin(): void {
    this.tricks.spin.track(this.wheelQuadrant());
  }

  private wheelQuadrant(): number {
    const rear = this.joint(JOINT.REAR_WHEEL);
    const front = this.joint(JOINT.FRONT_WHEEL);
    const dx = front.x - rear.x;
    const dy = front.y - rear.y;
    if (dy <= 0) return dx >= 0 ? 0 : 1;
    return dx >= 0 ? 3 : 2;
  }

  canSteer(): boolean {
    switch (this.animation) {
      case ANIMATION.GRIZZLY:
      case ANIMATION.HEADACHE:
      case ANIMATION.CRAZY_COW:
      case CRASH_ANIMATION:
        return false;
      default:
        return true;
    }
  }

  get spinCount(): number {
    return this.tricks.spin.count;
  }

  get spinTracking(): boolean {
    return this.tricks.spin.tracking;
  }

  isGrounded(): boolean {
    return this.airborneFrames < COYOTE_FRAMES;
  }

  get trackLength(): number {
    return this.terrain.trackLength;
  }

  get airborne(): number {
    return this.airborneFrames;
  }

  get spraySprite(): number {
    return this.sprayStrip;
  }

  get boosting(): boolean {
    return this.boostTimer > 0;
  }
}
