import { DESIGN_SCALE, LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../core/config.ts';

export interface SafeAreaInsets {
  readonly top: number;
  readonly right: number;
  readonly bottom: number;
  readonly left: number;
}

export const NO_INSETS: SafeAreaInsets = { top: 0, right: 0, bottom: 0, left: 0 };

export type Orientation = 'portrait' | 'landscape';

export interface ViewportSize {
  readonly width: number;
  readonly height: number;
}

export type VisualViewportLike = EventTarget & ViewportSize;

export interface ViewportView extends EventTarget {
  readonly innerWidth: number;
  readonly innerHeight: number;
  readonly visualViewport?: VisualViewportLike | null;
}

export interface ViewportMetrics {
  readonly scale: number;
  readonly width: number;
  readonly height: number;
  readonly left: number;
  readonly top: number;
  readonly orientation: Orientation;
  readonly insets: SafeAreaInsets;
}

export interface FitOptions {
  readonly logicalWidth?: number;
  readonly logicalHeight?: number;
  readonly insets?: SafeAreaInsets;
}

const MIN_SCALE = 1 / 16;

export function fitViewport(
  size: ViewportSize,
  options: FitOptions = {},
): ViewportMetrics {
  const logicalWidth = options.logicalWidth ?? LOGICAL_WIDTH;
  const logicalHeight = options.logicalHeight ?? LOGICAL_HEIGHT;
  const insets = options.insets ?? NO_INSETS;

  const usableWidth = Math.max(0, size.width - insets.left - insets.right);
  const usableHeight = Math.max(0, size.height - insets.top - insets.bottom);

  const raw = Math.min(usableWidth / logicalWidth, usableHeight / logicalHeight);
  const scale = Math.max(raw, MIN_SCALE);

  const width = logicalWidth * scale;
  const height = logicalHeight * scale;

  return {
    scale,
    width,
    height,
    left: insets.left + (usableWidth - width) / 2,
    top: insets.top + (usableHeight - height) / 2,
    orientation: size.width > size.height ? 'landscape' : 'portrait',
    insets,
  };
}

export interface ViewportCanvas {
  readonly style: Pick<CSSStyleDeclaration, 'width' | 'height'>;
}

export interface ViewportHost {
  readonly style: Pick<CSSStyleDeclaration, 'setProperty'>;
  setAttribute(name: string, value: string): void;
}

export function applyViewport(
  metrics: ViewportMetrics,
  targets: { canvas?: ViewportCanvas; host?: ViewportHost },
): void {
  if (targets.canvas) {
    targets.canvas.style.width = `${metrics.width}px`;
    targets.canvas.style.height = `${metrics.height}px`;
  }
  const host = targets.host;
  if (!host) return;
  host.style.setProperty('--vp-scale', `${metrics.scale}`);
  host.style.setProperty('--vp-screen-scale', `${metrics.scale * DESIGN_SCALE}`);
  host.style.setProperty('--vp-width', `${metrics.width}px`);
  host.style.setProperty('--vp-height', `${metrics.height}px`);
  host.style.setProperty('--vp-left', `${metrics.left}px`);
  host.style.setProperty('--vp-top', `${metrics.top}px`);
  host.setAttribute('data-orientation', metrics.orientation);
}

export function viewportSize(view: ViewportView = window): ViewportSize {
  const visual = view.visualViewport;
  if (visual) return { width: visual.width, height: visual.height };
  return { width: view.innerWidth, height: view.innerHeight };
}

const PROBE_STYLE =
  'position:fixed;top:0;left:0;width:0;height:0;visibility:hidden;pointer-events:none;' +
  'padding:env(safe-area-inset-top) env(safe-area-inset-right) ' +
  'env(safe-area-inset-bottom) env(safe-area-inset-left);';

export function readSafeAreaInsets(doc: Document = document): SafeAreaInsets {
  const probe = doc.createElement('div');
  probe.style.cssText = PROBE_STYLE;
  doc.body.appendChild(probe);
  const computed = doc.defaultView?.getComputedStyle(probe);
  const insets: SafeAreaInsets = {
    top: parsePx(computed?.paddingTop),
    right: parsePx(computed?.paddingRight),
    bottom: parsePx(computed?.paddingBottom),
    left: parsePx(computed?.paddingLeft),
  };
  probe.remove();
  return insets;
}

function parsePx(value: string | undefined): number {
  const parsed = Number.parseFloat(value ?? '');
  return Number.isFinite(parsed) ? parsed : 0;
}

export interface ViewportOptions {
  canvas?: ViewportCanvas;
  host?: ViewportHost;
  onChange?: (metrics: ViewportMetrics) => void;
  view?: ViewportView;
  document?: Document;
  readInsets?: () => SafeAreaInsets;
}

export class Viewport {
  private readonly options: ViewportOptions;
  private readonly view: ViewportView;
  private readonly doc: Document | undefined;
  private readonly readInsets: () => SafeAreaInsets;
  private detachers: Array<() => void> = [];
  private current: ViewportMetrics;

  constructor(options: ViewportOptions = {}) {
    this.options = options;
    this.view = options.view ?? window;
    this.doc =
      options.document ?? (typeof document === 'undefined' ? undefined : document);
    const doc = this.doc;
    this.readInsets =
      options.readInsets ?? (() => (doc ? readSafeAreaInsets(doc) : NO_INSETS));
    this.current = fitViewport(viewportSize(this.view), { insets: this.readInsets() });
  }

  get metrics(): ViewportMetrics {
    return this.current;
  }

  attach(): () => void {
    this.refresh();
    this.listen(this.view, 'resize');
    this.listen(this.view, 'orientationchange');
    const visual = this.view.visualViewport;
    if (visual) this.listen(visual, 'resize');
    return () => this.detach();
  }

  detach(): void {
    for (const detacher of this.detachers) detacher();
    this.detachers = [];
  }

  refresh(): ViewportMetrics {
    const metrics = fitViewport(viewportSize(this.view), { insets: this.readInsets() });
    this.current = metrics;
    applyViewport(metrics, {
      canvas: this.options.canvas,
      host: this.options.host ?? this.doc?.documentElement,
    });
    this.options.onChange?.(metrics);
    return metrics;
  }

  private listen(target: EventTarget, type: string): void {
    const listener = (): void => {
      this.refresh();
    };
    target.addEventListener(type, listener);
    this.detachers.push(() => target.removeEventListener(type, listener));
  }
}
