import {
  CHALLENGES,
  CHALLENGE_TYPES,
  FIXED_SHIFT,
  SPRITE_STRIPS,
} from '../data/constants.ts';
import { BIKE_LENGTH_FIXED, JOINT, type Bike } from './Bike.ts';
import { MARKER_KIND, levelFor } from './Levels.ts';
import { POPUP } from './TrickDetector.ts';

export const RACE_FLAG = {
  TIMED: 1,
  COUNTDOWN: 2,
  POINT_TO_POINT: 4,
  SHOW_DOWN: 8,
  COMBO: 16,
  FREE_RIDE: 32,
  NO_REPLAY: 64,
  GHOST_ONLY: 128,
} as const;

export const RACE_MODE = { PLAY: 0, WATCH_GHOST: RACE_FLAG.GHOST_ONLY } as const;

export const MS_PER_TICK = 60;

export const COUNTDOWN_MS = 45000;

const START_FLAG_STRIP = 5;

const RUNNING_LEFT_LIMIT = 15360;

const STAGED_LEFT_MARGIN = 7680;

const TYPE_FLAGS: ReadonlyArray<{ flags: number; runLimit?: number }> = [
  { flags: RACE_FLAG.TIMED, runLimit: 1 },
  { flags: RACE_FLAG.COUNTDOWN },
  { flags: RACE_FLAG.TIMED | RACE_FLAG.POINT_TO_POINT },
  { flags: RACE_FLAG.POINT_TO_POINT | RACE_FLAG.COUNTDOWN },
  { flags: RACE_FLAG.TIMED | RACE_FLAG.SHOW_DOWN, runLimit: 1 },
  { flags: RACE_FLAG.TIMED | RACE_FLAG.COUNTDOWN | RACE_FLAG.COMBO, runLimit: 1 },
  { flags: RACE_FLAG.TIMED | RACE_FLAG.FREE_RIDE },
];

export function raceFlagsFor(challenge: number, mode: number = RACE_MODE.PLAY): number {
  return mode | (TYPE_FLAGS[CHALLENGES[challenge]!.type]?.flags ?? 0);
}

export function runLimitFor(challenge: number): number | undefined {
  return TYPE_FLAGS[CHALLENGES[challenge]!.type]?.runLimit;
}

export function targetFormatFor(challenge: number): number {
  return CHALLENGE_TYPES[CHALLENGES[challenge]!.type]!.targetFormat;
}

export interface TrackLines {
  startX: number;
  finishX: number;
}

export function linesFor(track: number, flags: number): TrackLines {
  const half = SPRITE_STRIPS[START_FLAG_STRIP]!.width >> 1;
  const lines: TrackLines = { startX: 0, finishX: 0 };
  for (const marker of levelFor(track).markers) {
    if (marker.kind !== MARKER_KIND.START) continue;
    const x = (marker.x + half) << FIXED_SHIFT;
    if ((flags & RACE_FLAG.POINT_TO_POINT) === 0) {
      lines.startX = x;
      break;
    }
    if (lines.startX === 0) {
      lines.startX = x;
      continue;
    }
    lines.finishX = x;
    break;
  }
  return lines;
}

export type RaceBike = Pick<
  Bike,
  | 'crashTimer'
  | 'gapToPlayer'
  | 'trackLength'
  | 'rearWheelPreviousX'
  | 'jointX'
  | 'startX'
  | 'leftLimitX'
  | 'wrapCount'
  | 'step'
  | 'placeAtStart'
  | 'clearTrickCounts'
  | 'scoreTricks'
  | 'resetBoost'
>;

export class Runner {
  running = false;
  finished = false;
  timeMs = 0;
  runs = 0;
  beyondLine = false;

  readonly bike: RaceBike;

  constructor(bike: RaceBike) {
    this.bike = bike;
  }
}

export interface RaceHooks {
  startRecording?(): void;
  stopRecording?(frame: number): void;
  frame?(frame: number): void;
  startPlayback?(): void;
  stopReplay?(): void;
  takeReplay?(improved: boolean): void;
  replayFinished?(): boolean;
  opponentIdle?(): boolean;
  setOpponent?(profile: number): void;
  recordResult?(challenge: number, timeMs: number): void;
  finishChallenge?(): void;
  banner?(entry: number): void;
  drainTrickCounts?(): void;
}

export interface RaceStateOptions {
  mode?: number;
  runLimit?: number;
  hooks?: RaceHooks;
}

export class RaceState {
  readonly challenge: number;
  readonly flags: number;
  readonly startX: number;
  readonly finishX: number;
  readonly runLimit: number;

  readonly player: Runner;
  readonly opponent?: Runner;

  simFrame = 0;

  awaitingStart: boolean;

  private bestTimeSeen = 0;

  private readonly hooks: RaceHooks;

  constructor(
    challenge: number,
    player: RaceBike,
    opponent?: RaceBike,
    options: RaceStateOptions = {},
  ) {
    this.challenge = challenge;
    this.flags = raceFlagsFor(challenge, options.mode ?? RACE_MODE.PLAY);
    this.runLimit = runLimitFor(challenge) ?? options.runLimit ?? 1;
    this.hooks = options.hooks ?? {};

    const lines = linesFor(CHALLENGES[challenge]!.track, this.flags);
    this.startX = lines.startX;
    this.finishX = lines.finishX;

    this.player = new Runner(player);
    if (opponent !== undefined) this.opponent = new Runner(opponent);
    this.awaitingStart = !this.hasFlag(RACE_FLAG.GHOST_ONLY);
    this.resetRun();
  }

  hasFlag(flag: number): boolean {
    return (this.flags & flag) !== 0;
  }

  get focused(): Runner {
    return this.hasFlag(RACE_FLAG.GHOST_ONLY) && this.opponent !== undefined
      ? this.opponent
      : this.player;
  }

  recordsReplay(): boolean {
    return (
      this.hasFlag(RACE_FLAG.TIMED) &&
      !this.hasFlag(RACE_FLAG.POINT_TO_POINT) &&
      !this.hasFlag(RACE_FLAG.NO_REPLAY) &&
      !this.hasFlag(RACE_FLAG.SHOW_DOWN)
    );
  }

  usesOpponent(): boolean {
    return (
      (this.hasFlag(RACE_FLAG.TIMED) && !this.hasFlag(RACE_FLAG.NO_REPLAY)) ||
      this.hasFlag(RACE_FLAG.POINT_TO_POINT) ||
      this.hasFlag(RACE_FLAG.FREE_RIDE)
    );
  }

  releaseStart(): void {
    this.awaitingStart = false;
  }

  resetRun(): void {
    this.awaitingStart = !this.hasFlag(RACE_FLAG.GHOST_ONLY);
    this.simFrame = 0;

    const player = this.player.bike;
    player.clearTrickCounts(false);
    player.resetBoost();
    player.wrapCount = 0;
    this.hooks.stopRecording?.(-1);
    player.startX = this.startX - BIKE_LENGTH_FIXED;
    player.leftLimitX = player.startX - STAGED_LEFT_MARGIN;
    player.placeAtStart();
    this.player.running = false;
    this.player.finished = false;
    this.player.beyondLine = false;
    this.resetTimer(this.player);

    if (this.opponent === undefined) return;
    const opponent = this.opponent.bike;
    opponent.clearTrickCounts(false);
    opponent.resetBoost();
    opponent.wrapCount = 0;
    if (!this.hasFlag(RACE_FLAG.NO_REPLAY)) this.hooks.stopReplay?.();
    if (this.hasFlag(RACE_FLAG.SHOW_DOWN)) {
      this.hooks.setOpponent?.(CHALLENGES[this.challenge]!.opponent);
      opponent.startX = this.startX - RUNNING_LEFT_LIMIT;
      opponent.placeAtStart();
    }
    this.opponent.running = false;
    this.opponent.finished = false;
    this.opponent.beyondLine = false;
    this.resetTimer(this.opponent);
    if (this.hasFlag(RACE_FLAG.GHOST_ONLY)) this.hooks.startPlayback?.();
  }

  resetTimer(runner: Runner): void {
    runner.timeMs = 0;
    runner.runs = 0;
    if (this.hasFlag(RACE_FLAG.COUNTDOWN) && !this.hasFlag(RACE_FLAG.TIMED)) {
      runner.timeMs = COUNTDOWN_MS;
    }
  }

  update(): void {
    if (this.awaitingStart) return;

    this.checkLineCrossing(this.player);
    if (this.opponent !== undefined && !this.opponentIsIdle()) {
      this.checkLineCrossing(this.opponent);
    }

    this.hooks.frame?.(this.simFrame);

    if (!this.hasFlag(RACE_FLAG.GHOST_ONLY) && !this.player.finished) {
      this.player.bike.step();
      this.updateTimer(this.player);
    }
    if (
      this.opponent !== undefined &&
      !this.opponentIsIdle() &&
      !this.opponent.finished
    ) {
      this.opponent.bike.step();
      this.updateTimer(this.opponent);
      if (this.hasFlag(RACE_FLAG.SHOW_DOWN)) this.updateGap();
    }

    const focused = this.focused;
    if (focused.running && !focused.finished) this.simFrame += 1;
  }

  private updateGap(): void {
    const opponent = this.opponent;
    if (opponent === undefined) return;
    const length = opponent.bike.trackLength;
    opponent.bike.gapToPlayer =
      opponent.runs * length +
      opponent.bike.rearWheelPreviousX -
      (this.player.runs * length + this.player.bike.rearWheelPreviousX);
  }

  updateTimer(runner: Runner): void {
    if (!runner.running) return;
    if (this.hasFlag(RACE_FLAG.TIMED)) {
      runner.timeMs += MS_PER_TICK;
      return;
    }
    if (runner.timeMs <= 0) {
      this.finishRun(this.focused);
      return;
    }
    runner.timeMs -= MS_PER_TICK;
  }

  checkLineCrossing(runner: Runner): void {
    const bike = runner.bike;
    if (bike.crashTimer >= 0 || runner.finished) return;

    const previous = bike.rearWheelPreviousX;
    const current = bike.jointX[JOINT.REAR_WHEEL]!;

    if (!this.hasFlag(RACE_FLAG.POINT_TO_POINT)) {
      if (runner.running) {
        if (previous <= this.startX && current > this.startX) {
          if (!runner.beyondLine) this.finishRun(runner);
          runner.beyondLine = false;
          return;
        }
        if (current <= this.startX && previous > this.startX) runner.beyondLine = true;
        return;
      }
      if (previous > this.startX && current > this.startX) this.startRun(runner);
      return;
    }

    if (!runner.running) {
      if (current > this.startX) this.startRun(runner);
      return;
    }
    if (current > this.finishX) this.finishRun(runner);
  }

  startRun(runner: Runner): void {
    if (runner === this.player) {
      if (this.recordsReplay()) this.hooks.startRecording?.();
      if (!this.hasFlag(RACE_FLAG.GHOST_ONLY) && this.usesOpponent()) {
        this.hooks.startPlayback?.();
      }
    }
    this.resetTimer(runner);
    runner.bike.leftLimitX = RUNNING_LEFT_LIMIT;
    runner.running = true;
    runner.bike.clearTrickCounts(false);
    if (runner === this.focused) this.hooks.banner?.(POPUP.STARTED);
  }

  finishRun(runner: Runner): void {
    runner.runs += 1;

    if (runner === this.player) {
      const improved = this.improvedBestTime();
      if (this.recordsReplay()) {
        this.hooks.stopRecording?.(this.simFrame);
        if (this.usesOpponent()) this.hooks.takeReplay?.(improved);
        this.hooks.startRecording?.();
      }
      this.simFrame = 0;
    }

    if (
      this.usesOpponent() &&
      runner === this.opponent &&
      this.hooks.replayFinished?.() === true
    ) {
      if (this.recordsReplay() && this.hasFlag(RACE_FLAG.TIMED)) {
        this.hooks.stopRecording?.(-1);
      }
      this.hooks.stopReplay?.();
    }

    runner.finished = this.runShouldEnd(runner);

    if (runner !== this.focused) return;
    if (runner.finished) {
      this.hooks.finishChallenge?.();
      this.hooks.banner?.(POPUP.FINISHED);
      return;
    }
    if (this.hasFlag(RACE_FLAG.FREE_RIDE)) this.startRun(runner);
  }

  improvedBestTime(): boolean {
    if (!this.hasFlag(RACE_FLAG.TIMED)) return true;
    if (this.bestTimeSeen === 0 || this.bestTimeSeen > this.player.timeMs) {
      this.bestTimeSeen = this.player.timeMs;
      return true;
    }
    return false;
  }

  runShouldEnd(runner: Runner): boolean {
    let ends = false;

    if (
      this.hasFlag(RACE_FLAG.TIMED) &&
      (runner.runs += 1) >= this.runLimit &&
      !this.hasFlag(RACE_FLAG.FREE_RIDE)
    ) {
      ends = true;
    }
    if (this.flags === RACE_FLAG.COUNTDOWN) {
      ends = runner.timeMs <= 0;
    } else if (this.hasFlag(RACE_FLAG.COUNTDOWN)) {
      ends = true;
    }

    if (runner === this.player && this.hasFlag(RACE_FLAG.FREE_RIDE)) {
      this.hooks.recordResult?.(this.challenge, runner.timeMs);
    }

    if (!ends) {
      runner.bike.wrapCount = 0;
    } else {
      runner.bike.scoreTricks();
      this.hooks.drainTrickCounts?.();
    }
    return ends;
  }

  private opponentIsIdle(): boolean {
    return this.hooks.opponentIdle?.() ?? false;
  }
}
