import './style.css';
import { AudioService } from './audio/AudioService.ts';
import { Haptics } from './audio/Haptics.ts';
import { SFX_TRACKS } from './audio/Sfx.ts';
import {
  MUSIC_TRACKS,
  WebAudioSink,
  trackUrls,
  webAudioAvailable,
} from './audio/WebAudioSink.ts';
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from './core/config.ts';
import { Game } from './core/Game.ts';
import { Input } from './core/Input.ts';
import { Lifecycle } from './core/Lifecycle.ts';
import { SOFT_KEYS } from './data/constants.ts';
import { GhostStore, loadShippedGhosts } from './game/Ghost.ts';
import { loadLevels } from './game/Levels.ts';
import { LanguageService } from './i18n/Strings.ts';
import { loadAtlases } from './render/Atlas.ts';
import { recordFrame, type TextureLookup } from './render/BikeView.ts';
import { Renderer } from './render/Renderer.ts';
import { pxFromTexels } from './render/units.ts';
import { SaveService } from './save/SaveService.ts';
import {
  AppShell,
  SHELL_MODE,
  type RaceRequest,
  type ShellRace,
  type ShellTouchState,
} from './scenes/AppShell.ts';
import { RaceScene } from './scenes/RaceScene.ts';
import { Progression } from './scenes/Results.ts';
import { SplashScene } from './scenes/SplashScene.ts';
import { FONT, fontHeight, installFonts, measureFor } from './ui/Font.ts';
import { FIRST_TRICK_TEXT, TRICK_NAME_COUNT } from './ui/Hud.ts';
import type { MenuMetrics } from './ui/MenuList.ts';
import {
  MENU_LAYOUT,
  RACE_LAYOUT,
  TouchControls,
  isTouchLikely,
} from './ui/TouchControls.ts';

const APP_PROPERTIES: Readonly<Record<string, string>> = {
  'MIDlet-Name': 'Freestyle Moto-X II',
  'MIDlet-Vendor': 'I-play',
  'MIDlet-Version': '0.4.0',
};

const ATLAS_SHARE = 0.9;

const mount = document.querySelector<HTMLDivElement>('#app');
if (!mount) throw new Error('missing #app mount point');

const renderer = await Renderer.create(mount);
installFonts();

const save = new SaveService();
save.open();

const input = new Input();
input.attach();

const ghosts = new GhostStore({ storage: window.localStorage });
const haptics = new Haptics({ save });
const audio = new AudioService({ save });
const language = new LanguageService({ save });

const game = new Game({ target: renderer, input });

const lifecycle = new Lifecycle({
  sink: {
    pause(): void {
      audio.stopSound();
      input.clear();
      game.scenes.current?.pause?.();
    },
  },
});
lifecycle.attach();

const touch = isTouchLikely()
  ? new TouchControls({
      sink: input,
      layout: MENU_LAYOUT,
      labels: { 'soft-left': '', 'soft-right': '' },
    })
  : null;
touch?.mount();

function followShell(state: ShellTouchState): void {
  touch?.setLayout(state.mode === SHELL_MODE.RACE ? RACE_LAYOUT : MENU_LAYOUT, {
    'soft-left': state.left ?? '',
    'soft-right': state.right ?? '',
  });
}

function armAudio(): void {
  const start = (): void => {
    window.removeEventListener('pointerdown', start);
    window.removeEventListener('keydown', start);
    if (webAudioAvailable()) audio.setSink(new WebAudioSink());
    audio.unlock();
  };
  window.addEventListener('pointerdown', start, { once: true });
  window.addEventListener('keydown', start, { once: true });
}
armAudio();

async function warmAudio(): Promise<void> {
  const music = trackUrls(MUSIC_TRACKS);
  const sfx = trackUrls(SFX_TRACKS, 'assets/sfx/');
  const urls = [
    ...Object.keys(MUSIC_TRACKS).map((record) => music(Number(record))),
    ...Object.keys(SFX_TRACKS).map((record) => sfx(Number(record))),
  ].filter((url): url is string => url !== null);

  await Promise.all(urls.map((url) => fetch(url).catch(() => null)));
}

let textures: TextureLookup | null = null;

function trickNames(): readonly string[] {
  return Array.from({ length: TRICK_NAME_COUNT }, (_, index) =>
    language.table.text(FIRST_TRICK_TEXT + index),
  );
}

function createRace(request: RaceRequest, atlas: TextureLookup): ShellRace {
  return new RaceScene({
    challenge: request.challenge,
    mode: request.mode,
    shell: request.shell,
    save,
    input,
    audio,
    haptics,
    ghosts,
    view: {
      layers: renderer.layers,
      textures: atlas,
      trickNames: trickNames(),
      swapSoftKeys: false,
    },
  });
}

function menuMetrics(atlas: TextureLookup): MenuMetrics {
  return {
    screenWidth: LOGICAL_WIDTH,
    screenHeight: LOGICAL_HEIGHT,
    titleFontHeight: fontHeight(FONT.TITLE),
    menuFontHeight: fontHeight(FONT.MENU),
    smallFontHeight: fontHeight(FONT.SMALL),
    softKeyIconHeight: pxFromTexels(
      atlas[recordFrame(SOFT_KEYS[0]!.iconRecord)]?.height ?? 0,
    ),
    measureTitle: measureFor(FONT.TITLE),
    measureMenu: measureFor(FONT.MENU),
    measureSmall: measureFor(FONT.SMALL),
  };
}

const splash = new SplashScene({
  view: { layers: renderer.layers },
  boot: {
    openStores: () => save.open(),

    splashTextures: () => loadAtlases(['ui']),

    load: async (onProgress) => {
      textures = await loadAtlases(undefined, {
        onProgress: (fraction) => onProgress(fraction * ATLAS_SHARE),
      });
      await Promise.all([
        language.start(),
        warmAudio(),
        loadShippedGhosts(),
        loadLevels(),
      ]);
      onProgress(1);
    },

    done: () => {
      const atlas = textures!;
      game.scenes.replace(
        new AppShell({
          save,
          input,
          audio,
          language,
          haptics,
          metrics: menuMetrics(atlas),
          progression: new Progression({ save, slots: language.table, ghosts }),
          createRace: (request) => createRace(request, atlas),
          appProperties: APP_PROPERTIES,
          view: { layers: renderer.layers, textures: atlas },
          onShutdown: () => game.stop(),
          onTouchState: followShell,
          openUrl: (url) => window.open(url, '_blank', 'noopener') !== null,
        }),
      );
      audio.playMusic(false);
    },
  },
});

game.start(splash);

if (import.meta.env.DEV) {
  (globalThis as unknown as { motox: unknown }).motox = game;
}

async function dropServiceWorker(): Promise<void> {
  const worker = navigator.serviceWorker;
  if (worker) {
    const registrations = await worker.getRegistrations();
    await Promise.all(registrations.map((registration) => registration.unregister()));
  }

  if (globalThis.caches) {
    const names = await caches.keys();
    await Promise.all(
      names
        .filter((name) => name.startsWith('motox-'))
        .map((name) => caches.delete(name)),
    );
  }
}

void dropServiceWorker().catch(() => null);
