import { DEBUG_TOGGLES, INPUT_BIT } from '../data/constants.ts';

export const ACTION = {
  ACCEL: INPUT_BIT.UP | INPUT_BIT.KEY_2,
  BRAKE: INPUT_BIT.DOWN | INPUT_BIT.KEY_8,
  LEAN_LEFT: INPUT_BIT.LEFT | INPUT_BIT.KEY_4,
  LEAN_RIGHT: INPUT_BIT.RIGHT | INPUT_BIT.KEY_6,
  FIRE: INPUT_BIT.FIRE | INPUT_BIT.KEY_5,
  BOOST: INPUT_BIT.KEY_2,
  TRICK_KEY_3: INPUT_BIT.KEY_3,
  TRICK_KEY_7: INPUT_BIT.KEY_7,
  TRICK_KEY_9: INPUT_BIT.KEY_9,
  TRICK_KEY_1: INPUT_BIT.KEY_1,
  TRICK_STAR: INPUT_BIT.STAR,
  TRICK_KEY_0: INPUT_BIT.KEY_0,
  TRICK_HASH: INPUT_BIT.HASH,
  SOFT_LEFT: INPUT_BIT.SOFT_LEFT,
  SOFT_RIGHT: INPUT_BIT.SOFT_RIGHT,
} as const;

export type Action = (typeof ACTION)[keyof typeof ACTION];

export const DEFAULT_BINDINGS: Readonly<Record<string, number>> = {
  ArrowUp: INPUT_BIT.UP,
  KeyW: INPUT_BIT.UP,
  ArrowRight: INPUT_BIT.RIGHT,
  KeyD: INPUT_BIT.RIGHT,
  ArrowDown: INPUT_BIT.DOWN,
  KeyS: INPUT_BIT.DOWN,
  ArrowLeft: INPUT_BIT.LEFT,
  KeyA: INPUT_BIT.LEFT,
  Space: INPUT_BIT.FIRE,
  Enter: INPUT_BIT.FIRE,
  Digit0: INPUT_BIT.KEY_0,
  Digit1: INPUT_BIT.KEY_1,
  Digit2: INPUT_BIT.KEY_2,
  Digit3: INPUT_BIT.KEY_3,
  Digit4: INPUT_BIT.KEY_4,
  Digit5: INPUT_BIT.KEY_5,
  Digit6: INPUT_BIT.KEY_6,
  Digit7: INPUT_BIT.KEY_7,
  Digit8: INPUT_BIT.KEY_8,
  Digit9: INPUT_BIT.KEY_9,
  Numpad0: INPUT_BIT.KEY_0,
  Numpad1: INPUT_BIT.KEY_1,
  Numpad2: INPUT_BIT.KEY_2,
  Numpad3: INPUT_BIT.KEY_3,
  Numpad4: INPUT_BIT.KEY_4,
  Numpad5: INPUT_BIT.KEY_5,
  Numpad6: INPUT_BIT.KEY_6,
  Numpad7: INPUT_BIT.KEY_7,
  Numpad8: INPUT_BIT.KEY_8,
  Numpad9: INPUT_BIT.KEY_9,
  NumpadMultiply: INPUT_BIT.STAR,
  BracketLeft: INPUT_BIT.STAR,
  NumpadDivide: INPUT_BIT.HASH,
  BracketRight: INPUT_BIT.HASH,
};

export const DEFAULT_SOFT_BINDINGS: Readonly<Record<string, SoftKeySide>> = {
  F1: 'left',
  F2: 'right',
  Escape: 'right',
};

export type SoftKeySide = 'left' | 'right';

export const CHEAT_SEQUENCE: readonly number[] = [
  INPUT_BIT.HASH,
  INPUT_BIT.KEY_2,
  INPUT_BIT.KEY_0,
  INPUT_BIT.KEY_0,
];

export interface InputOptions {
  bindings?: Readonly<Record<string, number>>;
  softBindings?: Readonly<Record<string, SoftKeySide>>;
  swapSoftKeys?: boolean;
  cheatsEnabled?: boolean;
  onDebugToggle?(index: number): void;
}

export class Input {
  private heldBits = 0;
  private frameBits = 0;
  private releasedBits = 0;
  private softKeyEvents = 0;
  private cheatProgress = 0;

  private readonly bindings: Readonly<Record<string, number>>;
  private readonly softBindings: Readonly<Record<string, SoftKeySide>>;
  private detachers: Array<() => void> = [];

  swapSoftKeys: boolean;
  cheatsEnabled: boolean;
  onDebugToggle?: (index: number) => void;

  constructor(options: InputOptions = {}) {
    this.bindings = options.bindings ?? DEFAULT_BINDINGS;
    this.softBindings = options.softBindings ?? DEFAULT_SOFT_BINDINGS;
    this.swapSoftKeys = options.swapSoftKeys ?? false;
    this.cheatsEnabled = options.cheatsEnabled ?? true;
    this.onDebugToggle = options.onDebugToggle;
  }

  attach(target: EventTarget = window): () => void {
    const down = (event: Event): void => {
      const key = event as KeyboardEvent;
      if (key.repeat) return;
      if (this.handleKey(key.code, true)) key.preventDefault();
    };
    const up = (event: Event): void => {
      const key = event as KeyboardEvent;
      if (this.handleKey(key.code, false)) key.preventDefault();
    };
    const blur = (): void => this.clear();

    target.addEventListener('keydown', down);
    target.addEventListener('keyup', up);
    target.addEventListener('blur', blur);

    const detach = (): void => {
      target.removeEventListener('keydown', down);
      target.removeEventListener('keyup', up);
      target.removeEventListener('blur', blur);
    };
    this.detachers.push(detach);
    return detach;
  }

  detach(): void {
    for (const detacher of this.detachers) detacher();
    this.detachers = [];
  }

  private handleKey(code: string, down: boolean): boolean {
    const side = this.softBindings[code];
    if (side !== undefined) {
      if (down) this.pressSoftKey(side);
      return true;
    }
    const bit = this.bindings[code];
    if (bit === undefined) return false;
    if (down) this.press(bit);
    else this.release(bit);
    return true;
  }

  press(bit: number): void {
    this.trackCheat(bit);
    if (bit !== 0) this.heldBits |= bit;
  }

  release(bit: number): void {
    this.releasedBits |= bit;
  }

  pressSoftKey(side: SoftKeySide): void {
    const logicalLeft = this.swapSoftKeys ? side === 'right' : side === 'left';
    this.softKeyEvents |= logicalLeft ? INPUT_BIT.SOFT_LEFT : INPUT_BIT.SOFT_RIGHT;
  }

  private trackCheat(bit: number): void {
    if (!this.cheatsEnabled) return;
    if (this.cheatProgress === CHEAT_SEQUENCE.length) {
      for (let i = 0; i < DEBUG_TOGGLES.length; i++) {
        if (bit !== DEBUG_TOGGLES[i]!.keyBit) continue;
        if (i === 0) break;
        this.onDebugToggle?.(i);
        break;
      }
      this.cheatProgress = 0;
    }
    this.cheatProgress =
      CHEAT_SEQUENCE[this.cheatProgress] === bit ? this.cheatProgress + 1 : 0;
  }

  latch(): void {
    this.frameBits = this.heldBits;
    this.heldBits &= ~this.releasedBits;
    this.releasedBits = 0;
  }

  clear(): void {
    this.releasedBits = 0;
    this.heldBits = 0;
    this.frameBits = 0;
  }

  anyKeyHeld(): boolean {
    return this.heldBits !== 0;
  }

  isDown(mask: number): boolean {
    return (this.frameBits & mask) !== 0;
  }

  consume(mask: number): boolean {
    if (!this.isDown(mask)) return false;
    this.heldBits &= ~mask;
    return true;
  }

  takeSoftKeyEvents(): number {
    const events = this.softKeyEvents;
    this.softKeyEvents = 0;
    return events;
  }

  get bits(): { held: number; frame: number; released: number } {
    return {
      held: this.heldBits,
      frame: this.frameBits,
      released: this.releasedBits,
    };
  }
}

export interface InputBike {
  isGrounded(): boolean;
  requestTrick(animation: number): void;
  pressInput(bits: number): void;
}

const TRICK_ANIMATION = {
  GRIZZLY: 1,
  HEADACHE: 2,
  LAZY_BOY: 3,
  CORDOVA: 4,
  DOUBLE_GRAB: 5,
  TSUNAMI: 6,
  BAR_HOP: 7,
  ROCK_SOLID: 8,
  MC_METZ: 9,
  CRAZY_COW: 10,
} as const;

const BIKE = {
  LEAN_LEFT: 0x10,
  LEAN_RIGHT: 0x20,
  BRAKE: 0x40,
  THROTTLE: 0x80,
  BOOST: 0xc0,
} as const;

export class RaceInput {
  throttleLatched = false;

  sample(input: Input, bike: InputBike, latchedThrottle: boolean): void {
    this.sampleTricks(input, bike);
    this.sampleThrottle(input, bike, latchedThrottle);
    if (input.isDown(ACTION.LEAN_LEFT)) bike.pressInput(BIKE.LEAN_LEFT);
    if (input.isDown(ACTION.LEAN_RIGHT)) bike.pressInput(BIKE.LEAN_RIGHT);
  }

  private sampleTricks(input: Input, bike: InputBike): void {
    if (bike.isGrounded()) {
      if (input.consume(ACTION.TRICK_KEY_3)) bike.requestTrick(TRICK_ANIMATION.GRIZZLY);
      else if (input.consume(ACTION.TRICK_KEY_7))
        bike.requestTrick(TRICK_ANIMATION.HEADACHE);
      else if (input.consume(ACTION.TRICK_KEY_9))
        bike.requestTrick(TRICK_ANIMATION.CRAZY_COW);
      return;
    }
    if (input.consume(ACTION.TRICK_KEY_1)) bike.requestTrick(TRICK_ANIMATION.LAZY_BOY);
    else if (input.consume(ACTION.TRICK_KEY_3))
      bike.requestTrick(TRICK_ANIMATION.CORDOVA);
    else if (input.consume(ACTION.TRICK_KEY_7))
      bike.requestTrick(TRICK_ANIMATION.TSUNAMI);
    else if (input.consume(ACTION.TRICK_KEY_9))
      bike.requestTrick(TRICK_ANIMATION.DOUBLE_GRAB);
    else if (input.consume(ACTION.TRICK_STAR)) bike.requestTrick(TRICK_ANIMATION.MC_METZ);
    else if (input.consume(ACTION.TRICK_KEY_0))
      bike.requestTrick(TRICK_ANIMATION.ROCK_SOLID);
    else if (input.consume(ACTION.TRICK_HASH)) bike.requestTrick(TRICK_ANIMATION.BAR_HOP);
  }

  private sampleThrottle(input: Input, bike: InputBike, latched: boolean): void {
    if (latched) {
      if (input.consume(ACTION.BOOST)) {
        bike.pressInput(BIKE.BOOST);
        this.throttleLatched = true;
      } else if (input.consume(ACTION.ACCEL) || input.consume(ACTION.FIRE)) {
        bike.pressInput(BIKE.THROTTLE);
        this.throttleLatched = !this.throttleLatched;
      } else if (input.isDown(ACTION.BRAKE)) {
        bike.pressInput(BIKE.BRAKE);
        this.throttleLatched = false;
      } else if (this.throttleLatched) {
        bike.pressInput(BIKE.THROTTLE);
      } else {
        bike.pressInput(0);
      }
      return;
    }
    this.throttleLatched = false;
    if (input.isDown(ACTION.BOOST)) {
      bike.pressInput(BIKE.BOOST);
      this.throttleLatched = true;
    } else if (input.isDown(ACTION.ACCEL) || input.isDown(ACTION.FIRE)) {
      bike.pressInput(BIKE.THROTTLE);
      this.throttleLatched = true;
    } else if (input.isDown(ACTION.BRAKE)) {
      bike.pressInput(BIKE.BRAKE);
    } else {
      bike.pressInput(0);
    }
  }
}
