import { Container, Sprite } from 'pixi.js';

import type { AudioService } from '../audio/AudioService.ts';
import type { Haptics } from '../audio/Haptics.ts';
import { SfxDirector, sampleRide } from '../audio/Sfx.ts';
import { DESIGN_SCALE, SCREEN_HEIGHT, SCREEN_WIDTH } from '../core/config.ts';
import { ACTION, RaceInput, type Input } from '../core/Input.ts';
import type { Scene } from '../core/Scene.ts';
import {
  CHALLENGES,
  ENVIRONMENT,
  ENVIRONMENTS,
  FIXED_SHIFT,
  PART,
  SETUPS,
  SPRITE_STRIPS,
  TRACKS,
} from '../data/constants.ts';
import { BIKE_LENGTH_FIXED, type Bike } from '../game/Bike.ts';
import {
  ReplayBike,
  encodeGhost,
  ghostHooks,
  shippedGhostBytes,
  type GhostStore,
} from '../game/Ghost.ts';
import { levelFor } from '../game/Levels.ts';
import { RACE_FLAG, RACE_MODE, RaceState } from '../game/RaceState.ts';
import { Terrain } from '../game/Terrain.ts';
import { TrickDetector } from '../game/TrickDetector.ts';
import { BikeView, recordFrame, type TextureLookup } from '../render/BikeView.ts';
import { Camera2D } from '../render/Camera2D.ts';
import { SkyBand } from '../render/ParallaxLayer.ts';
import { ParticleFx, emitBikeSpray } from '../render/ParticleFx.ts';
import { WORLD_LAYERS, type Layers } from '../render/Renderer.ts';
import { ShadowView } from '../render/ShadowView.ts';
import { TerrainView, TileMap } from '../render/TerrainView.ts';
import { SPRITE_SCALE, px } from '../render/units.ts';
import type { SaveService } from '../save/SaveService.ts';
import { Hud, hudLayout, progressScale } from '../ui/Hud.ts';
import type { HudView, ProgressSource } from '../ui/Hud.ts';

export const MARKER_STRIP = 5;

export function tireBit(environment: number): number {
  const known = environment > ENVIRONMENT.SNOW ? ENVIRONMENT.CONCRETE : environment;
  return 1 << (PART.STREET + known);
}

export function markersFor(challenge: number) {
  return levelFor(CHALLENGES[challenge]!.track).markers;
}

export function setupMaskFor(challenge: number, save: SaveService): number {
  const row = CHALLENGES[challenge]!;
  const environment = TRACKS[row.track]!.environment;
  if (row.setup < 0) return save.fittedParts(environment);
  return SETUPS[row.setup]!.partMask | tireBit(environment);
}

export interface RaceShell {
  finished?(state: RaceState): void;
  paused?(): void;
  goals?(): void;
  lapResult?(challenge: number, timeMs: number): void;
}

export interface RaceSceneView {
  layers: Layers;
  textures: TextureLookup;
  trickNames?: readonly string[];
  swapSoftKeys?: boolean;
}

export interface RaceSceneOptions {
  challenge: number;
  save: SaveService;
  input: Input;
  mode?: number;
  runLimit?: number;
  audio?: AudioService;
  haptics?: Haptics | null;
  shell?: RaceShell;
  view?: RaceSceneView;
  ghosts?: GhostStore;
}

interface RaceViews {
  layers: Layers;
  camera: Camera2D;
  sky: SkyBand;
  terrain: TerrainView;
  markers: Container;
  bikes: readonly [BikeView, BikeView];
  shadows: readonly [ShadowView, ShadowView];
  fx: ParticleFx;
  hud: Hud;
}

export class RaceScene implements Scene {
  readonly challenge: number;
  readonly state: RaceState;
  readonly player: ReplayBike;
  readonly opponent: ReplayBike;
  readonly terrain: Terrain;
  readonly tilemap: TileMap;

  readonly tricks = new TrickDetector();
  readonly keys = new RaceInput();

  private readonly save: SaveService;
  private readonly input: Input;
  private readonly shell: RaceShell;
  private readonly audio: AudioService | undefined;
  private readonly sfx: SfxDirector | undefined;
  private readonly viewOptions: RaceSceneView | undefined;

  private views: RaceViews | null = null;

  private readonly hudView: { -readonly [K in keyof HudView]: HudView[K] } = {
    boostCharges: 0,
    throttleLatched: false,
    timeMs: 0,
    player: undefined as ProgressSource | undefined,
    opponent: undefined as ProgressSource | undefined,
  };

  private frame = 0;

  private announced = false;

  constructor(options: RaceSceneOptions) {
    this.challenge = options.challenge;
    this.save = options.save;
    this.input = options.input;
    this.shell = options.shell ?? {};
    this.audio = options.audio;
    this.viewOptions = options.view;
    if (options.audio) {
      this.sfx = new SfxDirector(options.audio, options.haptics ?? null);
    }

    const track = CHALLENGES[this.challenge]!.track;
    this.terrain = Terrain.forTrack(track);
    this.tilemap = TileMap.forTrack(track);

    this.player = new ReplayBike(this.terrain);
    this.opponent = new ReplayBike(this.terrain, { isOpponent: true });
    this.setUpBikes(track);

    this.loadGhost(options.mode ?? RACE_MODE.PLAY, options.ghosts);

    this.state = this.buildState(options);
  }

  private setUpBikes(track: number): void {
    const environment = ENVIRONMENTS[TRACKS[track]!.environment]!;
    for (const bike of [this.player, this.opponent]) {
      bike.buildSkeleton();
      bike.setTrack(track);
      bike.setSurfaceGrip(environment.surfaceGrip);
    }

    this.player.applyParts(setupMaskFor(this.challenge, this.save));
    this.player.bikeVariant = this.save.selectedBike;
    this.opponent.clearReplay();
  }

  private buildState(options: RaceSceneOptions): RaceState {
    return new RaceState(this.challenge, this.player, this.opponent, {
      mode: options.mode ?? RACE_MODE.PLAY,
      ...(options.runLimit === undefined ? {} : { runLimit: options.runLimit }),
      hooks: {
        ...ghostHooks(this.player, this.opponent),
        recordResult: (challenge, timeMs) => this.shell.lapResult?.(challenge, timeMs),
        drainTrickCounts: () => {
          this.tricks.drain(this.state.focused.bike as Bike);
        },
        banner: (entry) => {
          this.tricks.push(entry);
        },
        finishChallenge: () => this.finish(),
      },
    });
  }

  private loadGhost(mode: number, store?: GhostStore): void {
    const record = CHALLENGES[this.challenge]!.ghostRecord;
    const watching = (mode & RACE_FLAG.GHOST_ONLY) !== 0;
    const shipped = record > 0 ? shippedGhostBytes(record) : null;

    if (shipped !== null) {
      if (watching) {
        this.opponent.loadGhost(shipped);
      } else {
        this.player.loadGhost(shipped);
        if (this.player.startSnapshot !== null) {
          this.player.loadSnapshot(this.player.startSnapshot, 0);
        }
        this.player.clearReplay();
        this.player.bikeVariant = this.save.selectedBike;
      }
    }

    if (!watching && store) {
      const best = store.load(this.challenge);
      if (best) this.opponent.loadGhost(encodeGhost(best));
    }
  }

  enter(): void {
    this.buildViews();
    this.input.clear();
    this.audio?.playMusic(true);
    this.sfx?.start();
    this.views?.hud.invalidate();
  }

  exit(): void {
    this.sfx?.stop();
    this.audio?.stopSound();
    this.destroyViews();
  }

  setActive(active: boolean): void {
    const views = this.views;
    if (views) {
      views.sky.graphics.visible = active;
      views.terrain.container.visible = active;
      views.markers.visible = active;
      for (const shadow of views.shadows) shadow.graphics.visible = active;
      for (const view of views.bikes) view.container.visible = active;
      views.fx.container.visible = active;
      views.hud.container.visible = active;
    }
    if (active) {
      this.sfx?.start();
      views?.hud.invalidate();
    } else {
      this.sfx?.stop();
    }
  }

  refreshPlayerSetup(variantOnly: boolean): void {
    if (variantOnly) {
      this.player.bikeVariant = this.save.selectedBike;
      return;
    }
    const environment = TRACKS[CHALLENGES[this.challenge]!.track]!.environment;
    this.player.applyParts(this.save.fittedParts(environment));
    this.player.bikeVariant = this.save.selectedBike;
    if (this.state.player.running) this.restart();
  }

  pause(): void {
    this.setActive(false);
    this.audio?.stopSound();
  }

  resume(): void {
    this.input.clear();
    this.audio?.playMusic(true);
    this.setActive(true);
  }

  update(): void {
    this.frame += 1;
    ReplayBike.frameCount = this.frame;
    this.input.latch();

    if (this.handleSoftKey()) return;

    if (this.state.awaitingStart) {
      if (!this.input.anyKeyHeld()) return;
      this.state.releaseStart();
    }

    if (!this.state.hasFlag(RACE_FLAG.GHOST_ONLY)) {
      this.keys.sample(this.input, this.player, this.save.latchedThrottle);
    }

    this.state.update();

    this.stepEffects();
    this.spellPopup();
    this.sfx?.update(sampleRide(this.player));
  }

  private handleSoftKey(): boolean {
    const events = this.input.takeSoftKeyEvents();
    if (events === 0) return false;
    if (events === ACTION.SOFT_LEFT) this.shell.paused?.();
    else if (events === ACTION.SOFT_RIGHT) this.shell.goals?.();
    return true;
  }

  private stepEffects(): void {
    const views = this.views;
    if (!views) return;
    if (this.drawsPlayer()) {
      emitBikeSpray(views.fx, this.player, this.state.player.finished);
    }
    if (this.drawsOpponent()) {
      emitBikeSpray(views.fx, this.opponent, this.state.opponent?.finished ?? true);
    }
    views.fx.step();
  }

  private spellPopup(): void {
    const focused = this.state.focused;
    if (!focused.running) return;
    const entry = this.tricks.update(focused.bike as Bike, this.frame);
    if (entry >= 0 && this.views) this.views.hud.spellTrick(this.views.fx, entry);
  }

  restart(): void {
    this.keys.throttleLatched = false;
    this.tricks.reset();
    this.views?.fx.clear();
    this.announced = false;
    this.state.resetRun();
    this.views?.hud.invalidate();
  }

  private finish(): void {
    if (this.announced) return;
    this.announced = true;
    this.sfx?.stop();
    this.shell.finished?.(this.state);
  }

  render(): void {
    const views = this.views;
    if (!views) return;

    const { camera } = views;
    camera.follow(this.state.focused.bike as Bike);
    this.applyCamera(views);
    views.sky.sync(camera);
    views.terrain.scrollTo(camera.x, camera.y);
    this.placeMarkers(views);

    this.drawBike(views, 0, this.player, this.drawsPlayer());
    this.drawBike(views, 1, this.opponent, this.drawsOpponent());

    views.fx.sync(camera);

    const hudView = this.hudView;
    hudView.boostCharges = (this.state.focused.bike as Bike).boostCharges;
    hudView.throttleLatched = this.keys.throttleLatched;
    hudView.timeMs = this.state.focused.timeMs;
    hudView.player = this.state.hasFlag(RACE_FLAG.GHOST_ONLY) ? undefined : this.player;
    hudView.opponent = this.opponentIsIdle() ? undefined : this.opponent;
    views.hud.draw(hudView);
  }

  private applyCamera(views: RaceViews): void {
    const { camera, layers } = views;
    for (const name of WORLD_LAYERS) {
      const layer = layers[name];
      layer.scale.set(DESIGN_SCALE);
      layer.position.set(px(-camera.x), px(-camera.y));
    }
  }

  private placeMarkers(views: RaceViews): void {
    views.markers.x = views.camera.seamShift();
  }

  private drawBike(
    views: RaceViews,
    index: 0 | 1,
    bike: ReplayBike,
    visible: boolean,
  ): void {
    const view = views.bikes[index]!;
    const shadow = views.shadows[index]!;
    if (!visible) {
      view.container.visible = false;
      shadow.graphics.visible = false;
      return;
    }

    const offset = views.camera.wrapOffset(bike.drawLeft, bike.drawRight);
    if (offset === undefined) {
      view.container.visible = false;
      shadow.graphics.visible = false;
      return;
    }

    view.container.visible = true;
    shadow.graphics.visible = true;
    view.container.x = offset;
    shadow.graphics.x = offset;
    shadow.sync(bike, this.terrain);
    view.sync(bike);
  }

  drawsPlayer(): boolean {
    return !this.state.hasFlag(RACE_FLAG.GHOST_ONLY);
  }

  drawsOpponent(): boolean {
    const opponent = this.state.opponent;
    if (!opponent) return false;
    if (this.state.hasFlag(RACE_FLAG.SHOW_DOWN)) return true;
    if (!this.opponent.hasReplay()) return false;
    if (!opponent.running && !opponent.finished) return false;
    return this.save.showGhost || this.state.hasFlag(RACE_FLAG.GHOST_ONLY);
  }

  private opponentIsIdle(): boolean {
    return this.opponent.isIdle();
  }

  private buildViews(): void {
    const options = this.viewOptions;
    if (!options || this.views) return;
    const { layers, textures } = options;

    const camera = this.buildCamera();

    const sky = new SkyBand(this.tilemap.skyColour);
    const terrain = new TerrainView(
      this.tilemap,
      frame(textures, recordFrame(this.tilemap.tilesheetRecord)),
    );

    const markers = this.buildMarkers(textures);

    const bikes = [new BikeView(textures), new BikeView(textures)] as const;
    const shadows = [new ShadowView(), new ShadowView()] as const;
    const fx = new ParticleFx(textures);

    const hud = this.buildHud(options);

    layers.bg.addChild(sky.graphics);
    layers.terrain.addChild(terrain.container);
    layers.entities.addChild(markers);
    for (const shadow of shadows) layers.entities.addChild(shadow.graphics);
    for (const view of bikes) layers.entities.addChild(view.container);
    layers.fx.addChild(fx.container);
    layers.hud.addChild(hud.container);

    this.views = { layers, camera, sky, terrain, markers, bikes, shadows, fx, hud };
  }

  private buildCamera(): Camera2D {
    return new Camera2D({
      worldHeight: this.tilemap.pixelHeight,
      trackLengthFixed: this.terrain.trackLength,
      terrainMaxYFixed: this.terrain.maxY,
      bikeLength: BIKE_LENGTH_FIXED >> FIXED_SHIFT,
    });
  }

  private buildMarkers(textures: TextureLookup): Container {
    const markers = new Container({ label: 'markers' });
    const flag = frame(textures, recordFrame(SPRITE_STRIPS[MARKER_STRIP]!.record));
    for (const marker of markersFor(this.challenge)) {
      const sprite = new Sprite({ texture: flag, label: 'marker', scale: SPRITE_SCALE });
      sprite.position.set(marker.x, marker.y);
      markers.addChild(sprite);
    }
    return markers;
  }

  private buildHud(options: RaceSceneView): Hud {
    const layout = hudLayout(SCREEN_WIDTH, SCREEN_HEIGHT, options.swapSoftKeys ?? false);
    return new Hud(options.textures, {
      layout,
      scale: progressScale(layout, this.state.startX, this.progressSpan()),
      ...(options.trickNames ? { trickNames: options.trickNames } : {}),
    });
  }

  private progressSpan(): number {
    return this.state.hasFlag(RACE_FLAG.POINT_TO_POINT)
      ? this.state.finishX - this.state.startX
      : this.terrain.trackLength;
  }

  private destroyViews(): void {
    const views = this.views;
    if (!views) return;
    views.sky.destroy();
    views.terrain.destroy();
    views.markers.destroy({ children: true });
    for (const view of views.bikes) view.destroy();
    for (const shadow of views.shadows) shadow.destroy();
    views.fx.destroy();
    views.hud.destroy();
    this.views = null;
  }
}

function frame(textures: TextureLookup, name: string) {
  const texture = textures[name];
  if (!texture) throw new Error(`no atlas frame '${name}'`);
  return texture;
}
