import { ASSET_SCALE, DESIGN_SCALE } from '../core/config.ts';

export const SPRITE_SCALE = 1 / ASSET_SCALE;

export const UI_SPRITE_SCALE = DESIGN_SCALE / ASSET_SCALE;

export function px(screenUnits: number): number {
  return screenUnits * DESIGN_SCALE;
}

export function toScreen(designUnits: number): number {
  return designUnits / DESIGN_SCALE;
}

export function texels(screenUnits: number): number {
  return screenUnits * ASSET_SCALE;
}

export function pxFromTexels(texturePixels: number): number {
  return texturePixels * UI_SPRITE_SCALE;
}

export function shiftPx(designUnits: number, bits: number): number {
  return px(Math.floor(toScreen(designUnits) / 2 ** bits));
}

export function dividePx(designUnits: number, divisor: number): number {
  return px(Math.trunc(toScreen(designUnits) / divisor));
}

export function floorPx(designUnits: number): number {
  return px(Math.floor(toScreen(designUnits)));
}
