import { PROGRESS, type SaveService, type VolumeSlot } from '../save/SaveService.ts';

export const VOLUME_DIVISOR = 20;

export const MAX_LEVEL = 5;

export const LOOP_FOREVER = 0;

export const PLAY_ONCE = 1;

export function levelOf(volume: number): number {
  const level = Math.trunc(volume / VOLUME_DIVISOR);
  return level < 0 ? 0 : level > MAX_LEVEL ? MAX_LEVEL : level;
}

export interface SoundRequest {
  record: number;
  music: boolean;
  loop: boolean;
  level: number;
}

export interface SfxVoice {
  readonly active: boolean;
  setRate(rate: number): void;
  stop(): void;
}

export interface AudioSink {
  setLevels(music: number, sfx: number): void;
  play(request: SoundRequest): void;
  stop(): void;
  stopMusic?(): void;
  loop?(request: SoundRequest, rate: number): SfxVoice | null;
  unlock?(): void;
  readonly unlocked?: boolean;
}

export class SilentSink implements AudioSink {
  setLevels(): void {}
  play(): void {}
  stop(): void {}
}

export interface AudioServiceOptions {
  save: SaveService;
  sink?: AudioSink;
  soundPresent?: boolean;
  mixSfxOverMusic?: boolean;
}

export class AudioService {
  readonly save: SaveService;
  readonly soundPresent: boolean;
  readonly mixSfxOverMusic: boolean;

  private sink: AudioSink;

  private playingMusic = false;

  private sounding = false;

  private musicLevel = 0;
  private sfxLevel = 0;

  private request: SoundRequest | null = null;

  constructor(options: AudioServiceOptions) {
    this.save = options.save;
    this.sink = options.sink ?? new SilentSink();
    this.soundPresent = options.soundPresent ?? true;
    this.mixSfxOverMusic = options.mixSfxOverMusic ?? true;
    this.applyVolumes();
  }

  get unlocked(): boolean {
    return this.sink.unlocked ?? true;
  }

  get current(): SoundRequest | null {
    return this.request;
  }

  get levels(): { music: number; sfx: number } {
    return { music: this.musicLevel, sfx: this.sfxLevel };
  }

  setSink(sink: AudioSink): void {
    const pending = this.request;
    this.stopSound();
    this.sink = sink;
    this.applyVolumes();
    if (pending && this.musicLevel > 0) {
      this.request = pending;
      if (this.unlocked) this.start();
    }
  }

  unlock(): void {
    this.sink.unlock?.();
    if (this.unlocked && this.request && !this.sounding) this.start();
  }

  playSound(record: number, music: boolean, loop: boolean): void {
    this.applyVolumes();
    if (record < 0) return;
    this.play(record, music, loop);
  }

  playMusic(loop: boolean): void {
    this.playSound(this.save.musicTrack, true, loop);
  }

  playSfx(record: number, loop = false): void {
    this.playSound(record, false, loop);
  }

  loopSfx(record: number, rate = 1): SfxVoice | null {
    this.applyVolumes();
    if (record < 0 || !this.mixSfxOverMusic) return null;
    if (this.sfxLevel === 0 || !this.unlocked) return null;
    return (
      this.sink.loop?.(
        { record, music: false, loop: true, level: this.sfxLevel },
        rate,
      ) ?? null
    );
  }

  stopSound(): void {
    this.request = null;
    this.sounding = false;
    this.sink.stop();
  }

  private stopMusicOnly(): void {
    this.request = null;
    this.sounding = false;
    if (this.sink.stopMusic) this.sink.stopMusic();
    else this.sink.stop();
  }

  applyVolumes(): void {
    this.musicLevel = this.soundPresent ? levelOf(this.save.musicVolume) : 0;
    this.sfxLevel = this.soundPresent ? levelOf(this.save.sfxVolume) : 0;
    this.sink.setLevels(this.musicLevel, this.sfxLevel);
    if (this.playingMusic && this.musicLevel === 0) {
      if (this.mixSfxOverMusic) this.stopMusicOnly();
      else this.stopSound();
    }
  }

  toggleVolume(slot: VolumeSlot): void {
    this.save.toggleVolume(slot);
    this.applyVolumes();
    if (slot === PROGRESS.MUSIC_VOLUME) this.playMusic(false);
  }

  selectMusicTrack(record: number): void {
    this.save.musicTrack = record;
    this.playMusic(false);
  }

  private play(record: number, music: boolean, loop: boolean): void {
    const level = music ? this.musicLevel : this.sfxLevel;
    if (!music && this.mixSfxOverMusic) {
      if (level > 0) this.sink.play({ record, music, loop, level });
      return;
    }
    if (this.mixSfxOverMusic) this.stopMusicOnly();
    else this.stopSound();
    this.playingMusic = music;
    if (level === 0) return;
    this.request = { record, music, loop, level };
    if (this.unlocked) this.start();
  }

  private start(): void {
    const request = this.request;
    if (!request) return;
    this.sounding = true;
    this.sink.play(request);
  }
}
