import { MENU_ITEMS, type MenuItem } from '../data/constants.ts';
import { PROGRESS, type Progress, type SaveService } from '../save/SaveService.ts';
import {
  EXIT_LINK,
  applyExitLink,
  removeMenuItem,
  type ExitLinkProperties,
} from '../scenes/HighScores.ts';
import {
  TEMPLATE_COUNT,
  formatString,
  formatStrings,
  type StringSlots,
} from '../scenes/Results.ts';

export const LANGUAGES = ['EN', 'FR', 'IT', 'DE', 'ES'] as const;

export const LANGUAGE_UNSET = 5;

export const LANGUAGE_TAG_LENGTH = 2;

export const LANGUAGE_MENU = 28;

export const OPTIONS_MENU = 18;

export const TITLE_MENU = 0;

export const LANGUAGE_ROW_STRING = 61;

export const SET_LANGUAGE = 12;

export const BUSY_LOADING = 153;

export const APP_PROPERTIES_STRING = 0;

export const TOGGLE_TEXT = { ON: 62, OFF: 63 } as const;

export const OPTION_TOGGLES = [
  { string: 18, slot: PROGRESS.LATCHED_THROTTLE },
  { string: 2, slot: PROGRESS.VIBRATION },
  { string: 5, slot: PROGRESS.SHOW_GHOST },
] as const;

export const SOUND_TOGGLE = { string: 3, slot: PROGRESS.MUSIC_VOLUME } as const;

export const I18N_BASE = 'assets/i18n/';

export function languageFile(tag: string, base: string = I18N_BASE): string {
  return `${base}${tag.toLowerCase()}.json`;
}

export function languageIndexOf(tag: string | null): number {
  if (tag === null) return -1;
  return LANGUAGES.indexOf(tag as (typeof LANGUAGES)[number]);
}

export function forcedLanguageOf(value: string | null | undefined): string | null {
  if (value === null || value === undefined) return null;
  const trimmed = value.trim();
  return trimmed.length === LANGUAGE_TAG_LENGTH ? trimmed : null;
}

export function startupLanguageIndex(stored: number): number {
  if (stored === LANGUAGE_UNSET) return 0;
  if (stored < 0 || stored >= LANGUAGES.length) return 0;
  return stored;
}

export interface StringSource {
  readonly languages: readonly string[];
  load(tag: string): Promise<readonly string[]>;
}

export class JsonStringSource implements StringSource {
  readonly languages: readonly string[];
  private readonly base: string;
  private readonly fetchImpl: typeof fetch;

  constructor(
    options: {
      languages?: readonly string[];
      base?: string;
      fetch?: typeof fetch;
    } = {},
  ) {
    this.languages = options.languages ?? LANGUAGES;
    this.base = options.base ?? I18N_BASE;
    this.fetchImpl = options.fetch ?? ((...args) => globalThis.fetch(...args));
  }

  async load(tag: string): Promise<readonly string[]> {
    const response = await this.fetchImpl(languageFile(tag, this.base));
    if (!response.ok) throw new Error(`i18n: ${tag} ${response.status}`);
    return (await response.json()) as readonly string[];
  }
}

export class StringTable implements StringSlots {
  language: string | null = null;
  languageIndex = -1;

  private strings: string[] = [];
  private templates: readonly string[] = [];

  constructor(strings: readonly string[] = [], tag: string | null = null) {
    if (strings.length > 0 || tag !== null) this.adopt(strings, tag);
  }

  get loaded(): boolean {
    return this.language !== null;
  }

  adopt(strings: readonly string[], tag: string | null): void {
    this.strings = [...strings];
    this.templates = this.strings.slice(0, TEMPLATE_COUNT);
    this.language = tag;
    this.languageIndex = languageIndexOf(tag);
  }

  text(id: number): string {
    if (id === -1) return '';
    const slot = id < 0 ? id & 0xff : id;
    return this.strings[slot] ?? '';
  }

  template(id: number): string {
    return this.templates[id] ?? '';
  }

  setString(id: number, value: string): void {
    this.strings[id] = value;
  }
}

export function setToggleLabel(
  slots: StringSlots,
  stringId: number,
  value: number | boolean,
): void {
  const on = typeof value === 'boolean' ? value : value !== 0;
  formatString(slots, stringId, slots.text(on ? TOGGLE_TEXT.ON : TOGGLE_TEXT.OFF));
}

export function refreshOptionLabels(slots: StringSlots, progress: Progress): void {
  for (const toggle of OPTION_TOGGLES) {
    setToggleLabel(slots, toggle.string, progress[toggle.slot]);
  }
}

export function refreshSoundLabel(slots: StringSlots, progress: Progress): void {
  setToggleLabel(slots, SOUND_TOGGLE.string, progress[SOUND_TOGGLE.slot]);
}

export interface AppProperties {
  name: string;
  vendor: string;
  version: string;
}

export interface RefreshStringsOptions {
  appProperties?: AppProperties | null;
  exitLink?: ExitLinkProperties;
  exitItems?: readonly MenuItem[];
}

export function refreshStrings(
  slots: StringSlots,
  options: RefreshStringsOptions = {},
): readonly MenuItem[] {
  const { appProperties = null, exitLink = { url: null, label: null } } = options;
  if (appProperties !== null) {
    formatStrings(slots, APP_PROPERTIES_STRING, [
      appProperties.name,
      appProperties.vendor,
      appProperties.version,
    ]);
  }
  return applyExitLink(
    slots,
    exitLink,
    options.exitItems ?? MENU_ITEMS[EXIT_LINK.MENU] ?? [],
  );
}

export function applyForcedLanguage(
  forced: string | null,
  items: readonly MenuItem[] = MENU_ITEMS[OPTIONS_MENU] ?? [],
): readonly MenuItem[] {
  return forced === null ? items : removeMenuItem(items, LANGUAGE_ROW_STRING);
}

export interface LanguageHost {
  showBusy?(stringId: number): void;
  hideBusy?(): void;
  refreshStrings?(): void;
  back?(): void;
}

export interface LanguageServiceOptions {
  save: SaveService;
  source?: StringSource;
  table?: StringTable;
  host?: LanguageHost;
  forcedLanguage?: string | null;
}

export class LanguageService {
  readonly table: StringTable;
  readonly forced: string | null;

  private readonly save: SaveService;
  private readonly source: StringSource;
  private host: LanguageHost;

  constructor(options: LanguageServiceOptions) {
    this.save = options.save;
    this.source = options.source ?? new JsonStringSource();
    this.table = options.table ?? new StringTable();
    this.host = options.host ?? {};
    this.forced = forcedLanguageOf(options.forcedLanguage ?? null);
  }

  setHost(host: LanguageHost): void {
    this.host = host;
  }

  async loadLanguage(tag: string): Promise<boolean> {
    if (this.table.language !== null && this.table.language === tag) return true;
    const shipped = this.source.languages;
    const resolved = shipped.includes(tag)
      ? tag
      : shipped.length === 1
        ? shipped[0]!
        : null;
    if (resolved === null) return false;
    try {
      const strings = await this.source.load(resolved);
      this.table.adopt(strings, resolved);
      return true;
    } catch {
      return false;
    }
  }

  async start(): Promise<boolean> {
    if (this.forced !== null) {
      const loaded = await this.loadLanguage(this.forced);
      if (loaded) this.save.language = this.table.languageIndex;
      return loaded;
    }
    return this.loadLanguage(LANGUAGES[startupLanguageIndex(this.save.language)]!);
  }

  bootScreen(): number {
    return this.save.language === LANGUAGE_UNSET ? LANGUAGE_MENU : TITLE_MENU;
  }

  async selectLanguage(param: number): Promise<boolean> {
    const tag = LANGUAGES[param];
    if (tag === undefined) return false;
    this.host.showBusy?.(BUSY_LOADING);
    try {
      const loaded = await this.loadLanguage(tag);
      if (!loaded) return false;
      this.save.language = this.table.languageIndex;
      this.save.saveProgress();
      this.host.refreshStrings?.();
      this.host.back?.();
      return true;
    } finally {
      this.host.hideBusy?.();
    }
  }

  menuSelection(): number | null {
    if (this.forced !== null) return null;
    const index = this.save.language;
    return index === LANGUAGE_UNSET || index < 0 || index >= LANGUAGES.length
      ? null
      : index;
  }

  optionsItems(items?: readonly MenuItem[]): readonly MenuItem[] {
    return applyForcedLanguage(this.forced, items);
  }
}
