import { FIXED_SHIFT } from '../data/constants.ts';

export function fixedMul(a: number, b: number): number {
  return Math.imul(a, b) >> FIXED_SHIFT;
}

export function fixedDiv(a: number, b: number): number {
  return ((a << FIXED_SHIFT) / b) | 0;
}

function squaredSum(x: number, y: number): number {
  const bx = BigInt(x | 0);
  const by = BigInt(y | 0);
  return Number(BigInt.asIntN(32, (bx * bx + by * by) >> 10n));
}

export function sqrtFixed(value: number): number {
  let root = 0;
  let remainder = value | 0;
  let bit = 0x40000000;

  do {
    const trial = (root + bit) | 0;
    root >>= 1;
    if (trial <= remainder) {
      remainder = (remainder - trial) | 0;
      root = (root + bit) | 0;
    }
    bit >>= 2;
  } while (bit !== 0);

  if (root < remainder) root += 1;
  return root << 5;
}

export function lengthFixed(x: number, y: number): number {
  return sqrtFixed(squaredSum(x, y));
}

export function inverseLengthFixed(x: number, y: number): number {
  const squared = squaredSum(x, y);
  if (squared === 0) return 1;

  const length = sqrtFixed(squared);
  if (length > 0) return (0x100000 / length) | 0;
  return approximateInverseLength(x, y);
}

function approximateInverseLength(x: number, y: number): number {
  let a = x < 0 ? -x : x;
  let b = y < 0 ? -y : y;
  if (a < b) [a, b] = [b, a];

  let estimate = (a * 1007 + b * 441) | 0;
  if (a < b << 4) estimate = (estimate - a * 40) | 0;
  return (0x100000 / ((estimate + 512) >> 10)) | 0;
}
