import { CHALLENGES } from '../../data/constants.ts';
import { TRICK_SLOTS } from '../../game/Bike.ts';
import { TRICK_TEXT_BASE } from '../../game/TrickDetector.ts';

import { RESULT_STRING, RESULT_TEXT, type StringSlots } from './strings.ts';

const LAST_GROUNDED_TRICK = 4;

export function requirementText(
  slots: StringSlots,
  challenge: number,
  trickTotals?: ArrayLike<number>,
  hints?: readonly (string | null)[],
): string {
  const mask = CHALLENGES[challenge]!.requirements;
  const listed = (slot: number): boolean =>
    (mask & (1 << slot)) !== 0 && (trickTotals === undefined || trickTotals[slot] === 0);

  let grounded = false;
  let airborne = false;
  for (let slot = 0; slot < TRICK_SLOTS; slot += 1) {
    if (!listed(slot)) continue;
    if (slot <= LAST_GROUNDED_TRICK) grounded = true;
    else airborne = true;
  }

  let text = grounded ? slots.text(RESULT_TEXT.GROUNDED) : '';
  let pendingAirborneHeader = airborne;
  for (let slot = 0; slot < TRICK_SLOTS; slot += 1) {
    if (!listed(slot)) continue;
    if (text.length > 0) text += '\n';
    if (slot > LAST_GROUNDED_TRICK && pendingAirborneHeader) {
      if (grounded) text += '\n';
      text += `${slots.text(RESULT_TEXT.AIRBORNE)}\n`;
      pendingAirborneHeader = false;
    }
    text += slots.text(TRICK_TEXT_BASE + slot);
    const hint = hints?.[slot];
    if (hint !== undefined && hint !== null) text += ` ${hint}`;
  }

  slots.setString(RESULT_STRING.REQUIREMENTS, text);
  return text;
}

export function landedTrickText(
  slots: StringSlots,
  trickTotals: ArrayLike<number>,
): string {
  let text = '';
  for (let slot = 0; slot < TRICK_SLOTS; slot += 1) {
    for (let count = 0; count < (trickTotals[slot] ?? 0); count += 1) {
      text += `\n${slots.text(TRICK_TEXT_BASE + slot)}`;
    }
  }
  return text.length === 0 ? slots.text(RESULT_TEXT.NONE) : text;
}
