import { Container, Graphics, Sprite, type Texture } from 'pixi.js';

import { LOGICAL_HEIGHT, LOGICAL_WIDTH, TICK_MS } from '../core/config.ts';
import type { Scene } from '../core/Scene.ts';
import { recordFrame, type TextureLookup } from '../render/BikeView.ts';
import type { Layers } from '../render/Renderer.ts';
import { UI_SPRITE_SCALE, floorPx, px, shiftPx } from '../render/units.ts';

export const SPLASH_IMAGE_MS = 2000;

export const SPLASH_RECORDS = [0, 1, 2] as const;

export const SPLASH_GROUND = { EARLY: 0xffffff, LAST: 0xa51710 } as const;

export const SPLASH_BAR = { TRACK: 0xc0c0c0, FILL: 0x50337d } as const;

export interface SplashBoot {
  openStores?(): void;
  splashTextures?(): Promise<TextureLookup>;
  load?(onProgress: (fraction: number) => void): Promise<void>;
  build?(): void;
  done?(): void;
}

export interface SplashSceneView {
  layers: Layers;
  textures?: TextureLookup;
}

export interface SplashSceneOptions {
  boot?: SplashBoot;
  view?: SplashSceneView;
}

export class SplashScene implements Scene {
  private step = 0;
  private index = 0;
  private elapsedMs = 0;
  private handedOff = false;

  private progress = 0;
  private loading = false;
  private loaded = false;

  failure: unknown = null;

  private readonly boot: SplashBoot;
  private readonly viewOptions: SplashSceneView | undefined;

  private textures: TextureLookup | undefined;
  private root: Container | null = null;
  private ground: Graphics | null = null;
  private image: Sprite | null = null;
  private bar: Graphics | null = null;
  private drawnIndex = -1;
  private drawnProgress = -1;

  constructor(options: SplashSceneOptions = {}) {
    this.boot = options.boot ?? {};
    this.viewOptions = options.view;
    this.textures = options.view?.textures;
  }

  get bootStep(): number {
    return this.step;
  }

  get splashIndex(): number {
    return this.index;
  }

  get loadProgress(): number {
    return this.progress;
  }

  enter(): void {
    this.index = 0;
    this.elapsedMs = 0;

    const view = this.viewOptions;
    if (view) {
      const root = new Container({ label: 'splash' });
      this.ground = new Graphics();
      this.image = new Sprite();
      this.image.anchor.set(0.5, 0.5);
      this.image.scale.set(UI_SPRITE_SCALE);
      this.image.x = shiftPx(LOGICAL_WIDTH, 1);
      this.image.y = shiftPx(LOGICAL_HEIGHT, 1);
      this.bar = new Graphics();
      root.addChild(this.ground, this.image, this.bar);
      view.layers.overlay.addChild(root);
      this.root = root;
    }

    const splashTextures = this.boot.splashTextures;
    if (splashTextures && !this.textures) {
      void splashTextures().then(
        (textures) => this.setTextures(textures),
        (error: unknown) => console.warn('splash art failed to load', error),
      );
    }
  }

  exit(): void {
    this.root?.destroy({ children: true });
    this.root = null;
    this.ground = null;
    this.image = null;
    this.bar = null;
  }

  setTextures(textures: TextureLookup): void {
    this.textures = textures;
    this.drawnIndex = -1;
  }

  update(): void {
    if (this.step === 0) ++this.step;

    if (this.step === 1) {
      this.boot.openStores?.();
      ++this.step;
      this.startLoad();
      this.stepSplash();
      return;
    }

    if (this.step === 2 && this.loaded) ++this.step;

    if (this.step === 3) {
      this.boot.build?.();
      this.step = 5;
      this.stepSplash();
      return;
    }

    if (this.step === 5) {
      this.stepSplash();
      return;
    }

    if (this.step === 6) this.step += 2;
    if (this.step === 7) return;

    if (this.step === 8 && !this.handedOff) {
      this.handedOff = true;
      this.boot.done?.();
    }

    this.stepSplash();
  }

  render(): void {
    if (!this.root) return;

    if (this.index !== this.drawnIndex) {
      this.drawnIndex = this.index;
      const colour = this.index === 2 ? SPLASH_GROUND.LAST : SPLASH_GROUND.EARLY;
      this.ground!.clear().rect(0, 0, LOGICAL_WIDTH, LOGICAL_HEIGHT).fill(colour);
      const texture = this.splashTexture(this.index);
      this.image!.visible = texture !== undefined;
      if (texture) this.image!.texture = texture;
    }

    const barUp = this.step >= 2 && this.step < 5;
    const shown = barUp ? this.progress : -1;
    if (shown === this.drawnProgress) return;
    this.drawnProgress = shown;

    const bar = this.bar!;
    bar.clear();
    if (!barUp) return;

    const top = LOGICAL_HEIGHT - px(9);
    bar.rect(px(5), top, LOGICAL_WIDTH - px(10), px(7)).fill(SPLASH_BAR.TRACK);
    const filled = floorPx((LOGICAL_WIDTH - px(12)) * clamp01(this.progress));
    if (filled > 0) bar.rect(px(6), top + px(1), filled, px(5)).fill(SPLASH_BAR.FILL);
  }

  private stepSplash(): void {
    this.elapsedMs += TICK_MS;

    if (this.step === 5 && this.index === 2) {
      if (this.elapsedMs >= SPLASH_IMAGE_MS) ++this.step;
      return;
    }

    if (this.elapsedMs > SPLASH_IMAGE_MS) {
      if (++this.index > 2) this.index = 2;
      this.elapsedMs = 0;
    }
  }

  private startLoad(): void {
    const load = this.boot.load;
    if (this.loading || this.loaded) return;
    if (!load) {
      this.loaded = true;
      return;
    }

    this.loading = true;
    void load((fraction) => {
      this.progress = clamp01(fraction);
    }).then(
      () => {
        this.progress = 1;
        this.loaded = true;
      },
      (error: unknown) => {
        this.failure = error;
        console.error('boot failed', error);
      },
    );
  }

  private splashTexture(index: number): Texture | undefined {
    const record = SPLASH_RECORDS[index];
    if (record === undefined) return undefined;
    return this.textures?.[recordFrame(record)];
  }
}

function clamp01(value: number): number {
  return value < 0 ? 0 : value > 1 ? 1 : value;
}
