import { STATE } from '../game/Bike.ts';

import type { AudioService, SfxVoice } from './AudioService.ts';
import type { Haptics } from './Haptics.ts';

export const SFX = {
  ENGINE: 1000,
  JUMP: 1001,
  LAND: 1002,
  CRASH: 1003,
  MENU_MOVE: 1004,
  MENU_SELECT: 1005,
} as const;

export const SFX_TRACKS: Readonly<Record<number, string>> = {
  [SFX.ENGINE]: 'engine.ogg',
  [SFX.JUMP]: 'jump.ogg',
  [SFX.LAND]: 'land.ogg',
  [SFX.CRASH]: 'crash.ogg',
  [SFX.MENU_MOVE]: 'menu-move.ogg',
  [SFX.MENU_SELECT]: 'menu-select.ogg',
};

export const ENGINE_IDLE_RATE = 0.7;

export const ENGINE_TOP_RATE = 1.9;

export const ENGINE_AIRBORNE = 0.85;

export const ENGINE_RATE_STEP = 0.06;

export const JUMP_TICKS = 4;

export interface RideSample {
  speed: number;
  airborne: number;
  crashed: boolean;
}

function unit(value: number): number {
  return value < 0 ? 0 : value > 1 ? 1 : value;
}

export function engineRateOf(sample: RideSample): number {
  const span = ENGINE_TOP_RATE - ENGINE_IDLE_RATE;
  let load = unit(sample.speed);
  if (sample.airborne > JUMP_TICKS && load < ENGINE_AIRBORNE) load = ENGINE_AIRBORNE;
  return ENGINE_IDLE_RATE + span * load;
}

export function sampleRide(bike: {
  groundSpeed: number;
  airborne: number;
  crashTimer: number;
  state: Int32Array;
}): RideSample {
  const topSpeed = bike.state[STATE.TOP_SPEED] ?? 0;
  const speed = bike.groundSpeed < 0 ? -bike.groundSpeed : bike.groundSpeed;
  return {
    speed: topSpeed > 0 ? unit(speed / topSpeed) : 0,
    airborne: bike.airborne,
    crashed: bike.crashTimer >= 0,
  };
}

export class SfxDirector {
  private readonly audio: AudioService;

  private readonly haptics: Haptics | null;

  private engine: SfxVoice | null = null;

  private running = false;

  private wasAirborne = false;
  private wasCrashed = false;
  private rate = ENGINE_IDLE_RATE;

  constructor(audio: AudioService, haptics: Haptics | null = null) {
    this.audio = audio;
    this.haptics = haptics;
  }

  get engineRunning(): boolean {
    return this.engine?.active ?? false;
  }

  get engineRate(): number {
    return this.rate;
  }

  start(): void {
    this.running = true;
    this.wasAirborne = false;
    this.wasCrashed = false;
    this.rate = ENGINE_IDLE_RATE;
  }

  stop(): void {
    this.running = false;
    this.engine?.stop();
    this.engine = null;
    this.haptics?.cancel();
  }

  update(sample: RideSample): void {
    if (!this.running) return;

    const airborne = sample.airborne > JUMP_TICKS;
    if (sample.crashed && !this.wasCrashed) {
      this.audio.playSfx(SFX.CRASH);
      this.haptics?.crash();
      this.stopEngine();
    } else if (!sample.crashed) {
      if (airborne && !this.wasAirborne) this.audio.playSfx(SFX.JUMP);
      else if (!airborne && this.wasAirborne) this.audio.playSfx(SFX.LAND);
    }
    this.wasAirborne = airborne;
    this.wasCrashed = sample.crashed;

    if (sample.crashed) return;

    const target = engineRateOf(sample);
    const step = target - this.rate;
    this.rate +=
      step > ENGINE_RATE_STEP
        ? ENGINE_RATE_STEP
        : step < -ENGINE_RATE_STEP
          ? -ENGINE_RATE_STEP
          : step;

    if (!this.engine?.active) this.engine = this.audio.loopSfx(SFX.ENGINE, this.rate);
    else this.engine.setRate(this.rate);
  }

  menuMove(): void {
    this.audio.playSfx(SFX.MENU_MOVE);
  }

  menuSelect(): void {
    this.audio.playSfx(SFX.MENU_SELECT);
  }

  private stopEngine(): void {
    this.engine?.stop();
    this.engine = null;
    this.rate = ENGINE_IDLE_RATE;
  }
}
