export const STALL_PAUSE_MS = 1500;

export interface LifecycleSink {
  pause(): void;
}

export interface VisibilityDocument extends EventTarget {
  readonly hidden: boolean;
}

export interface LifecycleOptions {
  sink: LifecycleSink;
  document?: VisibilityDocument;
  view?: EventTarget;
  stallMs?: number;
  pauseOnBlur?: boolean;
}

export class Lifecycle {
  private readonly sink: LifecycleSink;
  private readonly doc: VisibilityDocument | undefined;
  private readonly view: EventTarget | undefined;
  private readonly stallMs: number;
  private readonly pauseOnBlur: boolean;
  private detachers: Array<() => void> = [];
  private armed = true;
  private lastPoke: number | undefined;

  constructor(options: LifecycleOptions) {
    this.sink = options.sink;
    this.doc =
      options.document ?? (typeof document === 'undefined' ? undefined : document);
    this.view = options.view ?? (typeof window === 'undefined' ? undefined : window);
    this.stallMs = options.stallMs ?? STALL_PAUSE_MS;
    this.pauseOnBlur = options.pauseOnBlur ?? false;
  }

  attach(): () => void {
    const doc = this.doc;
    if (doc) {
      this.listen(doc, 'visibilitychange', () => {
        if (doc.hidden) this.hide();
        else this.armed = true;
      });
    }
    const view = this.view;
    if (view) {
      this.listen(view, 'pagehide', () => this.hide());
      this.listen(view, 'freeze', () => this.hide());
      this.listen(view, 'resume', () => {
        this.armed = true;
        this.lastPoke = undefined;
      });
      if (this.pauseOnBlur) this.listen(view, 'blur', () => this.hide());
    }
    return () => this.detach();
  }

  detach(): void {
    for (const detacher of this.detachers) detacher();
    this.detachers = [];
  }

  hide(): void {
    if (!this.armed) return;
    this.armed = false;
    this.lastPoke = undefined;
    this.sink.pause();
  }

  poke(now: number): void {
    const previous = this.lastPoke;
    this.lastPoke = now;
    if (this.stallMs <= 0 || previous === undefined) return;
    if (now - previous > this.stallMs) this.hide();
  }

  resume(): void {
    this.armed = true;
    this.lastPoke = undefined;
  }

  get isArmed(): boolean {
    return this.armed;
  }

  private listen(target: EventTarget, type: string, handler: () => void): void {
    target.addEventListener(type, handler);
    this.detachers.push(() => target.removeEventListener(type, handler));
  }
}
