const MULTIPLIER = 0x5deece66dn;
const ADDEND = 0xbn;
const MASK = (1n << 48n) - 1n;

const DOUBLE_UNIT = 1 / 2 ** 53;

export class JavaRandom {
  private seed = 0n;

  constructor(seed: number | bigint = Date.now()) {
    this.setSeed(seed);
  }

  setSeed(seed: number | bigint): void {
    this.seed = (BigInt(seed) ^ MULTIPLIER) & MASK;
  }

  next(bits: number): number {
    this.seed = (this.seed * MULTIPLIER + ADDEND) & MASK;
    return Number(BigInt.asIntN(32, this.seed >> BigInt(48 - bits)));
  }

  nextInt(): number {
    return this.next(32);
  }

  nextLong(): bigint {
    const high = BigInt(this.next(32));
    const low = BigInt(this.next(32));
    return BigInt.asIntN(64, (high << 32n) + low);
  }

  nextDouble(): number {
    return (this.next(26) * 2 ** 27 + this.next(27)) * DOUBLE_UNIT;
  }

  between(min: number, max: number): number {
    if (max === min) return min;
    let n = this.nextInt();
    if (n < 0) n = -n | 0;
    return (min + (n % (max - min))) | 0;
  }
}
