import type { AppShell } from '../AppShell.ts';
import { openExitLink } from '../HighScores.ts';
import { SHELL_ACTION } from './actions.ts';
import { BUSY_STRING, SHELL_MODE } from './screens.ts';

export function showBusy(shell: AppShell, stringId: number): void {
  shell.busy = true;
  if (shell.list?.tickerText != null) shell.previousTicker = shell.list.tickerText;
  shell.view?.setBusy(shell.table.text(stringId));
  if (shell.mode === SHELL_MODE.RACE) shell.race?.setActive(false);
}

export function hideBusyQuiet(shell: AppShell): void {
  shell.busy = false;
  shell.view?.setBusy(null);
  shell.list?.setTicker(shell.previousTicker);
  shell.previousTicker = null;
  shell.input.clear();
  if (shell.mode === SHELL_MODE.RACE) shell.race?.setActive(true);
}

export function hideBusy(shell: AppShell): void {
  hideBusyQuiet(shell);
  if (shell.mode !== SHELL_MODE.RACE) shell.refreshScreen();
}

export function clearAllData(shell: AppShell): void {
  shell.showBusy(BUSY_STRING.DELETING);
  shell.save.clearAllStores();
  shell.save.resetProgress(false);
  shell.board = null;
  shell.save.loadBestResults();
  shell.hideBusy();
  shell.runAction(SHELL_ACTION.BACK, -1);
}

export function openShellExitLink(shell: AppShell, param: number): void {
  const open = shell.openUrl;
  if (!open) return;
  openExitLink(param, shell.exitLink, {
    open,
    shutdown: () => {
      shell.shutdown();
    },
  });
}

export function shutdown(shell: AppShell): void {
  shell.showBusy(BUSY_STRING.EXITING);
  shell.save.flushAllStores();
  shell.audio.stopSound();
  shell.onShutdown?.();
}

export function installLanguageHost(shell: AppShell): void {
  shell.language.setHost({
    showBusy: (stringId) => {
      shell.showBusy(stringId);
    },
    hideBusy: () => {
      shell.hideBusy();
    },
    refreshStrings: () => {
      shell.refreshStrings();
    },
    back: () => {
      shell.runAction(SHELL_ACTION.BACK, -1);
    },
  });
}
