import {
  MENUS,
  MENU_ICON,
  MENU_ITEMS,
  STRING,
  type Menu,
  type MenuItem,
} from '../../data/constants.ts';
import { refreshStrings } from '../../i18n/Strings.ts';
import { highScoreScreen, removeMenuItem } from '../HighScores.ts';
import { appProperty } from './properties.ts';

import type { AppShell } from '../AppShell.ts';
import { SHELL_ACTION } from './actions.ts';
import { CONDITION, conditionMet } from './Conditions.ts';
import { SCREEN } from './screens.ts';

export const RANK_ICON_BASE = MENU_ICON.RANK_NONE;

export const BONUS_GROUP_STRING = STRING.BONUS;

export const FREE_RIDE_STRINGS = [
  STRING.FREE_RIDE_SEATTLE,
  STRING.FREE_RIDE_DENVER,
] as const;

export const SOUND_ROW_STRINGS = [STRING.JUKEBOX, STRING.MUSIC, STRING.SOUND] as const;

export const HIGH_SCORE_ROW_INDEX = 1;

export const HIGH_SCORE_ROW: MenuItem = {
  labelString: STRING.HIGH_SCORE,
  icon: 1,
  tickerString: STRING.CHECK_OUT_WHAT_OTHER,
  action: SHELL_ACTION.OPEN_WITH_BACK,
  param: SCREEN.SCORES,
  enabled: 1,
  condition: CONDITION.SAVED_RESULTS,
};

export function copyRows(items: readonly MenuItem[]): MenuItem[] {
  return items.map((item) => ({ ...item }));
}

export class MenuModel {
  menus: Menu[] = [];
  items: MenuItem[][] = [];

  partsHeader: Menu = MENUS[SCREEN.PARTS]!;
  partsItems: MenuItem[] = [];
  careerTemplate: MenuItem[] = [];
  freeRideTemplate: MenuItem[] = [];
  challengeTemplate: MenuItem[] = [];

  build(shell: AppShell): void {
    this.menus = MENUS.map((menu) => ({ ...menu }));
    this.items = MENU_ITEMS.map((items) => copyRows(items));

    const board = highScoreScreen({ titleString: HIGH_SCORE_ROW.labelString });
    this.menus[SCREEN.SCORES] = board.menu;
    this.items[SCREEN.SCORES] = board.items;
    const title = this.items[SCREEN.TITLE]!;
    this.items[SCREEN.TITLE] = [
      ...title.slice(0, HIGH_SCORE_ROW_INDEX),
      { ...HIGH_SCORE_ROW },
      ...title.slice(HIGH_SCORE_ROW_INDEX),
    ];

    shell.screenBack.length = 0;
    shell.screenSelection.length = 0;
    for (let index = 0; index < this.menus.length; index += 1) {
      shell.screenBack.push(0);
      shell.screenSelection.push(0);
    }
    shell.screenBack[SCREEN.TITLE] = SCREEN.EXIT;

    this.partsItems = this.items[SCREEN.PARTS]!;
    this.partsHeader = this.menus[SCREEN.PARTS]!;
    this.careerTemplate = this.items[SCREEN.CAREER]!;
    this.freeRideTemplate = this.items[SCREEN.FREE_RIDE]!;
    this.challengeTemplate = this.items[SCREEN.CHALLENGE]!;

    this.items[SCREEN.OPTIONS] = copyRows(this.optionRows(shell));
    this.refreshExitScreen(shell);
  }

  refreshExitScreen(shell: AppShell): void {
    const properties = shell.properties;
    this.items[SCREEN.EXIT] = copyRows(
      refreshStrings(shell.table, {
        appProperties: {
          name: appProperty(properties, 'MIDlet-Name') ?? '',
          vendor: appProperty(properties, 'MIDlet-Vendor') ?? '',
          version: appProperty(properties, 'MIDlet-Version') ?? '',
        },
        exitLink: shell.exitLink,
        exitItems: MENU_ITEMS[SCREEN.EXIT] ?? [],
      }),
    );
  }

  private optionRows(shell: AppShell): readonly MenuItem[] {
    let rows: readonly MenuItem[] = shell.language.optionsItems(
      this.items[SCREEN.OPTIONS]!,
    );
    if (shell.soundPresent) return rows;
    for (const label of SOUND_ROW_STRINGS) rows = removeMenuItem(rows, label);
    return rows;
  }

  private groupRank(shell: AppShell, careerRow: number): number {
    const group = this.items[SCREEN.CAREER]![careerRow]!.param;
    const rows = this.items[group] ?? [];
    let rank = 4;
    for (let index = 0; index < rows.length - 1; index += 1) {
      rank = Math.min(rank, shell.save.challengeRank(rows[index]!.param));
    }
    return rank;
  }

  rebuildCareerMenu(shell: AppShell): void {
    let rows: readonly MenuItem[] = copyRows(this.careerTemplate);
    const unlocked = shell.save.unlocked;
    if (!unlocked.freeRide1 && !unlocked.freeRide2) {
      rows = removeMenuItem(rows, BONUS_GROUP_STRING);
    }
    const items = copyRows(rows);
    this.items[SCREEN.CAREER] = items;
    for (let index = 0; index < items.length - 1; index += 1) {
      const item = items[index]!;
      if (item.labelString === BONUS_GROUP_STRING) continue;
      item.icon = RANK_ICON_BASE + this.groupRank(shell, index);
    }
  }

  refreshRankIcons(shell: AppShell, screen: number): void {
    if (screen === SCREEN.FREE_RIDE) {
      this.items[SCREEN.FREE_RIDE] = copyRows(this.freeRideRows(shell));
      return;
    }
    const rows = this.items[screen] ?? [];
    for (let index = 0; index < rows.length - 1; index += 1) {
      const item = rows[index]!;
      item.icon = RANK_ICON_BASE + shell.save.challengeRank(item.param);
    }
  }

  private freeRideRows(shell: AppShell): readonly MenuItem[] {
    let rows: readonly MenuItem[] = copyRows(this.freeRideTemplate);
    if (!shell.save.freeRideUnlocked(0))
      rows = removeMenuItem(rows, FREE_RIDE_STRINGS[0]);
    if (!shell.save.freeRideUnlocked(1))
      rows = removeMenuItem(rows, FREE_RIDE_STRINGS[1]);
    return rows;
  }

  applyConditions(shell: AppShell, screen: number): void {
    for (const item of this.items[screen] ?? []) {
      item.enabled = conditionMet(shell, item.condition, item.param) ? 1 : 0;
    }
  }
}
