export const REPLAY_MODE = {
  IDLE: 0,
  RECORDING: 1,
  PLAYBACK: 2,
  AI: 3,
} as const;

export const AI_COLUMN = {
  ENGINE: 0,
  SPRINT: 1,
  BOOST: 2,
  GROUND_LEAN: 3,
  AIR_LEAN: 4,
  TRICK_CHANCE: 5,
  TRICK_HEIGHT: 6,
} as const;

function profileCell(profile: number, column: number): number {
  return AI_PROFILES[profile]?.[`col${column}`] ?? 0;
}

