export class ReplayBike extends Bike {
  static frame = 0;

  static frameCount = 0;

  static random = new JavaRandom();

  private replayMode: number = REPLAY_MODE.IDLE;

  result = -1;

  startSnapshot: Int32Array | null = null;
  eventStream: Uint8Array | null = null;

  private recorded: number[] = [];
  private lastInputBits = -1;
  private lastEventFrame = 0;

  private readAt = 0;
  private nextEventFrame = 0;
  private replayEnded = false;

  isIdle(): boolean {
    return this.replayMode === REPLAY_MODE.IDLE;
  }

  replayFinished(): boolean {
    return this.replayMode === REPLAY_MODE.PLAYBACK && this.replayEnded;
  }

  hasReplay(): boolean {
    return this.startSnapshot !== null && this.eventStream !== null;
  }

  get mode(): number {
    return this.replayMode;
  }

  startRecording(): void {
    this.recorded = [];
    this.lastInputBits = -1;
    this.inputBits = 0;
    this.replayMode = REPLAY_MODE.RECORDING;
  }

  stopRecording(result: number): void {
    this.result = result;
    if (this.replayMode !== REPLAY_MODE.RECORDING) return;
    if (result > 0) {
      this.eventStream = Uint8Array.from(this.recorded);
    } else {
      this.eventStream = null;
      this.startSnapshot = null;
    }
    this.recorded = [];
    this.replayMode = REPLAY_MODE.IDLE;
  }

  private recordInput(frame: number): void {
    const delta = frame - this.lastEventFrame;
    if (this.inputBits === this.lastInputBits && delta < EVENT_MAX_GAP) return;
    this.lastEventFrame = frame;
    this.recorded.push(delta & 0xff, this.inputBits & 0xff);
    this.lastInputBits = this.inputBits;
  }

  takeReplayFrom(other: ReplayBike): void {
    if (other.startSnapshot === null) return;
    this.result = other.result;
    this.startSnapshot = other.startSnapshot;
    this.eventStream = other.eventStream;
    this.replayMode = REPLAY_MODE.IDLE;
  }

  startPlayback(): void {
    if (!this.hasReplay()) return;
    this.nextEventFrame = 0;
    this.inputBits = 0;
    this.replayEnded = false;
    this.readAt = 0;
    this.crashTimer = -1;
    this.replayMode = REPLAY_MODE.PLAYBACK;
  }

  stopReplay(): void {
    this.replayMode = REPLAY_MODE.IDLE;
  }

  clearReplay(): void {
    this.stopReplay();
    this.startSnapshot = null;
    this.eventStream = null;
    this.result = -1;
  }

  loadGhost(bytes: Uint8Array): boolean {
    this.replayMode = REPLAY_MODE.IDLE;
    const ghost = decodeGhost(bytes);
    if (ghost === null) return false;
    this.track = ghost.track;
    this.result = ghost.result;
    this.startSnapshot = ghost.snapshot;
    this.eventStream = ghost.events;
    return true;
  }

  toGhost(): Ghost | null {
    if (this.startSnapshot === null || this.eventStream === null) return null;
    return {
      track: this.track,
      result: this.result,
      snapshot: this.startSnapshot,
      events: this.eventStream,
    };
  }

  setOpponent(profile: number): void {
    this.opponentProfile = profile;
    this.replayMode = profile >= 0 ? REPLAY_MODE.AI : REPLAY_MODE.IDLE;
  }

  private updateAi(): void {
    if (this.crashTimer >= 0) return;
    const profile = this.opponentProfile;

    let leanTarget = -(profileCell(profile, AI_COLUMN.AIR_LEAN) << 4);

    if (this.isGrounded()) {
      leanTarget = this.rideGround(profile, leanTarget);
    } else {
      this.tryAirTrick(profile);
    }

    this.steerToLean(leanTarget);
  }

  private rideGround(profile: number, leanTarget: number): number {
    if (this.rearGrounded) {
      this.aiTargetHeight = this.rearContactNormal[1]!;
      if (this.frontGrounded) {
        this.aiTargetHeight += this.frontContactNormal[1]!;
        this.aiTargetHeight >>= 1;
      }
    }
    if (this.rearGrounded || this.frontGrounded) {
      const maySprint = profileCell(profile, AI_COLUMN.SPRINT) !== 0;
      const mayBoost = profileCell(profile, AI_COLUMN.BOOST) !== 0;
      if (maySprint && this.gapToPlayer > 4 * BIKE_LENGTH_FIXED) {
        if ((ReplayBike.frameCount & 1) === 0) this.pressInput(BIKE_INPUT.THROTTLE);
      } else if (mayBoost && this.gapToPlayer < -12 * BIKE_LENGTH_FIXED) {
        this.pressInput(BIKE_INPUT.BOOST);
      } else {
        this.pressInput(BIKE_INPUT.THROTTLE);
      }
      leanTarget =
        this.aiTargetHeight - (profileCell(profile, AI_COLUMN.GROUND_LEAN) << 4);
    }
    return leanTarget;
  }

  private tryAirTrick(profile: number): void {
    const rear = jointAt(JOINT.REAR_WHEEL);
    const rise = this.joints[rear + JOINT_Y]! - this.joints[rear + JOINT_PREVIOUS_Y]!;
    const height = this.terrain.heightAt(this.joints[rear + JOINT_X]!) - this.bounds.minY;
    const floor = profileCell(profile, AI_COLUMN.TRICK_HEIGHT) << 10;
    if (height > floor && rise < -512) {
      const chance = profileCell(profile, AI_COLUMN.TRICK_CHANCE);
      if (chance > 0 && ReplayBike.random.between(0, chance) === chance >> 1) {
        this.requestTrick(ReplayBike.random.between(3, 9));
      }
    }
  }

  private steerToLean(leanTarget: number): void {
    this.updateHeading();
    const swing =
      !this.frontGrounded || !this.rearGrounded
        ? (this.headingY - this.previousHeadingY) << 7
        : 0;
    const wanted = -((((this.headingY + swing - leanTarget) << 10) >> 7) | 0) | 0;
    const error = (wanted - this.lean) | 0;
    if (Math.abs(error) > 128) {
      if (error < 0) this.pressInput(BIKE_INPUT.LEAN_LEFT);
      if (error > 0) this.pressInput(BIKE_INPUT.LEAN_RIGHT);
    }
    this.previousHeadingY = this.headingY;
  }

  protected override enginePenalty(): number {
    if (!this.isOpponent || this.replayMode !== REPLAY_MODE.AI) return 0;
    return profileCell(this.opponentProfile, AI_COLUMN.ENGINE) << 7;
  }

  protected override sampleInput(): void {
    const frame = ReplayBike.frame;

    if (this.replayMode === REPLAY_MODE.RECORDING) {
      if (frame === 0) {
        this.startSnapshot = new Int32Array(this.snapshotSize());
        this.saveSnapshot(this.startSnapshot);
        this.lastEventFrame = 0;
      }
      this.recordInput(frame);
      return;
    }

    if (this.replayMode === REPLAY_MODE.PLAYBACK) {
      if (this.nextEventFrame <= frame) this.readEvent(frame);
      return;
    }

    if (this.replayMode === REPLAY_MODE.AI) this.updateAi();
  }

  protected override retainsInput(): boolean {
    return this.replayMode === REPLAY_MODE.PLAYBACK;
  }

  private readEvent(frame: number): void {
    if (frame === 0) {
      this.nextEventFrame = 0;
      if (this.startSnapshot !== null) this.loadSnapshot(this.startSnapshot);
      this.readAt = 1;
    }

    const bits = this.readByte();
    if (bits < 0) {
      this.endReplay();
      return;
    }
    this.inputBits = bits;

    const delta = this.readByte();
    if (delta < 0) {
      this.endReplay();
      return;
    }
    this.nextEventFrame += delta;
  }

  private readByte(): number {
    const stream = this.eventStream;
    if (stream === null || this.readAt >= stream.length) return -1;
    return stream[this.readAt++]!;
  }

  private endReplay(): void {
    this.replayEnded = true;
    this.nextEventFrame = 0x7fffffff;
  }
}

export function ghostHooks(player: ReplayBike, opponent?: ReplayBike): RaceHooks {
  return {
    frame(frame: number): void {
      ReplayBike.frame = frame;
    },
    startRecording(): void {
      player.startRecording();
    },
    stopRecording(frame: number): void {
      player.stopRecording(frame);
    },
    startPlayback(): void {
      opponent?.startPlayback();
    },
    stopReplay(): void {
      opponent?.stopReplay();
    },
    takeReplay(improved: boolean): void {
      if (opponent === undefined) return;
      if (improved && player.hasReplay()) opponent.takeReplayFrom(player);
    },
    replayFinished(): boolean {
      return opponent?.replayFinished() ?? false;
    },
    opponentIdle(): boolean {
      return opponent?.isIdle() ?? true;
    },
    setOpponent(profile: number): void {
      opponent?.setOpponent(profile);
    },
  };
}

export const GHOST_VERSION = 1;

export const GHOST_BUDGET_BYTES = 60 * 1024;

export interface GhostStoreOptions {
  storage: StorageLike;
  prefix?: string;
  budget?: number;
  migrations?: Readonly<Record<number, (bytes: Uint8Array) => Uint8Array>>;
}

export class GhostStore {
  private readonly storage: StorageLike;
  private readonly prefix: string;
  private readonly budget: number;
  private readonly migrations: Readonly<
    Record<number, (bytes: Uint8Array) => Uint8Array>
  >;

  constructor(options: GhostStoreOptions) {
    this.storage = options.storage;
    this.prefix = options.prefix ?? 'motox.';
    this.budget = options.budget ?? GHOST_BUDGET_BYTES;
    this.migrations = options.migrations ?? {};
  }

  private key(challenge: number): string {
    return `${this.prefix}ghost.${challenge}`;
  }

  load(challenge: number): Ghost | null {
    const raw = this.storage.getItem(this.key(challenge));
    if (raw === null) return null;

    let version = 0;
    let payload = raw;
    const match = /^v(\d+):/.exec(raw);
    if (match !== null) {
      version = Number(match[1]);
      payload = raw.slice(match[0].length);
    }

    let bytes: Uint8Array;
    try {
      bytes = decodeBase64(payload);
    } catch {
      return null;
    }

    while (version < GHOST_VERSION) {
      const migration = this.migrations[version];
      if (migration === undefined) return null;
      bytes = migration(bytes);
      version += 1;
    }

    return decodeGhost(bytes);
  }

  save(challenge: number, ghost: Ghost): boolean {
    const previous = this.load(challenge);
    if (previous !== null && previous.result !== 0 && ghost.result >= previous.result) {
      return false;
    }

    const bytes = encodeGhost(ghost);
    if (this.usedBytes(challenge) + bytes.length > this.budget) return false;

    this.storage.setItem(this.key(challenge), `v${GHOST_VERSION}:${encodeBase64(bytes)}`);
    return true;
  }

  clear(challenge: number): void {
    this.storage.removeItem(this.key(challenge));
  }

  usedBytes(except = -1): number {
    let total = 0;
    for (let challenge = 0; challenge < CHALLENGE_COUNT; challenge += 1) {
      if (challenge === except) continue;
      const stored = this.load(challenge);
      if (stored !== null) total += encodeGhost(stored).length;
    }
    return total;
  }
}
