import {
  CHALLENGES,
  CHALLENGE_TYPES,
  RANK,
  STRING,
  TARGET_FORMAT,
  type Challenge,
} from '../data/constants.ts';
import { TRICK, TRICK_SLOTS } from './Bike.ts';
import { TRICK_TEXT_BASE } from './TrickDetector.ts';

const MS_PER_TICK = 60;

const COUNTED_TRICK_FIRST = TRICK.CORDOVA;
const COUNTED_TRICK_LAST = TRICK.MC_METZ;

export const MEASURE_TEXT = {
  TIME: STRING.TIME,
  TRICKS: STRING.TRICKS,
  SHOW_DOWN: STRING.YOUR_TIME,
} as const;

export const POINTS_FIRST_MEDAL = 100;
export const POINTS_PER_STEP = 50;

export interface RunOutcome {
  timeMs: number;
  trickTotals: ArrayLike<number>;
  opponentTimeMs?: number;
}

export interface ChallengeResult {
  rank: number;
  result: number;
  measureTextId: number;
  missingTrickTextIds: readonly number[];
}

export function rankFor(
  value: number,
  gold: number,
  silver: number,
  bronze: number,
): number {
  if (value > bronze) return RANK.UNRANKED;
  if (value > silver) return RANK.BRONZE;
  if (value > gold) return RANK.SILVER;
  return RANK.GOLD;
}

export function isComboChallenge(challenge: number): boolean {
  return CHALLENGES[challenge]!.type === 5;
}

export function missingTricks(
  challenge: number,
  trickTotals?: ArrayLike<number>,
): number[] {
  const mask = CHALLENGES[challenge]!.requirements;
  const missing: number[] = [];
  for (let slot = 0; slot < TRICK_SLOTS; slot += 1) {
    if ((mask & (1 << slot)) === 0) continue;
    if (trickTotals !== undefined && trickTotals[slot] !== 0) continue;
    missing.push(slot);
  }
  return missing;
}

export function gradeChallenge(challenge: number, outcome: RunOutcome): ChallengeResult {
  const row = CHALLENGES[challenge]!;
  const format = CHALLENGE_TYPES[row.type]!.targetFormat;
  const [bronze, silver, gold] = targets(row, format);

  switch (format) {
    case TARGET_FORMAT.TIME_MINUTES:
      return gradeTime(challenge, outcome, bronze, silver, gold);
    case TARGET_FORMAT.NUMBER:
      return gradeTrickCount(outcome, bronze, silver, gold);
    case TARGET_FORMAT.TRICK_LIST:
      return gradeTrickList(outcome, bronze, silver, gold);
    case TARGET_FORMAT.TIME_SECONDS:
      return gradeShowDown(outcome, bronze, silver, gold);
    default:
      return {
        rank: RANK.UNRANKED,
        result: 0,
        measureTextId: MEASURE_TEXT.TIME,
        missingTrickTextIds: [],
      };
  }
}

function targets(row: Challenge, format: number): [number, number, number] {
  const scale =
    format === TARGET_FORMAT.TIME_MINUTES || format === TARGET_FORMAT.TIME_SECONDS
      ? MS_PER_TICK
      : 1;
  return [row.targetBronze * scale, row.targetSilver * scale, row.targetGold * scale];
}

function gradeTime(
  challenge: number,
  outcome: RunOutcome,
  bronze: number,
  silver: number,
  gold: number,
): ChallengeResult {
  let rank = rankFor(outcome.timeMs, gold, silver, bronze);
  let missing: number[] = [];

  if (isComboChallenge(challenge)) {
    missing = missingTricks(challenge, outcome.trickTotals);
    if (missing.length > 0) rank = RANK.UNRANKED;
  }

  return {
    rank,
    result: outcome.timeMs,
    measureTextId: MEASURE_TEXT.TIME,
    missingTrickTextIds: missing.map(textIdOf),
  };
}

function gradeTrickCount(
  outcome: RunOutcome,
  bronze: number,
  silver: number,
  gold: number,
): ChallengeResult {
  let landed = 0;
  for (let slot = COUNTED_TRICK_FIRST; slot <= COUNTED_TRICK_LAST; slot += 1) {
    landed += outcome.trickTotals[slot] ?? 0;
  }
  return {
    rank: rankFor(-landed, -gold, -silver, -bronze),
    result: -landed,
    measureTextId: MEASURE_TEXT.TRICKS,
    missingTrickTextIds: [],
  };
}

function gradeTrickList(
  outcome: RunOutcome,
  bronze: number,
  silver: number,
  gold: number,
): ChallengeResult {
  const totals = Int32Array.from(outcome.trickTotals as ArrayLike<number>);
  let rank: number = RANK.UNRANKED;
  const missing: number[] = [];

  if (totals[bronze]! > 0) {
    rank = RANK.BRONZE;
    totals[bronze] = totals[bronze]! - 1;
    if (totals[silver]! > 0) {
      rank = RANK.SILVER;
      totals[silver] = totals[silver]! - 1;
      if (totals[gold]! > 0) {
        totals[gold] = totals[gold]! - 1;
        rank = RANK.GOLD;
      } else {
        missing.push(gold);
      }
    } else {
      missing.push(silver);
    }
  } else {
    missing.push(bronze);
  }

  return {
    rank,
    result: 0,
    measureTextId: MEASURE_TEXT.TRICKS,
    missingTrickTextIds: missing.map(textIdOf),
  };
}

function gradeShowDown(
  outcome: RunOutcome,
  bronze: number,
  silver: number,
  gold: number,
): ChallengeResult {
  const margin = (outcome.opponentTimeMs ?? 0) - outcome.timeMs;
  return {
    rank: margin >= 0 ? rankFor(-margin, -gold, -silver, -bronze) : RANK.UNRANKED,
    result: outcome.timeMs,
    measureTextId: MEASURE_TEXT.SHOW_DOWN,
    missingTrickTextIds: [],
  };
}

export function improvesRank(previousRank: number, rank: number): boolean {
  if (rank === RANK.UNRANKED || rank === RANK.NONE) return false;
  return previousRank === RANK.NONE || previousRank < rank;
}

export function careerPointsFor(previousRank: number, rank: number): number {
  if (!improvesRank(previousRank, rank)) return 0;
  let points = previousRank < RANK.BRONZE ? POINTS_FIRST_MEDAL : 0;
  if (rank >= RANK.SILVER && previousRank < RANK.SILVER) points += POINTS_PER_STEP;
  if (rank >= RANK.GOLD && previousRank < RANK.GOLD) points += POINTS_PER_STEP;
  return points;
}

export function unlockedPartFor(
  challenge: number,
  previousRank: number,
  rank: number,
): number {
  const row = CHALLENGES[challenge]!;
  if (!improvesRank(previousRank, rank)) return -1;
  if (row.unlockPart < 0) return -1;
  if (previousRank >= row.unlockRank || rank < row.unlockRank) return -1;
  return row.unlockPart;
}

function textIdOf(slot: number): number {
  return TRICK_TEXT_BASE + slot;
}
