import { SOFT_KEYS } from '../../data/constants.ts';

import type { AppShell } from '../AppShell.ts';
import { RACE_SOFT_KEY, SHELL_MODE } from './screens.ts';
import type { ShellTouchState } from './types.ts';

function softKeyLabel(shell: AppShell, key: number): string | null {
  const row = SOFT_KEYS[key];
  if (!row) return null;
  return shell.table.text(row.labelString);
}

export function touchState(shell: AppShell): ShellTouchState {
  const mode = shell.mode;
  if (shell.busy || mode === SHELL_MODE.SPLASH) return { mode, left: null, right: null };
  if (mode === SHELL_MODE.RACE) {
    const left = RACE_SOFT_KEY.LEFT;
    const right = RACE_SOFT_KEY.RIGHT;
    return shell.swapSoftKeys
      ? { mode, left: softKeyLabel(shell, right), right: softKeyLabel(shell, left) }
      : { mode, left: softKeyLabel(shell, left), right: softKeyLabel(shell, right) };
  }
  const bar = shell.list?.softKeyBar() ?? { left: -1, right: -1 };
  return {
    mode,
    left: softKeyLabel(shell, bar.left),
    right: softKeyLabel(shell, bar.right),
  };
}

export function sameTouchState(
  last: ShellTouchState | null,
  next: ShellTouchState,
): boolean {
  return (
    last !== null &&
    last.mode === next.mode &&
    last.left === next.left &&
    last.right === next.right
  );
}
