import {
  GHOST_INPUT_FLAGS,
  GHOST_TRICK_NAMES,
  SNAPSHOT_JOINT_FIELDS,
  SNAPSHOT_JOINT_NAMES,
  SNAPSHOT_STATE_FIELDS,
  SNAPSHOT_TAIL_FIELDS,
  type SnapshotStateField,
  type SnapshotTailField,
} from '../data/snapshot-layout.ts';

export const GHOST_MAGIC = 0x4e4f5553;

export const EVENT_MAX_GAP = 255;

export const TRICK_MASK = 0x0f;

const HEADER_BYTES = 13;

export interface Ghost {
  track: number;
  result: number;
  snapshot: Int32Array;
  events: Uint8Array;
}

export type GhostJoint = { name: string } & Record<
  (typeof SNAPSHOT_JOINT_FIELDS)[number],
  number
>;

export type GhostStart = {
  state: Record<SnapshotStateField, number>;
  joints: readonly GhostJoint[];
} & Record<SnapshotTailField, number>;

export interface GhostEvent {
  frame: number;
  input: readonly string[];
  trick?: string;
}

export interface GhostJson {
  record: number;
  track: number;
  challenges: readonly number[];
  resultFrames: number;
  staleTrack: boolean;
  start: GhostStart;
  events: readonly GhostEvent[];
}

export interface GhostIdentity {
  record: number;
  challenges: readonly number[];
  staleTrack: boolean;
}

export function decodeGhost(bytes: Uint8Array): Ghost | null {
  if (bytes.length < HEADER_BYTES) return null;
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (view.getInt32(0, false) !== GHOST_MAGIC) return null;

  const track = view.getUint8(4);
  const result = view.getInt32(5, false);
  const snapshotInts = view.getInt32(9, false);
  if (snapshotInts < 0) return null;

  let at = HEADER_BYTES;
  if (at + snapshotInts * 4 + 4 > bytes.length) return null;
  const snapshot = new Int32Array(snapshotInts);
  for (let i = 0; i < snapshotInts; i += 1, at += 4)
    snapshot[i] = view.getInt32(at, false);

  const eventBytes = view.getInt32(at, false);
  at += 4;
  if (eventBytes < 0 || at + eventBytes > bytes.length) return null;

  return { track, result, snapshot, events: bytes.slice(at, at + eventBytes) };
}

export function encodeGhost(ghost: Ghost): Uint8Array {
  const bytes = new Uint8Array(
    HEADER_BYTES + ghost.snapshot.length * 4 + 4 + ghost.events.length,
  );
  const view = new DataView(bytes.buffer);

  view.setInt32(0, GHOST_MAGIC, false);
  view.setUint8(4, ghost.track & 0xff);
  view.setInt32(5, ghost.result | 0, false);
  view.setInt32(9, ghost.snapshot.length, false);

  let at = HEADER_BYTES;
  for (const value of ghost.snapshot) {
    view.setInt32(at, value, false);
    at += 4;
  }
  view.setInt32(at, ghost.events.length, false);
  bytes.set(ghost.events, at + 4);
  return bytes;
}

export function snapshotInts(): number {
  return (
    SNAPSHOT_STATE_FIELDS.length +
    SNAPSHOT_JOINT_NAMES.length * SNAPSHOT_JOINT_FIELDS.length +
    SNAPSHOT_TAIL_FIELDS.length
  );
}

function inputNames(bits: number): string[] {
  const names: string[] = [];
  let left = bits & 0xf0;
  for (const flag of GHOST_INPUT_FLAGS) {
    if ((left & flag.bits) === flag.bits) {
      names.push(flag.name);
      left &= ~flag.bits;
    }
  }
  if (left !== 0) throw new Error(`input bits ${bits} leave ${left} unnamed`);
  return names;
}

function inputBits(event: GhostEvent): number {
  let bits = 0;
  for (const name of event.input) {
    const flag = GHOST_INPUT_FLAGS.find((entry) => entry.name === name);
    if (flag === undefined) throw new Error(`unknown input '${name}'`);
    bits |= flag.bits;
  }
  const trick =
    event.trick === undefined
      ? 0
      : (GHOST_TRICK_NAMES as readonly string[]).indexOf(event.trick);
  if (trick < 0) throw new Error(`unknown trick '${event.trick}'`);
  return (bits | trick) & 0xff;
}

function readEvents(bytes: Uint8Array): GhostEvent[] {
  const events: GhostEvent[] = [];
  let frame = 0;
  for (let at = 0; at + 1 < bytes.length; at += 2) {
    frame += bytes[at]!;
    const bits = bytes[at + 1]!;
    const event: GhostEvent = { frame, input: inputNames(bits) };
    const trick = bits & TRICK_MASK;
    if (trick !== 0) {
      const name = GHOST_TRICK_NAMES[trick];
      if (name === undefined) throw new Error(`event bits ${bits} name no animation`);
      event.trick = name;
    }
    events.push(event);
  }
  return events;
}

function writeEvents(events: readonly GhostEvent[]): Uint8Array {
  const bytes: number[] = [];
  let frame = 0;
  let held = 0;
  for (const event of events) {
    let delta = event.frame - frame;
    if (delta < 0) throw new Error(`event frame ${event.frame} runs backwards`);
    while (delta > EVENT_MAX_GAP) {
      bytes.push(EVENT_MAX_GAP, held);
      delta -= EVENT_MAX_GAP;
    }
    held = inputBits(event);
    bytes.push(delta, held);
    frame = event.frame;
  }
  return Uint8Array.from(bytes);
}

export function ghostToJson(ghost: Ghost, identity: GhostIdentity): GhostJson {
  const snapshot = ghost.snapshot;
  let slot = 0;

  const state = {} as Record<SnapshotStateField, number>;
  for (const field of SNAPSHOT_STATE_FIELDS) state[field] = snapshot[slot++]!;

  const joints = SNAPSHOT_JOINT_NAMES.map((name) => {
    const joint = { name } as GhostJoint;
    for (const field of SNAPSHOT_JOINT_FIELDS) joint[field] = snapshot[slot++]!;
    return joint;
  });

  const start = { state, joints } as unknown as GhostStart;
  for (const field of SNAPSHOT_TAIL_FIELDS) start[field] = snapshot[slot++]!;

  return {
    record: identity.record,
    track: ghost.track,
    challenges: identity.challenges,
    resultFrames: ghost.result,
    staleTrack: identity.staleTrack,
    start,
    events: readEvents(ghost.events),
  };
}

export function ghostFromJson(json: GhostJson): Ghost {
  const snapshot = new Int32Array(snapshotInts());
  let slot = 0;

  for (const field of SNAPSHOT_STATE_FIELDS) snapshot[slot++] = json.start.state[field];
  for (const joint of json.start.joints) {
    for (const field of SNAPSHOT_JOINT_FIELDS) snapshot[slot++] = joint[field];
  }
  for (const field of SNAPSHOT_TAIL_FIELDS) snapshot[slot++] = json.start[field];

  return {
    track: json.track,
    result: json.resultFrames,
    snapshot,
    events: writeEvents(json.events),
  };
}
