import { fixedDiv, fixedMul, inverseLengthFixed, sqrtFixed } from '../core/fixed.ts';
import { FIXED_ONE, FIXED_SHIFT } from '../data/constants.ts';

import type { Terrain } from './Terrain.ts';

export const JOINT_STRIDE = 7;

export const JOINT_X = 0;
export const JOINT_Y = 1;
export const JOINT_PREVIOUS_X = 2;
export const JOINT_PREVIOUS_Y = 3;
export const JOINT_FORCE_X = 4;
export const JOINT_FORCE_Y = 5;
export const JOINT_WEIGHT = 6;

export const LINK_STRIDE = 4;
export const SUSPENSION_STRIDE = 5;
export const ANGLE_LIMIT_STRIDE = 5;

export const CONTACT_SKIN = -7680;

export interface Heading {
  x: number;
  y: number;
}

export interface Bounds {
  minX: number;
  maxX: number;
  minY: number;
  maxY: number;
}

export function shiftRight(value: number, bits: number): number {
  return Math.floor(value / 2 ** bits);
}

function toInt(value: number): number {
  return value | 0;
}

export function jointAt(index: number): number {
  return index * JOINT_STRIDE;
}

export interface JointOwner {
  joints: Int32Array;
}

export class JointRef {
  private readonly owner: JointOwner;
  readonly at: number;

  constructor(owner: JointOwner, index: number) {
    this.owner = owner;
    this.at = jointAt(index);
  }

  get x(): number {
    return this.owner.joints[this.at + JOINT_X]!;
  }

  set x(value: number) {
    this.owner.joints[this.at + JOINT_X] = value;
  }

  get y(): number {
    return this.owner.joints[this.at + JOINT_Y]!;
  }

  set y(value: number) {
    this.owner.joints[this.at + JOINT_Y] = value;
  }

  get previousX(): number {
    return this.owner.joints[this.at + JOINT_PREVIOUS_X]!;
  }

  set previousX(value: number) {
    this.owner.joints[this.at + JOINT_PREVIOUS_X] = value;
  }

  get previousY(): number {
    return this.owner.joints[this.at + JOINT_PREVIOUS_Y]!;
  }

  set previousY(value: number) {
    this.owner.joints[this.at + JOINT_PREVIOUS_Y] = value;
  }

  get forceX(): number {
    return this.owner.joints[this.at + JOINT_FORCE_X]!;
  }

  set forceX(value: number) {
    this.owner.joints[this.at + JOINT_FORCE_X] = value;
  }

  get forceY(): number {
    return this.owner.joints[this.at + JOINT_FORCE_Y]!;
  }

  set forceY(value: number) {
    this.owner.joints[this.at + JOINT_FORCE_Y] = value;
  }

  get weight(): number {
    return this.owner.joints[this.at + JOINT_WEIGHT]!;
  }
}

export function buildJoints(
  definitions: ReadonlyArray<{ x: number; y: number; weight: number }>,
): Int32Array {
  const joints = new Int32Array(definitions.length * JOINT_STRIDE);
  for (let i = 0; i < definitions.length; i += 1) {
    const at = jointAt(i);
    const definition = definitions[i]!;
    joints[at + JOINT_X] = definition.x << FIXED_SHIFT;
    joints[at + JOINT_Y] = definition.y << FIXED_SHIFT;
    joints[at + JOINT_WEIGHT] = definition.weight;
  }
  return joints;
}

export function translateJoints(joints: Int32Array, dx: number, dy: number): void {
  for (let at = 0; at < joints.length; at += JOINT_STRIDE) {
    joints[at + JOINT_X] = joints[at + JOINT_X]! + dx;
    joints[at + JOINT_Y] = joints[at + JOINT_Y]! + dy;
    joints[at + JOINT_PREVIOUS_X] = joints[at + JOINT_PREVIOUS_X]! + dx;
    joints[at + JOINT_PREVIOUS_Y] = joints[at + JOINT_PREVIOUS_Y]! + dy;
  }
}

export function measureLinks(joints: Int32Array, links: Int32Array): void {
  for (let i = 0; i < links.length; i += LINK_STRIDE) {
    const a = jointAt(links[i]!);
    const b = jointAt(links[i + 1]!);
    const dx = joints[b + JOINT_X]! - joints[a + JOINT_X]!;
    const dy = joints[b + JOINT_Y]! - joints[a + JOINT_Y]!;
    links[i + 2] = ((Math.imul(dx, dx) + Math.imul(dy, dy)) | 0) >> FIXED_SHIFT;
  }
}

export function measureSuspension(joints: Int32Array, suspension: Int32Array): void {
  for (let i = 0; i < suspension.length; i += SUSPENSION_STRIDE) {
    const a = jointAt(suspension[i]!);
    const b = jointAt(suspension[i + 1]!);
    const dx = joints[b + JOINT_X]! - joints[a + JOINT_X]!;
    const dy = joints[b + JOINT_Y]! - joints[a + JOINT_Y]!;
    const length = sqrtFixed(
      ((Math.imul(dx, dx) + Math.imul(dy, dy)) | 0) >> FIXED_SHIFT,
    );
    suspension[i + 2] = fixedDiv(dy, length);
    suspension[i + 3] = -fixedDiv(dx, length);
  }
}

export function measureAngleLimits(joints: Int32Array, limits: Int32Array): void {
  for (let i = 0; i < limits.length; i += ANGLE_LIMIT_STRIDE) {
    const b = jointAt(limits[i + 1]!);
    const c = jointAt(limits[i + 2]!);
    const dy = joints[c + JOINT_Y]! - joints[b + JOINT_Y]!;
    const dx = -(joints[c + JOINT_X]! - joints[b + JOINT_X]!);
    limits[i + 3] = inverseLengthFixed(dy, dx);
  }
}

export function integrate(
  joints: Int32Array,
  gravity: number,
  leftLimitX: number,
  bounds: Bounds,
): void {
  let minX = Number.MAX_SAFE_INTEGER;
  let minY = Number.MAX_SAFE_INTEGER;
  let maxX = -Number.MAX_SAFE_INTEGER;
  let maxY = -Number.MAX_SAFE_INTEGER;

  for (let at = 0; at < joints.length; at += JOINT_STRIDE) {
    const x = joints[at + JOINT_X]!;
    const y = joints[at + JOINT_Y]!;
    const nextX =
      (x + (x - joints[at + JOINT_PREVIOUS_X]!) + joints[at + JOINT_FORCE_X]!) | 0;
    const nextY =
      (y + (y - joints[at + JOINT_PREVIOUS_Y]!) + joints[at + JOINT_FORCE_Y]! + gravity) |
      0;

    joints[at + JOINT_FORCE_X] = 0;
    joints[at + JOINT_FORCE_Y] = 0;
    joints[at + JOINT_X] = nextX > leftLimitX ? nextX : leftLimitX;
    joints[at + JOINT_Y] = nextY;
    joints[at + JOINT_PREVIOUS_X] = x;
    joints[at + JOINT_PREVIOUS_Y] = y;

    if (nextX < minX) minX = nextX;
    if (nextX > maxX) maxX = nextX;
    if (nextY < minY) minY = nextY;
    if (nextY > maxY) maxY = nextY;
  }

  bounds.minX = minX;
  bounds.maxX = maxX;
  bounds.minY = minY;
  bounds.maxY = maxY;
}

export function relaxConstraints(
  joints: Int32Array,
  links: Int32Array,
  suspension: Int32Array,
  angleLimits: Int32Array,
  updateHeading: () => Heading,
): void {
  for (let pass = 0; pass < 2; pass += 1) {
    relaxLinks(joints, links);
    const heading = updateHeading();
    relaxSuspension(joints, suspension, heading);
    relaxAngleLimits(joints, angleLimits);
  }
}

function relaxLinks(joints: Int32Array, links: Int32Array): void {
  for (let i = 0; i < links.length;) {
    const a = jointAt(links[i++]!);
    const b = jointAt(links[i++]!);
    const restSquared = links[i++]!;
    const stiffness = links[i++]!;

    let dx = joints[b + JOINT_X]! - joints[a + JOINT_X]!;
    let dy = joints[b + JOINT_Y]! - joints[a + JOINT_Y]!;
    const lengthSquared = shiftRight(dx * dx + dy * dy, FIXED_SHIFT);

    let bias =
      Math.trunc((restSquared * FIXED_ONE) / (lengthSquared + restSquared)) - 512;

    let weightA = joints[a + JOINT_WEIGHT]!;
    let weightB = joints[b + JOINT_WEIGHT]!;
    if (weightA !== weightB) {
      bias = Math.trunc((bias * FIXED_ONE) / (weightA + weightB));
    } else {
      weightA = FIXED_ONE;
      weightB = FIXED_ONE;
    }
    if (stiffness !== FIXED_ONE) {
      bias = shiftRight(bias * stiffness, FIXED_SHIFT);
    }

    dx = toInt(shiftRight(dx * bias, FIXED_SHIFT));
    dy = toInt(shiftRight(dy * bias, FIXED_SHIFT));

    joints[a + JOINT_X] = joints[a + JOINT_X]! - fixedMul(dx, weightA);
    joints[a + JOINT_Y] = joints[a + JOINT_Y]! - fixedMul(dy, weightA);
    joints[b + JOINT_X] = joints[b + JOINT_X]! + fixedMul(dx, weightB);
    joints[b + JOINT_Y] = joints[b + JOINT_Y]! + fixedMul(dy, weightB);
  }
}

function pushApart(
  joints: Int32Array,
  a: number,
  b: number,
  pushX: number,
  pushY: number,
): void {
  joints[a + JOINT_X] = joints[a + JOINT_X]! + toInt(pushX);
  joints[a + JOINT_Y] = joints[a + JOINT_Y]! + toInt(pushY);
  joints[b + JOINT_X] = joints[b + JOINT_X]! - toInt(pushX);
  joints[b + JOINT_Y] = joints[b + JOINT_Y]! - toInt(pushY);
}

function relaxSuspension(
  joints: Int32Array,
  suspension: Int32Array,
  heading: Heading,
): void {
  for (let i = 0; i < suspension.length;) {
    const a = jointAt(suspension[i++]!);
    const b = jointAt(suspension[i++]!);
    const axisX = suspension[i++]!;
    const axisY = suspension[i++]!;
    const minExtension = suspension[i++]!;

    const alongX = shiftRight(axisX * heading.x - axisY * heading.y, FIXED_SHIFT);
    const alongY = shiftRight(axisX * heading.y + axisY * heading.x, FIXED_SHIFT);

    let dx = joints[b + JOINT_X]! - joints[a + JOINT_X]!;
    let dy = joints[b + JOINT_Y]! - joints[a + JOINT_Y]!;
    let amount = shiftRight(dx * alongX + dy * alongY, FIXED_SHIFT);
    let pushX = shiftRight(alongX * amount, FIXED_SHIFT + 1);
    let pushY = shiftRight(alongY * amount, FIXED_SHIFT + 1);

    pushApart(joints, a, b, pushX, pushY);

    dx = joints[b + JOINT_X]! - joints[a + JOINT_X]!;
    dy = joints[b + JOINT_Y]! - joints[a + JOINT_Y]!;
    const acrossX = -alongY;
    const acrossY = alongX;
    amount = shiftRight(dx * acrossX + dy * acrossY, FIXED_SHIFT) - minExtension;
    if (amount >= 0) continue;

    pushX = shiftRight(amount * acrossX, FIXED_SHIFT + 1);
    pushY = shiftRight(amount * acrossY, FIXED_SHIFT + 1);
    pushApart(joints, a, b, pushX, pushY);
  }
}

function relaxAngleLimits(joints: Int32Array, limits: Int32Array): void {
  for (let i = 0; i < limits.length;) {
    const a = jointAt(limits[i++]!);
    const b = jointAt(limits[i++]!);
    const c = jointAt(limits[i++]!);
    const inverseLength = limits[i++]!;
    const limit = limits[i++]!;

    const dx = joints[b + JOINT_X]! - joints[a + JOINT_X]!;
    const dy = joints[b + JOINT_Y]! - joints[a + JOINT_Y]!;
    const armX = fixedMul(joints[b + JOINT_Y]! - joints[c + JOINT_Y]!, inverseLength);
    const armY = fixedMul(-(joints[b + JOINT_X]! - joints[c + JOINT_X]!), inverseLength);

    const overshoot = shiftRight(dx * armX + dy * armY, FIXED_SHIFT) - limit;
    if (overshoot >= 0) continue;

    joints[a + JOINT_X] =
      joints[a + JOINT_X]! + shiftRight(overshoot * armX, FIXED_SHIFT);
    joints[a + JOINT_Y] =
      joints[a + JOINT_Y]! + shiftRight(overshoot * armY, FIXED_SHIFT);
  }
}

export class TerrainContact {
  private first = 0;
  private last = -1;
  private minY = 0;
  hits = 0;

  readonly terrain: Terrain;

  constructor(terrain: Terrain) {
    this.terrain = terrain;
  }

  begin(bounds: Bounds): void {
    const terrainY = this.terrain.y;
    this.first = this.terrain.segmentAt(bounds.minX);
    this.last = this.terrain.segmentAt(bounds.maxX);

    let minY = Number.MAX_SAFE_INTEGER;
    for (let i = this.first; i <= this.last + 1; i += 1) {
      const y = terrainY[i]!;
      if (y < minY) minY = y;
    }
    this.minY = minY;
    if (bounds.maxY < minY) this.last = this.first - 1;
    this.hits = 0;
  }

  collide(
    joints: Int32Array,
    index: number,
    normalOut: Int32Array,
    stiffness: number,
    scale: number,
    isContactJoint: boolean,
  ): number {
    if (this.last < this.first) return 0;

    const at = jointAt(index);
    const skin = isContactJoint ? 0 : CONTACT_SKIN;
    const y = joints[at + JOINT_Y]!;
    if (y < this.minY) return 0;
    if (y + skin < this.minY) return 0;
    this.hits += 1;

    const x = joints[at + JOINT_X]!;

    const nearest = this.nearestSegment(x, y);
    if (nearest < 0) return 0;

    let penetration = this.penetrationAt(x, y, nearest, skin);
    if (penetration < 0) return 0;
    if (scale !== FIXED_ONE) penetration = shiftRight(penetration * scale, FIXED_SHIFT);

    return this.applyContact(joints, at, nearest, penetration, stiffness, normalOut);
  }

  private nearestSegment(x: number, y: number): number {
    if (this.first === this.last) return this.first;

    const terrainX = this.terrain.x;
    const terrainY = this.terrain.y;
    const normalX = this.terrain.normalX;
    const normalY = this.terrain.normalY;

    let nearest = -1;
    let best = 2147483647;
    let segment = this.first;
    do {
      const startX = x - terrainX[segment]!;
      const startY = y - terrainY[segment]!;
      const endX = x - terrainX[segment + 1]!;
      const endY = y - terrainY[segment + 1]!;
      const tangentX = normalY[segment]!;
      const tangentY = -normalX[segment]!;

      let distance: number;
      if (shiftRight(startX * tangentX + startY * tangentY, FIXED_SHIFT) <= 0) {
        distance = shiftRight(startX * startX + startY * startY, FIXED_SHIFT);
      } else if (shiftRight(endX * tangentX + endY * tangentY, FIXED_SHIFT) >= 0) {
        distance = shiftRight(endX * endX + endY * endY, FIXED_SHIFT);
      } else {
        const along = shiftRight(
          startX * normalX[segment]! + startY * normalY[segment]!,
          FIXED_SHIFT,
        );
        distance = shiftRight(along * along, FIXED_SHIFT);
      }
      if (distance <= best) {
        best = distance;
        nearest = segment;
      }
    } while (++segment <= this.last);
    return nearest;
  }

  private penetrationAt(x: number, y: number, nearest: number, skin: number): number {
    const surfaceX = this.terrain.normalX[nearest]!;
    const surfaceY = this.terrain.normalY[nearest]!;
    return (
      shiftRight(
        (x - this.terrain.x[nearest]!) * surfaceX +
          (y - this.terrain.y[nearest]!) * surfaceY,
        FIXED_SHIFT,
      ) + skin
    );
  }

  private applyContact(
    joints: Int32Array,
    at: number,
    nearest: number,
    penetration: number,
    stiffness: number,
    normalOut: Int32Array,
  ): number {
    const surfaceX = this.terrain.normalX[nearest]!;
    const surfaceY = this.terrain.normalY[nearest]!;
    const previousX = joints[at + JOINT_PREVIOUS_X]!;
    const previousY = joints[at + JOINT_PREVIOUS_Y]!;

    const x = toInt(
      joints[at + JOINT_X]! - shiftRight(surfaceX * penetration, FIXED_SHIFT),
    );
    const y = toInt(
      joints[at + JOINT_Y]! - shiftRight(surfaceY * penetration, FIXED_SHIFT),
    );

    const tangentX = surfaceY;
    const tangentY = -surfaceX;
    let slide =
      (Math.imul(tangentX, x - previousX) + Math.imul(tangentY, y - previousY)) >>
      FIXED_SHIFT;
    slide = fixedMul(slide, stiffness);

    joints[at + JOINT_X] = (x - fixedMul(tangentX, slide)) | 0;
    joints[at + JOINT_Y] = (y - fixedMul(tangentY, slide)) | 0;
    normalOut[0] = tangentX;
    normalOut[1] = tangentY;
    return toInt(penetration);
  }
}
