import { STOPPIE_FRAMES, TRICK, TRICK_SLOTS, WHEELIE_FRAMES } from './BikeLayout.ts';

const AIR_TRICK_FIRST = 3;
const AIR_TRICK_LAST = 9;

const TRICK_FOR_ANIMATION: ReadonlyArray<number | undefined> = [
  undefined,
  TRICK.GRIZZLY,
  TRICK.HEADACHE,
  TRICK.LAZY_BOY,
  TRICK.CORDOVA,
  TRICK.DOUBLE_GRAB,
  TRICK.TSUNAMI,
  TRICK.BAR_HOP,
  TRICK.ROCK_SOLID,
  TRICK.MC_METZ,
  TRICK.CRAZY_COW,
];

export class SpinTracker {
  count = 0;
  tracking = false;
  private quadrant = 0;

  begin(quadrant: number): void {
    if (this.tracking) return;
    this.count = 0;
    this.quadrant = quadrant;
    this.tracking = true;
  }

  track(quadrant: number): void {
    if (!this.tracking || quadrant === this.quadrant) return;
    if (Math.abs(quadrant - this.quadrant) === 1) {
      this.count += quadrant - this.quadrant;
    } else if (quadrant > this.quadrant) {
      this.count -= 1;
    } else {
      this.count += 1;
    }
    this.quadrant = quadrant;
  }

  take(): number {
    if (!this.tracking) return 0;
    this.tracking = false;
    if (this.count > 0) this.count += 1;
    if (this.count < 0) this.count -= 1;
    return (this.count / 4) | 0;
  }
}

export class TrickScorer {
  readonly totals = new Int32Array(TRICK_SLOTS);
  readonly pending = new Int32Array(TRICK_SLOTS);
  readonly spin = new SpinTracker();

  private readonly animationCompletions = new Int32Array(11);
  private wheelieFrames = 0;
  private stoppieFrames = 0;

  countWheelie(): void {
    this.wheelieFrames += 1;
  }

  countStoppie(): void {
    this.stoppieFrames += 1;
  }

  completeAnimation(animation: number): void {
    this.animationCompletions[animation] = this.animationCompletions[animation]! + 1;
  }

  clear(keepTotals: boolean): void {
    this.spin.tracking = false;
    this.wheelieFrames = 0;
    this.stoppieFrames = 0;
    if (!keepTotals) this.totals.fill(0);
    this.pending.fill(0);
    this.animationCompletions.fill(0);
  }

  score(): number {
    this.scoreHeldWheels();
    this.scoreSpins();
    return this.scoreCompletedAnimations();
  }

  private scoreHeldWheels(): void {
    if (this.wheelieFrames >= WHEELIE_FRAMES) {
      this.pending[TRICK.WHEELIE] =
        this.pending[TRICK.WHEELIE]! + ((this.wheelieFrames / WHEELIE_FRAMES) | 0);
    }
    if (this.stoppieFrames >= STOPPIE_FRAMES) {
      this.pending[TRICK.STOPPIE] =
        this.pending[TRICK.STOPPIE]! + ((this.stoppieFrames / STOPPIE_FRAMES) | 0);
    }
    this.wheelieFrames = 0;
    this.stoppieFrames = 0;
  }

  private scoreSpins(): void {
    if (!this.spin.tracking) return;
    const spins = this.spin.take();
    if (spins < 0) this.pending[TRICK.NOSE_FLIP] = this.pending[TRICK.NOSE_FLIP]! - spins;
    if (spins > 0) this.pending[TRICK.BACK_FLIP] = this.pending[TRICK.BACK_FLIP]! + spins;
  }

  private scoreCompletedAnimations(): number {
    let airTricks = 0;
    for (
      let animation = 0;
      animation < this.animationCompletions.length;
      animation += 1
    ) {
      while (this.animationCompletions[animation]! > 0) {
        const trick = TRICK_FOR_ANIMATION[animation];
        if (trick !== undefined) {
          this.pending[trick] = this.pending[trick]! + 1;
          if (animation >= AIR_TRICK_FIRST && animation <= AIR_TRICK_LAST) airTricks += 1;
        }
        this.animationCompletions[animation] = this.animationCompletions[animation]! - 1;
      }
    }
    return airTricks;
  }
}
