export const POPUP = { STARTED: TRICK_SLOTS, FINISHED: TRICK_SLOTS + 1 } as const;

export const POPUP_QUEUE_SIZE = 32;

export const POPUP_FRAME_MASK = 7;

export interface TrickCounters {
  readonly trickPending: Int32Array;
  readonly trickTotals: Int32Array;
}

export class TrickDetector {
  private readonly queue = new Int8Array(POPUP_QUEUE_SIZE);
  private top = -1;

  get queued(): number {
    return this.top + 1;
  }

  reset(): void {
    this.top = -1;
  }

  drain(bike: TrickCounters): number {
    let queued = 0;
    for (let slot = 0; slot < bike.trickPending.length; slot += 1) {
      while (bike.trickPending[slot]! > 0) {
        if (this.push(slot)) queued += 1;
        bike.trickTotals[slot] = bike.trickTotals[slot]! + 1;
        bike.trickPending[slot] = bike.trickPending[slot]! - 1;
      }
    }
    return queued;
  }

  push(entry: number): boolean {
    if (this.top + 1 >= POPUP_QUEUE_SIZE) return false;
    this.top += 1;
    this.queue[this.top] = entry;
    return true;
  }

  isPopupFrame(frame: number): boolean {
    return (frame & POPUP_FRAME_MASK) === 0;
  }

  update(bike: TrickCounters, frame: number): number {
    this.drain(bike);
    if (!this.isPopupFrame(frame) || this.top < 0) return -1;
    const entry = this.queue[this.top]!;
    this.top -= 1;
    return entry;
  }
}
