import {
  MAX_LEVEL,
  type AudioSink,
  type SfxVoice,
  type SoundRequest,
} from './AudioService.ts';
import { SFX_TRACKS } from './Sfx.ts';

export type TrackResolver = (record: number) => string | null;

export interface AudioContextLike {
  readonly state: string;
  readonly destination: AudioNode;
  createGain(): GainNode;
  createBufferSource(): AudioBufferSourceNode;
  decodeAudioData(data: ArrayBuffer): Promise<AudioBuffer>;
  resume(): Promise<void>;
  close(): Promise<void>;
}

export interface WebAudioSinkOptions {
  context?: AudioContextLike | (() => AudioContextLike);
  resolve?: TrackResolver;
  fetch?: typeof fetch;
}

export const MUSIC_TRACKS: Readonly<Record<number, string>> = {
  8: 'res-008.ogg',
  9: 'res-009.ogg',
  10: 'res-010.ogg',
};

export function trackUrls(
  names: Readonly<Record<number, string>>,
  base = 'assets/audio/',
): TrackResolver {
  return (record) => {
    const name = names[record];
    return name === undefined ? null : base + name;
  };
}

export function defaultTracks(): TrackResolver {
  const music = trackUrls(MUSIC_TRACKS);
  const sfx = trackUrls(SFX_TRACKS, 'assets/sfx/');
  return (record) => music(record) ?? sfx(record);
}

export function webAudioAvailable(): boolean {
  return typeof globalThis.AudioContext === 'function';
}

export class WebAudioSink implements AudioSink {
  private readonly makeContext: () => AudioContextLike;
  private readonly resolve: TrackResolver;
  private readonly fetchImpl: typeof fetch;

  private context: AudioContextLike | null = null;
  private musicBus: GainNode | null = null;
  private sfxBus: GainNode | null = null;

  private readonly buffers = new Map<string, AudioBuffer>();

  private musicSources = new Set<AudioBufferSourceNode>();
  private sfxSources = new Set<AudioBufferSourceNode>();

  private voices = new Set<Voice>();

  private generation = 0;
  private sfxGeneration = 0;

  private gestured = false;
  private musicLevel = 0;
  private sfxLevel = 0;

  constructor(options: WebAudioSinkOptions = {}) {
    const context = options.context;
    this.makeContext =
      typeof context === 'function'
        ? context
        : context
          ? () => context
          : () => new AudioContext() as unknown as AudioContextLike;
    this.resolve = options.resolve ?? defaultTracks();
    this.fetchImpl = options.fetch ?? ((...args) => globalThis.fetch(...args));
  }

  get unlocked(): boolean {
    return this.gestured || this.context?.state === 'running';
  }

  unlock(): void {
    this.gestured = true;
    const context = this.ensureContext();
    if (context.state !== 'running') void context.resume().catch(() => {});
  }

  setLevels(music: number, sfx: number): void {
    this.musicLevel = music;
    this.sfxLevel = sfx;
    if (this.musicBus) this.musicBus.gain.value = gainOf(music);
    if (this.sfxBus) this.sfxBus.gain.value = gainOf(sfx);
  }

  play(request: SoundRequest): void {
    const generation = request.music ? ++this.generation : ++this.sfxGeneration;
    const url = this.resolve(request.record);
    if (url === null) return;
    void this.load(url)
      .then((buffer) => {
        const current = request.music ? this.generation : this.sfxGeneration;
        if (generation !== current || !buffer) return;
        this.start(buffer, request);
      })
      .catch(() => {});
  }

  loop(request: SoundRequest, rate: number): SfxVoice | null {
    const url = this.resolve(request.record);
    if (url === null) return null;
    const voice = new Voice(rate);
    this.voices.add(voice);
    const generation = this.sfxGeneration;
    void this.load(url)
      .then((buffer) => {
        if (voice.stopped || generation !== this.sfxGeneration || !buffer) {
          voice.deactivate();
          return;
        }
        const source = this.start(buffer, { ...request, loop: true });
        if (source) {
          voice.attach(source, () => {
            this.sfxSources.delete(source);
            this.voices.delete(voice);
          });
        } else voice.deactivate();
      })
      .catch(() => voice.deactivate());
    return voice;
  }

  stop(): void {
    this.generation++;
    this.stopSources(this.musicSources);
    this.musicSources = new Set();
    this.stopSfx();
  }

  stopMusic(): void {
    this.generation++;
    this.stopSources(this.musicSources);
    this.musicSources = new Set();
  }

  stopSfx(): void {
    this.sfxGeneration++;
    this.stopSources(this.sfxSources);
    this.sfxSources = new Set();
    for (const voice of this.voices) voice.deactivate();
    this.voices.clear();
  }

  private stopSources(sources: Set<AudioBufferSourceNode>): void {
    for (const source of sources) {
      source.onended = null;
      try {
        source.stop();
      } catch {}
      source.disconnect();
    }
  }

  async close(): Promise<void> {
    this.stop();
    this.buffers.clear();
    const context = this.context;
    this.context = null;
    this.musicBus = null;
    this.sfxBus = null;
    if (context) await context.close().catch(() => {});
  }

  private start(
    buffer: AudioBuffer,
    request: SoundRequest,
  ): AudioBufferSourceNode | null {
    const context = this.ensureContext();
    const bus = request.music ? this.musicBus : this.sfxBus;
    if (!bus) return null;
    const sources = request.music ? this.musicSources : this.sfxSources;
    const source = context.createBufferSource();
    source.buffer = buffer;
    source.loop = request.loop;
    source.connect(bus);
    source.onended = () => {
      sources.delete(source);
      source.disconnect();
    };
    sources.add(source);
    source.start();
    return source;
  }

  private async load(url: string): Promise<AudioBuffer | null> {
    const cached = this.buffers.get(url);
    if (cached) return cached;
    const response = await this.fetchImpl(url);
    if (!response.ok) return null;
    const bytes = await response.arrayBuffer();
    const buffer = await this.ensureContext().decodeAudioData(bytes);
    this.buffers.set(url, buffer);
    return buffer;
  }

  private ensureContext(): AudioContextLike {
    let context = this.context;
    if (!context) {
      context = this.context = this.makeContext();
      const music = context.createGain();
      const sfx = context.createGain();
      music.connect(context.destination);
      sfx.connect(context.destination);
      this.musicBus = music;
      this.sfxBus = sfx;
      this.setLevels(this.musicLevel, this.sfxLevel);
    }
    return context;
  }
}

class Voice implements SfxVoice {
  private source: AudioBufferSourceNode | null = null;
  private release: (() => void) | null = null;
  private rate: number;
  private live = true;
  stopped = false;

  constructor(rate: number) {
    this.rate = rate;
  }

  get active(): boolean {
    return this.live;
  }

  attach(source: AudioBufferSourceNode, release: () => void): void {
    this.source = source;
    this.release = release;
    source.playbackRate.value = this.rate;
    const ended = source.onended;
    source.onended = (event) => {
      ended?.call(source, event);
      this.live = false;
    };
  }

  setRate(rate: number): void {
    this.rate = rate;
    if (this.source) this.source.playbackRate.value = rate;
  }

  stop(): void {
    this.stopped = true;
    this.live = false;
    const source = this.source;
    this.source = null;
    this.release?.();
    this.release = null;
    if (!source) return;
    source.onended = null;
    try {
      source.stop();
    } catch {}
    source.disconnect();
  }

  deactivate(): void {
    this.live = false;
  }
}

export function gainOf(level: number): number {
  return level <= 0 ? 0 : level >= MAX_LEVEL ? 1 : level / MAX_LEVEL;
}
