import {
  CHALLENGE_COUNT,
  PARTS,
  PART_CATEGORY_SLUGS,
  PART_NAMES,
  RANK,
} from '../data/constants.ts';

export const SAVE_VERSION = 2;

export const ENVIRONMENT_COUNT = 4;

export const VOLUME_ON = 50;

export const DEFAULT_MUSIC_TRACK = 8;

export const LANGUAGE_UNSET = 5;

export const DEFAULT_FITTED_PARTS = 69649;

export const PROGRESS = {
  LANGUAGE: 'language',
  MUSIC_VOLUME: 'musicVolume',
  MUSIC_TRACK: 'musicTrack',
  SFX_VOLUME: 'sfxVolume',
  VIBRATION: 'vibration',
  SHOW_GHOST: 'showGhost',
  LATCHED_THROTTLE: 'latchedThrottle',
  BIKE: 'bike',
  CAREER_POINTS: 'careerPoints',
  LAST_THEME: 'lastTheme',
} as const;

export type VolumeSlot = typeof PROGRESS.MUSIC_VOLUME | typeof PROGRESS.SFX_VOLUME;

export type ToggleSlot =
  | typeof PROGRESS.VIBRATION
  | typeof PROGRESS.SHOW_GHOST
  | typeof PROGRESS.LATCHED_THROTTLE;

export const VOLUME_SLOT_BY_MENU_PARAM: Readonly<Record<number, VolumeSlot>> = {
  1: PROGRESS.MUSIC_VOLUME,
  3: PROGRESS.SFX_VOLUME,
};

export const RANK_NAMES = ['none', 'bronze', 'silver', 'gold'] as const;

export type RankName = (typeof RANK_NAMES)[number];

export interface UnlockFlags {
  freeRide1: boolean;
  freeRide2: boolean;
}

export type FittedParts = Record<string, string | null>;

export interface Progress {
  language: number;
  musicVolume: number;
  musicTrack: number;
  sfxVolume: number;
  vibration: boolean;
  showGhost: boolean;
  latchedThrottle: boolean;
  bike: number;
  unlockedParts: string[];
  unlocked: UnlockFlags;
  fittedParts: FittedParts[];
  ranks: Record<string, RankName>;
  careerPoints: number;
  lastTheme: number;
}

export interface ProgressDefaults {
  soundOn?: boolean;
  vibrationOn?: boolean;
}

export function partIdOf(slug: string): number {
  return PART_NAMES.indexOf(slug);
}

export function partSlugOf(part: number): string | null {
  return PART_NAMES[part] ?? null;
}

export function rankNameOf(rank: number): RankName {
  return RANK_NAMES[rank] ?? 'none';
}

export function rankValueOf(name: string): number {
  const rank = RANK_NAMES.indexOf(name as RankName);
  return rank < 0 ? RANK.NONE : rank;
}

export function challengeKey(challenge: number): string {
  return `challenge-${String(challenge).padStart(2, '0')}`;
}

export function challengeOfKey(key: string): number {
  const match = /^challenge-(\d+)$/.exec(key);
  if (match === null) return -1;
  const challenge = Number(match[1]);
  return challenge < CHALLENGE_COUNT ? challenge : -1;
}

export function categoryMask(category: number): number {
  let mask = 0;
  for (let part = 0; part < PARTS.length; part++) {
    if (PARTS[part]!.category === category) mask |= 1 << part;
  }
  return mask;
}

export function fittedFromMask(mask: number): FittedParts {
  const fitted: FittedParts = {};
  for (let category = 0; category < PART_CATEGORY_SLUGS.length; category++) {
    const bits = mask & categoryMask(category);
    let slug: string | null = null;
    for (let part = 0; part < PARTS.length; part++) {
      if ((bits & (1 << part)) !== 0) {
        slug = partSlugOf(part);
        break;
      }
    }
    fitted[PART_CATEGORY_SLUGS[category]!] = slug;
  }
  return fitted;
}

export function fittedMaskOf(fitted: FittedParts): number {
  let mask = 0;
  for (const slug of Object.values(fitted)) {
    if (slug === null) continue;
    const part = partIdOf(slug);
    if (part >= 0) mask |= 1 << part;
  }
  return mask;
}

export function defaultFittedParts(): FittedParts[] {
  const fitted: FittedParts[] = [];
  for (let environment = 0; environment < ENVIRONMENT_COUNT; environment++) {
    fitted.push(fittedFromMask(DEFAULT_FITTED_PARTS));
  }
  return fitted;
}

export function defaultUnlockedParts(): string[] {
  return partsOfMask(DEFAULT_FITTED_PARTS);
}

export function partsOfMask(mask: number): string[] {
  const slugs: string[] = [];
  for (let part = 0; part < PARTS.length; part++) {
    if ((mask & (1 << part)) !== 0) slugs.push(partSlugOf(part)!);
  }
  return slugs;
}

export function defaults(options: ProgressDefaults = {}): Progress {
  const volume = options.soundOn === false ? 0 : VOLUME_ON;
  return {
    language: LANGUAGE_UNSET,
    musicVolume: volume,
    musicTrack: DEFAULT_MUSIC_TRACK,
    sfxVolume: volume,
    vibration: options.vibrationOn !== false,
    showGhost: true,
    latchedThrottle: true,
    bike: -1,
    unlockedParts: defaultUnlockedParts(),
    unlocked: { freeRide1: false, freeRide2: false },
    fittedParts: defaultFittedParts(),
    ranks: {},
    careerPoints: 0,
    lastTheme: -1,
  };
}

export function toJson(progress: Progress): unknown {
  return {
    version: SAVE_VERSION,
    language: progress.language,
    music: { volume: progress.musicVolume, track: progress.musicTrack },
    sfxVolume: progress.sfxVolume,
    vibration: progress.vibration,
    showGhost: progress.showGhost,
    latchedThrottle: progress.latchedThrottle,
    bike: progress.bike,
    unlockedParts: [...progress.unlockedParts],
    unlocked: { ...progress.unlocked },
    fittedParts: progress.fittedParts.map((fitted) => ({ ...fitted })),
    ranks: { ...progress.ranks },
    careerPoints: progress.careerPoints,
    lastTheme: progress.lastTheme,
  };
}

export function fromJson(value: unknown): Progress | null {
  const document = asRecord(value);
  if (document === null || document.version !== SAVE_VERSION) return null;

  const music = asRecord(document.music) ?? {};
  const unlocked = asRecord(document.unlocked) ?? {};
  const base = defaults();

  return {
    language: intOf(document.language, base.language),
    musicVolume: intOf(music.volume, base.musicVolume),
    musicTrack: intOf(music.track, base.musicTrack),
    sfxVolume: intOf(document.sfxVolume, base.sfxVolume),
    vibration: boolOf(document.vibration, base.vibration),
    showGhost: boolOf(document.showGhost, base.showGhost),
    latchedThrottle: boolOf(document.latchedThrottle, base.latchedThrottle),
    bike: intOf(document.bike, base.bike),
    unlockedParts: partListOf(document.unlockedParts),
    unlocked: {
      freeRide1: boolOf(unlocked.freeRide1, false),
      freeRide2: boolOf(unlocked.freeRide2, false),
    },
    fittedParts: fittedListOf(document.fittedParts),
    ranks: rankMapOf(document.ranks),
    careerPoints: intOf(document.careerPoints, 0),
    lastTheme: intOf(document.lastTheme, base.lastTheme),
  };
}

export function bestToJson(results: ArrayLike<number>): unknown {
  const map: Record<string, number> = {};
  for (let challenge = 0; challenge < results.length; challenge++) {
    const result = results[challenge]! | 0;
    if (result !== 0) map[challengeKey(challenge)] = result;
  }
  return { version: SAVE_VERSION, results: map };
}

export function bestFromJson(value: unknown): Int32Array<ArrayBuffer> | null {
  const document = asRecord(value);
  if (document === null || document.version !== SAVE_VERSION) return null;
  const results = new Int32Array(CHALLENGE_COUNT);
  const map = asRecord(document.results) ?? {};
  for (const [key, result] of Object.entries(map)) {
    const challenge = challengeOfKey(key);
    if (challenge >= 0) results[challenge] = intOf(result, 0);
  }
  return results;
}

function asRecord(value: unknown): Record<string, unknown> | null {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;
  return value as Record<string, unknown>;
}

function intOf(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value | 0 : fallback;
}

function boolOf(value: unknown, fallback: boolean): boolean {
  return typeof value === 'boolean' ? value : fallback;
}

function partListOf(value: unknown): string[] {
  if (!Array.isArray(value)) return defaultUnlockedParts();
  const parts: number[] = [];
  for (const slug of value) {
    if (typeof slug !== 'string') continue;
    const part = partIdOf(slug);
    if (part >= 0 && !parts.includes(part)) parts.push(part);
  }
  parts.sort((left, right) => left - right);
  return parts.map((part) => partSlugOf(part)!);
}

function fittedListOf(value: unknown): FittedParts[] {
  const rows = Array.isArray(value) ? value : [];
  const fitted: FittedParts[] = [];
  for (let environment = 0; environment < ENVIRONMENT_COUNT; environment++) {
    const row = asRecord(rows[environment]);
    if (row === null) {
      fitted.push(fittedFromMask(DEFAULT_FITTED_PARTS));
      continue;
    }
    const parsed: FittedParts = {};
    for (const category of PART_CATEGORY_SLUGS) {
      const slug = row[category];
      parsed[category] = typeof slug === 'string' && partIdOf(slug) >= 0 ? slug : null;
    }
    fitted.push(parsed);
  }
  return fitted;
}

function rankMapOf(value: unknown): Record<string, RankName> {
  const map = asRecord(value) ?? {};
  const ranks: Record<string, RankName> = {};
  for (const [key, name] of Object.entries(map)) {
    if (challengeOfKey(key) < 0 || typeof name !== 'string') continue;
    const rank = rankValueOf(name);
    if (rank !== RANK.NONE) ranks[key] = rankNameOf(rank);
  }
  return ranks;
}
