import type { FrameStats } from './FrameStats.ts';
import { MAX_STEPS_PER_FRAME, TICK_MS } from './config.ts';

export interface LoopOptions {
  stats?: FrameStats;
}

export interface LoopCallbacks {
  update(): void;
  render(alpha: number): void;
}

export class Loop {
  private readonly callbacks: LoopCallbacks;
  private readonly stats: FrameStats | undefined;
  private accumulator = 0;
  private lastTime = 0;
  private frameHandle = 0;
  private running = false;
  private ticks = 0;

  constructor(callbacks: LoopCallbacks, options: LoopOptions = {}) {
    this.callbacks = callbacks;
    this.stats = options.stats;
  }

  get tick(): number {
    return this.ticks;
  }

  start(): void {
    if (this.running) return;
    this.running = true;
    this.lastTime = performance.now();
    this.accumulator = 0;
    this.stats?.reset();
    this.frameHandle = requestAnimationFrame(this.frame);
  }

  stop(): void {
    if (!this.running) return;
    this.running = false;
    cancelAnimationFrame(this.frameHandle);
  }

  step(count = 1): void {
    for (let i = 0; i < count; i++) {
      this.ticks++;
      this.callbacks.update();
    }
    this.callbacks.render(this.accumulator / TICK_MS);
  }

  advance(now: number): void {
    this.accumulator += now - this.lastTime;
    this.lastTime = now;

    const maxBacklog = MAX_STEPS_PER_FRAME * TICK_MS;
    if (this.accumulator > maxBacklog) this.accumulator = maxBacklog;

    let steps = 0;
    while (this.accumulator >= TICK_MS) {
      this.accumulator -= TICK_MS;
      steps++;
    }

    this.step(steps);
    this.stats?.sample(now, steps);
  }

  private readonly frame = (now: number): void => {
    this.frameHandle = requestAnimationFrame(this.frame);
    this.advance(now);
  };
}
