import { SHIPPED_GHOSTS } from '../data/constants.ts';

import { encodeGhost, ghostFromJson, type Ghost, type GhostJson } from './GhostFormat.ts';

export const GHOST_BASE = 'assets/ghosts/';

export function ghostUrl(record: number, base: string = GHOST_BASE): string {
  return `${base}ghost-${record}.json`;
}

const shipped = new Map<number, Ghost>();

export function registerShippedGhost(json: GhostJson): void {
  shipped.set(json.record, ghostFromJson(json));
}

export function forgetShippedGhosts(): void {
  shipped.clear();
}

export function shippedGhostCount(): number {
  return shipped.size;
}

export function shippedGhostBytes(record: number): Uint8Array | null {
  const ghost = shipped.get(record);
  return ghost === undefined ? null : encodeGhost(ghost);
}

export function shippedGhostFor(challenge: number): Ghost | null {
  const entry = SHIPPED_GHOSTS.find((ghost) => ghost.challenges.includes(challenge));
  if (entry === undefined) return null;
  return shipped.get(entry.record) ?? null;
}

export interface LoadShippedGhostOptions {
  base?: string;
  fetch?: typeof fetch;
  onProgress?: (progress: number) => void;
}

export async function loadShippedGhosts(
  options: LoadShippedGhostOptions = {},
): Promise<number> {
  const base = options.base ?? GHOST_BASE;
  const fetchImpl =
    options.fetch ?? ((...args: Parameters<typeof fetch>) => globalThis.fetch(...args));

  let done = 0;
  await Promise.all(
    SHIPPED_GHOSTS.map(async (entry) => {
      const response = await fetchImpl(ghostUrl(entry.record, base));
      if (!response.ok) throw new Error(`ghost ${entry.record}: ${response.status}`);
      registerShippedGhost((await response.json()) as GhostJson);
      done += 1;
      options.onProgress?.(done / SHIPPED_GHOSTS.length);
    }),
  );
  return shipped.size;
}
