import { BitmapText, Container, Graphics, Rectangle, Sprite, Texture } from 'pixi.js';

import {
  FIXED_SHIFT,
  MENU_ICON,
  MENU_ICONS,
  MENU_SCROLL,
  SOFT_KEYS,
} from '../data/constants.ts';
import type { MenuItem } from '../data/constants.ts';
import {
  anchorAt,
  recordFrame,
  stripFrame,
  stripPivot,
  type TextureLookup,
} from '../render/BikeView.ts';
import { UI_SPRITE_SCALE, px, pxFromTexels, shiftPx } from '../render/units.ts';
import type { ScorePairRow } from '../scenes/HighScores.ts';

import { FONT, FONT_SIZE, ShadowText } from './Font.ts';
import {
  ARROW_FRAME,
  ARROW_STRIP,
  MENU_COLOR,
  SCREEN_KIND,
  SOFT_KEY_INSET,
  LAYOUT,
  iconStripOf,
  stepMarquee,
  type MenuList,
  type MenuRow,
} from './MenuList.ts';

export const BACKDROP_RECORD = 89;

export const BACKDROP_INSET = px(5);

export const SOFT_KEY_BASELINE = px(1);

export const BUSY_TICKER_INSET = px(5);

export const MARKER_ICON = {
  FITTED_PART: MENU_ICON.FITTED_PART,
  JUKEBOX_TRACK: MENU_ICON.JUKEBOX_TRACK,
  SELECTED_BIKE: MENU_ICON.SELECTED_BIKE,
} as const;

export interface MenuScreenOptions {
  itemMarker?(item: MenuItem, index: number): number;
  scorePairRows?(firstRowY: number): readonly ScorePairRow[];
}

interface RowView {
  label: ShadowText;
  icon: Sprite;
  marker: Sprite;
  iconIndex: number;
  markerIndex: number;
}

interface SoftKeyView {
  icon: Sprite;
  label: BitmapText;
}

function uiSprite(label?: string): Sprite {
  const sprite = new Sprite({ scale: UI_SPRITE_SCALE });
  if (label !== undefined) sprite.label = label;
  return sprite;
}

function frame(textures: TextureLookup, name: string): Texture {
  const texture = textures[name];
  if (!texture) throw new Error(`no atlas frame '${name}'`);
  return texture;
}

function pinStripFrame(
  sprite: Sprite,
  textures: TextureLookup,
  strip: number,
  index: number,
): void {
  const pivot = stripPivot(strip);
  sprite.texture = frame(textures, stripFrame(strip, index));
  anchorAt(sprite, pivot.x, pivot.y);
}

function pinMenuIcon(sprite: Sprite, textures: TextureLookup, icon: number): void {
  pinStripFrame(sprite, textures, iconStripOf(icon), MENU_ICONS[icon]!.frame);
}

export class MenuScreen {
  readonly container = new Container({ label: 'menu' });
  readonly overlay = new Container({ label: 'menu-overlay' });

  private readonly ground = new Graphics({ label: 'menu-ground' });
  private readonly frameBands = new Graphics({ label: 'menu-frame' });
  private readonly backdrop = new Container({ label: 'menu-backdrop' });
  private readonly backdropBands: Sprite[] = [];

  private readonly titleIcon = uiSprite('menu-title-icon');
  private readonly title: ShadowText;

  private readonly listContainer = new Container({ label: 'menu-list' });
  private readonly listMask = new Graphics({ label: 'menu-clip' });
  private readonly rows: RowView[] = [];
  private readonly values: ShadowText[] = [];

  private readonly upArrow = uiSprite('menu-arrow-up');
  private readonly downArrow = uiSprite('menu-arrow-down');
  private readonly ticker: ShadowText;

  private readonly softKeyBar = new Container({ label: 'menu-soft-keys' });
  private readonly softKeys: readonly [SoftKeyView, SoftKeyView];

  private readonly busy = new Container({ label: 'menu-busy' });
  private readonly busyGround = new Graphics({ label: 'menu-busy-ground' });
  private readonly busyTicker: ShadowText;

  private readonly textures: TextureLookup;
  private readonly options: MenuScreenOptions;

  private list: MenuList | null = null;
  private busyText: string | null = null;

  constructor(textures: TextureLookup, options: MenuScreenOptions = {}) {
    this.textures = textures;
    this.options = options;

    this.buildBackdropBands(textures);

    this.title = new ShadowText({ font: FONT.TITLE, color: MENU_COLOR.LABEL });
    this.title.label = 'menu-title';
    this.ticker = new ShadowText({ font: FONT.SMALL, color: MENU_COLOR.SELECTED });
    this.ticker.label = 'menu-ticker';

    pinStripFrame(this.upArrow, textures, ARROW_STRIP, ARROW_FRAME.UP);
    pinStripFrame(this.downArrow, textures, ARROW_STRIP, ARROW_FRAME.DOWN);

    this.listContainer.mask = this.listMask;

    this.container.addChild(
      this.ground,
      this.backdrop,
      this.frameBands,
      this.titleIcon,
      this.title,
      this.listMask,
      this.listContainer,
      this.upArrow,
      this.downArrow,
      this.ticker,
    );

    this.softKeys = [this.newSoftKey('left'), this.newSoftKey('right')];
    for (const side of this.softKeys) this.softKeyBar.addChild(side.icon, side.label);

    this.busyTicker = new ShadowText({ font: FONT.SMALL, color: MENU_COLOR.SELECTED });
    this.busyTicker.label = 'menu-busy-ticker';
    this.busy.addChild(this.busyGround, this.busyTicker);
    this.busy.visible = false;

    this.overlay.addChild(this.softKeyBar, this.busy);
  }

  private buildBackdropBands(textures: TextureLookup): void {
    const source = frame(textures, recordFrame(BACKDROP_RECORD));
    const bandHeight = Math.trunc(source.frame.height / MENU_SCROLL.length);
    for (let band = 0; band < MENU_SCROLL.length; band += 1) {
      const texture = new Texture({
        source: source.source,
        frame: new Rectangle(
          source.frame.x,
          source.frame.y + band * bandHeight,
          source.frame.width,
          bandHeight,
        ),
      });
      const sprite = uiSprite(`menu-backdrop-${band}`);
      sprite.texture = texture;
      this.backdropBands.push(sprite);
      this.backdrop.addChild(sprite);
    }
  }

  setList(list: MenuList | null): void {
    this.list = list;
    this.container.visible = list !== null;
    if (!list) {
      this.softKeyBar.visible = false;
      return;
    }

    this.paintFrame(list);

    const { bands, metrics } = list;
    const screenWidth = metrics.screenWidth;

    this.listMask
      .clear()
      .rect(LAYOUT.iconGap, list.listTop, bands.contentWidth, list.listHeight)
      .fill(MENU_COLOR.SELECTED);

    this.paintBusyGround(list);

    const centreX = shiftPx(screenWidth, 1);
    this.upArrow.position.set(centreX, bands.titleBottom + LAYOUT.listGap);
    this.downArrow.position.set(centreX, bands.footerTop + LAYOUT.listGap);

    this.buildTitle(list);
    this.buildRows(list);
  }

  private paintFrame(list: MenuList): void {
    const { bands, metrics } = list;
    const { screenWidth, screenHeight } = metrics;

    this.ground.clear().rect(0, 0, screenWidth, screenHeight).fill(MENU_COLOR.BACKGROUND);
    this.frameBands
      .clear()
      .rect(0, bands.titleBottom, screenWidth, bands.dividerHeight)
      .rect(0, bands.footerTop, screenWidth, bands.dividerHeight)
      .rect(0, bands.softKeyTop, screenWidth, screenHeight - bands.softKeyTop)
      .fill(MENU_COLOR.DIVIDER);
    for (const y of [
      bands.titleBottom,
      bands.headerBottom,
      bands.footerTop,
      bands.tickerTop,
      bands.softKeyTop,
    ]) {
      this.frameBands.rect(0, y, screenWidth, LAYOUT.titleGap);
    }
    this.frameBands.fill(MENU_COLOR.RULE);
  }

  private paintBusyGround(list: MenuList): void {
    const { screenWidth, screenHeight, smallFontHeight } = list.metrics;
    this.busyGround
      .clear()
      .rect(0, 0, screenWidth, screenHeight)
      .fill(MENU_COLOR.BACKGROUND);
    this.busyTicker.position.set(
      BUSY_TICKER_INSET,
      screenHeight - smallFontHeight - BUSY_TICKER_INSET,
    );
  }

  setBusy(text: string | null): void {
    this.busyText = text;
    this.busy.visible = text !== null;
    if (text !== null) this.busyTicker.text = text;
  }

  draw(frameCount: number): void {
    if (this.busyText !== null) {
      this.container.visible = false;
      this.softKeyBar.visible = false;
      return;
    }

    const list = this.list;
    this.container.visible = list !== null;
    if (!list) {
      this.softKeyBar.visible = false;
      return;
    }

    if (this.showParts(list)) {
      this.upArrow.visible = false;
      this.downArrow.visible = false;
      return;
    }

    this.drawBackdrop(list, frameCount);
    this.drawTitle(list);

    list.step();
    this.drawRows(list);
    this.upArrow.visible = list.scrollUpArrow;
    this.downArrow.visible = list.scrollDownArrow;

    if (list.tickerText !== null) {
      this.ticker.text = list.tickerText;
      this.ticker.position.set(list.stepTicker(), list.bands.tickerTop + LAYOUT.titleGap);
    }

    this.drawSoftKeys(list);
  }

  private showParts(list: MenuList): boolean {
    const empty = list.items.length === 0;
    this.backdrop.visible = !empty;
    this.titleIcon.visible = !empty && list.menu.titleIcon >= 0;
    this.title.visible = !empty && list.menu.titleString !== -1;
    this.listContainer.visible = !empty;
    this.ticker.visible = !empty && list.tickerText !== null;
    this.softKeyBar.visible = !empty;
    return empty;
  }

  destroy(): void {
    this.container.destroy({ children: true });
    this.overlay.destroy({ children: true });
  }

  private drawBackdrop(list: MenuList, frameCount: number): void {
    const bandCount = MENU_SCROLL.length;
    const bands = this.backdropBands;
    const bandHeight = pxFromTexels(bands[0]!.texture.frame.height);
    const top = list.bands.footerTop - bandHeight * bandCount;
    let row = ((frameCount % bandCount) + bandCount) % bandCount;
    for (let band = 0; band < bandCount; band += 1) {
      const offset = px(MENU_SCROLL[row]!.offsetX >> FIXED_SHIFT);
      bands[band]!.position.set(-BACKDROP_INSET + offset, top + band * bandHeight);
      row += 1;
      if (row >= bandCount) row = 0;
    }
  }

  private buildTitle(list: MenuList): void {
    const { titleIcon, titleString } = list.menu;
    if (titleIcon >= 0) {
      pinMenuIcon(this.titleIcon, this.textures, titleIcon);
      this.titleIcon.position.set(LAYOUT.titleTop, LAYOUT.titleTop);
    }
    this.title.text = titleString === -1 ? '' : list.label(titleString);
  }

  private drawTitle(list: MenuList): void {
    if (list.menu.titleString === -1) return;
    const marquee = list.titleMarquee;
    const x = marquee.active
      ? list.metrics.screenWidth - stepMarquee(marquee)
      : list.menu.titleIcon >= 0
        ? LAYOUT.titleTop + pxFromTexels(this.titleIcon.texture.width) + LAYOUT.titleGap
        : LAYOUT.titleTop;
    this.title.position.set(x, LAYOUT.titleTop);
  }

  private buildRows(list: MenuList): void {
    const wanted =
      list.kind === SCREEN_KIND.SCORE_PAIRS
        ? (this.options.scorePairRows?.(0).length ?? 0)
        : list.items.length;

    while (this.rows.length < wanted) {
      const label = new ShadowText({ font: FONT.MENU });
      const icon = uiSprite();
      const marker = uiSprite();
      icon.visible = false;
      marker.visible = false;
      this.listContainer.addChild(icon, marker, label);
      this.rows.push({ label, icon, marker, iconIndex: -1, markerIndex: -1 });
    }
    for (let index = wanted; index < this.rows.length; index += 1) {
      const view = this.rows[index]!;
      view.label.visible = false;
      view.icon.visible = false;
      view.marker.visible = false;
    }
    for (const value of this.values) value.visible = false;
  }

  private drawRows(list: MenuList): void {
    if (list.kind === SCREEN_KIND.NONE) {
      for (const row of this.rows) {
        row.label.visible = false;
        row.icon.visible = false;
        row.marker.visible = false;
      }
      return;
    }
    if (list.kind === SCREEN_KIND.SCORE_PAIRS) {
      this.drawScorePairs(list);
      return;
    }
    this.drawMenuRows(list);
  }

  private drawMenuRows(list: MenuList): void {
    const rows = list.rows();
    for (let index = 0; index < this.rows.length; index += 1) {
      const view = this.rows[index]!;
      const row = rows[index];
      if (!row) {
        view.label.visible = false;
        view.icon.visible = false;
        view.marker.visible = false;
        continue;
      }

      view.label.visible = true;
      view.label.text = row.text;
      view.label.color = row.color;
      view.label.anchorX = row.centred ? 0.5 : 0;
      view.label.position.set(row.x, row.y);

      this.drawRowIcons(view, row);
    }
  }

  private drawRowIcons(view: RowView, row: MenuRow): void {
    const icon = row.icon;
    view.icon.visible = icon >= 0;
    if (icon >= 0) {
      if (icon !== view.iconIndex) {
        pinMenuIcon(view.icon, this.textures, icon);
        view.iconIndex = icon;
      }
      view.icon.position.set(row.iconX, row.iconY);
    }

    const marker =
      icon >= 0 ? (this.options.itemMarker?.(row.item, row.index) ?? -1) : -1;
    view.marker.visible = marker >= 0;
    if (marker >= 0) {
      if (marker !== view.markerIndex) {
        pinMenuIcon(view.marker, this.textures, marker);
        view.markerIndex = marker;
      }
      view.marker.position.set(row.iconX, row.iconY);
    }
  }

  private drawScorePairs(list: MenuList): void {
    const pairs = this.options.scorePairRows?.(list.firstRowY) ?? [];
    for (let index = 0; index < this.rows.length; index += 1) {
      const view = this.rows[index]!;
      const pair = pairs[index];
      view.icon.visible = false;
      view.marker.visible = false;
      if (!pair) {
        view.label.visible = false;
        const spare = this.values[index];
        if (spare) spare.visible = false;
        continue;
      }

      view.label.visible = true;
      view.label.text = pair.label;
      view.label.color = pair.color;
      view.label.anchorX = pair.centred ? 0.5 : 0;
      view.label.position.set(pair.labelX, pair.y);

      let value = this.values[index];
      if (!value) {
        value = new ShadowText({ font: FONT.MENU });
        this.values[index] = value;
        this.listContainer.addChild(value);
      }
      value.visible = !pair.centred;
      if (!pair.centred) {
        value.text = pair.value ?? '';
        value.color = pair.color;
        value.position.set(pair.valueX, pair.y);
      }
    }
  }

  private newSoftKey(side: 'left' | 'right'): SoftKeyView {
    const icon = uiSprite(`menu-soft-${side}-icon`);
    const label = new BitmapText({
      text: '',
      style: {
        fontFamily: FONT.SMALL,
        fontSize: FONT_SIZE[FONT.SMALL],
        fill: MENU_COLOR.SELECTED,
        whiteSpace: 'pre',
      },
    });
    label.label = `menu-soft-${side}-label`;
    icon.visible = false;
    label.visible = false;
    return { icon, label };
  }

  private drawSoftKeys(list: MenuList): void {
    const bar = list.softKeyBar();
    const { screenWidth, screenHeight, smallFontHeight } = list.metrics;
    const bottom = screenHeight - SOFT_KEY_BASELINE;

    for (const [end, row] of [
      ['left', bar.left],
      ['right', bar.right],
    ] as const) {
      const view = this.softKeys[end === 'left' ? 0 : 1];
      const key = row >= 0 ? SOFT_KEYS[row] : undefined;
      if (!key) {
        view.icon.visible = false;
        view.label.visible = false;
        continue;
      }

      const right = end === 'right';
      const x = right ? screenWidth - SOFT_KEY_INSET : SOFT_KEY_INSET;
      if (key.iconRecord >= 0) {
        view.icon.texture = frame(this.textures, recordFrame(key.iconRecord));
        view.icon.anchor.set(right ? 1 : 0, 1);
        view.icon.position.set(x, bottom);
        view.icon.visible = true;
        view.label.visible = false;
      } else {
        view.label.text = list.label(key.labelString);
        view.label.anchor.x = right ? 1 : 0;
        view.label.position.set(x, bottom - smallFontHeight);
        view.label.visible = true;
        view.icon.visible = false;
      }
    }
  }
}
