import {
  CHALLENGES,
  CHALLENGE_COUNT,
  PARTS,
  PART_CATEGORY_SLUGS,
} from '../data/constants.ts';
import { improvesRank, unlockedPartFor } from '../game/ScoreModel.ts';
import {
  bestFromV1,
  decodeV1Value,
  progressFromV1,
  V1_PROGRESS_LENGTH,
} from './legacy-v1.ts';
import {
  bestFromJson,
  bestToJson,
  categoryMask,
  challengeKey,
  DEFAULT_FITTED_PARTS,
  defaults,
  ENVIRONMENT_COUNT,
  fittedMaskOf,
  fromJson,
  LANGUAGE_UNSET,
  partIdOf,
  partSlugOf,
  PROGRESS,
  rankNameOf,
  rankValueOf,
  SAVE_VERSION,
  toJson,
  VOLUME_ON,
  VOLUME_SLOT_BY_MENU_PARAM,
  type Progress,
  type UnlockFlags,
  type VolumeSlot,
} from './Progress.ts';

export {
  categoryMask,
  DEFAULT_FITTED_PARTS,
  ENVIRONMENT_COUNT,
  LANGUAGE_UNSET,
  PROGRESS,
  SAVE_VERSION,
  VOLUME_SLOT_BY_MENU_PARAM,
};
export type { Progress, VolumeSlot };

export const STORE = { OPTIONS: 0, BEST: 1 } as const;

export const STORE_NAMES = ['progress', 'best'] as const;

export const LEGACY_STORE_NAMES = ['nrkopt', 'nrkhis'] as const;

export const BACKUP_SUFFIX = '.v1backup';

export const STORE_ERROR = { NONE: 0, MISSING: 1, FULL: 2, FAILED: 3 } as const;

export const POINTS_PER_CHALLENGE = 100;

const FREE_RIDE_TYPE = 6;

const FREE_RIDE_CHALLENGE = { FIRST: 58, SECOND: 59 } as const;

export interface StorageLike {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export interface SaveServiceOptions {
  storage?: StorageLike | null;
  prefix?: string;
  soundDefaultOn?: boolean;
  vibrationDefaultOn?: boolean;
}

export class MemoryStorage implements StorageLike {
  private readonly entries = new Map<string, string>();

  getItem(key: string): string | null {
    return this.entries.get(key) ?? null;
  }

  setItem(key: string, value: string): void {
    this.entries.set(key, value);
  }

  removeItem(key: string): void {
    this.entries.delete(key);
  }
}

function defaultStorage(): StorageLike {
  try {
    const storage = (globalThis as { localStorage?: StorageLike }).localStorage;
    if (storage) {
      storage.getItem('motox.probe');
      return storage;
    }
  } catch {}
  return new MemoryStorage();
}

export class SaveService {
  private readonly storage: StorageLike;
  private readonly prefix: string;
  private readonly soundDefaultOn: boolean;
  private readonly vibrationDefaultOn: boolean;

  private storeDirty = 0;
  private storeError: number = STORE_ERROR.NONE;

  progress: Progress;
  bestResults = new Int32Array(CHALLENGE_COUNT);

  constructor(options: SaveServiceOptions = {}) {
    this.storage = options.storage ?? defaultStorage();
    this.prefix = options.prefix ?? 'motox.';
    this.soundDefaultOn = options.soundDefaultOn ?? true;
    this.vibrationDefaultOn = options.vibrationDefaultOn ?? true;
    this.progress = this.freshProgress();
  }

  takeStoreError(): number {
    const error = this.storeError;
    this.storeError = STORE_ERROR.NONE;
    return error;
  }

  markStoreDirty(slot: number): void {
    this.storeDirty |= 1 << slot;
  }

  flushStore(slot: number): void {
    const bit = 1 << slot;
    if ((this.storeDirty & bit) === 0) return;
    const document =
      slot === STORE.OPTIONS ? toJson(this.progress) : bestToJson(this.bestResults);
    this.write(this.keyFor(slot), JSON.stringify(document));
    if (this.storeError === STORE_ERROR.NONE) this.storeDirty &= ~bit;
  }

  flushAllStores(): void {
    for (let slot = 0; slot < STORE_NAMES.length; slot++) this.flushStore(slot);
  }

  clearStore(slot: number): void {
    this.storage.removeItem(this.keyFor(slot));
    this.storage.removeItem(this.legacyKeyFor(slot));
    this.storeDirty &= ~(1 << slot);
  }

  clearAllStores(): void {
    for (let slot = 0; slot < STORE_NAMES.length; slot++) this.clearStore(slot);
  }

  readStoredProgress(): Progress | null {
    return fromJson(this.readJson(STORE.OPTIONS));
  }

  readStoredBestResults(): Int32Array<ArrayBuffer> | null {
    return bestFromJson(this.readJson(STORE.BEST));
  }

  private keyFor(slot: number): string {
    return this.prefix + STORE_NAMES[slot];
  }

  private legacyKeyFor(slot: number): string {
    return this.prefix + LEGACY_STORE_NAMES[slot];
  }

  private backupKeyFor(slot: number): string {
    return this.keyFor(slot) + BACKUP_SUFFIX;
  }

  private freshProgress(): Progress {
    return defaults({
      soundOn: this.soundDefaultOn,
      vibrationOn: this.vibrationDefaultOn,
    });
  }

  private read(key: string): string | null {
    this.storeError = STORE_ERROR.NONE;
    let value: string | null;
    try {
      value = this.storage.getItem(key);
    } catch {
      this.storeError = STORE_ERROR.FAILED;
      return null;
    }
    if (value === null) this.storeError = STORE_ERROR.MISSING;
    return value;
  }

  private readJson(slot: number): unknown {
    const value = this.read(this.keyFor(slot));
    if (value === null) return null;
    try {
      return JSON.parse(value);
    } catch {
      this.storeError = STORE_ERROR.FAILED;
      return null;
    }
  }

  private readLegacyInts(slot: number): Int32Array<ArrayBuffer> | null {
    const value = this.read(this.legacyKeyFor(slot));
    if (value === null) return null;
    const ints = decodeV1Value(value);
    if (ints === null) {
      this.storeError = STORE_ERROR.FAILED;
      return null;
    }
    try {
      this.storage.setItem(this.backupKeyFor(slot), value);
      this.storage.removeItem(this.legacyKeyFor(slot));
    } catch {}
    this.markStoreDirty(slot);
    return ints;
  }

  private write(key: string, value: string): void {
    this.storeError = STORE_ERROR.NONE;
    try {
      this.storage.setItem(key, value);
    } catch (error) {
      const name = (error as { name?: string }).name;
      this.storeError =
        name === 'QuotaExceededError' || name === 'NS_ERROR_DOM_QUOTA_REACHED'
          ? STORE_ERROR.FULL
          : STORE_ERROR.FAILED;
    }
  }

  open(): void {
    this.loadProgress();
    this.loadBestResults();
  }

  loadProgress(): void {
    const stored = this.readStoredProgress();
    this.takeStoreError();
    if (stored !== null) {
      this.progress = stored;
      return;
    }
    const ints = this.readLegacyInts(STORE.OPTIONS);
    this.takeStoreError();
    if (ints !== null && ints.length === V1_PROGRESS_LENGTH) {
      this.progress = progressFromV1(ints);
      return;
    }
    if (ints !== null) this.clearStore(STORE.OPTIONS);
    this.progress = this.freshProgress();
    this.resetProgress(true);
  }

  resetProgress(full: boolean): void {
    const fresh = this.freshProgress();
    const progress = this.progress;
    if (full) {
      progress.language = fresh.language;
      progress.musicVolume = fresh.musicVolume;
      progress.sfxVolume = fresh.sfxVolume;
      progress.musicTrack = fresh.musicTrack;
      progress.vibration = fresh.vibration;
      progress.showGhost = fresh.showGhost;
      progress.latchedThrottle = fresh.latchedThrottle;
      progress.bike = fresh.bike;
    }
    progress.careerPoints = 0;
    progress.unlockedParts = fresh.unlockedParts;
    progress.unlocked = fresh.unlocked;
    progress.fittedParts = fresh.fittedParts;
    progress.ranks = {};
    progress.lastTheme = fresh.lastTheme;
  }

  saveProgress(): void {
    this.markStoreDirty(STORE.OPTIONS);
    this.flushStore(STORE.OPTIONS);
  }

  loadBestResults(): void {
    const stored = this.readStoredBestResults();
    this.takeStoreError();
    if (stored !== null) {
      this.bestResults = stored;
      return;
    }
    const ints = this.readLegacyInts(STORE.BEST);
    this.takeStoreError();
    this.bestResults = ints === null ? new Int32Array(CHALLENGE_COUNT) : bestFromV1(ints);
  }

  saveBestResults(): void {
    this.markStoreDirty(STORE.BEST);
    this.flushStore(STORE.BEST);
  }

  get language(): number {
    return this.progress.language;
  }

  set language(index: number) {
    this.progress.language = index;
  }

  get languageUnset(): boolean {
    return this.language === LANGUAGE_UNSET;
  }

  get musicVolume(): number {
    return this.progress.musicVolume;
  }

  get sfxVolume(): number {
    return this.progress.sfxVolume;
  }

  toggleVolume(slot: VolumeSlot): void {
    this.progress[slot] = this.progress[slot] === 0 ? VOLUME_ON : 0;
  }

  get musicTrack(): number {
    return this.progress.musicTrack;
  }

  set musicTrack(record: number) {
    this.progress.musicTrack = record;
  }

  get vibration(): boolean {
    return this.progress.vibration;
  }

  set vibration(on: boolean) {
    this.progress.vibration = on;
  }

  get showGhost(): boolean {
    return this.progress.showGhost;
  }

  set showGhost(on: boolean) {
    this.progress.showGhost = on;
  }

  get latchedThrottle(): boolean {
    return this.progress.latchedThrottle;
  }

  set latchedThrottle(on: boolean) {
    this.progress.latchedThrottle = on;
  }

  get bikeChoice(): number {
    return this.progress.bike;
  }

  set bikeChoice(bike: number) {
    this.progress.bike = bike;
  }

  get selectedBike(): number {
    return Math.max(0, this.bikeChoice);
  }

  get lastTheme(): number {
    return this.progress.lastTheme;
  }

  set lastTheme(theme: number) {
    this.progress.lastTheme = theme;
  }

  get unlocked(): UnlockFlags {
    return this.progress.unlocked;
  }

  freeRideUnlocked(track: number): boolean {
    return track === 0 ? this.unlocked.freeRide1 : this.unlocked.freeRide2;
  }

  unlockFreeRide(track: number): void {
    if (track === 0) this.progress.unlocked.freeRide1 = true;
    else this.progress.unlocked.freeRide2 = true;
  }

  partUnlocked(part: number): boolean {
    const slug = partSlugOf(part);
    return slug !== null && this.progress.unlockedParts.includes(slug);
  }

  unlockPart(part: number): void {
    const slug = partSlugOf(part);
    if (slug === null || this.progress.unlockedParts.includes(slug)) return;
    const parts = [...this.progress.unlockedParts, slug];
    parts.sort((left, right) => partIdOf(left) - partIdOf(right));
    this.progress.unlockedParts = parts;
  }

  fittedParts(environment: number): number {
    return fittedMaskOf(this.progress.fittedParts[environment] ?? {});
  }

  fitPart(environment: number, part: number): boolean {
    const slug = partSlugOf(part);
    const fitted = this.progress.fittedParts[environment];
    if (slug === null || fitted === undefined) return false;
    if ((this.fittedParts(environment) & (1 << part)) !== 0) return false;
    const category = PART_CATEGORY_SLUGS[PARTS[part]!.category];
    if (category === undefined) return false;
    fitted[category] = slug;
    return true;
  }

  challengeRank(challenge: number): number {
    return rankValueOf(this.progress.ranks[challengeKey(challenge)] ?? 'none');
  }

  recordRank(challenge: number, rank: number): boolean {
    const previous = this.challengeRank(challenge);
    if (!improvesRank(previous, rank)) return false;
    this.progress.ranks[challengeKey(challenge)] = rankNameOf(rank);
    const part = unlockedPartFor(challenge, previous, rank);
    if (part >= 0 && !this.partUnlocked(part)) this.unlockPart(part);
    return true;
  }

  bestResult(challenge: number): number {
    return this.bestResults[challenge]!;
  }

  recordResult(challenge: number, result: number, save = true): boolean {
    const previous = this.bestResults[challenge]!;
    if (previous !== 0 && result >= previous) return false;
    this.bestResults[challenge] = result;
    if (save) this.saveBestResults();
    return true;
  }

  get careerPoints(): number {
    return this.progress.careerPoints;
  }

  addCareerPoints(points: number): number {
    if (points <= 0) return 0;
    const before = this.careerPoints;
    const after = before + points;
    let unlocked = 0;
    for (let challenge = 0; challenge < CHALLENGE_COUNT; challenge++) {
      const needed = pointsNeeded(challenge);
      if (needed > before && needed <= after) unlocked++;
    }
    this.progress.careerPoints = after;
    this.saveProgress();
    return unlocked;
  }

  challengeUnlocked(challenge: number): boolean {
    if (CHALLENGES[challenge]!.type === FREE_RIDE_TYPE) {
      if (challenge === FREE_RIDE_CHALLENGE.FIRST) return this.unlocked.freeRide1;
      if (challenge === FREE_RIDE_CHALLENGE.SECOND) return this.unlocked.freeRide2;
      return false;
    }
    return this.careerPoints >= pointsNeeded(challenge);
  }
}

function pointsNeeded(challenge: number): number {
  return Math.max(0, challenge - 1) * POINTS_PER_CHALLENGE;
}
