import {
  PART_CATEGORY,
  PARTS,
  SETUPS,
  STRING,
  TRACKS,
  type MenuItem,
} from '../../data/constants.ts';
import { categoryMask } from '../../save/SaveService.ts';
import { MARKER_ICON } from '../../ui/MenuScreen.ts';

import type { AppShell } from '../AppShell.ts';
import { tireBit } from '../RaceScene.ts';
import { RESULT_TEXT } from '../Results.ts';
import { SHELL_ACTION } from './actions.ts';
import { copyRows } from './MenuModel.ts';
import { SCREEN } from './screens.ts';

export const PART_PROMISE_STRING = STRING.BIKE_PART_AVAILABLE_TO;

const SETUP_CATEGORIES: readonly number[] = [
  PART_CATEGORY.TIRES,
  PART_CATEGORY.SUSPENSION,
  PART_CATEGORY.ENGINE,
  PART_CATEGORY.NITRO,
];

const MASK_BITS = 32;

function lowestSetBit(mask: number): number {
  if (mask === 0) return MASK_BITS;
  return MASK_BITS - 1 - Math.clz32(mask & -mask);
}

export function itemMarker(shell: AppShell, item: MenuItem): number {
  if (shell.screen === SCREEN.PARTS) {
    const fitted = shell.save.fittedParts(shell.environment);
    return (fitted & (1 << item.param)) !== 0 ? MARKER_ICON.FITTED_PART : -1;
  }
  if (shell.screen === SCREEN.JUKEBOX && item.param === shell.save.musicTrack) {
    return MARKER_ICON.JUKEBOX_TRACK;
  }
  if (
    shell.screen === SCREEN.BIKE &&
    item.action === SHELL_ACTION.SELECT_BIKE &&
    item.param === shell.save.bikeChoice
  ) {
    return MARKER_ICON.SELECTED_BIKE;
  }
  return -1;
}

export function fitPart(shell: AppShell, part: number): void {
  if (!shell.save.fitPart(shell.environment, part)) return;
  shell.race?.refreshPlayerSetup(false);
  shell.save.saveProgress();
  shell.list?.select(shell.selectedItem, 0, false);
}

export function selectBike(shell: AppShell, bike: number): void {
  if (shell.save.bikeChoice !== bike) {
    shell.save.bikeChoice = bike;
    shell.race?.refreshPlayerSetup(true);
    shell.save.saveProgress();
  }
  if (shell.screenBack[SCREEN.BIKE] === SCREEN.TITLE) {
    shell.screenBack[SCREEN.CAREER] = SCREEN.TITLE;
    shell.openScreen(SCREEN.CAREER, false);
    return;
  }
  shell.runAction(SHELL_ACTION.BACK, -1);
}

export function openPartsMenu(shell: AppShell): void {
  const model = shell.model;
  model.menus[SCREEN.PARTS] = { ...model.partsHeader };
  model.items[SCREEN.PARTS] = copyRows(
    model.partsItems.filter((item) => item.enabled !== 0),
  );
}

export function partsSoftKeyGate(
  shell: AppShell,
  items: readonly MenuItem[],
  index: number,
): { left: boolean; right: boolean } {
  const item = items[index];
  if (item && item.action === SHELL_ACTION.FIT_PART) {
    const fitted = shell.save.fittedParts(shell.environment);
    return { left: (fitted & (1 << item.param)) === 0, right: true };
  }
  return { left: true, right: true };
}

export function setupPartNames(shell: AppShell, setup: number, track: number): string[] {
  const slots = shell.table;
  const mask = SETUPS[setup]!.partMask | tireBit(TRACKS[track]!.environment);
  return SETUP_CATEGORIES.map((category) => {
    const part = lowestSetBit(mask & categoryMask(category));
    const label = part < PARTS.length ? PARTS[part]!.nameString : RESULT_TEXT.NONE;
    return slots.text(label);
  });
}
