export const FRAME_BUDGET_MS = 1000 / 60;

export const FRAME_WINDOW = 120;

export interface FrameStatsOptions {
  window?: number;
  budgetMs?: number;
}

export class FrameStats {
  readonly window: number;

  readonly budgetMs: number;

  private readonly durations: Float64Array;
  private readonly stepCounts: Float64Array;
  private readonly scratch: Float64Array;

  private next = 0;
  private filled = 0;
  private lastTime = 0;
  private started = false;
  private total = 0;

  constructor(options: FrameStatsOptions = {}) {
    this.window = Math.max(1, options.window ?? FRAME_WINDOW);
    this.budgetMs = options.budgetMs ?? FRAME_BUDGET_MS;
    this.durations = new Float64Array(this.window);
    this.stepCounts = new Float64Array(this.window);
    this.scratch = new Float64Array(this.window);
  }

  sample(now: number, steps = 0): void {
    if (!this.started) {
      this.started = true;
      this.lastTime = now;
      return;
    }

    const duration = now - this.lastTime;
    this.lastTime = now;
    this.durations[this.next] = duration;
    this.stepCounts[this.next] = steps;
    this.next = (this.next + 1) % this.window;
    if (this.filled < this.window) this.filled += 1;
    this.total += 1;
  }

  get frames(): number {
    return this.filled;
  }

  get sampled(): number {
    return this.total;
  }

  get elapsedMs(): number {
    let sum = 0;
    for (let i = 0; i < this.filled; i += 1) sum += this.durations[i]!;
    return sum;
  }

  get fps(): number {
    const elapsed = this.elapsedMs;
    return elapsed > 0 ? (this.filled * 1000) / elapsed : 0;
  }

  get meanMs(): number {
    return this.filled === 0 ? 0 : this.elapsedMs / this.filled;
  }

  get worstMs(): number {
    let worst = 0;
    for (let i = 0; i < this.filled; i += 1) {
      const duration = this.durations[i]!;
      if (duration > worst) worst = duration;
    }
    return worst;
  }

  get longFrames(): number {
    let count = 0;
    for (let i = 0; i < this.filled; i += 1) {
      if (this.durations[i]! > this.budgetMs) count += 1;
    }
    return count;
  }

  get meanSteps(): number {
    if (this.filled === 0) return 0;
    let sum = 0;
    for (let i = 0; i < this.filled; i += 1) sum += this.stepCounts[i]!;
    return sum / this.filled;
  }

  percentileMs(fraction: number): number {
    if (this.filled === 0) return 0;

    const scratch = this.scratch;
    for (let i = 0; i < this.filled; i += 1) {
      const value = this.durations[i]!;
      let j = i - 1;
      while (j >= 0 && scratch[j]! > value) {
        scratch[j + 1] = scratch[j]!;
        j -= 1;
      }
      scratch[j + 1] = value;
    }

    const clamped = fraction < 0 ? 0 : fraction > 1 ? 1 : fraction;
    const rank = Math.ceil(clamped * this.filled);
    return scratch[Math.max(0, rank - 1)]!;
  }

  reset(): void {
    this.next = 0;
    this.filled = 0;
    this.total = 0;
    this.started = false;
    this.lastTime = 0;
  }
}
