import type { AppShell } from '../AppShell.ts';
import {
  HighScoreBoard,
  SCORE_PAIR_ROWS,
  scorePairRows,
  type ScorePair,
  type ScorePairRow,
} from '../HighScores.ts';

export const BOARD_HOME_ROW = SCORE_PAIR_ROWS >> 1;

const BLANK_PAIRS: readonly ScorePair[] = new Array<ScorePair>(SCORE_PAIR_ROWS).fill({
  label: '',
  value: '',
});

export function buildBoard(shell: AppShell): void {
  const page = shell.board?.page ?? 0;
  shell.board = new HighScoreBoard({
    save: shell.save,
    slots: shell.table,
    label: (id) => shell.text(id),
    entryOptions: { includeChallenge: (c) => shell.save.challengeUnlocked(c) },
  });
  shell.board.setPage(page);
}

export function boardRows(shell: AppShell, firstRowY: number): readonly ScorePairRow[] {
  if (shell.board) return shell.board.rows(firstRowY, shell.metrics);
  return scorePairRows(BLANK_PAIRS, firstRowY, shell.metrics);
}

export function turnBoardPage(shell: AppShell, index: number): void {
  if (index < BOARD_HOME_ROW) shell.board?.pageUp();
  else if (index > BOARD_HOME_ROW) shell.board?.pageDown();
  shell.list?.select(BOARD_HOME_ROW, 0, false);
}
