import { Graphics } from 'pixi.js';

import { FIXED_SHIFT } from '../data/constants.ts';
import type { Terrain } from '../game/Terrain.ts';

export const SHADOW_SLOPES = [256, 768] as const;

export const SHADOW_COLOURS = [0x50301a, 0x302010, 0x000000, 0x302010, 0x50301a] as const;

export const GROUND_MARGIN = 15360;

export const CHASSIS_DROP = 8704;

export const RIDER_DROP = 15360;

export const CRASH_ANIMATION = 11;

export const SHADOW_POINT_SLOTS = 64;

export const CHASSIS_JOINTS = 4;
export const MEASURED_JOINTS = 9;

export interface ShadowSource {
  readonly jointX: Int32Array;
  readonly jointY: Int32Array;
  readonly animation: number;
}

export class ShadowView {
  readonly graphics = new Graphics({ label: 'shadow' });

  private readonly points = new Int32Array(SHADOW_POINT_SLOTS);

  private readonly hit = new Int32Array(2);

  sync(bike: ShadowSource, terrain: Terrain): void {
    this.graphics.clear();

    let chassisMinX = Infinity;
    let chassisMaxX = -Infinity;
    let chassisMinY = Infinity;
    let riderMinX = Infinity;
    let riderMaxX = -Infinity;
    let riderMinY = Infinity;

    for (let joint = 0; joint < MEASURED_JOINTS; joint += 1) {
      const x = bike.jointX[joint]!;
      const y = bike.jointY[joint]!;
      if (joint < CHASSIS_JOINTS) {
        if (x < chassisMinX) chassisMinX = x;
        if (x > chassisMaxX) chassisMaxX = x;
        if (y < chassisMinY) chassisMinY = y;
      } else {
        if (x < riderMinX) riderMinX = x;
        if (x > riderMaxX) riderMaxX = x;
        if (y < riderMinY) riderMinY = y;
      }
    }

    this.draw(terrain, chassisMinX, chassisMaxX, chassisMinY, CHASSIS_DROP);
    if (bike.animation === CRASH_ANIMATION) {
      this.draw(terrain, riderMinX, riderMaxX, riderMinY, RIDER_DROP);
    }
  }

  destroy(): void {
    this.graphics.destroy();
  }

  private draw(
    terrain: Terrain,
    minX: number,
    maxX: number,
    top: number,
    drop: number,
  ): void {
    const count = buildShadow(this.points, this.hit, terrain, minX, maxX, top, drop);
    const points = this.points;

    for (let pass = -2; pass < 3; pass += 1) {
      const offset = pass << 1;
      let fromX = points[0]!;
      let fromY = points[1]!;
      for (let at = 2; at < count; at += 2) {
        const toX = points[at]!;
        const toY = points[at + 1]!;
        if (fromX >= 0 && fromY >= 0 && toX >= 0 && toY >= 0) {
          this.graphics
            .moveTo(fromX, fromY + offset)
            .lineTo(toX, toY + offset)
            .stroke({ width: 1, color: SHADOW_COLOURS[pass + 2], alignment: 0.5 });
        }
        fromX = toX;
        fromY = toY;
      }
    }
  }
}

function castEdge(
  hit: Int32Array,
  terrain: Terrain,
  fromX: number,
  top: number,
  toX: number,
  groundY: number,
): number {
  const segment = terrain.firstSegmentCrossing(fromX, top, toX, groundY);
  if (segment < 0) return -1;
  terrain.intersectionPoint(hit, segment, fromX, top, toX, groundY);
  return segment;
}

function pushEdge(
  out: Int32Array,
  count: number,
  fromX: number,
  fromY: number,
  toX: number,
  toY: number,
  drop: number,
): number {
  out[count++] = fromX >> FIXED_SHIFT;
  out[count++] = (fromY + drop) >> FIXED_SHIFT;
  out[count++] = toX >> FIXED_SHIFT;
  out[count++] = (toY + drop) >> FIXED_SHIFT;
  return count;
}

function pushGap(out: Int32Array, count: number): number {
  out[count++] = -1;
  out[count++] = -1;
  out[count++] = -1;
  out[count++] = -1;
  return count;
}

export function buildShadow(
  out: Int32Array,
  hit: Int32Array,
  terrain: Terrain,
  minX: number,
  maxX: number,
  top: number,
  drop: number,
): number {
  const groundY = terrain.maxY + GROUND_MARGIN;
  const fall = groundY - top;

  const leftEnd = minX + ((fall * SHADOW_SLOPES[0]) >> FIXED_SHIFT);
  if (leftEnd < minX) return 0;

  const leftSegment = castEdge(hit, terrain, minX, top, leftEnd, groundY);
  if (leftSegment < 0) return 0;
  const x = hit[0]!;
  const y = hit[1]!;

  const rightEnd = maxX + ((fall * SHADOW_SLOPES[1]) >> FIXED_SHIFT);
  const rightSegment = castEdge(hit, terrain, maxX, top, rightEnd, groundY);
  if (rightSegment < 0) return 0;
  const endX = hit[0]!;
  const endY = hit[1]!;

  if (leftSegment === rightSegment) {
    return pushEdge(out, 0, x, y, endX, endY, drop);
  }

  hit[0] = x;
  hit[1] = y;
  const count = traceVertices(out, hit, terrain, leftSegment, rightSegment, drop);

  return pushEdge(out, count, hit[0]!, hit[1]!, endX, endY, drop);
}

function traceVertices(
  out: Int32Array,
  cursor: Int32Array,
  terrain: Terrain,
  leftSegment: number,
  rightSegment: number,
  drop: number,
): number {
  let count = 0;
  for (let vertex = leftSegment + 1; vertex <= rightSegment; vertex += 1) {
    const vertexX = terrain.x[vertex]!;
    const vertexY = terrain.y[vertex]!;
    count =
      (vertexY - cursor[1]!) >> 1 < vertexX - cursor[0]!
        ? pushEdge(out, count, cursor[0]!, cursor[1]!, vertexX, vertexY, drop)
        : pushGap(out, count);
    cursor[0] = vertexX;
    cursor[1] = vertexY;
    if (count >= SHADOW_POINT_SLOTS - 4) break;
  }
  return count;
}
