import { Container, Graphics } from 'pixi.js';

import { DESIGN_SCALE } from '../core/config.ts';
import { px } from './units.ts';

export interface ParallaxCamera {
  readonly x: number;
  readonly y: number;
  readonly viewportWidth: number;
  readonly viewportHeight: number;
}

export class SkyBand {
  readonly graphics = new Graphics({ label: 'sky' });

  private readonly colour: number;
  private height = -1;

  constructor(skyColour: number) {
    this.colour = skyColour;
    this.graphics.scale.set(DESIGN_SCALE);
  }

  sync(camera: ParallaxCamera): void {
    const height = Math.min(Math.max(0, -camera.y), camera.viewportHeight);
    if (height === this.height) return;

    this.height = height;
    this.graphics.clear();
    if (height > 0)
      this.graphics.rect(0, 0, camera.viewportWidth, height).fill(this.colour);
  }

  destroy(): void {
    this.graphics.destroy();
  }
}

export class ParallaxLayer {
  readonly container: Container;

  readonly factorX: number;
  readonly factorY: number;

  constructor(factorX: number, factorY: number = factorX, label = 'parallax') {
    this.factorX = factorX;
    this.factorY = factorY;
    this.container = new Container({ label, scale: DESIGN_SCALE });
  }

  sync(camera: ParallaxCamera): void {
    this.container.position.set(
      px(-camera.x * this.factorX),
      px(-camera.y * this.factorY),
    );
  }

  destroy(): void {
    this.container.destroy({ children: true });
  }
}
